window.ATLAS_I18N_LOR={"01IO012":["Disciplinas Gemelas","Doy +3|+0 o +0|+3 a un aliado en esta ronda.","","''No temas al cambio, pues te cuestionará y pondrá a prueba tus límites. El cambio es nuestro mejor maestro''. —Karma","Hechizo",[],["Jonia"],"COMÚN"],"01IO015":["Yasuo","Cuando lances Aturdir o Retirada a un enemigo, le infligiré 2 de daño.","Si lanzaste Aturdir o Retirada a 5+ unidades.","''La muerte es como el viento...''.","Unidad",[],["Jonia"],"Campeón"],"01IO020":["Guardiana de Máscaras","Cuando me invocan, el resto de los aliados obtiene +1|+0 en esta ronda.","","''Hoy tu rostro será reflejo de disciplina, entrenamiento, humildad y equilibrio. Hoy eres Kinkou''.","Unidad",[],["Jonia"],"COMÚN"],"01IO045":["Heraldo de la Primavera","Al apoyar: Doy Robo de Vida al aliado que apoyo en esta ronda.","","''En el invierno podíamos oír el andar de\npisadas sobre la nieve. \nCon su despertar nuevas enredaderas y hojas brotaron.\nEl suelo del bosque anunciaba así el cambio de estación''.\n—Poema de Shon-Xan","Unidad",[],["Jonia"],"COMÚN"],"01IO008":["Blandefilos Feérica","Cuando lanzas Aturdir o Retirada a una unidad, recibo +2|+0.","","''¡¿Así que te parezco peludita y adorable?! ¡A ver si ESTO también te parece adorable!''.","Unidad",["YORDLE"],["Jonia"],"RARA"],"01IO040":["Espadachín Kinkou","","","''Aquí estaban nuestras escuelas, templos y hogares. Ahora solo quedan las ruinas para escondernos. La Orden de Zed mancilló el legado de este lugar sagrado y me aseguraré de que paguen''.","Unidad",[],["Jonia"],"COMÚN"],"01IO041":["Karma","Fin de la ronda: Creo en la mano un hechizo aleatorio de tus regiones.","Si tienes Iluminación.","''La reflexión es el camino para enfocar la mente y encontrar la forma de superar un obstáculo''.","Unidad",[],["Jonia"],"Campeón"],"01IO011":["Retirada","Retiro a un aliado.","","Un guerrero sabio sabe cuando la batalla está perdida. Una retirada a tiempo significa una futura victoria.","Hechizo",[],["Jonia"],"COMÚN"],"01IO009":["Zed","Al atacar: Invoco 1 Sombra Viviente atacante con mis estadísticas.","Si me he visto a mí o a mis aliados Sombras Vivientes Golpear dos veces el nexo enemigo.","''El balance es una ilusión. Las sombras me mostraron el poder verdadero''.","Unidad",[],["Jonia"],"Campeón"],"01IO014":["Anciano de Valleclaro","Cuando me invocan, otorgo +1|+1 a los aliados en la mano.","","La sabiduría jonia se conserva en escritos, pero son los relatos y las enseñanzas de los ancianos venerados de esa tierra los que les dan vida a los textos del pasado.","Unidad",[],["Jonia"],"COMÚN"],"01IO005":["Poro Ágil","","","''Sé que suena un poco absurdo, pero lo último que recuerdo es... ¿... algo peludo?''. —Bandolero de Navori","Unidad",["PORO"],["Jonia"],"COMÚN"],"01IO044":["Conspirador de Navori","Debes Retirar a un aliado para usarme.","","''¡Rápido! ¡Hay que salir de aquí! ¿Que quién soy? Te lo diré en el camino, lo prometo...''.","Unidad",[],["Jonia"],"COMÚN"],"01IO023":["Protectora Gémica","Al jugar: Otorgo +3|+3 a un aliado en tu mano.","","''En época de conflicto, los aldeanos buscaron la ayuda de la antigua protectora de Valle Otoñal. Aquellos que llegaron hasta su corazón recibieron su bendición y cambiaron el rumbo de la batalla''.\n—Saga de las Tierras Originarias","Unidad",[],["Jonia"],"RARA"],"01IO029":["Semillas Sembradas","Otorgo +1|+0 a los aliados en la mano.","","''No solo las semillas, queridos aprendices. El legado de la tierra misma es la promesa de un futuro mejor''. —Karma","Hechizo",[],["Jonia"],"RARA"],"01IO003":["Marca de la Muerte","Elimino el efecto Endeble de un aliado y lo otorgo a un enemigo.","","''Soy el filo en la oscuridad''. —Zed\n\n","Hechizo",[],["Jonia"],"RARA"],"01IO047":["Fulgor Sombrío","Otorgo Endeble a TODOS los seguidores en combate.","","Cuando se altera el balance de los flujos de magia, estos pasan del mundo espiritual al mundo de los mortales... casi siempre con consecuencias alarmantes.","Hechizo",[],["Jonia"],"ÉPICA"],"01IO026":["Mentor Inspirador","Al jugar: Otorgo +1|+0 a un aliado en tu mano.","","''¡Me llevó años conseguir este cuerpo increíble! ¡Días inagotables de avistar aves, describir nubes y de llevar bandejas llenas de bollos! ¡Mi constancia es admirable!''.","Unidad",[],["Jonia"],"COMÚN"],"01IO024":["Alba y Ocaso","Invoco 2 copias exactas de un aliado con Endeble.","","''Shen es un hombre atrapado entre los peligros de dos mundos y les fallará a ambos. Yo solo me consagro a Jonia''. —Zed","Hechizo",[],["Jonia"],"RARA"],"01IO028":["Mordelón Escamoso","Al jugar: Recibo +3|+0 o +0|+3.","","Uno de los habitantes más viejos de Valleclaro. Ha resistido el paso del tiempo gracias a una adaptación constante.","Unidad",["REPTIL"],["Jonia"],"COMÚN"],"01IO057":["Asesina Sombría","Cuando me invocan, roba 1.","","Se desliza con gracia\nSus pasos mudos entre las sombras\nSus garras son el único rastro.","Unidad",[],["Jonia"],"COMÚN"],"01IO032":["Shen","Al apoyar: Doy Barrera al aliado que apoyo en esta ronda.","Si he visto a aliados recibir Barrera 5 veces.","''El reino espiritual y el de los mortales se entrelazan como hilos en una manta...''. ","Unidad",[],["Jonia"],"Campeón"],"01IO013":["Demonio Sombrío","","","''¿Qué sacrificarías por poder? Tu camino comienza con un juramento que no termina hasta arrebatarte todo lo que tienes''. —Zed","Unidad",[],["Jonia"],"COMÚN"],"01IO018":["Prisa","Doy +1|+0 y Ataque Rápido a un aliado en esta ronda.","","El combate no es más que una carrera para acabar con la vida del otro antes de que te arrebate la tuya.","Hechizo",[],["Jonia"],"COMÚN"],"01IO056":["Yone, el Cazavientos","Al jugar: Lanzo Aturdir a 2 enemigos.","","''Cuando era niño le pregunté a mi hermano: ¿el viento huye o te sigue? En ese entonces me siguió para buscar consejo. Ahora yo lo sigo a él para hacer justicia''.\n","Unidad",[],["Jonia"],"RARA"],"01IO016":["Sabio del Céfiro","Al jugar: Creo una copia exacta de una carta en tu mano que no sea Sabio del Céfiro.","","''El guerrero lloraba su pérdida mientras el anciano lo consolaba y decía: 'Busca al sabio de los cielos, pues solo él es capaz de devolvernos lo que se perdió en vida, pero permanece en el recuerdo'''.\n—Saga de las Tierras Originarias","Unidad",["AVE"],["Jonia"],"RARA"],"01IO036":["Vigilante de Valleclaro","Al golpear: Reduzco en 1 el costo de la unidad más cara en la mano.","","''Patrulla, se acerca una... no... ¡DOS criaturas enormes y peludas hacia nosotros! Necesitamos ref... Ah, esperen. El telescopio está al revés...''.","Unidad",["YORDLE"],["Jonia"],"COMÚN"],"01IO033":["Minah Piesligeros","Al jugar: Lanzo Retirada a 3 enemigos.","","''Íbamos a toda prisa a través de la pradera cuando de pronto, esta CHICA saltó de repente y ¡CATAPLUM...! El choque nos dejó sin aliento''. —Bandolero de Navori","Unidad",[],["Jonia"],"ÉPICA"],"01IO001":["Ritual de Renovación","Curo 4 a un aliado o a tu nexo. Roba 1.","","''El cuerpo estará completo cuando la mente alcance la iluminación''. —Karma","Hechizo",[],["Jonia"],"RARA"],"01IO010":["Unidos","Intercambio a 2 aliados y les doy Barrera en esta ronda.","","''Avanzo con pasos en equilibrio''. —Shen\n","Hechizo",[],["Jonia"],"RARA"],"01IO022":["Fantasma","Doy Evasión a un aliado en esta ronda.","","''Vete, escóndete y no vuelvas hasta que hayas cumplido con tu tarea''. —Zed","Hechizo",[],["Jonia"],"COMÚN"],"01IO021":["Cría de los Vientos","Cuando me invocan, el resto de los aliados obtiene +2|+2 en esta ronda.","","''La primavera llega primero a los acantilados de Jonia, donde el batido de las nuevas alas baña la tierra con una suave brisa estacional''.\n—Saga de las Tierras Originarias","Unidad",[],["Jonia"],"ÉPICA"],"01IO054":["Perspicacia de las Edades","Creo en la mano otro hechizo aleatorio de tus regiones.\nIluminación: Creo 2 hechizos.","","''Cuando tu esperanza flaquee, recuerda que no estás solo. El pasado, que está lleno de nuevos amaneceres y nuevas esperanzas, siempre estará a tu lado''. —Karma","Hechizo",[],["Jonia"],"RARA"],"01IO027":["Umbramante Silenciosa","Golpe al Nexo: Creo una copia mía en la mano.","","''No se puede confiar en la carne, es frágil. Tan delicada como la línea que separa la luz de la oscuridad''.","Unidad",[],["Jonia"],"ÉPICA"],"01IO031":["Sorbenubes","Tus hechizos de Ráfaga y Enfoque cuestan 1 menos.","","Sus canciones se oían desde las aldeas: ondas sonoras largas y graves que resonaban entre cielo y ladera. Extrañas, sin forma, como las nubes del atardecer.","Unidad",[],["Jonia"],"RARA"],"01IO002":["Voluntad de Jonia","Lanzo Retirada a una unidad.","","Cuando los invasores pisaron Jonia por primera vez, supieron que someter a los habitantes de estas tierras no sería suficiente.","Hechizo",[],["Jonia"],"COMÚN"],"01IO017":["Filoveloz de Navori","Cuando me invocan, recibo Evasión en esta ronda.","","''Descuida, le quitaré hasta los dientes. Sácame de aquí y te prometo que nos repartiremos el botín. ¡No me digas que no es un buen trato!''.","Unidad",["YORDLE"],["Jonia"],"COMÚN"],"01IO042":["Discípulo de Combate","Cuando invocas a otro aliado, recibo +1|+1 en esta ronda.","","''¿Cuál es el punto de combatir si no hay nadie que aprecie tus movimientos?''.","Unidad",[],["Jonia"],"COMÚN"],"01IO006":["Dúo de Valleclaro","Cuando invocas a otro aliado, recibo +1|+0 en esta ronda.","","''¡Oye, cuidado con esas ramas! ¡A la izquierda! ¡IZQUIERDA!''. \n''Cuando me lleves TÚ a mí, bola de pelo, iremos a donde tú quieras. ¡Por ahora mando yo!''.","Unidad",[],["Jonia"],"RARA"],"01IO050":["Abrecaminos Kinkou","Alianza: Invoco un aliado de 1 de costo de tu mazo.","","Allá a donde va, siempre se asegura de que otros puedan seguirla.","Unidad",[],["Jonia"],"RARA"],"01IO048":["Yusari","","","''Su orden nos expulsó de nuestras tierras. Ha demostrado su poder, maestro Zed. Ahora es mi turno de probar que soy digno de sus enseñanzas''.","Unidad",[],["Jonia"],"RARA"],"01IO007":["Ren, la Daga Sombría","Al golpear: Creo 1 Demonio Sombrío en la mano.","","''Puedes huir, luchar o esconderte. No importa, las sombras vinieron por ti''.","Unidad",[],["Jonia"],"ÉPICA"],"01IO053":["Reanimador Esmeralda","Con Iluminación: Obtengo +4|+4.","","''Nuestros instintos más básicos impulsan la guerra, pero los instintos no tienen dominio sobre nuestras grandes virtudes: confianza, paciencia y meditación''.","Unidad",[],["Jonia"],"COMÚN"],"01IO004":["Poción de Vida","Curo 3 a un aliado o a tu nexo.","","Cada generación, región y familia tiene su propio remedio casero, aunque es indiscutible que algunos son más eficaces que otros.","Hechizo",[],["Jonia"],"COMÚN"],"01IO049":["Denegar","Detengo un hechizo rápido, uno lento o una habilidad.","","No.","Hechizo",[],["Jonia"],"RARA"],"01IO052":["Asaltacaminos de Navori","Cuando me invocan, invoco 1 Bandolero de Navori con mis estadísticas.","","''Solía ser un músico itinerante, famoso en cada aldea de aquí a Placidium... hasta que la nación de Noxus atacó. Ahora subsisto de pequeños robos. Mi mamá tenía razón, debí ser curandero...''.","Unidad",[],["Jonia"],"COMÚN"],"01IO030":["El Empíreo","","","''El propio cielo se levantó con remolinos de nubes y fuertes vientos que azotaban nuestra brigada. Intentamos seguirlo, pero ¿quién puede alcanzar al viento?''. —General Legionario","Unidad",["DRAGÓN"],["Jonia"],"ÉPICA"],"01IO019":["Cuidadora de Valleclaro","Cuando un aliado obtiene Barrera, recibo +2|+0.","","''El claro protege a los suyos, pero tú... tú no eres de aquí''.","Unidad",[],["Jonia"],"COMÚN"],"01IO046":["Tempestad de Acero","Lanzo Aturdir a un enemigo atacante.","","\"¡Hasagi!\". —Yasuo","Hechizo",["ELEMENTAL"],["Jonia"],"RARA"],"01IO037":["Refugio del Espíritu","Doy Barrera y Robo de Vida a un aliado en esta ronda.","","''Esta espada fue de mi padre. Espero que te dé la fuerza que yo no tuve en su momento''. —Shen","Hechizo",[],["Jonia"],"COMÚN"],"01IO043":["Moldeador de Ríos","Al golpear: Roba un hechizo.","","''Somos los orgullosos hijos de las Tierras Originarias: su magia fluye por nuestra sangre vastaya al igual que por nuestro reino''.","Unidad",[],["Jonia"],"RARA"],"01IO038":["Monja Solitaria","Al jugar: Lanzo Retirada a todos los demás aliados.","","''Buenos reflejos e instintos son la única compañía que deseo''.","Unidad",[],["Jonia"],"RARA"],"01IO039":["Permutación Sombría","Lanzo Retirada a un aliado para invocar 1 Sombra Viviente en su lugar.","","¿De verdad te enfrentas al enemigo que crees ver? ¿O es un engaño de las sombras?","Hechizo",[],["Jonia"],"COMÚN"],"01IO055":["Guardián del Ki","Otorgo Barrera a un aliado en la mano.\nRoba 1.","","''Aquellos que protegen el equilibrio cuentan con la protección de los Kinkou''. —Shen\n","Hechizo",[],["Jonia"],"COMÚN"],"01NX020":["Draven","Cuando me invocan o al Golpear: Creo 1 Hacha Giratoria en la mano.","Si Golpeé con un total de 2+ Hachas Giratorias.","''¿Quieres un autógrafo? A la fila''.","Unidad",[],["Noxus"],"Campeón"],"01NX006":["Vladimir","Al jugar: Inflijo 1 de daño a cualquier número de aliados para infligir ese daño a un enemigo.","Si lograste que 5+ aliados sobrevivieran al daño.","Despiadado, frío, cruel, misterioso, intuitivo, encantador.\nIrresistible...","Unidad",[],["Noxus"],"Campeón"],"01NX004":["Golpe de Sacrificio","Mato a una unidad con 3 o menos de poder.","","Todos mueren, pero los débiles mueren antes.","Hechizo",[],["Noxus"],"RARA"],"01NX048":["Curador Carmesí","Cuando sobrevivo al daño, creo una unidad Carmesí aleatoria en la mano.","","''¡Tiernos compañeros míos!''. ''Mientes, querido. Recibí cierta invitación''. ''… ¡la Juerga Interminable! ¡Sí!''. ''Así parece. Yo iré con mi familia''. ''Siempre quieres saltarte al postre, querido. ¿Qué hay de ti, Kye? ¿Nos acompañarás?''.","Unidad",[],["Noxus"],"COMÚN"],"01NX038":["Darius","","Si veo que el nexo enemigo tiene la mitad de su Vida inicial o menos.","''Con su voluntad de hierro y fuerza de titán, no hay mejor general para la Legión Trifariana''. —Swain\n","Unidad",[],["Noxus"],"Campeón"],"01NX023":["Huésped Aracnoide","Cuando me invocan, otorgo +2|+0 a otros aliados araña.","","Una sola mirada y serás suyo; una sola mordida y serás de ellas.","Unidad",["ARAÑA"],["Noxus"],"RARA"],"01NX013":["Maniobra Decisiva","Lanzo Aturdir a un enemigo. Doy +2|+0 a todos los aliados en esta ronda.","","''Cualquiera puede atacar enemigos con fuerza descomunal; pero se necesita visión para esconder esa fuerza hasta el momento indicado''. —Swain","Hechizo",[],["Noxus"],"RARA"],"01NX046":["Vigía Aracnoide","Al jugar: Lanzo Aturdir a un enemigo.","","''¡Esa mujer me cautiva! Sus largas piernas, su melodiosa y dulce voz; y sus ojos, rojos como las rosas. ¡Y aceptó cenar conmigo esta noche!''. —Aristócrata Desafortunado","Unidad",["ARAÑA"],["Noxus"],"COMÚN"],"01NX047":["Transfusión","Inflijo 1 de daño a un aliado para dar +2|+2 a otro aliado en esta ronda.","","''Es dar y recibir: tú das y yo recibo''. —Vladimir","Hechizo",[],["Noxus"],"COMÚN"],"01NX040":["Saboteadora Legionaria","Al atacar: Inflijo 1 de daño al nexo enemigo.","","''Aunque nuestros rompeescudos pueden partir a un hombre en dos, la legión tiene otros talentos cuando se requiere un toque más... discreto''. —Swain","Unidad",[],["Noxus"],"COMÚN"],"01NX025":["Vínculo Fraterno","Otorgo +2|+0 a 2 aliados.","","''Los lazos que se forjan en la guerra son tan fuertes como los familiares, pues la sangre une a ambos''. —Veterano Legionario","Hechizo",[],["Noxus"],"COMÚN"],"01NX055":["Araña Hogareña","Cuando me invocan, invoco 1 Arañita.","","''Mis arañas adoran la compañía. Lástima que el sentimiento nunca sea recíproco''. —Elise","Unidad",["ARAÑA"],["Noxus"],"COMÚN"],"01NX030":["Discípula Carmesí","Cuando sobrevivo al daño, inflijo 1 de daño al nexo enemigo.","","''¡Edvin! Por fin te encuentro, querido. ¡Justo pensaba en ti!''. ''Estaremos ambos presentes…''. ''Acompáñame entonces. Prometo que será divertido''. ''¿O tal vez no?''.","Unidad",[],["Noxus"],"RARA"],"01NX007":["Cantabatallas de la Arena","Al atacar: Doy +1|+0 a otros aliados atacantes en esta ronda.","","Lanzó un brioso rugido. En ese instante, el corazón de la arena palpitó al ritmo del suyo; aquellas masas enardecidas no dejaban de vitorear por su triunfo.","Unidad",[],["Noxus"],"RARA"],"01NX021":["Merodeador Legionario","Al atacar: Otorgo +1|+1 a tus Merodeadores Legionarios aliados en todas partes.","","La Legión Trifariana está repleta de bandidos oportunistas que se aprovechan de los débiles y de los heridos.","Unidad",[],["Noxus"],"COMÚN"],"01NX009":["Favorito del Público","Cuando me invocan, recibo +1|+1 por cada aliado adicional que tengas.","","Hay duelistas que son famosos por su carisma. Otros por la rapidez de su técnica. Vessid no posee nada de eso, pero nadie es tan efectivo para destazar a un rival.","Unidad",[],["Noxus"],"RARA"],"01NX011":["Muerte Giratoria","Un aliado en combate golpea a un enemigo en combate.","","''Tengo el mejor trabajo''. —Draven","Hechizo",[],["Noxus"],"COMÚN"],"01NX053":["El Duelo","Si tienes un aliado con 5+ de poder, mato a TODAS las unidades con 4 o menos de poder.","","''¡¡EEEES LA HORA DE LA VERDAAAAAD!!''. —Cantabatallas de la Arena","Hechizo",[],["Noxus"],"ÉPICA"],"01NX054":["Rugido Intimidante","Lanzo Aturdir a TODOS los enemigos con 4 o menos de poder.","","''Tomó una buena bocanada de aire... puede que nos dé un... ¡Sí! Ahí lo tienen, amigos: ¡el famoso grito de guerra de Thunder! ¡A todos por aquí se nos puso la carne de gallina, Thuuunder!''. —Cantabatallas de la Arena","Hechizo",[],["Noxus"],"RARA"],"01NX029":["Veterano Legionario","Cuando otro aliado sobrevive al daño, este recibe +1|+0.","","Regresó de la guerra al filo de la muerte. Solo los cuidados de su marido y los bálsamos del boticario lograron salvarlo. Noxus no reparó en gastos para que su experto consejero sobreviviera.","Unidad",[],["Noxus"],"ÉPICA"],"01NX014":["Shiraza, la Daga","Inflijo daño doble al nexo.","","''¡¿Qué fue lo que dijo?! Ese hombre es un cabeza hueca, aunque esos hombros...''.","Unidad",[],["Noxus"],"ÉPICA"],"01NX042":["Katarina","Cuando me invocan, creo 1 Filo de la Daga Fugaz en la mano.","Si he golpeado una vez. Cuando subo de nivel, lanza Retirada sobre mí.","''No hay nada como un poco de práctica de puntería demaciana para agudizar los sentidos...''.","Unidad",[],["Noxus"],"Campeón"],"01NX051":["Capitán Farron","Cuando me invocan, creo 2 Diezmar en la mano.","","En el sumidero de Zaun, el joven Benn Farron era una amenaza. Inestable e intolerable. Lo admitieron en las filas de Noxus. Reconocido e imparable.","Unidad",[],["Noxus"],"ÉPICA"],"01NX012":["Retaguardia Legionario","","","En Noxus, donde se honra a los soldados por su audacia en la batalla, cuidar la retaguardia es lo mismo que un castigo.","Unidad",[],["Noxus"],"COMÚN"],"01NX043":["Filo de la Daga","Inflijo 1 de daño a cualquier objetivo.","","''Una daga puede cortar lo que sea en las manos correctas... lo que sea''. —Katarina","Hechizo",[],["Noxus"],"COMÚN"],"01NX037":["Granadero Legionario","Último Aliento: Inflijo 1 de daño al nexo enemigo.","","A cada noxiano se le enseña que vivir al servicio del imperio es una buena inversión, pero pocos se atreven a dar sus vidas como los granaderos legionarios.","Unidad",[],["Noxus"],"COMÚN"],"01NX010":["General Legionario","Cuando me invocan, recibo +1|+1 por cada unidad a la que hayas lanzado Aturdir o Retirada en esta partida.","","Cada noxiano conoce los tres Principios de la Fuerza; sin embargo, si un soldado desea subir de rango, también debe dominarlos.","Unidad",[],["Noxus"],"COMÚN"],"01NX017":["Tamborilera Legionaria","Al apoyar: Doy Ataque Rápido al aliado que apoyo en esta ronda.","","La legión expandió el imperio con cada redoble de su tambor. Nadie podía detenerlos. Nadie los detuvo.","Unidad",[],["Noxus"],"COMÚN"],"01NX003":["Correapuestas de la Arena","Inicio de la ronda: Descarto tu carta de menor costo para robar 1.","","''... creíste que SOLO Shiraza había sobrevivido. Y ese niño jonio, aunque sin brazo, no está muerto. Es un sobreviviente, ¿no? Esos detalles se pueden corregir...''.","Unidad",["YORDLE"],["Noxus"],"RARA"],"01NX039":["Visión","Cuando me juegan o me descartan, otorgo +1|+0 a los aliados.","","''Aquellos que no pueden ver el futuro no tienen cabida en él''. —Jericho Swain.","Hechizo",[],["Noxus"],"RARA"],"01NX041":["Rompeescudos Trifariano","","","''No tengo paciencia para sitiar a nadie. Llama a los rompeescudos''. —Darius","Unidad",[],["Noxus"],"COMÚN"],"01NX036":["Duelista Minotauro","Inicio de la ronda: Lanzo Aturdir al enemigo Más débil.","","''No me importa quién te hizo daño ni qué te hicieron. Si quieres ayuda en el foso, pagas por adelantado. No hay descuentos por historias tristes''.","Unidad",[],["Noxus"],"RARA"],"01NX044":["Ariete Martillante","Al atacar: Recibo +4|+0.","","''Señor, se rehúsan a abrir las puertas. Exigen hablar con Darius, pero él está a dos días de distancia. ¿Enviamos mensajeros?''.\n''Eso no será necesario''.","Unidad",[],["Noxus"],"ÉPICA"],"01NX005":["Aristócrata Carmesí","Al jugar: Inflijo 1 de daño a un aliado y le otorgo +1|+0 y Arrollar.","","''Eh, ¿tú también? Al Baile de la Ju…''. ''¡La mía es intolerable!''. ''Respeto demasiado a mi padre como para… tal vez deberíamos llevar el mismo atuendo''.","Unidad",[],["Noxus"],"COMÚN"],"01NX016":["Aspirante Trifariano","Cuando me invocan, recibo +2|+0 si tienes otro aliado de Noxus.","","''El título será tuyo cuando las batallas consuman el filo de tu hacha y tus botas se cubran de sangre''. —Veterano Legionario","Unidad",[],["Noxus"],"COMÚN"],"01NX019":["Poder","Doy +3|+0 y Arrollar a un aliado en esta ronda.","","''Cuando insinúo que algo está sobrevalorado no significa que no sea bueno, solo que está sobrevalorado''. —Darius","Hechizo",[],["Noxus"],"COMÚN"],"01NX015":["Mi Preciosa","","","Ella las ama a todas, pero ama más a esta.","Unidad",["ARAÑA"],["Noxus"],"COMÚN"],"01NX050":["Loto Mortal","Inflijo 1 de daño a TODAS las unidades en combate.","","''¡Baila conmigo!''. —Katarina","Hechizo",[],["Noxus"],"RARA"],"01NX056":["Shunpo","Inflijo 2 de daño a un enemigo y lanzo Preparar.","","Cuando ves la daga ya es demasiado tarde.","Hechizo",[],["Noxus"],"COMÚN"],"01NX033":["Asesora Trifariana","Cuando me invocan, roba 1 por cada aliado con 5+ de poder que poseas.","","''Solo un ojo implacable y sagaz puede distinguir a aquellos dignos de pertenecer a la Legión trifariana, pero ella distingue a los lobos de las ovejas a kilómetros''. —General Legionario","Unidad",[],["Noxus"],"RARA"],"01NX052":["Sangre por Sangre","Inflijo 1 de daño a un seguidor aliado. Si sobrevive, creo una copia en la mano.","","La primera clase de un hemomante suele ser un desastre.","Hechizo",[],["Noxus"],"COMÚN"],"01NX045":["Duelista Salvaje","","","''Y ahora: ¡ZARPAS! Hubo SANGRE en la última pelea contra los Cinco Locos... ahora tres. ¡Bien! ¿Cuál será la víctima de hoy? ¡Se aceptan sus apuestas! ¡Cuatro a uno!''. —Karl, Correapuestas de la Arena","Unidad",[],["Noxus"],"RARA"],"01NX031":["Buscaglorias Trifariana","","","Ganar un lugar en la Legión Trifariana es suficiente para la mayoría, pero no para todos.","Unidad",[],["Noxus"],"RARA"],"01NX002":["Diezmar","Inflijo 4 de daño al nexo enemigo.","","''A veces necesitas ingenio táctico para golpear una fortaleza. Otras, solo tienes que pegarle más fuerte''. —Darius","Hechizo",[],["Noxus"],"RARA"],"01NX008":["Jinete de Basiliscos","Alianza: Recibo +1|+1 y Arrollar.","","Esta unidad en particular utiliza caballos, pero no para cabalgar. Son un manjar para las bestias.","Unidad",[],["Noxus"],"RARA"],"01NX034":["Poro Cariñoso","","","''En Noxus no hay lugar para... para débi... ¡ALGUIEN QUÍTEME ESTO DE ENCIMA!''. —Darius","Unidad",["PORO"],["Noxus"],"COMÚN"],"01NX035":["Superfan de Draven","Cuando me invocan, muevo a Draven hasta arriba de tu mazo si ya no lo tienes en la mano o en juego.","","''¿Quieres un autógrafo? ¡A... a la fila!''.","Unidad",[],["Noxus"],"COMÚN"],"01NX026":["Trifariano Temerario","","","''La Legión puede convertir el vicio de la imprudencia en una herramienta muy útil''. —Swain","Unidad",[],["Noxus"],"COMÚN"],"01NX027":["Elixir de Furia","Doy +3|+0 a un aliado en esta ronda.","","''Si alguien desprecia una mano amiga, un puño hará que lo lamente''.\n—Axioma noxiano","Hechizo",[],["Noxus"],"COMÚN"],"01NX022":["Guillotina Noxiana","Mato a una unidad dañada para crear 1 Guillotina Noxiana con Fugaz en la mano.","","Para Darius la misericordia es un ataque con guante blanco.","Hechizo",[],["Noxus"],"RARA"],"01NX032":["Reanimador Carmesí","Cuando me invocan, inflijo 1 de daño a los demás aliados.","","''Aunque no lo quisiera, me obligarías a ir. Así que... claro''.","Unidad",[],["Noxus"],"RARA"],"01NX024":["Kato, el Brazo","Al apoyar: Doy +3|+0 y Arrollar al aliado que apoyo en esta ronda.","","''Shiraza es una excelente novia... digo, amiga. Claro que no somos pareja; pero si lo fuéramos, buscaría la forma de desearle un feliz aniversario. Gracias, no más preguntas''.","Unidad",[],["Noxus"],"ÉPICA"],"01NX049":["Astucia","Lanzo Aturdir a un enemigo.","","''Haz que tus enemigos se ahorquen ellos mismos y no tendrás que arrastrarlos tú al cadalso''. —Jericho Swain","Hechizo",[],["Noxus"],"COMÚN"],"01DE031":["Oradores del Alba","Fin de la ronda: Otorgo +1|+1 a los otros aliados si un aliado murió en esta ronda.","","''La maldad ganó la batalla, pero no ganará la guerra. ¡Que la memoria de nuestros caídos sea su armadura!''.","Unidad",[],["Demacia"],"ÉPICA"],"01DE022":["Lucian","","Si he visto morir a 4+ aliados o a una Senna aliada.","''Estaré bien, Senna. Siempre y cuando te tenga a mi lado''.","Unidad",[],["Demacia"],"Campeón"],"01DE019":["Movilizar","Reduzco en 1 el costo de los aliados en tu mano.","","''De los campos de cultivo al frente de batalla en solo dos semanas. Eso es lo que esperamos de cada persona capaz en Demacia''. —Garen","Hechizo",[],["Demacia"],"RARA"],"01DE042":["Lux","","Si te he visto jugar 6+ de maná de hechizos. Cuando subo de nivel, creo 1 Chispa Final en la mano.","''Siempre supe que había algo diferente en mí... una luz en mi interior. ¡No sé qué es, pero lo averiguaré!''. ","Unidad",[],["Demacia"],"Campeón"],"01DE010":["Lancero Aliveloz","Último Aliento: Creo una carta Élite aleatoria en la mano.","","''Se necesita valor para confiarle la vida a un aliplata, sobre todo en combate y tan lejos del suelo... también audacia y mucha resistencia''. —Garen","Unidad",["ÉLITE","AVE"],["Demacia"],"RARA"],"01DE020":["Defensora de la Vanguardia","","","''Aunque no sabíamos qué eran esas criaturas, los rostros de los camaradas a nuestro lado eran lo único que necesitábamos conocer''.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"01DE034":["Herrero Bélico","Cuando invocas una Élite, le otorgo +1|+1.","","Las guerras se ganan en la forja.","Unidad",[],["Demacia"],"RARA"],"01DE002":["Tianna Guardia de la Corona","Cuando me invocan, lanzo Preparar.","","''Nuestra casa sangró por este reino. No le darás la espalda al honor de la familia por unos cuantos trucos de luz''.","Unidad",[],["Demacia"],"ÉPICA"],"01DE012":["Garen","Cuando me invocan, doy +1|+1 a otros aliados en esta ronda.","Si he golpeado dos veces.","El entrenamiento y la resiliencia son el único camino de un soldado. No flaquearemos aunque estemos de frente al peligro.","Unidad",["ÉLITE"],["Demacia"],"Campeón"],"01DE017":["Resistencia Solitaria","Si tienes solo 1 aliado, le otorgo +3|+3.","","Cuando otros fracasan, depende de los verdaderos héroes encontrar el camino del triunfo.","Hechizo",[],["Demacia"],"RARA"],"01DE045":["Fiora","","Si he matado a 2 enemigos.","''De la arena a los torneos y de los entrenamientos a las batallas, mi alma ansía un oponente digno. No pararé hasta demostrar mi grandeza''.","Unidad",[],["Demacia"],"Campeón"],"01DE052":["Formación de Acero","Cuando me invocan o al Atacar: Doy Barrera a los aliados en esta ronda.","","''Esta formación es la base de nuestras tácticas de batalla y requiere la fe de cada soldado en su escudo y en los escudos de sus compañeros. Mientras continúen de pie, nuestro reino vivirá''. —Garen\n","Unidad",[],["Demacia"],"ÉPICA"],"01DE021":["Persecución Implacable","Lanzo Preparar.",""," ''Todos deben enfrentar sus miedos. Por suerte para ti, estoy aquí''. —Lucian\n","Hechizo",[],["Demacia"],"COMÚN"],"01DE025":["Arresto","Un aliado lanza Capturar a una unidad.","","''Somos la ley y tú su súbdito. Esa es la única verdad y debes someterte a ella''. —Cazamagos Persuasor","Hechizo",[],["Demacia"],"COMÚN"],"01DE007":["Juicio","Un aliado en combate golpea a todos los enemigos en combate.","","La justicia siempre llega para todos.","Hechizo",[],["Demacia"],"ÉPICA"],"01DE055":["Duelista Laurent","Al jugar: Otorgo Desafío a un aliado en la mano.","","''Parecía solo un niño bonito con una espada costosa... ¡pero vaya que sabía usarla! Le pedí la revancha, pero no entendí su nombre debido a ese acento ridículo''. —Alférez demaciano","Unidad",[],["Demacia"],"COMÚN"],"01DE048":["Cazamagos Incitador","Obtengo +2|+2 cuando hayas jugado un hechizo de 6+ de costo en esta partida.","","''En el pasado, la terrible magia usada en las Guerras Rúnicas hizo sucumbir a toda Runaterra. Nuestra orden nació para acabar con toda la magia y salvar nuestro reino''. —Manual de los Cazamagos","Unidad",[],["Demacia"],"RARA"],"01DE001":["Portaestandarte de la Vanguardia","Alianza: Otorgo +1|+1 a otros aliados.","","''Nuestro estandarte ondea por nuestro rey, nuestras casas y ciudadanos; por nuestra lealtad a Demacia. Entiende su relevancia, llévalo en alto y muéstralo con orgullo''. —Tianna Guardia de la Corona","Unidad",["ÉLITE"],["Demacia"],"RARA"],"01DE043":["Chefs de Guerra","Al apoyar: Doy +1|+1 al aliado que apoyo en esta ronda.","","Nadie en el ejército demaciano debe ser tomado a la ligera.","Unidad",[],["Demacia"],"COMÚN"],"01DE049":["Poro Valiente","","","''El nuevo recluta posee la perseverancia y el coraje de nuestros mejores soldados. ¿Formará parte de la Vanguardia? Es... más pequeño que los demás, pero ya veremos''. —Sargento de la Vanguardia","Unidad",["PORO"],["Demacia"],"COMÚN"],"01DE053":["Caballero Laurent","Al golpear: Creo en la mano otro seguidor aleatorio de tus regiones con Desafío.","","''... oh, mon dieu''. —Fiora","Unidad",[],["Demacia"],"ÉPICA"],"01DE033":["Remembranza","Cuesto 1 menos por cada aliado que haya muerto en esta ronda. Invoco 1 seguidor de Demacia aleatorio de 5 de costo.","","''Hoy corregiremos las injusticias que castigaron a quienes nos precedieron. Los sacrificios de nuestros camaradas no serán en vano''. —Guardiana Radiante","Hechizo",[],["Demacia"],"RARA"],"01DE044":["Valor Redoblado","Curo por completo a un aliado y duplico su poder y su vida.","","En Demacia, decir que eres tan fuerte como dos enemigos no es solo fanfarronería.","Hechizo",[],["Demacia"],"RARA"],"01DE024":["Cazamagos Conservador","Último Aliento: Creo en la mano un hechizo aleatorio de una región distinta a Demacia con costo 6+ .","","''Aunque los objetos arcanos despiertan una enorme fascinación, es mejor que sean nuestros expertos quienes se encarguen de ellos, no nuestros nobles pero incultos ciudadanos''.\n—Manual de los Cazamagos","Unidad",[],["Demacia"],"COMÚN"],"01DE004":["Aliplata de la Vanguardia","Al jugar: Invoco una copia idéntica de mí.","","Se precipitaron desde las nubes como rayos de plata; raudos y seguros, se lanzaron hacia sus objetivos. Fue entonces que, tan rápido como llegaron, desaparecieron. ","Unidad",["ÉLITE","AVE"],["Demacia"],"COMÚN"],"01DE011":["Protegido Laurent","","","''¡¿QUE HIZO QUÉ?! ¡Le confié los sables dobles invaluables de Pierre de Guillard! ¡Dijo que solo los usaría para entrenar!''. —Guardaespadas Laurent","Unidad",[],["Demacia"],"COMÚN"],"01DE047":["Sucesión","Invoco 1 Vanguardia Valerosa.","","La armadura de la Vanguardia Valerosa se hereda de un soldado al otro. De esa forma, los nuevos reclutas pueden sentir el peso y el orgullo de su responsabilidad.","Hechizo",[],["Demacia"],"COMÚN"],"01DE046":["Vigilante de la Vanguardia","","","Que sea silencioso no lo hace seguro.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"01DE050":["Purificar","Silencio a un seguidor.","","''Tu insignia gris de petricita es tu principal defensa contra la magia; simboliza nuestras responsabilidades y les recuerda a otros nuestra autoridad. Hónrala sobre todas las cosas''.\n—Manual de los Cazamagos","Hechizo",[],["Demacia"],"COMÚN"],"01DE040":["Cazamagos Persuasor","Obtengo +1|+1 y Desafío cuando hayas jugado un hechizo de 6+ de costo en esta partida.","","''Ciudadanos de Demacia, velar por su seguridad es un honor, pero hoy debemos pedirles su más absoluto apoyo, pues a pesar de nuestras murallas, ¡los magos aún caminan entre nosotros!''.\n","Unidad",[],["Demacia"],"RARA"],"01DE036":["Escudera de la Vanguardia","Cuando invocas una Élite, mi costo se reduce 1.","","''Cada persona y viaje en mi vida me enseñaron algo nuevo. Sin embargo, mientras más aprendía y más fuerte me volvía, más entendía lo largo que era el camino''. —Cithria, Escudera de la Vanguardia\n","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"01DE037":["Estocada","Doy +3|+0 y Barrera a un aliado en esta ronda.","","''¡Peleas como un poro! No esperaba otra cosa''. —Fiora","Hechizo",[],["Demacia"],"RARA"],"01DE014":["Refuerzos","Invoco 2 Vanguardias Valerosas y otorgo +1|+1 a los aliados Élite.","","''Nuestros rivales lo saben: si golpean a uno de nosotros, nos golpean a todos''.\n—El Código de la Vanguardia\n","Hechizo",[],["Demacia"],"RARA"],"01DE015":["Guardiana Radiante","Cuando me invocan, recibo Robo de Vida y Dureza si un aliado murió en esta ronda.","","''Hordas de manos no muertas jalaron y enterraron a sus camaradas. Solo ella sobrevivió: un faro de justicia cuya espada parecía cantar el nombre de los caídos con cada corte''. —Alférez demaciano","Unidad",[],["Demacia"],"RARA"],"01DE003":["Guardaespadas Laurent","Al jugar: Otorgo +2|+2 a un aliado.","","''Sí, son hermosas. Sin embargo, como cualquier instrumento, su verdadera belleza solo reluce en las manos de un maestro''. ","Unidad",[],["Demacia"],"RARA"],"01DE026":["Combate Singular","Un aliado y un enemigo se Golpean entre sí.","","''No más palabras; hablemos con nuestras armas''. —Fiora","Hechizo",[],["Demacia"],"COMÚN"],"01DE032":["Barrera Prismática","Doy Barrera a un aliado en esta ronda.","","''El mundo te dará la espalda si eres diferente. La gente dirá que ser distinto te hace débil, pero en realidad nos hace fuertes y compasivos. ¡Te protegeré hasta en las horas más oscuras!''. —Lux","Hechizo",[],["Demacia"],"COMÚN"],"01DE027":["En Garde","Doy Desafío a los aliados en esta ronda.","","''No hay demaciano que rechace una lección de esgrima con un Laurent... y que aún siga vivo''. —Fiora","Hechizo",[],["Demacia"],"RARA"],"01DE006":["Sargento de la Vanguardia","Cuando me invocan, creo 1 ¡Por Demacia! en la mano.","","''Lidera nuestras prácticas día y noche, y siempre es el primero en saltar a la batalla. Duro como el acero y firme como roca; no podría haber elegido un mejor líder''. —Alférez demaciano","Unidad",["ÉLITE"],["Demacia"],"RARA"],"01DE038":["Senna, Centinela de la Luz","La primera vez que un Lucian aliado muera, obtengo +1|+1 y Ataque Doble.","","''Nuestros centinelas son la primera línea de defensa entre la horda de no muertos inagotables y los reinos de los hombres. Golpeamos primero y con gran fuerza, y JAMÁS retrocedemos cuando las vidas de nuestros compañeros están en peligro''.","Unidad",[],["Demacia"],"RARA"],"01DE041":["Espalda con Espalda","Doy +3|+3 a 2 aliados en esta ronda.","","''¡Cúbreme, voy a atacar!''.\n''Qué curioso, yo estaba a punto de pedirte lo mismo''.\n—Lorn y Dax del Batallón de Oriente","Hechizo",[],["Demacia"],"RARA"],"01DE035":["¡Por Demacia!","Doy +3|+3 a los aliados en esta ronda.","","''Son nuestros hogares, familias y hermanos de armas; es nuestro orgullo, honor y fuerza. Hoy, mientras defendemos la existencia de todo ello, no olvidemos gritar a una voz: ¡DEMACIA!''. —Sargento de la Vanguardia","Hechizo",[],["Demacia"],"RARA"],"01DE018":["Golpe Radiante","Doy +1|+1 a un aliado en esta ronda.","","''Los no muertos pelean como si no hubiera un mañana. Nos aseguraremos de que así sea''. —Lucian\n\n","Hechizo",[],["Demacia"],"COMÚN"],"01DE009":["Protectora de Acero","Al jugar: Doy Barrera a un aliado en esta ronda.","","''Somos una nación próspera porque el destino de cada guerrero es una joya que no estamos dispuestos a derrochar''. —Rey Jarvan III","Unidad",[],["Demacia"],"COMÚN"],"01DE039":["Cithria de Pradonubes","","","''Todas las noches mientras afilaba su espada, mi madre solía contarme historias sobre los legendarios héroes de Demacia; no había noche que no soñara con una aventura y hoy esos sueños comenzarán a hacerse realidad''.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"01DE056":["Noblespada de la Vanguardia","Al atacar: Recibo +2|+2.","","El grito de batalla resuena y la tierra se mueve bajo mis pies. Solo necesito la orden de mi señora para hacer su voluntad y conocer mi destino.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"01DE029":["Rastreadora Plumaveloz","Cuando invocas a otro aliado, recibo Desafío.","","Estos parientes de los raptores aliplata poseen el mismo instinto depredador que sus primos, aunque no parecen nada conscientes de su tamaño diminuto.","Unidad",["AVE"],["Demacia"],"COMÚN"],"01DE028":["Caballería de la Vanguardia","","","La Vanguardia no requería tambores ni música para marcar su paso: el sonido constante y rítmico de los caballos al andar era suficiente.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"01DE013":["Cota de Malla","Otorgo Dureza a un aliado.","","El acero demaciano es conocido en el mundo por su resistencia superior. Su forja requiere de herreros de renombre tan fuertes como él.","Hechizo",[],["Demacia"],"COMÚN"],"01DE023":["Cazamagos Investigadora","Creo 1 Arresto en la mano cuando hayas jugado un hechizo de 6+ de costo en esta partida.","","''Lamentamos la intrusión, pero vamos a necesitar su absoluta cooperación. Se nos notificó de ciertos... 'sucesos extraños'...''.","Unidad",[],["Demacia"],"COMÚN"],"01DE051":["Cithria la Audaz","Al atacar: Doy +1|+1 y Temible al resto de los aliados atacantes en esta ronda.","","''Las leyendas jamás fueron solo ficción para mí: eran aventuras que me llamaban. Dejé Pradonubes para encontrar mi propia aventura, pero descubrí que tendría muchas más. Y que apenas comenzaban''.\n","Unidad",["ÉLITE"],["Demacia"],"ÉPICA"],"01DE054":["Redentora de la Vanguardia","Cuando me invocan, roba una unidad si un aliado muere en esta ronda.","","''¡Recordaremos a nuestros caídos con cada grito de guerra, con cada corte de nuestras espadas y con cada choque de nuestros escudos! ¡Hoy la victoria es nuestra!''.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"01DE030":["Aliplata en Picada","","","Llovieron flechas a montones desde los muros de la fortaleza; pero nadie pudo darle a la mota plateada que surcaba el cielo.","Unidad",["AVE"],["Demacia"],"COMÚN"],"01PZ040":["Jinx","","Si veo que tu mano está vacía.","''¿Qué hay, Carapescado?''\n''¡Me preocupas, Jinx! Es que cuando te aburres...''\n''... ¡solo quiero hacer explotar algo! ¡Qué buena idea, Carapescado!''","Unidad",[],["Piltóver y Zaun"],"Campeón"],"01PZ008":["Teemo","Golpe al Nexo: Planto 5 Hongos Venenosos en cartas aleatorias del mazo enemigo.","Si has plantado 15+ Hongos Venenosos.","''Regla 154 del explorador de Bandle: ¡No temas a lo desconocido! Regla 276: ¡Los habitantes del bosque son nuestros amigos! Regla 354: ¡Si es peludo, se puede tocar, pero no comer! Regla 417...''.","Unidad",["YORDLE"],["Ciudad de Bandle","Piltóver y Zaun"],"Campeón"],"01PZ056":["Heimerdinger","Cuando juegas un hechizo, creo una Torreta del mismo costo con Fugaz en la mano. Cuesta 0.","Si invocaste 12+ de poder de aliados Tecnología.","''¿Científico loco? ¡Bah! Puede que sea algo excéntrico y desordenado, pero estoy en todos mis cabales. ¡Gracias por tu preocupación!''.","Unidad",["YORDLE"],["Ciudad de Bandle","Piltóver y Zaun"],"Campeón"],"01PZ013":["Experimentador Aumentado","Al jugar: Descarta tu mano. Roba 3. Inflijo 3 de daño a un enemigo.","","Sus sueños le costaron las manos, pero persistió. Nada se interpondría en su camino.","Unidad",[],["Piltóver y Zaun"],"ÉPICA"],"01PZ007":["Carro Electrurdido","Al apoyar: Creo 4 copias en tu mazo del aliado que apoyo.","","El sonido de los cañones atraía a la plaza a las multitudes que querían ver el espectáculo. Tomará semanas quitarse todo el confeti del cabello.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"01PZ018":["Prodigio de la Academia","","","¿Cómo apunta? Muy buena pregunta.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"01PZ019":["Aprendiz Entusiasta","Cuando me invocan, restablezco 2 de maná de hechizos.","","No todo el mundo está hecho para traer el progreso a Piltóver. Hay gente que necesita algo de ayuda... como los que no entienden los inventos.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"01PZ025":["Vendedor de Hongos","Cuando juegas un hechizo, planto 3 Hongos Venenosos en el mazo enemigo.","","''¿Son de calidad?''.\n''¡Claro! ¡De primera! ¡Yo mismo hablé con ellos!''.\n''A ver, dámelos... espera... ¿qué?''.\n''¡Ajá! ¡Este se va a casar!''.\n''¿Cuántos te comiste?''.\n''... ¡con un percebe!''.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"01PZ048":["Corina Veraza","Al jugar: Lanzo Aniquilar a las 5 cartas de arriba del mazo para infligir 1 de daño a todos los enemigos y al nexo enemigo por cada hechizo aniquilado.","","''Los piltovianos son cerrados y no ven más que engranajes y chatarra; no valoran el delicado arte de cada tallo, cada pétalo, cada célula de mi cultivario. Les daré un destino lleno de inmerecida gracia''.","Unidad",[],["Piltóver y Zaun"],"ÉPICA"],"01PZ028":["Dispositivo Improvisado","Cuando me juegas o me descartas, invoco 1 Escurridizo de Chatarra.","","Con un puñado de chatarra y muy poco tiempo, la joven inventora recordó una peculiar fuente de inspiración: una criatura que vio escurrirse por los ríos de una jungla muy lejana.","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"01PZ050":["Fuerza de Hechizo Creciente","Doy +4|+0 y Ataque Rápido a un aliado en esta ronda.","","''Hace cosquillas cuando empieza a brillar. Es normal... ¿no?''. —Ezreal","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"01PZ054":["Pumdillero Novato","Al atacar: Inflijo 2 de daño al nexo enemigo.","","''¿Estás seguro de que es buena idea?''.\n''Nop''.\n''Debías responder que sí''.\n''Entonces mejor no preguntes''.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"01PZ030":["Personaje Sospechoso","Al jugar: Elige a un seguidor y me transformo en su copia exacta.","","''¡Hola, compañeros quimobarones!\".","Unidad",["YORDLE"],["Piltóver y Zaun"],"RARA"],"01PZ017":["Vendedor de Toneles Usados","Cuando me invocan, invoco 2 Toneles Cáusticos.","","''¿Te envía Ziel? Ya le dije, lo suyo es suyo. No puedo devolverle el dinero de algo que no he visto, ¿no? En cualquier caso, recibí otra tanda de toneles de primera que no me importaría repartir...''.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"01PZ038":["Dragador del Sumidero","Al jugar: Descarta una carta para robar 1.","","En el sumidero no se desperdicia nada.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"01PZ036":["Ezreal","Golpe al Nexo: Creo 1 Disparo Místico con Fugaz en la mano.","Si fijaste enemigos como objetivo 8+ veces.","''¿Gafas? Listo. ¿Bufanda? Listo. Guantelete increíble con propiedades mágicas que claro que entiendo a la perfección? Listo, listo yyyyyyy listo''.","Unidad",[],["Piltóver y Zaun"],"Campeón"],"01PZ035":["Jae Medarda","Cuando me seleccionan como objetivo, roba 1.","","Jae, heredero del prestigioso clan Medarda de Piltóver, siempre ha preferido salir en busca de antiguos artefactos en lugar de ocuparse del negocio familiar... para disgusto de su padre.","Unidad",[],["Piltóver y Zaun"],"ÉPICA"],"01PZ010":["Nube de Hongos","Planto 5 Hongos Venenosos en el mazo enemigo.","","Primero, un golpe seco cuando el hongo surte efecto. Luego, un dolor punzante que te debilita. Por último, el eco de una risa...","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"01PZ045":["Pilluela Zaunita","Al jugar: Descarta una carta para robar 1.","","''Uno pensaría que las ratas del sumidero cuidan de los suyos''.\n''Solo se lamentan, hermano''.\n''Una pena... Eh, ¿viste mi bolso?''.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"01PZ002":["Tabernero del Callejón","Cuando me invocan, creo en la mano una carta aleatoria por cada copia de Tabernero del Callejón que hayas invocado en esta partida.","","''Así es, amigo; es un trago suave. Tan suave como el olor del sumidero. El balde está al lado de la ruleta de cantos''.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"01PZ004":["Descarga Certera","Inflijo 3 de daño a un enemigo o al nexo enemigo, luego 2 a otro y después 1 a otro más.","","''Los golpes de suerte no existen cuando tienes talento''. —Ezreal","Hechizo",[],["Piltóver y Zaun"],"ÉPICA"],"01PZ020":["Poro Audaz","","","Su primer lanzamiento fue pura casualidad: se metió en un cañón del Día del Progreso mientras se pavoneaba. Ahora es la estrella de Piltóver: surca los cielos y emociona al público que la mira desde abajo.","Unidad",["PORO"],["Piltóver y Zaun"],"COMÚN"],"01PZ046":["Copias Falsificadas","Elige una carta en la mano y creo 4 copias idénticas en tu mazo.","","La imitación es la forma más sincera de robo.","Hechizo",[],["Piltóver y Zaun"],"RARA"],"01PZ052":["Disparo Místico","Inflijo 2 de daño a cualquier objetivo.","","''Yo nunca fallo. Aunque sí he hecho uno que otro disparo de advertencia...''. —Ezreal","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"01PZ033":["Prrfección Miaucánica","Si jugaste 20 cartas nuevas en esta partida, invoco Gatástrofe.","","''Al final, salimos engañados los que hicimos posible la visión de von Yipp. No sabíamos lo que habíamos creado, el terrible poder que liberaríamos''. —Ingeniero de proyecto piltoviano","Hechizo",[],["Piltóver y Zaun"],"ÉPICA"],"01PZ005":["Transmodulador Hextech","Transformo un seguidor en una copia idéntica de otro seguidor.","","''¡DECÍAS QUE QUERÍAS PERDER PESO!''.\n''¿Y ME CONVERTISTE EN UN YORDLE?''.\n''¡PERDISTE PESO!''.\n''¡PERO SOY UN YORDLE!''.","Hechizo",[],["Piltóver y Zaun"],"RARA"],"01PZ021":["Secuaces de Midenstokke","Golpe al Nexo: Invoco una copia exacta de mí.","","''Señor Berz, lo encontramos dormido DENTRO de la caja fuerte, cubierto en oro y aferrado a la puerta rota''.\n''No era yo, había un tipo igualito a mí''.\n''Todavía no suelta la puerta''.\n''Pruébalo''.","Unidad",[],["Piltóver y Zaun"],"RARA"],"01PZ031":["Impacto de Statikk","Inflijo 1 de daño a un enemigo o al nexo enemigo, y 1 de daño a otro más.\nRoba 1.","","''¡Y así es como descubrimos el arco eléctrico! Por supuesto, mi predecesor ya había postulado su hipótesis sobre dicho evento, pero subestimó el alcance del arco. Pobrecito...''. —Heimerdinger","Hechizo",[],["Piltóver y Zaun"],"RARA"],"01PZ059":["Triturabot Dorado","","","MATAR. APLASTAR. DESTRUIR. REPETIR.","Unidad",["TECNOLOGÍA"],["Piltóver y Zaun"],"COMÚN"],"01PZ001":["Chatarra","Descarta hasta 2 para usar esta carta. Roba 1 por cada carta descartada.","","''¡Guuuuau! ¡¿CINCO GUARDIAS Y UN GÓLEM?! ¡Un momento! ¡Tengo justo lo necesario! Déjame veeer...''. —Jinx","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"01PZ057":["Ensamblaje de Chatarra","Invoco 2 Escurridizos de Chatarra.","","Dos gentiles criaturas separadas por un obstáculo infranqueable de terreno por fin se reúnen en las tibias aguas del sumidero.","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"01PZ027":["Rayo Termogénico","Gasta todo tu maná para usarme.\nInflijo esa cantidad de daño a una unidad.","","''Hemos agotado el tiempo y los fondos. A pesar de que el rayo funciona, no hemos logrado regular su consumo de energía''. —Experimentador zaunita","Hechizo",[],["Piltóver y Zaun"],"RARA"],"01PZ055":["Académica Astuta","Cuando robas una carta, recibo +1|+0 en esta ronda.","","La imaginación es la chispa de un gran invento, pero hace falta investigar para que se convierta en una hoguera.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"01PZ014":["Invento Sin Licencia","Invoco 1 Artilugio Ilegal.","","''Sus destrozos son variados: temblores de explosiones lejanas, gases putrefactos de las fisuras. Pronto uno de esos idiotas acabará destrozando la ciudad''. —Filántropo piltoviano","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"01PZ034":["Chatarrero del Sumidero","Alianza: Creo 1 Mapa del Sumidero en la mano. Cuesta 0 en esta ronda.","","Pronto los niños zaunitas comenzaron a explorar los viejos túneles y los niveles más profundos de las Vías. Descubrieron un mundo diferente y lleno de amigos.","Unidad",[],["Piltóver y Zaun"],"RARA"],"01PZ003":["Bot de Ensamblaje","Cuando juegas un hechizo, recibo +1|+1.","","''Cualquier tonto puede construir una máquina; sin embargo, hacer que una mente mecanizada logre una VERDADERA evolución requiere ingenio. Falta poco para que esos malditos burócratas vuelvan arrastrándose...''. —Klas Henwick","Unidad",[],["Piltóver y Zaun"],"RARA"],"01PZ044":["Guitarrista Quimopunk","Al jugar: Inflijo 1 de daño a todos los enemigos.","","''... su solo desemboca en una escala menor armónica, justo antes de arpegiar (sí, esa palabra existe) hacia la transposición del puente. Seguramente jamás entenderás su obra''. —Max Bliff, portero","Unidad",[],["Piltóver y Zaun"],"RARA"],"01PZ029":["Benefactor Eminente","Al jugar: Manifiesto una carta épica de tus regiones.","","''En el pasado fui un hombre violento. Aplastaba a la competencia mientras amasaba mi fortuna. Ahora realizo labores altruistas y confío en que el invierno me absuelva de mis fechorías''.","Unidad",[],["Piltóver y Zaun"],"RARA"],"01PZ051":["Herrisueña","Todos tus hechizos y Habilidades infligen 1 de daño adicional.","","''¿Quieres un extra de explosiones? ¡Viniste al lugar correcto!''.","Unidad",[],["Piltóver y Zaun"],"RARA"],"01PZ023":["Profesor von Yipp","Cuando invocas un aliado con costo de 1, este recibe +2|+2.","","''Hoy tengo el honor de presentar mi nuevo invento ante el comité, como lo demostró mi colega...''.","Unidad",["GATO"],["Piltóver y Zaun"],"RARA"],"01PZ024":["Volticiano Inestable","Obtengo +4|+0 y Ataque Rápido cuando hayas jugado un hechizo de 6+ de costo en esta partida.","","Nombre: Klas Henwick. Edad: 51. Tipo de permiso: Condicional clase 2. Estado: Revocado. Comentarios: Ignoró las advertencias continuas sobre la reducción de explosiones en el laboratorio. (Caso 13X764NM). TIENE PROHIBIDA LA ENTRADA.","Unidad",[],["Piltóver y Zaun"],"RARA"],"01PZ049":["¡Día del Progreso!","Roba 3 y reduce 1 el costo de esas cartas.","","¡DÍA DEL PROGRESO!\n¡Celebra en la PLAZA DE LAS PUERTAS DEL SOL!\n¡Disfruta las MARAVILLAS HEXTECH!\n¡Sorpréndete con el PORO AUDAZ!\n¡Escucha al HOMBRE DEL MAÑANA hablar sobre HOY!\n¡Entrada LIBRE! \n¡Los niños piltovianos son bienvenidos!","Hechizo",[],["Piltóver y Zaun"],"ÉPICA"],"01PZ006":["Guardián de la Plaza","Cuesto 1 menos por cada hechizo que hayas jugado en esta partida.","","Tienes veinte segundos para obedecer.","Unidad",[],["Piltóver y Zaun"],"RARA"],"01PZ053":["Horda de Womps","Cuando me invocan, creo 1 Nube de Hongos en la mano.","","''¡Como lo oyes! ¡Van escondidos en grupo por ahí! PARECE que están locos, pero es porque no entiendes. ¡Tienen grandes planes! Grandes planes. Hongos. Pan con queso... ¿Qué estaba diciendo?''. —Vendedor de Hongos","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"01PZ012":["¡Mascafuegos!","Si me descartas, me invoco.","","''¡A ELLOS, MASCAFUEGUITOS!''. —Jinx","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"01PZ039":["¡Comienza a Emocionarte!","Para usarme, descarta 1.\nInflijo 3 de daño a cualquier objetivo.","","''¡FUEGO EN EL FUEGO!''. —Jinx","Hechizo",[],["Piltóver y Zaun"],"RARA"],"01PZ016":["Chispa de Genio","Creo en la mano un hechizo aleatorio de tus regiones con costo de 6+.\nRestablezco tu maná de hechizos.","","Solo hace falta una epifanía para iniciar un legado.","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"01PZ058":["Womp Rechoncho","Cuando me invocan, creo 2 Nubes de Hongos en la mano.","","''Viste una grande, ¿eh? Es tan pesada como un caballo y tan taimada como un rocoso. No la pierdas de vista, ¿eh? ¡Ese bombón es reina por algo!''. —Vendedor de Hongos","Unidad",["YORDLE"],["Piltóver y Zaun"],"RARA"],"01PZ009":["Aeronauta Amateur","","","''¿Máquinas voladoras personales? ¡Eso es una quimera! De hecho, acabo de pedirle a mi aprendiz que se deshiciera del último prototipo. ¿Dónde se habrá metido?''. —Ingeniero piltoviano","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"01PZ042":["Marinera Intrépida","Al apoyar: Doy Evasión al aliado que apoyo en esta ronda.","","Para muchos piltovianos la ciencia y la invención son la forma de explorar lo desconocido desde la comodidad de su Ciudad del Progreso. Pocos se aventuran más allá del horizonte para descubrir algo mejor: el mundo.","Unidad",[],["Piltóver y Zaun"],"RARA"],"01PZ026":["Mapa del Sumidero","Otorgo Evasión a un aliado.","","''¡Los piltillos creen saberlo todo, pero sus mapas solo señalan los lugares que les indicamos nosotros! No conocen el terreno, pero tú sí... por un módico precio''. —Ajuna Lem, Chatarrero del Sumidero","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"01PZ043":["Carterista Quimopunk","Golpe al Nexo: Creo una copia idéntica de un hechizo aleatorio del mazo enemigo en la mano.","","Creían que los desterrados bajo Ciudad del Progreso se volvían los unos contra los otros. En vez de eso, se unieron y trabajaron juntos para construir un hogar. No era gran cosa, pero era su hogar: Zaun.","Unidad",[],["Piltóver y Zaun"],"RARA"],"01PZ047":["Tonel Cáustico","Último Aliento: Inflijo 1 de daño a AMBOS nexos.","","''Te diría que usaras un traje, pero acabarías sudado como axila de womp. Usa guantes. Y si te cae algo de eso encima, que no sea sobre algo importante''. —Ziel, Capataz zaunita","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"01FR024":["Anivia","Al atacar: Inflijo 1 de daño a todos los enemigos y al nexo enemigo.\nÚltimo Aliento: Revivo como Huenivia.","Si tienes Iluminación.","''Nací en esta tierra severa y es mi deber protegerla. Ni el tiempo, ni la guerra, ni la muerte misma perturbarán mi guardia''.","Unidad",["AVE"],["El Fréljord"],"Campeón"],"01FR039":["Tryndamere","","En vez de morir, subo de nivel.","''No mueras por tu causa. Vive por ella...''.","Unidad",[],["El Fréljord"],"Campeón"],"01FR006":["Legado de los Hijos del Hielo","Otorgo +2|+2 a un aliado y a todas sus copias en todas partes.","","''Como Hijos del Hielo que somos, la magia del Fréljord corre por nuestras venas. Nuestros ancestros sellaron un mal antiguo, y de nosotros depende impedir su regreso''. —Gregor el Guardián","Hechizo",[],["El Fréljord"],"COMÚN"],"01FR022":["Halcón del Augurio","Cuando me invocan, otorgo +1|+1 a los primeros 2 aliados de tu mazo.","","''Nuestros saqueadores se han acercado tres veces a las puertas avarosanas, y tres veces los esperaron con los arcos listos. ¿Qué magia delata nuestros ataques?''. —Steffen Noble Pielmarcada","Unidad",["AVE"],["El Fréljord"],"COMÚN"],"01FR042":["Vientos Adversos","Lanzo Helar a 2 enemigos.","","''¿Me desafías en mi propio territorio? Esta batalla te queda grande''. —Anivia","Hechizo",["ELEMENTAL"],["El Fréljord"],"RARA"],"01FR009":["Braum","La primera vez que sobreviva al daño, invoco 1 Poro Majestuoso.","Si sobreviví a 10+ de daño total.","''¡Papá, cuéntanos la historia de Braum y su puerta!''.\n''Cuando se cayó y partió una montaña en dos''.\n''¡Ah! O aquella en la que salvó la taberna de un furibundo yeti!''.","Unidad",[],["El Fréljord"],"Campeón"],"01FR018":["Lobo Dientescarchado","Al golpear: Mato a cualquier unidad a la que golpee si tiene 0 de poder.","","Los depredadores de los páramos del norte han aprendido que las presas más fáciles son las víctimas del invierno.","Unidad",["PERRO"],["El Fréljord"],"RARA"],"01FR036":["Arquero Avarosano","Al jugar: Inflijo 1 de daño a un enemigo.","","En el Fréljord o cazas o te mueres.","Unidad",[],["El Fréljord"],"COMÚN"],"01FR045":["Steffen Noble Pielmarcada","Cuando sobrevivo al daño, recibo +3|+0.","","''Mi destino se entrelazó con el de la Garra Invernal cuando Sejuani me hizo mi primera cicatriz. Desde entonces, todas las demás las he ganado a su servicio''.","Unidad",[],["El Fréljord"],"COMÚN"],"01FR008":["Poro Solitario","Cuando me invocan, creo otro poro aleatorio con costo de 1.","","''Toda una vida en el Fréljord y nada enfría tanto el corazón como observar a este triste pequeñín''. —Pastor de Poros","Unidad",["PORO"],["El Fréljord"],"COMÚN"],"01FR055":["Fragmentación","Inflijo 4 de daño a un enemigo si tiene 0 de poder. Si no, lanzo Helar sobre él.","","''Cuando la Matriarca Invierno cabalga, el fuerte se ablanda y el débil perece''. —Steffen Noble Pielmarcada","Hechizo",["ELEMENTAL"],["El Fréljord"],"COMÚN"],"01FR038":["Ashe","Al atacar: Lanzo Helar al enemigo Más fuerte.","Si redujiste el Poder de 5+ enemigos a 0. Cuando subo de nivel, creo 1 Flecha de Cristal arriba de tu mazo.","''Cuando veo más allá de mi hogar, veo lo que hay, pero también lo que podría llegar a ser. Prosperidad y plenitud no solo para mi pueblo, sino para todos aquellos que buscan la paz. El Fréljord unido por fin''.","Unidad",[],["El Fréljord"],"Campeón"],"01FR029":["Ruego","Roba 1 campeón.","","''¡Vienen los saqueadores! Suenen la alarma y enciendan los fuegos, necesitamos toda la ayuda posible''. —Vigía Avarosano","Hechizo",[],["El Fréljord"],"RARA"],"01FR035":["Saqueadora sin Cicatrices","Cuando sobrevivo al daño, recibo +3|+0.","","''Los avarosanos crían a sus hijos para que crezcan débiles, sin preparación para el fragor de la batalla. Los nuestros nacen en las llamas de la guerra misma''. — Vrynna Madre Pielmarcada\n","Unidad",[],["El Fréljord"],"COMÚN"],"01FR020":["Avalancha","Inflijo 2 de daño a TODAS las unidades.","","El alma de toda avalancha es una piedrita que no quiso quedarse quieta.","Hechizo",["ELEMENTAL"],["El Fréljord"],"RARA"],"01FR014":["Cría de Yeti","Último Aliento: Creo 2 Yetis Enfurecidos en tu mazo.","","''¡Era muy pequeño y pacífico! No puedo creer que se haya convertido en todo un... bueno... en un yeti''. —Trampero Avarosano","Unidad",["YETI"],["El Fréljord"],"COMÚN"],"01FR049":["Lobo Acechador","Cuando me invocan, tu oponente invoca 1 Liebre Nevada.","","''Una liebre jamás aprenderá a ser lobo''.\n—Proverbio de la Garra Invernal","Unidad",["PERRO"],["El Fréljord"],"COMÚN"],"01FR037":["Escoltas Avarosanos","Alianza: Otorgo +3|+3 y Arrollar al aliado arriba de tu mazo.","","A medida que los refuerzos llegaban a la cumbre, los escoltas se inclinaban ante la matriarca guerrera. Ella, la reencarnación de Avarosa, su reina Ashe, había traído la promesa de la paz.","Unidad",[],["El Fréljord"],"RARA"],"01FR026":["Garraferoz Alfa","","","El poder de un caballo de guerra, la brutalidad inconsciente de un gato.","Unidad",["GATO"],["El Fréljord"],"COMÚN"],"01FR030":["Acero Quebradizo","Lanzo Helar a un enemigo con 3 o menos de vida.","","''¿Con frío? ¡Ja! ¡Esperemos que sean más resistentes que su acero estival!''. —Braum","Hechizo",["ELEMENTAL"],["El Fréljord"],"COMÚN"],"01FR013":["Vrynna Madre Pielmarcada","Cuando sobrevivo al daño, recibo +3|+0.","","''Prefiero morir congelada hasta los huesos que compartir mi hogar con los debiluchos de Ashe. Si es calor lo que buscan, eso les daré''.","Unidad",[],["El Fréljord"],"ÉPICA"],"01FR019":["Aliento del Invierno","Mato a todos los enemigos con 0 de poder, luego lanzo Helar a todos los enemigos.","","El invierno es la primera y la última matriarca guerrera a la que se enfrenta todo aquel que invade el Fréljord. Sus jurasangre son el viento y el frío implacables.","Hechizo",["ELEMENTAL"],["El Fréljord"],"ÉPICA"],"01FR041":["Guardapatrias Avarosano ","Cuando me invocan, otorgo +1|+1 a los aliados de tu mazo.","","''¡Muchas tribus, un solo estandarte! Quizá un día todo el Fréljord luche hombro a hombro''.","Unidad",[],["El Fréljord"],"ÉPICA"],"01FR025":["Pastor de Poros","Cuando me invocan, roba un poro si Contemplas un poro.","","Un rebaño solo necesita dos cosas: amor y compañía. Lo demás es extra.\n","Unidad",[],["El Fréljord"],"RARA"],"01FR054":["Saqueadora Pielmarcada","","","''Los fuertes cosechan lo que los débiles siembran. ¡Que aprendan esos avarosanos cuál es su sitio!''.","Unidad",[],["El Fréljord"],"RARA"],"01FR021":["Tarkaz, el Sinclán","Al atacar: Inflijo 1 de daño a TODAS las unidades en combate.","","''Tarkaz luchó más y mejor que el resto. Asumió su derrota humildemente. Bueno, más o menos...''. —Tryndamere","Unidad",[],["El Fréljord"],"ÉPICA"],"01FR043":["Corazón de la Nube","Al jugar: Transformo a tus seguidores Poros en 1 Nube de Poros y le otorgo sus estadísticas y palabras clave positivas.","","''Bueno, una historia más, pero guarden silencio, ¡que va a venir mamá!''\n''Hace tiempo, los saqueadores atacaron el pueblo de Avarosa. Sus defensas no eran suficientes y la batalla parecía perdida. Entonces apareció un poro que les ofreció ayuda...''.","Unidad",["PORO"],["El Fréljord"],"RARA"],"01FR033":["Piedras Wírdicas","Inicio de la ronda: Doy una gema de maná adicional en esta ronda.","","''Estas ruinas antiguas nos recuerdan que somos los últimos de una larga lista de tribus que han desafiado estas tierras salvajes''. —Ashe","Unidad",[],["El Fréljord"],"COMÚN"],"01FR011":["Arquero de Vallefrío","Al jugar: Lanzo Helar a un enemigo.","","Los avarosanos se enorgullecen de su clima agreste y de sus tierras gélidas, pero sus defensores perspicaces les llevan un paso adelante. ","Unidad",[],["El Fréljord"],"COMÚN"],"01FR050":["Tabernero Gentil","Al jugar: Curo 3 a un aliado o a tu nexo.","","''¡En el Búho Achispado todos son bienvenidos! Tenemos guisos y brebajes de todo tipo para combatir el frío. ¡Adelante!''.","Unidad",[],["El Fréljord"],"COMÚN"],"01FR052":["Ella la Errante","Al jugar: Lanzo Aniquilar a TODAS las unidades con 4 o menos de poder en juego y en las manos.","","''Me levanté de entre los escombros para toparme con una marca en el terreno a mi alrededor. Donde antes estaban mis compañeros, ahora solo había cenizas y una figura distante avanzaba en el horizonte...''. —Bjerg Trotamundos","Unidad",[],["El Fréljord"],"ÉPICA"],"01FR016":["Porogalletas","Otorgo +1|+1 a los Poros aliados en todas partes.","","''Se las comen, luego sacan la lengua y te observan, felices como elnuks. ¡Y hasta te piden más! No te atrevas a decirles que no''. —Negociadora avarosana","Hechizo",[],["El Fréljord"],"COMÚN"],"01FR005":["Furia de Batalla","Otorgo +8|+4 a un aliado.","","''Me dijeron que tengo mal carácter''. —Tryndamere","Hechizo",[],["El Fréljord"],"RARA"],"01FR023":["Llamado de la Matriarca","Invoco al aliado de arriba de tu mazo en este y en CADA inicio de la ronda.","","Un día se escuchará un llamado inconfundible por todo el Fréljord. Ese día todos saldrán a responderlo, pues este anuncia que nuestros antiguos enemigos han regresado una vez más.","Hechizo",[],["El Fréljord"],"ÉPICA"],"01FR047":["Místico Feral","Con Iluminación: Obtengo +4|+4.","","''Aquellos que aprenden a rugir como las bestias pronto olvidan su lengua materna''. —Anivia","Unidad",[],["El Fréljord"],"COMÚN"],"01FR056":["Yeti de Hielo","Cuando me invocan, lanzo Helar a los enemigos con 3 o menos de vida.","","''¡Aaaaaaaaaaaaaaaah!''. —Bjerg Trotamundos","Unidad",["YETI"],["El Fréljord"],"RARA"],"01FR027":["Elnuk Toro","","","Los cuentos avarosanos hablan del gruñón y terco ''Viejo Tío Elnuk''. Todo lo que quería era un pedazo tibio de hierba y algún conflicto donde meter las narices. ","Unidad",["ELNUK"],["El Fréljord"],"COMÚN"],"01FR057":["Mentalidad de Manada","Doy +2|+2 y Arrollar a los aliados en esta ronda.","","A un aullido solitario en la noche se le sumó otro y otro más. De pronto, toda la manada aulló al unísono; un conjunto de voces desbocadas que clamaban por sangre.","Hechizo",[],["El Fréljord"],"RARA"],"01FR004":["Elixir de Hierro","Doy +0|+2 a un aliado en esta ronda.","","''Difícil situación, ¿no? No te preocupes, el Búho sirve un brebaje especial tan potente que quita la escarcha de los huesos y hace que los bebés tengan pelo en pecho''. —Tabernero Gentil","Hechizo",[],["El Fréljord"],"COMÚN"],"01FR048":["Trampero Avarosano","Cuando me invocan, creo 1 Yeti Enfurecido en las primeras 3 cartas de tu mazo.","","''¡No he cazado nada en toda la semana! O esas bestias me ven venir o algo las está asustando...''.","Unidad",[],["El Fréljord"],"COMÚN"],"01FR017":["Tropa de Elnuks","Al jugar: Invoco a todos los elnuks de las 6 cartas de arriba de tu mazo y coloco el resto en tu mazo.","","''Los avarosanos son como elnuks: su mirada es sosa, les gusta el pasto y son víctimas fáciles de los sin marca. Su número es lo que los mantiene con vida''. — Vrynna Madre Pielmarcada","Unidad",["ELNUK"],["El Fréljord"],"COMÚN"],"01FR046":["Sé Valiente","Otorgo +3|+3 a un aliado herido.","","''A pesar de estar gravemente herido, Braum dejó escapar una carcajada. ¡Sabía que los héroes se forjan en los peores momentos!''.\n—La Leyenda de Braum","Hechizo",[],["El Fréljord"],"RARA"],"01FR012":["Catalizador de Eones","Doy una gema de maná vacía y curo 3 a tu nexo.","","Ni el rubí ni el zafiro superan el brillo de una piedra de eones, una gema brillante con propiedades de restauración legendarias.","Hechizo",[],["El Fréljord"],"COMÚN"],"01FR040":["Chamana Colmillo Escarchado","Inicio de la ronda: Lanzo Helar al enemigo Más fuerte.","","''Para fundirnos con lo salvaje debemos aprender a no refugiarnos del frío, y a deleitarnos con su brutalidad''.","Unidad",[],["El Fréljord"],"RARA"],"01FR031":["Yeti Ancestral","Fin de la ronda: Mi costo se reduce en 1.","","''¿Qué fue eso? Sonó como un estornudo. ¿Acaso los glaciares... estornudan?''. —Bjerg Trotamundos\n","Unidad",["YETI"],["El Fréljord"],"RARA"],"01FR053":["Poro Majestuoso","","","''El viejo Longhorn perdió un ojo defendiendo al mismísimo Rey Poro del ataque de un garraferoz. Después de todo, lo que importa no es el tamaño del arma, sino el del corazón''. —Pastor de Poros\n","Unidad",["PORO"],["El Fréljord"],"COMÚN"],"01FR010":["Juramento de Sangre","Otorgo +0|+3 a 2 aliados.","","''Seré una antorcha en tu corazón; un escudo protector. Permíteme encontrar la fuerza para protegernos y a nuestra gente. Que nuestras vidas fluyan como la sangre que sella este pacto''. —Tryndamere","Hechizo",[],["El Fréljord"],"RARA"],"01FR001":["Helada Centelleante","Lanzo Helar a un enemigo.","","El frío golpea sin avisar y hasta el más fiero guerrero es indefenso ante él.","Hechizo",["ELEMENTAL"],["El Fréljord"],"RARA"],"01FR032":["Vidente Astral","Cuando juegas un hechizo, otorgo +1|+1 al primer aliado de tu mazo.","","''Que tengan oídos agudos para escuchar la llegada del viento, pies ligeros para cruzar la nieve y una vista aguda para ver más allá del velo del invierno''.","Unidad",[],["El Fréljord"],"RARA"],"01FR051":["Cuentos Increíbles","Si tienes un yeti, invoco 1 Yeti Enfurecido. Si no, lo creo arriba de tu mazo.","","''Este tenía unas fauces repletas de dientes como cuchillos, puños enormes y ojos que daban miedo. Cuando rugía, ¡hacía temblar hasta los árboles! Me lo dijo el tío Bjerg''. —Ingvar la Joven","Hechizo",[],["El Fréljord"],"COMÚN"],"01FR034":["Ellos los Eternos","Cuando me invocan, obtengo +1|+1 por cada aliado que haya muerto.","","''Ah, el viejo Bjerg la ha pasado mal. Perdió a sus compañeros en el norte y regresó meses después pálido y balbuceando. Ahora, todo es 'bestias gigantes' por aquí y 'garras inmensas' por allá. Pobre...''. —Tabernero Gentil","Unidad",[],["El Fréljord"],"RARA"],"01FR007":["Bjerg Balbuceante","Cuando me invocan, roba una unidad con 5+ de poder.","","''¡D... debes creerme! ¡Te digo que era ENORMEEE!''.","Unidad",[],["El Fréljord"],"COMÚN"],"01FR003":["Vigía Avarosano","Último Aliento: Roba 1.","","''Una vez busqué mi lugar en lejanos campos de batalla; pero lo encontré al lado de mi gente, en mi hogar. Mis ojos son sus ojos y su seguridad está en mis manos''.","Unidad",[],["El Fréljord"],"COMÚN"],"01SI038":["Espectro Bromista","Cuando otro aliado muere, inflijo 1 de daño al nexo enemigo.","","Lo más cruel no fue masacrar a los soldados que confiaron en los llantos de una pequeña, sino sembrar la duda entre aquellos que lograron volver a casa e ignoraron las súplicas de sus hijas.","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI049":["Visión del Más Allá","Mato a un aliado para robar 2.","","''Me equivoqué. No estamos hechos para mirar más allá del velo. La verdad que ahí yace llega a un costo demasiado alto''. —Arie Wrence, Vindicador de la Vanguardia","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI053":["Elise","Al atacar: Invoco 1 Arañita atacante.","Si al inicio de la ronda tienes otras 3+ arañas.","Los oscuros lazos que atan a Elise, alguna vez cabeza de una poderosa casa de Noxus, a las Islas de la Sombra le dieron juventud y belleza sobrenatural a cambio de algunas almas desafortunadas. Fácil decisión.","Unidad",["ARAÑA"],["Islas de la Sombra"],"Campeón"],"01SI057":["Crocolito Ancestral","Para usarme, mata a 2 aliados.","","''Pónganlos en la jaula, ba-da-pum... \nArranquen cada alma una por una...\n¡Jamás los dejen escapar! ¡No, señor!\nO los espíritus harán un alboroto...''.","Unidad",["REPTIL"],["Islas de la Sombra"],"RARA"],"01SI023":["Pastora de Almas","Cuando invocas un aliado con Endeble, le otorgo +1|+1.","","Solo los caídos sabían que no iba sola. Solo ellos veían a las incontables almas que llevaba a las tierras del más allá.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI010":["Avalancha de Sombras","Invoco 2 Jinetes Espectrales.","","Viven ahora igual que como murieron: leales hasta el final.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI042":["Hecarim","Al atacar: Invoco 2 Jinetes Espectrales atacantes.","Si atacaste con 7+ aliados con Endeble.","Eso no es un trueno. La sombra de la guerra está en el horizonte.","Unidad",[],["Islas de la Sombra"],"Campeón"],"01SI027":["Ofrendas Frescas","Si 3+ aliados murieron en esta ronda, invoco 1 Vilemaw.","","''Póstrate ante tu dios con colmillos. O mejor aún: muere por él''. —Elise","Hechizo",[],["Islas de la Sombra"],"RARA"],"01SI048":["Guardián Maldito","Último Aliento: Invoco 1 Abominación Fugitiva.","","Locura y tiempo. Nunca existió peor combinación.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI018":["Escriba de Penas","Cuando me invocan, creo en la mano la copia de un aliado que haya muerto en esta partida.","","''Pero lo que nuestro autor ignoraba era que la Rui... la Ruin... ¡No puede ser! ¡La tinta se derramó de nuevo! Lo que nuestro autor... ¡No, no y no!''.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI030":["Kalista","","Si he visto morir a 3+ aliados.","En vida fue general, protectora y heroína. Su carne se pudría, pero su sed de venganza ardía con fuerza. Se convirtió en un espíritu inmortal de venganza.","Unidad",[],["Islas de la Sombra"],"Campeón"],"01SI035":["Rhasa, el Desgarrador","Al jugar: Mato a los 2 enemigos Más débiles si un aliado murió en esta ronda.","","''Dijeron que sería... 'una aventura de leyenda'. Dijeron que protegeríamos... el futuro de Demacia. Zarpamos con esperanza, pero... todas esas vidas... ¿Y para qué?''. —Arie Wrence, soldado demaciano","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"01SI005":["Acorazado Fantasmal","Cuesto 1 menos por cada aliado que haya muerto en esta partida.","","Este monstruo, antes bestia de carga de un reino olvidado, ahora hurga entre los restos de antiguos campos de batalla. De sobras cubre su caparazón y de almas su corazón.","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI037":["Poro Siniestro","","","Es decir, hay peores formas de morir.","Unidad",["PORO"],["Islas de la Sombra"],"COMÚN"],"01SI052":["Thresh","","Si he visto 6+ unidades morir.","''Uno, dos... resuenan las cadenas. Tres, cuatro... Se acercan hacia ti.\nCinco, seis, es el carcelero... Está detrás de ti...''.","Unidad",[],["Islas de la Sombra"],"Campeón"],"01SI033":["Comandante Ledros","Al jugar: Reduzco a la mitad la vida del nexo enemigo, redondeado.\nÚltimo Aliento: Regreso a la mano.","","El tiempo carcome los recuerdos de la mayoría de espíritus. En el caso de Ledros, el sufrimiento lo ancló a su pasado. Hay cosas que ni el tiempo puede absolver.","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"01SI003":["El Harrowing","Revivo a los 6 aliados Más fuertes que hayan muerto en esta partida y les otorgo Endeble.","","Algunas noches, una gran cantidad de espíritus hambrientos infestan la Niebla Negra. Vagan por los mares buscando vivos y alimentan la creciente oscuridad con más muerte.","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"01SI041":["El Perpetuo","Último Aliento: Revivo en el siguiente inicio de ronda y recibo +1|+1 por cada vez que haya muerto.","","El viejo mártir recordó cómo llevó a sus camaradas hacia su perdición; pero hace años que no recuerda por qué...","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"01SI045":["Absorbealmas","Lanzo Drenar y absorbo 4 de daño de un aliado.","","''Lo que te mata me hace más fuerte''. —Thresh","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI036":["Sensación Aracnofóbica","Si un aliado murió en esta ronda, invoco 2 Arañitas.","","Esa sensación que trepa por tu piel no es tan preocupante como la que sientes debajo de ella.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI051":["Prodigio Torturado","Cuando otro aliado muere o se activa Último Aliento: Recargo tu maná de hechizos.","","Se dedicó día y noche a perfeccionar su composición. Entonces, en un parpadeo, un oscuro silencio caló sus huesos. Otros gritaron y corrieron por sus vidas, él no vio nada.","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI012":["Isleño Despistado","Al jugar: Otorgo Endeble a un aliado en la mano y reduzco 1 su costo.","","Ah, pobre muchacho...","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI031":["Heraldo de Hierro","Al atacar: Recibo +1|+0 por cada aliado con Endeble que tengas.","","En la muerte y en la vida, su rugido porta el retorcido y oscuro mandato; en la muerte y en la vida, los caballeros de Hecarim obedecerán al llamado a la batalla.","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI034":["Lanza Negra","Si un aliado murió en esta ronda, inflijo 4 de daño a una unidad.","","''Nuestra lanza canta por los caídos''. —Kalista","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI043":["Aristócrata Desafortunado","Último Aliento: Invoco 1 Arañita.","","''¿Lady Elise? ¿A dónde... a dónde fue?''.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI009":["Espíritus Agitados","Al apoyar: Otorgo +2|+0 y Endeble al aliado que apoyo.","","Algunos miran la Ruina y solo ven destrucción y miseria. Otros ven el vaso medio lleno.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI007":["Reliquia Embrujada","Invoco 3 Espíritus Liberados.","","Tanto los vivos, que buscan llevárselos, como los muertos, que quieren conservarlos, desean estos artefactos antiguos.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI056":["Tejedora Frenética","Cuando me invocan, doy +1|+0 a los otros aliados Araña y -1|-0 a los enemigos en esta ronda.","","''Pueden tejer una telaraña del tamaño de un hombre en menos de un minuto... ¿quieres ver una demostración?''. —Elise","Unidad",["ARAÑA"],["Islas de la Sombra"],"RARA"],"01SI001":["Venganza","Mato a una unidad.","","Con su último aliento, los traicionados invocan a Kalista y esperan que su lanza les conceda la venganza.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI019":["La Caja","Inflijo 3 de daño a cada enemigo invocado esta ronda.","","''Nadie escapa''. —Thresh","Hechizo",[],["Islas de la Sombra"],"RARA"],"01SI011":["Carnicero Voraz","Para usarme, mata a un aliado.","","Eres lo que comes.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI014":["Espectro de la Niebla","Cuando me invocan, otorgo +1|+0 a otros Espectros de la Niebla aliados","","Estos espectros de las islas perdieron su identidad hace tiempo y se convirtieron en amalgamas del apetito más insaciable.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI022":["Marca de las Islas","Otorgo +2|+2 y Endeble a un aliado.","","Poder, sí, pero ¿a qué precio?","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI006":["Posesión","Roba un seguidor enemigo en esta ronda. (No puedes usarlo si ya tienes 6 aliados o hitos).","","Despertó con las manos rojas y el campamento estaba inusualmente tranquilo. ","Hechizo",[],["Islas de la Sombra"],"RARA"],"01SI028":["Alma Dividida","Invoco una copia exacta de un aliado. La copia tiene Endeble y 1|1.","","''Levanté el cuerpo del agua para identificar al pobre infeliz. Mientras posaba mi mano sobre su hombro giró y mostró su rostro. ¿Acaso era... yo?''. —Arie Wrence, soldado demaciano","Hechizo",[],["Islas de la Sombra"],"RARA"],"01SI025":["Atrocidad","Mato a un aliado para infligir daño equivalente a su poder a cualquier objetivo.","","Matar no significa nada para aquellos que no pueden morir.","Hechizo",[],["Islas de la Sombra"],"RARA"],"01SI046":["Llamado de la Niebla","Revivo a un aliado aleatorio que haya muerto en esta ronda.","","''La niebla separa el espíritu del cuerpo y deja atrás un mero reflejo de vida. La vi corromper mis tierras y ahora iré a esas islas malditas a acabar con esto''. —Arie Wrence, Vindicador de la Vanguardia.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI050":["Despertar del Nido","Invoco 3 Arañitas, luego otorgo +1|+0 a las arañas aliadas.","","Cuando nacen es cuando más hambrientas están.","Hechizo",[],["Islas de la Sombra"],"RARA"],"01SI016":["Llamaespectros","Alianza: Invoco 1 Espectro de la Niebla.","","Se aparece en completo silencio. Los horrores que vienen después son menos discretos.","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI021":["Carro de Tiburones","Último Aliento: La próxima vez que un aliado con Endeble ataque, revivo como atacante.","","''¿Que vio qué cosa? Ya veo. La locura es una cruel compañera, boticario. Al menos los otros tenían más sentido''. —Cirujano demaciano","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI032":["Cronista de la Ruina","Al jugar: Mato a un aliado y después lo revivo.","","En un tiempo se sentaba con su padre, un señor curador, mientras este repasaba sus libros polvorientos. Anhelaba que su hija tomara el mando; pero no de esta forma.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI058":["Remitente Etéreo","Al jugar: Mato a un aliado para invocar a un seguidor aleatorio que cueste 2 más.","","¡Espíritus, unan sus voces a la mía y juntos desataremos una oscuridad eterna!","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI054":["Agarre del Perpetuo","Dreno 3 de una unidad.","","El deseo de los muertos es silenciar los frenéticos latidos del corazón de los vivos.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI044":["Matrona Espectral","Al jugar: Elige un aliado en la mano e invoca una copia exacta con Endeble.","","La Ruina corrompió todo a su paso. Los bondadosos se volvieron crueles, los valientes sádicos y la razón dio pie al resentimiento.","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"01SI039":["Horror Aracnoide","","","Algunos espíritus malignos se inspiran en la fauna local y transforman criaturas conocidas en pesadillas.","Unidad",["ARAÑA"],["Islas de la Sombra"],"COMÚN"],"01SI020":["El Prendevelas","Cuando me invocan, revivo al campeón aliado Más fuerte.","","¿De qué sirve una vela casi extinta si no para iluminar a su sucesora?","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI029":["Lamento Devastador","Inflijo 1 de daño a todos los enemigos y curo 3 a tu nexo.","","Lo que nos mata, los hace más fuerte.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI004":["Azote de Aguasombrías","","","Algunos intentaron huir de la Ruina nadando bajo las olas, pues creían que la corrupción no se adentraría a las profundidades. Se equivocaron.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI026":["Presa del Carcelero","Último Aliento: Creo en la mano otro seguidor aleatorio con Último Aliento con costo de 3 o menos.","","Contuvo el aliento tanto como pudo y rezó por que el guardia siguiera su camino. No lo sabía, pero esta búsqueda sería el comienzo de los deliciosos tormentos de Thresh.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI040":["Festín Atroz","Lanzo Drenar y absorbo 1 de daño de una unidad para invocar 1 Arañita.","","''Mi... mi señora. No conocía su pasión por... ¡las arañas! ¿Sería tan amable de decirles que se alejen de mí? ¿Lady Elise? ¿Sí?''. —Lord Sassen, Aristócrata Desafortunado","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI015":["La Ruina","Mato a TODAS las unidades.","","Y pensar que algo tan puro como el amor puede causar algo tan cruel e ineludible. ","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"01SI055":["Engullealmas","","","''Mientras nuestras naves se acercan a esas tierras condenadas, me pregunto: ¿estos engendros infernales provienen de esta costa? ¿Estuvieron vivos alguna vez?''. —Arie Wrence, soldado demaciano","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI047":["Recuerdos Borrosos","Elige un seguidor. Creo una copia suya con Endeble en la mano.","","Por un momento ella recordó. La luz danzaba sobre su piel, las zarzamoras reventaban entre sus dientes y la frágil melodía en la brisa se desplazaba sobre su cabeza. Entonces... el recuerdo se desvaneció.","Hechizo",[],["Islas de la Sombra"],"RARA"],"02PZ001":["Submiaurino","Cuando me invocan, roba 1.\nDespués, si jugaste al menos otras 10 cartas nuevas en esta partida, recibo +4|+0.","","Nada podía detener su escape de esos humanos de pacotilla. Ni siquiera un poquito de agua...","Unidad",["GATO"],["Piltóver y Zaun"],"ÉPICA"],"02PZ010":["Investigador Veterano","Cuando me invocan, TODOS los jugadores roban 1.","","Algunos oficiales confían en su instinto para resolver un caso. Otros aprovechan sus contactos. Pero la fortaleza del oficial J. S. Harknor reside en la diligencia y el papeleo. Mucho papeleo.","Unidad",["YORDLE"],["Piltóver y Zaun"],"COMÚN"],"02PZ006":["¡Te tengo!","Cuando me robas, cuesto 2 menos en esta ronda.\nInflijo 3 de daño a una unidad.","","''¿Se puede probar estas esposas, Sr. Berz?''\n''¿Y yo qué gano?''\n''Se las puede quedar''.\n''Está bien''.\n''Está bajo arresto. ¡Llévenselo!''","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"02PZ004":["Rompebóvedas","Doy +2|+0 a un aliado en esta ronda.\nCreo 1 Rompebóvedas con Fugaz en la mano.","","''Mis manos hablan por mí''. —Vi","Hechizo",[],["Piltóver y Zaun"],"RARA"],"02PZ007":["Investigadora Perspicaz","Cuando juegas una carta de 2 de costo, roba 1 carta y le otorgo Fugaz.","","''Todos los detectives solucionan, pero los buenos detectives anticipan. Y un detective de primera, previene''. —La guía de los Protectores","Unidad",[],["Piltóver y Zaun"],"RARA"],"02PZ002":["Jefa Mecánica Zevi","Cuando robas una carta, le otorgo Fugaz y creo una copia idéntica de ella en tu mano.","","A los cinco años fabricó el primer cuchillo sónico multifrecuencia. Aunque no era muy práctico (casi siempre lo usaba para cortar sándwiches), le abrió las puertas del Departamento de Armamentos de élite de los Protectores.","Unidad",[],["Piltóver y Zaun"],"ÉPICA"],"02PZ008":["Vi","Cuando estoy en juego o en tu mano, recibo +1|+0 si usas otra carta (máx. +8|+0).","Si Golpeé e infligí 10+ de daño de un golpe.","''¡Guardia Vi, por favor! ¡Piense en la gente! ¡En el daño colateral! ¡En EL PAPELEO PARA QUEJAS POR LESIONES!''. —Investigadora Perspicaz","Unidad",[],["Piltóver y Zaun"],"Campeón"],"02PZ009":["Rastro de Evidencia","Creo en la mano una carta aleatoria de costo 2 de una de tus regiones. Cuesta 2 menos en esta ronda.","","''Y así —anunció el oficial Harknor— la pista nos llevó a...''.","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"02PZ003":["¡Brazo Listo!","Cuando me robas, cuesto 2 menos en esta ronda.\nAumento a un aliado a 4|4.","","''¡Hay problemas en los muelles! Toma esto y mándales saludos''. —Jefa Mecánica Zevi","Hechizo",[],["Piltóver y Zaun"],"RARA"],"02PZ005":["Guardias Patrulleros","Cuando me robas, cuesto 1 menos en esta ronda.","","La técnica de carrera de la guardia Mir era una broma frecuente entre los demás guardias. El guardia Kepple no entendía.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"02BW040":["Artillería Caparazón","","","''MI FORTALESA MAS GRANDE PROVAVLEMENTE SEA MI PODER SOBRE LA JENTE COMUN. Y AL PARECER MI HORTOGRAFIA TAMVIEN ES MUY BUNA''. —Nota escrita en la arena","Unidad",[],["Aguasturbias"],"COMÚN"],"02BW057":["Montaolas Resbaloso","","","''Le juro que he visto cosas muy extrañas sobre los arrecifes, capitán. ¿Qué les puso ese tonto a las naranjas? Eso es lo que quisiera saber...''. —Suboficial","Unidad",[],["Aguasturbias"],"COMÚN"],"02BW041":["La Bestia Oculta","","","''No le temas a la bestia que ya conoces,\nAlgunos a su ira sobreviven,\n¿Pero qué hay de aquellos que no lo lograron?\n¿Aquellos que en las profundidades terminaron?''. —Grabado en la viga de una taberna de Aguasturbias","Unidad",["MONSTRUO MARINO"],["Aguasturbias"],"COMÚN"],"02BW013":["Cortagargantas Furtiva","","","''... y el idiota dijo que tenía 'caderas que giraban con el viento'. Le dije que dejara de lamer botas o le cortaría la lengua''.","Unidad",[],["Aguasturbias"],"COMÚN"],"02BW034":["Ídolo Mono","Inicio de la ronda: Me inflijo 2 de daño e invoco 1 Mono Explosivo.","","''Esto es un... recuerdito. La tripulación lo robó de uno de mis viejos rivales, un demente. Resultó que los delirios del idiota acerca de 'antiguos poderes místicos' no estaban muy lejos de la verdad''. —Miss Fortune","Unidad",[],["Aguasturbias"],"RARA"],"02BW056":["Devorador de las Profundidades","Al jugar: Lanzo Aniquilar a un enemigo con menos vida que yo.","","''El otro día andaba navegando,\nen la Bahía de Aguasturbias navegando,\nY de la nada apareció en su navío,\nLa Dama Alada Bien Enterrada, en su navío...''. —''Balada de la Dama Alada Bien Enterrada''","Unidad",["MONSTRUO MARINO"],["Aguasturbias"],"ÉPICA"],"02BW060":["Corsaria Tirofino","Cuando los aliados atacan, inflijo 1 de daño al nexo enemigo.","","''Ser de baja estatura es sorpresivamente útil en las peleas. Resulta que a nadie se le ocurre mirar hacia abajo''.","Unidad",["YORDLE"],["Aguasturbias"],"COMÚN"],"02BW011":["Yordle Estafador","Alianza: Hurta 1 y creo 1 Disparo de Advertencia en tu mano.","","''Los amigos ayudan a sus amigos. ¿Pero y tú? ¡Me gusta el brillo de tus ojos y el destello de tu sable! Qué lindo sable en verdad''.","Unidad",["YORDLE"],["Aguasturbias"],"RARA"],"02BW030":["Coleccionista de Naufragios","Cuando me invocan, lanzo Desechar a 2 y creo 2 Tesoros en tu mazo.","","''Me parece que en estos días hay más tesoros bajo las olas que en la superficie. Sería muy fácil robarlo si no fuera por ella''. —Carnicero Cercenador","Unidad",["MONSTRUO MARINO"],["Aguasturbias"],"ÉPICA"],"02BW019":["Burbujoso","","","Corrientes vívidas de magia serpentean entre los arrecifes de las Islas de las Serpientes, alimentando así a los habitantes extraordinarios del mar.","Unidad",[],["Aguasturbias"],"COMÚN"],"02BW007":["Apostadora Impulsiva","Para usarme, descarta 2.\nAl atacar: Roba 2 cartas y les otorgo Fugaz.","","''La mayoría de las veces no es la gran cosa. Las mesas están repletas de tontos cantando y no enfocándose en el juego. No es que a mí me importe. Dinero es dinero y mejor en mi bolsillo que en el de ellos''.","Unidad",[],["Aguasturbias"],"RARA"],"02BW014":["Criaturas Coralinas","Cuando me invocan, creo en la mano un hechizo aleatorio de una de tus regiones con costo 1.","","La mayoría de las aguas poco profundas están repletas de vida marina, pero nada se compara con los arrecifes del Paso de Azur. El paso es un lugar mágico, de otro mundo, lleno de maravillas.","Unidad",[],["Aguasturbias"],"RARA"],"02BW055":["Capataz Cercenadora","Pillaje: Otorgo +1|+0 a los aliados de costo 1 en todas partes.","","Una vez que dispara, los Ganchos deben moverse con rapidez. La sangre en el agua atrae a todo tipo de compañía... y ninguna es bienvenida.","Unidad",[],["Aguasturbias"],"ÉPICA"],"02BW017":["Repartidor de Cítricos","Pillaje: Curo 3 a los aliados y al nexo. Luego, lanzo Preparar.","","''¡Todos los marineros se creen muy rudos! Grr esto, grr lo otro. Sí, sí. Qué bueno. ¡Pero aun así necesitan naranjas! Suavizan la piel, hacen que no se caigan los dientes y me hacen feliz. Te la comes o te la embarras. Fácil''.","Unidad",[],["Aguasturbias"],"RARA"],"02BW038":["Manta Rayita","Cuando me invocan, roba un hechizo de tu mazo que cueste 3 o menos.","","Una vez, Manta Rayita completó el circuito del Paso de Azur en menos de tres minutos. ¡Hasta tuvo que evadir el casco roto del Jilldaw al final! Ese día la corriente fue PERFECTA.","Unidad",[],["Aguasturbias"],"ÉPICA"],"02BW021":["Cazador Escamafilada","Al jugar: Otorgo Vulnerable a un enemigo.","","''He escuchado que nada kilómetros para encontrar a su presa y, cuando la encuentra, nunca falla el tiro. No sé si es un hombre o un pez, pero queda claro que conoce estas aguas mejor que nosotros''. —Carnicero Cercenador","Unidad",[],["Aguasturbias"],"RARA"],"02BW035":["Sheriff Lariette Rose","Cuando me invocan, otorgo Vulnerable a todos los enemigos.","","Puede que no haya ley en Aguasturbias, pero un grupo de almas valientes dentro de los confines de la ciudad no tiene problemas en hacer valer su propia idea de justicia.","Unidad",[],["Aguasturbias"],"ÉPICA"],"02BW058":["Carnicero Cercenador","Pillaje: Recibo +1|+1.","","Volverse parte de los Ganchos Cercenadores es un asunto muy sangriento. Los marineros deben demostrar sus habilidades en un barco, en una pelea y frente al bloque de carnicería. Los candidatos más desagradables logran las tres de una sola vez.","Unidad",[],["Aguasturbias"],"COMÚN"],"02BW028":["Revoltoso Rex","Pillaje: Juego Descarga de Cañones 7 veces sobre enemigos seleccionados de forma aleatoria.","","'Más allá de los marinos, más allá de los naufragios,\nla batalla llegó a su fin.\nNo hay más humo en las aguas, sus capitanes están con sus creadores,\ny sus naves abiertas cual tabla rota''. —''Vete a casa, Sally''","Unidad",[],["Aguasturbias"],"ÉPICA"],"02BW037":["Ojo Abisal","Golpe al Nexo: Roba una carta.","","''Sí, sí'', gritaron y zarparon,\nAl ver problemas en la bella Nashramae,\nPero la naturaleza dio un vuelco y muchos murieron,\nY los demás, para ver al ojo que todo lo ve su curso siguieron''. —''El ojo que todo lo ve''","Unidad",["MONSTRUO MARINO"],["Aguasturbias"],"RARA"],"02BW008":["Suboficial","Al jugar: Invoco 1 Barril de Pólvora o un seguidor aleatorio de costo 1.","","Descubrió que pocas cosas podían motivar tanto a un marinero como una mecha encendida.","Unidad",["YORDLE"],["Aguasturbias"],"RARA"],"02BW047":["Comesobras","Cuando me invocan, lanzo Desechar a 3.","","Hay que ser una persona muy especial para convertir equipo de altamar en perfecto estado en pura basura inutilizable. Pero si hay algo que se les da bastante bien, es eso. Solo eso.","Unidad",[],["Aguasturbias"],"COMÚN"],"02BW004":["Grumete del Heraldo","Cuando me invocan, invoco 1 Barril de Pólvora.","","''Eso. Podríamos atacarlos al amanecer, cuando la tripulación está despierta y los cañones están engrasados... O podríamos dejarles un regalito esta noche con mucho sigilo...''.","Unidad",[],["Aguasturbias"],"COMÚN"],"02BW002":["El Heraldo de la Muerte","Cuando me invocan, roba Gangplank.\nDuplico todo el daño que infligen tus hechizos, Habilidades y aliados.","","''Uy, será mejor que te despidas y bajes las velas,\nel Heraldo se acerca, se acerca.\nNos vamos a lo profundo, donde la muerte es rotunda,\nporque el Heraldo se acerca, se acerca!''. —''El Heraldo se acerca''","Unidad",[],["Aguasturbias"],"ÉPICA"],"02BW016":["Bot Tragamonedas","Cuando me invocan o al Inicio de la ronda: Recibo +0|+1 por cada carta que hayas robado en la última ronda e intercambio mis estadísticas.","","Un prototipo lanzó tres bombas y luego explotó. Los modelos más nuevos ya no tienen esta ''función''.","Unidad",[],["Aguasturbias"],"RARA"],"02BW027":["Flota de Caza","Cuando me invocan, tu oponente invoca 1 Narval Dorado.","","El oro que resplandece bajo las olas no son monedas ni lingotes; es el lustroso cuerno del ingenioso adversario del capitán del Matamarinos.","Unidad",[],["Aguasturbias"],"COMÚN"],"02BW050":["Solista Sutil","Pillaje: Reduzco en 2 el costo de los aliados en la mano y mazo.","","''¡Acompáñanos en un viaje musical! ¡Disfruta las melodías de toda Runaterra! Pero recuerda: necesitas monedas para pagar la entrada y agradecemos las propinas''. —Promotor de espectáculos","Unidad",[],["Aguasturbias"],"RARA"],"02BW015":["La Sirena","Cuando me invocan, roba Miss Fortune.\nMientras ataco, todos tus hechizos y Habilidades infligen 1 de daño adicional.","","No hay forma de confundir a la Sirena. Sus amplias y níveas velas, y su madera bien pulida la hacen ver igual de ágil y arreglada como la capitana en el timón.","Unidad",[],["Aguasturbias"],"ÉPICA"],"02BW010":["Porata Saqueador","Pillaje: Recibo 2 palabras clave aleatorias.","","''Su retrato lleva más tiempo que ningún otro en el tablero de recompensas. Es un demonio codicioso y despiadado que no permite que nadie se interponga en su camino. ¿Y lo peor? Que es... un bombón... Maldición''. —Gangplank","Unidad",["PORO"],["Aguasturbias"],"COMÚN"],"02BW009":["Tahúr del Billar","Cuando me invocan, roba 1 carta en el siguiente Inicio de la ronda y le otorgo Fugaz.","","''No 'me hace' sentido. Los vencía bien fácil, pero ese último... no se iba. Se me hace que no es mi día...''. —Apostadora Impulsiva","Unidad",[],["Aguasturbias"],"COMÚN"],"02BW005":["Asesina a Sueldo","Cuando me invocan, otorgo Vulnerable al enemigo Más fuerte.","","''¿Este es tu retrato? Uy, caes más pesado a los ojos de lo que pensé... Esperemos que tu cabeza haya valido mi tiempo''.","Unidad",[],["Aguasturbias"],"COMÚN"],"02BW039":["Cazadores de Jaulls","Cuando me invocan, creo un Monstruo Marino aleatorio en tu mano.","","La promesa de la fortuna lleva a innumerables marineros más allá de las aguas poco profundas. Las pobres almas no tardan en descubrir lo terroríficas que se tornan las aguas y por qué solo unos cuantos regresan.","Unidad",[],["Aguasturbias"],"RARA"],"02BW006":["Mago Misterioso","Al jugar: Transformo a un aliado en un seguidor aleatorio de costo 5.","","''¿Marvolio? Dónde... ¿dónde están mis manos?''.\n''¡Orita mismísimo las hago aparecer! ¡Listo! Este... ¡List... to...!''.\n''¡¿DÓNDE ESTÁN MIS MANOS?!''.\n''¡HORA DE IRME DE AQUÍ! ¡MUCHAS GRACIAS A TODOS!''.","Unidad",[],["Aguasturbias"],"RARA"],"02BW036":["Narval Dorado","","","Cuenta la leyenda que, alguna vez, una ballena blanca con un cuerno le robó a la Mujer Barbuda. Como castigo, la Barbuda cubrió a la codiciosa criatura en oro resplandeciente para incitar la avaricia en los demás por siempre.","Unidad",[],["Aguasturbias"],"COMÚN"],"02BW033":["Comerciante del Mercado Negro","Cuando robes una carta enemiga, reduzco su costo en 1.\nPillaje: Hurta 1.","","''¡Si lo quieres, yo lo tengo en existencia! Hasta tengo algunas 'cositas especiales'. ¡Solo recuerda que yo no figuro por ningún lado!''.","Unidad",[],["Aguasturbias"],"RARA"],"02BW032":["Gangplank","Cuando me invocan, invoco 1 Barril de Pólvora.","Si dañaste el nexo enemigo en 5+ rondas diferentes.","''No lo mires demasiado y que no se dé cuenta. Y no hables mal de él, porque conoce todos los rumores de Aguasturbias. Aquí viene. Baja la barbilla. Baja más la mirada''. —Grumete del Heraldo","Unidad",[],["Aguasturbias"],"Campeón"],"02BW022":["Miss Fortune","Cuando los aliados atacan, inflijo 1 de daño a todos los enemigos en combate y al nexo enemigo.","Si te he visto atacar 4 veces.","''¿'Señorita' Fortune? Aquí me llamarás Capitana''.","Unidad",[],["Aguasturbias"],"Campeón"],"02BW046":["Fizz","Cuando juegas un hechizo, recibo Evasión y detengo todos los hechizos y Habilidades que me tengan como objetivo en esta ronda.","Si jugaste 6+ hechizos.","De todas las figuras legendarias de Aguasturbias, Fizz es el más voluble. Algunos marineros lo maldicen por los innumerables naufragios que adornan la costa...","Unidad",["YORDLE"],["Ciudad de Bandle","Aguasturbias"],"Campeón"],"02BW026":["Twisted Fate","Al jugar: Usa una carta Destino.","Si te he visto robar 9 cartas.","''Ahora mira las manos, cuenta las cartas y pon atención. Solo recuerda...''.","Unidad",[],["Aguasturbias"],"Campeón"],"02BW053":["Nautilus","","Si tienes Profundidad. Cuando Subo de nivel, copio en tu mazo a los aliados Desechados de costo 4+.","''Un ancla hundió al Rencor. Se llevó a Finn a las profundidades y todo. Ahora quedamos unos pocos y se acerca la noche... y el frío. Lo siento, ma. Tenías razón. El Titán vive''. —Nota recuperada","Unidad",[],["Aguasturbias"],"Campeón"],"02BW061":["Ases de la Victoria","Cuando me robas, cuesto 1 menos en esta ronda.\nOtorgo +2|+1 a un aliado.","","''No hay nada mejor que una buena racha para ganar un montón de fichas''. —Twisted Fate","Hechizo",[],["Aguasturbias"],"COMÚN"],"02BW024":["Doble Desorden","Invoco 2 seguidores aleatorios de costo 1.","","''Oye, Gav. ¿No es aquel al que buscamos? Parece que encontró un amigo''.\n''¿Eso...? ¿Es un hombre tiburón, Baz?''.\n''También es mucho dinero, camarada. Andando...''. —Baz y Gav, cazarrecompensas en ciernes","Hechizo",[],["Aguasturbias"],"RARA"],"02BW003":["Toma de Rehenes","Pillaje: Lanzo Retirada sobre CUALQUIER seguidor y lo regreso a tu mano.","","''¡Ahora trabajas para nosotros!''. —Suboficial","Hechizo",[],["Aguasturbias"],"RARA"],"02BW025":["Carnada para Tiburones","Otorgo Vulnerable a un enemigo e invoco 1 Dientelargo.","","''¡Tiburón!''. —Fizz","Hechizo",[],["Aguasturbias"],"COMÚN"],"02BW012":["¡Más Pólvora!","Invoco 2 Barriles de Pólvora.","","''¡Barril va!''. —Gangplank","Hechizo",[],["Aguasturbias"],"COMÚN"],"02BW018":["Parrrlamentar","Inflijo 1 de daño a cualquier objetivo.\nSi muere, inflijo 1 de daño al nexo enemigo.","","La meditación al estilo de Gangplank suele ser breve y siempre es muy sangrienta.","Hechizo",[],["Aguasturbias"],"COMÚN"],"02BW048":["La Fuga","Invoco un seguidor aleatorio de costo 1.","","''¿Qué te parece, Baz? No se ve muy rudo''.\n''¿Seguro, Gav? Se escapó de la prisión, después de todo''.\n''Eso significa que es inteligente, no rudo. Vamos''. —Baz y Gav, cazarrecompensas en ciernes","Hechizo",[],["Aguasturbias"],"COMÚN"],"02BW043":["Elige una Carta","Para usarme, coloca una carta de tu mano en tu mazo.\nRoba 2 cartas en el siguiente Inicio de la ronda y les otorgo Fugaz.","","''Yo me creo mi propia suerte''. —Twisted Fate","Hechizo",[],["Aguasturbias"],"RARA"],"02BW051":["Juguetón Bromista","Retira a un aliado atacante del combate para usar Preparar.","","''¡Estoy a un salto adelante!''. —Fizz","Hechizo",[],["Aguasturbias"],"RARA"],"02BW054":["Aguas Revueltas","Lanzo Aturdir a un enemigo.\nColoco esa unidad en el mazo enemigo si tienes 1 Nautilus.","","''Los arrastraré al fondo...''. —Nautilus","Hechizo",[],["Aguasturbias"],"RARA"],"02BW042":["Unión Mental","En esta ronda, aumento el Poder y la Vida de los aliados en la cantidad de hechizos que has jugado en esta partida.","","La gente le tiene miedo a las corrientes y mareas alrededor de Aguasturbias con razón por su fuerza y cambios repentinos. Pero ningún marinero conoce realmente el poder que tienen esas aguas.","Hechizo",[],["Aguasturbias"],"ÉPICA"],"02BW059":["Tiro Fragmentado","Lanzo Desechar a 3.\nInflijo 7 de daño a una unidad.","","''Si lo hunde, valió la pena''. —Dicho de Aguasturbias","Hechizo",[],["Aguasturbias"],"RARA"],"02BW023":["Carnada para Monstruos","Reduzco en 1 el costo de los Monstruos Marinos aliados en todas partes.\nRoba un Monstruo Marino.","","Los marineros hablan de los días oscuros que se aproximan en golpes secos de voz, cuando los mares se arremolinen y hiervan, y horrores indecibles asciendan de las profundidades.","Hechizo",[],["Aguasturbias"],"RARA"],"02BW031":["Doble Bala","Inflijo 2 de daño a un enemigo.\nSi muere, inflijo 4 de daño al nexo enemigo.","","''Yo siempre disparo primero''. —Miss Fortune","Hechizo",[],["Aguasturbias"],"RARA"],"02BW029":["Rescate","Lanzo Desechar a 2.\nRoba 2.","","Los restos no flotan por mucho tiempo. Cualquier marino que conozca su oficio debe poder distinguir rápidamente lo valioso de la basura.","Hechizo",[],["Aguasturbias"],"COMÚN"],"02BW049":["Bienes Hurtados","Hurta 1.\nPillaje: Hurta 1 más.","","Lo que es mío, es mío, y lo que es tuyo... también es mío.","Hechizo",[],["Aguasturbias"],"COMÚN"],"02BW001":["Están Advertidos","Doy Vulnerable a un enemigo en esta ronda. Si muere, roba una carta.","","''¡Mantén la barbilla y el ánimo en alto, chico! Si el capitán te ve tristeando, te levantará, te rebanará y te hará alimento de gaviotas. ¡Mueve ese trasero!''. —Grumete del Heraldo","Hechizo",[],["Aguasturbias"],"COMÚN"],"02BW063":["Juego de Manos","Pillaje: Roba una carta aleatoria que no sea un campeón de la mano del enemigo.","","''Las cartas no son cuestión de suerte. Se trata de observar bien a las personas. Si logras que los de enfrente duden de sí mismos, ya te puedes ir apropiando de todo lo que llevan encima''. —Twisted Fate","Hechizo",[],["Aguasturbias"],"RARA"],"02BW045":["Lluvia de Plomo","Inflijo 1 de daño a tres objetivos seleccionados de forma aleatoria, incluso al nexo enemigo.","","''¡Que retumben los cañones!''. —Miss Fortune","Hechizo",[],["Aguasturbias"],"COMÚN"],"02BW020":["Disparo de Advertencia","Inflijo 1 de daño al nexo enemigo.","","''¡Tenías que disparar con todos, pescadillo! ¡Por eso se llama descarga!''. —Suboficial","Hechizo",[],["Aguasturbias"],"COMÚN"],"02BW044":["Tirar por la Borda","Lanzo Desechar a 4.","","''Si no vale su peso en oro, lo tiramos. Es lo mismo con ustedes, sabandijas. ¡A trabajar!''. —Suboficial","Hechizo",[],["Aguasturbias"],"RARA"],"02BW062":["Navegante Isleña","Cuando me invocan, invoco un seguidor aleatorio de costo 1 y le otorgo Explorar.","","''Lleva al cielo la luz de la Madre Serpiente,\nLlévala a las nubes sobre el mar.\nEl cielo mira hacia abajo con gris severidad,\nUna tranquila reflexión en su mirar.\nSonríe y está en paz...''.\n—''Oración a Nagakabouros''","Unidad",[],["Aguasturbias"],"RARA"],"02FR009":["Montalobos","Pillaje: Doy una gema de maná vacía.","","Los jinetes jóvenes de la Garra Invernal reciben un lobezno en cuanto pueden sostener un arma. Su crianza está dictada por la batalla: el lobo estará entrenado para atacar y mutilar, y el jinete para robar y saquear.","Unidad",[],["El Fréljord"],"COMÚN"],"02FR004":["Presa del Frío","Doy Helar y Vulnerable a un enemigo en esta ronda.","","''¡Esos sangrecaliente no sobrevivirían un solo día en el Fréljord!''. —Sejuani","Hechizo",["ELEMENTAL"],["El Fréljord"],"RARA"],"02FR002":["Sejuani","Al jugar: Doy Helar y Vulnerable a un enemigo en esta ronda.","Si dañaste el nexo enemigo en 5+ rondas diferentes.","Aunque su látigo de Hielo Puro es magnífico, la propia Sejuani es el arma forjada en el frío inclemente del Fréljord, reforzada para resistir las bajas temperaturas.","Unidad",[],["El Fréljord"],"Campeón"],"02FR001":["Doncella de las Brasas","Inicio de la ronda: Inflijo 1 de daño A TODO.","","''Cultivan sus campos frutales,\nEndebles siembran semillas.\nLas llamas consumen la vida, \nPorque la Garra Invernal todo lo domina''. —Dicho infantil de la Garra Invernal","Unidad",[],["El Fréljord"],"RARA"],"02FR005":["Cambiapieles Ursino","Pillaje: Me transformo en Ursino Garratormenta.","","Los ursinos nacen como seres humanos, pero sacrifican los elementos de sus vidas familiares por el poder salvaje que otorga el gran espíritu del Volibear.","Unidad",[],["El Fréljord"],"COMÚN"],"02FR010":["Botín Compartido","Otorgo +1|+1 a las primeras 3 unidades de tu mazo.\nPillaje: Roba 1 de ellas.","","''Comparte a diestra y siniestra''. —Invasora Implacable","Hechizo",[],["El Fréljord"],"RARA"],"02FR008":["El Colmillo Saqueador","Cuando me invocan, roba Sejuani.\nPillaje: Duplico el poder y la vida de los aliados en tu mazo.","","''Cuando llega la primavera y hace calor suficiente como para cultivar, llegan también los barcos... y la semilla que da comienzo al abundante crecimiento''. —Guardapatrias Avarosano","Unidad",[],["El Fréljord"],"ÉPICA"],"02FR007":["Furia del Norte","Doy +3|+4 a un aliado en esta ronda.","","''¡Abraza a tu bestia interior!''. —Sejuani","Hechizo",[],["El Fréljord"],"COMÚN"],"02FR006":["Invasora Implacable","","","La Garra Invernal no tiene igual en el Fréljord y todos conocen la fiereza de estos saqueadores implacables. Una vez que los invade la sed de sangre, solo resta implorar por una muerte veloz.","Unidad",[],["El Fréljord"],"COMÚN"],"02FR003":["Aurora Poreal","Creo 2 Poros aleatorios y 2 Porogalletas en tu mano.","","''Cuando le pides un deseo a un poro,\nY miras el cielo nocturno,\nVerás las porogalletas en el firmamento,\nBrillando cual estrellas en tus ojos''. —Ingvar la Joven","Hechizo",[],["El Fréljord"],"ÉPICA"],"02NX001":["El Leviatán","Cuando me invocan, roba Swain.\nInicio de la ronda: Inflijo 1 de daño dos veces al nexo enemigo.","","Cuando los jonios vieron la amenaza en el horizonte, creyeron que era un monstruo. Y no se equivocaban: el buque de guerra de acero era aterrador. Era el mayor logro de la ingeniería naval noxiana hasta el momento.","Unidad",[],["Noxus"],"ÉPICA"],"02NX007":["Swain","Golpe al Nexo: Inflijo 3 de daño al nexo enemigo.","Si infligiste 14+ de daño fuera del combate.","''Un poder más allá del entendimiento de los mortales me concedió la visión para mirar lo que otros no pueden. Yo observo a través de la oscuridad que tantos temen''.","Unidad",[],["Noxus"],"Campeón"],"02NX006":["Rompeciudades","Inicio de la ronda: Inflijo 1 de daño al nexo enemigo.","","La voz del anciano sonaba sorpresivamente tranquila. Y preguntó: ''Dime por favor, ¿cuál es el propósito de juntar piedras para construir muros más altos si los noxianos siempre se las arreglan para volverlos a derrumbar?''.","Unidad",[],["Noxus"],"RARA"],"02NX002":["Aurok Cuernobrillante","Al atacar: Lanzo Aturdir a todos los enemigos heridos.","","''Nos han subyugado durante generaciones. Entendimos la verdadera libertad cuando Noxus ocupó nuestras tierras. Por esa razón lucho en nombre del imperio''.","Unidad",[],["Noxus"],"ÉPICA"],"02NX009":["Parvada Hambrienta","Inflijo 4 de daño a una unidad si está herida o tiene Aturdir.","","Escucha. ¿Puedes oírlo? Es el estruendo del aleteo de miles de alas.","Hechizo",[],["Noxus"],"RARA"],"02NX004":["Artificiera Imperial","Al jugar: Inflijo 1 de daño a un aliado para infligir 2 de daño al nexo enemigo.","","''Rápido y silencioso hasta oír el PUM''.","Unidad",[],["Noxus"],"COMÚN"],"02NX003":["Fervor Noxiano","Inflijo 3 de daño a un aliado para infligir 3 de daño a cualquier objetivo.","","''Todos hacemos sacrificios''. —Jericho Swain","Hechizo",[],["Noxus"],"COMÚN"],"02NX010":["Jinete de Colmillo Acorazado","Los enemigos con 4 o menos de poder no pueden dañarme.","","''No se puede detener a una bestia de guerra una vez que está en movimiento. Lo mejor es quitarse del camino''. —Jinete de Basiliscos","Unidad",[],["Noxus"],"RARA"],"02NX008":["Mano de la Muerte","Inflijo 2 de daño a un enemigo y 1 de daño al nexo enemigo.","","''Intenta morir con honor''. —Swain","Hechizo",[],["Noxus"],"COMÚN"],"02NX005":["Balista de Hierro","","","''Un asedio es fácil de llevar a cabo con las herramientas adecuadas. Los allanadores los sacan y las ballestas los derriban''. —Ingeniero de asedio","Unidad",[],["Noxus"],"COMÚN"],"02DE003":["Ursotejón Leal","","","Es verdad eso que dicen: las mascotas se parecen a sus dueños.","Unidad",[],["Demacia"],"COMÚN"],"02DE008":["Compañero Cuernogrande","","","Los nuevos guardabosques pasan meses en el bosque con sus compañeros y aprenden a predecir cada movimiento de sus ciervos. Deben ser pacientes, pero una vez que se crea el vínculo, nada los podrá separar.","Unidad",[],["Demacia"],"COMÚN"],"02DE004":["Guardián Dienteverde","","","''Hice un juramento de proteger este bosque y a todos aquellos que busquen refugiarse en él''.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"02DE006":["Quinn","Cuando me invocan, invoco 1 Valor.","Si te he visto atacar 4 veces.","''Nuestra Quinn siempre ha sido una caballera guardabosques temeraria. Con Valor a su lado o surcando los cielos, no hay quien los detenga''. —Genevieve Corazón del Olmo, caballera guardabosques","Unidad",[],["Demacia"],"Campeón"],"02DE009":["Guardabosques Canoso","Último Aliento: Invoco 1 Ursotejón Leal.","","''Betrand empezó en los exploradores de Bandle. Se ganó todas las insignias menos la de 'Conducta alegre'''.","Unidad",["YORDLE"],["Demacia"],"RARA"],"02DE005":["Espíritu Indomable","Otorgo ''No me pueden dañar ni matar'' a un aliado.","","Ignorando el dolor de su pierna herida, la guarda se puso de pie y empuñó la espada una vez más. No solo era su propia determinación la que la mantenía en pie, sino la determinación de toda Demacia.","Hechizo",[],["Demacia"],"ÉPICA"],"02DE002":["Ataque Cegador","Invoco 1 Valor.","","''¡Está en mi cabello! ¡ESTÁ EN MI CABELLO!''. —Merodeador Legionario","Hechizo",[],["Demacia"],"RARA"],"02DE010":["Genevieve Corazón del Olmo","Cuando me invocan, doy +1|+1 a otros aliados en esta ronda.","","Inspira mucho ver a los guardas de Demacia en batalla. Luchan inseparables, como si fueran uno: humano y animal, lado a lado, con una determinación feroz.","Unidad",[],["Demacia"],"ÉPICA"],"02DE007":["Valor de Guardabosques","Doy Dureza a los aliados en esta ronda.","","''Cuando el enemigo se acerque, no permitan que el miedo entre en sus corazones. Los árboles nos protegen''. —Guardián Dienteverde","Hechizo",[],["Demacia"],"RARA"],"02DE001":["Golpe Coordinado","Elige un enemigo y 2 aliados lo Golpean uno tras otro.","","''¡A mí! ¡En línea!''. —Guardián Dienteverde","Hechizo",[],["Demacia"],"COMÚN"],"02SI005":["Extracción de Magia","Lanzo Desechar a 3.\nCuro 3 a los aliados.","","''Estas islas serán purificadas''. —Maokai","Hechizo",[],["Islas de la Sombra"],"RARA"],"02SI010":["Merodeador Germinante","Cuando me invocan, lanzo Desechar a 3.","","''El gran treant me siguió enseñando... criaturas. Esta... esparcir vida a medida que camina... maravilloso... aquí. ¡Estas islas sí son las Islas Bendecidas!''. —Diario recuperado","Unidad",[],["Islas de la Sombra"],"COMÚN"],"02SI008":["Maokai","En cada ronda, lanzo Desechar a 2 e invoco 1 Retoño la primera vez que invoques a otro aliado.","Si tus unidades murieron o Desecharon tus cartas 25+ veces.","Estas tierras malditas no serán capaces de quebrar a Maokai. El compromiso del treant era demasiado profundo y su furia brillaba con demasiado fulgor como para que alguien se interpusiera en su camino.","Unidad",[],["Islas de la Sombra"],"Campeón"],"02SI007":["Sapo Espinoso","Último Aliento: Lanzo Desechar a 2 y curo 2 a tu nexo.","","''... especie extraordinaria... la misma criatura que encontré de joven... ¡no había envejecido! Me pregunto... siguiente aldea. ¡Tal vez estas increíbles criaturas vivan por siempre!'' —Diario recuperado","Unidad",[],["Islas de la Sombra"],"COMÚN"],"02SI003":["Terror de las Mareas","Los Monstruos Marinos aliados obtienen Temible.\nAl atacar: Doy -2|-0 a los enemigos en esta ronda.","","Se dieron cuenta del peligro demasiado tarde. La bestia titánica abrió sus fauces y se abalanzó hacia ellos. Los cazadores solo esperaban la muerte mientras los infinitos dientes masticaban su barco.","Unidad",["MONSTRUO MARINO"],["Islas de la Sombra"],"ÉPICA"],"02SI001":["Barquero de Clarojamás","Cuando otro aliado muere, Dreno 1 del nexo enemigo.","","''Me topé con Niven... ¡el nuevo barquero! Nos llevó remando hasta... ¡Pero qué buena melodía venía cantando! Pero antes... debo invitarlo a cenar pronto''. —Diario recuperado","Unidad",[],["Islas de la Sombra"],"RARA"],"02SI002":["Planta Sobrealimentada","Cuando invoques un seguidor, mátalo para invocar 1 Planta Sobrealimentada.","","''Hoy... otro increíble... salió a la superficie... los niños se asustaron. Pero no era una amenaza. Toqué su hocico... criatura confiada. Debo juntarles más bayas''.\n—Diario recuperado","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"02SI004":["Cuidadora Maldita","Al jugar: Mato a un aliado para invocar 2 Retoños.","","''¡Todo corazón es como un jardín para arraigarse!''.","Unidad",[],["Islas de la Sombra"],"RARA"],"02SI006":["Bestia Ladrante","Recibo +2|+2 la primera vez que un aliado muera.","","Las criaturas de las Islas de la Sombra dejaron la sensiblería hace mucho tiempo. Todas tienen que comer.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"02SI009":["Lanzamiento de Retoño","Invoco 1 Retoño en el siguiente Inicio de la ronda.","","''¡Wiiii!''. —Retoño","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"02IO008":["Onda Sónica","Doy Desafío a un aliado en esta ronda.\nCreo 1 Golpe Resonante con Fugaz en la mano.","","''Domínate a ti mismo...''. —Lee Sin","Hechizo",[],["Jonia"],"COMÚN"],"02IO002":["Escamas del Dragón","Cuando me invocan, creo 1 Protección del Dragón en la mano.","","''El estudiante debe actuar con compasión, pues el Dragón alimentó las Tierras Originarias y las bendijo con calor y vida''. —Enseñanzas del Dragón","Unidad",[],["Jonia"],"COMÚN"],"02IO006":["Lee Sin","Cuando juegas un hechizo, recibo Desafío en esta ronda.\nSi juegas otro, recibo Barrera en esta ronda.","Si jugaste 8+ hechizos.","''El Dragón ayuda a los dignos. Les da vigor a los débiles y consuelo a los enfermos; luz a los perdidos y equilibrio a los estremecidos...''.","Unidad",[],["Jonia"],"Campeón"],"02IO004":["Cuernos del Dragón","","","''El estudiante debe esforzarse con todo su ahínco, pues el Dragón extrajo la tierra que yacía debajo de las olas y nos dio un lugar al que llamamos hogar''. —Enseñanzas del Dragón","Unidad",[],["Jonia"],"COMÚN"],"02IO003":["Ojo del Dragón","Inicio de la ronda: Flujo: Invoco 1 Cachorro de Dragón.","","''El estudiante debe pensar con claridad, pues el Dragón ayuda al sol a recorrer los cielos para revelar el mundo a nuestro alrededor''.\n—Enseñanzas del Dragón","Unidad",[],["Jonia"],"ÉPICA"],"02IO001":["Garras del Dragón","Cuando estoy en tu mano, invócame cuando juegues 2 hechizos en una ronda.","","''El estudiante debe escuchar con atención, pues los primeros sonidos fueron rugidos de Dragón y, con ellos, bendijo nuestros espíritus jóvenes con el regalo de la magia''. —Enseñanzas del Dragón","Unidad",[],["Jonia"],"COMÚN"],"02IO005":["Palma Conmocionante","Lanzo Aturdir a un enemigo para invocar 1 Cola del Dragón.","","''No me viste partir, ni me verás volver''. —Cola del Dragón","Hechizo",[],["Jonia"],"RARA"],"02IO010":["Repliegue","Lanzo Retirada a un aliado para crear 1 Retorno con Fugaz en la mano.","","Los primeros noxianos en pisar las playas de Jonia se toparon con un enemigo débil y desprevenido. Miles fueron masacrados, pero un puñado logró ponerse a salvo...","Hechizo",[],["Jonia"],"RARA"],"02IO007":["Furia del Dragón","Un aliado patea a un enemigo hacia el nexo enemigo y los Golpea, primero al enemigo y después al nexo enemigo.\nSi el enemigo sobrevive, lanza Retirada sobre él.","","''Debo desatar el Dragón, o me consumirá desde adentro''. —Lee Sin","Hechizo",[],["Jonia"],"ÉPICA"],"02IO009":["Meditación Profunda","Flujo: Cuesto 2 menos.\nRoba otros 2 hechizos.","","La meditación es un viaje sin destino; una senda que solo se puede seguir si te pierdes en el camino.","Hechizo",[],["Jonia"],"RARA"],"03NX019":["Cacería de Débiles","Tu oponente descarta al seguidor Más débil de la mano.","","''Este mundo no está hecho para los débiles. Cada día que pasa, el destino les inflige un nuevo tormento; un nuevo dolor. No reparto muerte; reparto misericordia''. —Arrel la Rastreadora","Hechizo",[],["Noxus"],"RARA"],"03NX022":["Zarpas Salvajes","Un aliado Golpea a un enemigo. Si tiene Arrollar, inflige el exceso de daño al nexo enemigo.","","''Vaya, ¡el salvaje se ve MEGASALVAJE hoy! ¡Será mejor que no se acerquen a sus zarpas!''. —Cantabatallas de la Arena","Hechizo",[],["Noxus"],"ÉPICA"],"03NX007":["Riven","Cuando me invocan, si tienes la ficha de ataque, o cuando ganes la ficha de ataque, lanzo Reforjar.","Si creaste Espada del Exilio.","''No huiré de mi pasado. Hice una promesa de enmendar mis malas acciones...''.","Unidad",[],["Noxus"],"Campeón"],"03NX006":["Empuñadura","Doy +2|+0 a un aliado en esta ronda y lanzo Reforjar.","","''Para conocer a tus enemigos, primero debes conocer sus armas. Estas te dirán cómo se mueven, cómo piensan y cómo atacarán. El arma es la expresión más pura de su usuario''. —Arrel la Rastreadora","Hechizo",[],["Noxus"],"COMÚN"],"03NX002":["Arrel la Rastreadora","Fin de la ronda: Si jugaste un hechizo sobre mí en esta ronda, Golpeo al enemigo Más débil.","","''Ocúltate y te encontraremos. \nRespira y te oiremos.\nHuye y te mataremos''.","Unidad",[],["Noxus"],"ÉPICA"],"03NX018":["Capturar","Lanzo Aturdir a un enemigo.\nSi tienes 1 Darius, lanzo Preparar.","","''Yo me encargaré de esto personalmente''. —Darius","Hechizo",[],["Noxus"],"RARA"],"03NX009":["Jinete Iracundo","","","''No hay nada mejor que cazar a otro soldado. Para rastrearlo, debes pensar y sentir igual que él; para atraparlo, debes temerle tanto como él te teme. Es un vínculo que pocos comprenderán, pero uno que disfruto como ninguno''.","Unidad",[],["Noxus"],"COMÚN"],"03NX017":["Basilisco Buscasangre","Al jugar: Inflijo 1 de daño 4 veces a un aliado y a un enemigo.","","Los entrenadores de basiliscos privan de alimento vivo a las bestias en los días previos a una batalla. Al ser liberadas, el salvajismo de las criaturas es imparable y no distinguen entre amigos y enemigos.","Unidad",["REPTIL"],["Noxus"],"ÉPICA"],"03NX015":["Habilidades de Supervivencia","Los aliados no pueden bajar a menos de 1 de vida en esta ronda.\nAl descartame, tu aliado Más fuerte no puede bajar a menos de 1 de vida en esta ronda.","","''Los dragartos captaron su aroma. La encontrarán y acabaremos con esto. No existe otra manera''. —Arrel la Rastreadora","Hechizo",[],["Noxus"],"RARA"],"03NX014":["Determinación Afilada","Doy +3|+2 a un aliado en esta ronda.","","''Sí, restauraré tus armas, me ocuparé de las monturas, y te prepararé la cena. Para eso sirvo, ¿no?''. —Erath, Portaespadas","Hechizo",[],["Noxus"],"COMÚN"],"03NX003":["Portaespadas","Último Aliento: Lanzo Reforjar.","","''Como dijeron las cazadoras: cien días con sus noches. Cien ampollas en estos pies; cien bichos en mi desayuno; cien asesinatos con espada y cien venganzas cobradas... y muchas más de cien amenazas de esos tres. Si yo te contara...''. ","Unidad",[],["Noxus"],"COMÚN"],"03NX001":["Chamán Rúnico","Cuando me invocan, lanzo Reforjar.","","''La mayoría de las armas son meras herramientas materiales, no mejores que las manos de quienes las forjaron. Sin embargo, un arma imbuida de magia rúnica trasciende el simple acero''.","Unidad",[],["Noxus"],"COMÚN"],"03NX005":["Cazadora Brutal","Cuando me invocan, recibo Ataque Rápido en esta ronda.","","''Ahí estás. ¡SABÍAMOS que no vendrías sin oponer resistencia! O eso esperábamos''.","Unidad",[],["Noxus"],"RARA"],"03BW006":["Jack, el Ganador","Inicio de la ronda: Creo 1 Dormir con los Peces en la mano.","","Jack obtuvo lecciones invaluables de sus años en el cuadrilátero. Aprendió que, si su oponente sangra, entonces puede sentir miedo. Aprendió lo fuerte que es una mirada silenciosa y lo poderosa que es la violencia desenfrenada.","Unidad",[],["Aguasturbias"],"ÉPICA"],"03BW010":["Brunch del Pantano","Un aliado Captura a otro y obtiene las estadísticas del aliado capturado.","","''Entra, camarada, y todo lo que anhelas será tuyo por toda la eternidad''. —Tahm Kench","Hechizo",[],["Aguasturbias"],"COMÚN"],"03BW005":["Costo Hundido","Coloco una unidad o Hito en su mazo.","","''Te di exactamente lo que querías. Jamás dije que duraría para siempre''. —Tahm Kench","Hechizo",[],["Aguasturbias"],"RARA"],"03BW004":["Tahm Kench","Cuando me invocan o al Inicio de la ronda: Creo 1 Un Gusto Adquirido en la mano.","Si Capturé 3+ unidades. Cuando Subo de nivel, lanzo Aniquilar a mis enemigos Capturados y libero a mis aliados.","''Conozco esa expresión. Sientes que las cartas que tienes no son las que mereces. Deseas tener las mejores cosas, ¿no es así? Permíteme satisfacer tu anhelo; haré que saborees todo lo que siempre deseaste. Todo lo que necesito es tu nombre en mi papel... y tú, camarada, sentirás la satisfacción por el resto de tu vida''.","Unidad",[],["Aguasturbias"],"Campeón"],"03BW002":["Lagarto Holgazán","Inicio de la ronda: Me inflijo 2 de daño.","","''¡Ah! ¡Qué tontas son las personas! Dales una bebida fría, una silla caliente y una sonrisa amable y te dirán toda clase de secretos. Y, ¿quién tiene una sonrisa más amable que el joven Leonard?''. —Croadora de la Fortuna","Unidad",[],["Aguasturbias"],"COMÚN"],"03BW014":["Monada o Nada","Invoco 1 Mono Explosivo.\nPillaje: Invoco otro en el siguiente Inicio de la ronda.","","''Ay... ¿crees que son lindos? ¡PUES NO LO SON! Se meten donde se les da la gana, son más sucios que un marinero con mareos y NUNCA SE CALLAN. ASÍ QUE ¡NADA DE MONOS EN EL BARCO! Y ES MI ÚLTIMA PALABRA''. —Suboficial","Hechizo",[],["Aguasturbias"],"COMÚN"],"03BW007":["Pulpúgil","Al jugar: Me inflijo 3 de daño.","","''Por supuesto, Pablo puede ser un poco 'problemático'... je... Y sí, le dieron una buena paliza... Pero ¿sabes algo? No hay nadie más por aquí que haya acumulado ocho asesinatos, camarada''. —Alevín el Sabiondo","Unidad",[],["Aguasturbias"],"COMÚN"],"03BW016":["Acorazado","Inflijo 1 de daño a una unidad. Invoco Barriles de Pólvora equivalentes a la cantidad de daño infligido.","","''El joven Gerent sonó la alarma justo antes del primer estallido. El casco se inclinó y el foque se cubrió en llamas, pero el Jilldaw resistió. Creí que eso era todo, pero, tras seguir la mirada de Gerent hacia el mar, vi cuatro botes más que venían hacia nosotros, todos cargados de pólvora''. —Sobreviviente del Jilldaw","Hechizo",[],["Aguasturbias"],"RARA"],"03BW001":["Los Muelles del Matadero","Inicio de la ronda: Lanzo Desechar a 1. Si tienes Profundidad, destrúyeme para invocar un Monstruo Marino aleatorio.","","Cada día, los residentes merodean los Muelles del Matadero para ver los horrores que los cazadores de Aguasturbias traen de las profundidades. A veces las criaturas están muertas... otras veces, no.","Hito",[],["Aguasturbias"],"ÉPICA"],"03BW015":["Crustáceo Malhumorado","Al jugar: Me inflijo 2 de daño.","","''¡¿PUEDES SONAR LA CAMPANA?! LE MONSTRARÉ A ESE ZOQUETE POR QUÉ TENGO TODOS ESOS APODOS: ¡'PABLO OCHO PUÑOS', 'EL KRAKEN ROMPEDOR', 'EL TERROR CON TENTÁCULOS'! ¡TU AGUIJOÑITO LLORARÁ POR SU MAMÁ CUANDO TERMINE CONTIGO!'' —Pulpúgil","Unidad",[],["Aguasturbias"],"COMÚN"],"03BW003":["Alevín el Sabiondo","Al jugar: Inflijo 1 de daño a todos los demás aliados y recibo +1|+0 por cada aliado afectado.","","El ascenso al poder suele ser un camino muy violento... pero no es usual que sea así de descuidado.","Unidad",[],["Aguasturbias"],"RARA"],"03BW017":["Pez Burbujeante","Cuesto 1 menos por cada hechizo que hayas jugado en esta partida.\nCuando me invocan, creo un hechizo aleatorio de tus regiones de 1 de costo en la mano.","","''¡Migua y apguende, pguincipiante! Tu misión es infiltguagte tgas las líneas enemigas, plantag tantas bombas como puedas y contagnos todo lo que VEAS. T-O-D-O. ¡¿ENTENDIDO?!''. —Almiguante Shelly, Artillería Caparazón","Unidad",[],["Aguasturbias"],"ÉPICA"],"03BW008":["Croadora de la Fortuna","Al jugar: Inflijo 1 de daño a mí misma y a un aliado para robar 1.","","''La vieja Babs tuvo algunos tropiezos: mató a un par de residentes en su época, pero supongo que eso le da un aire de autenticidad''. —Lagarto Holgazán","Unidad",[],["Aguasturbias"],"COMÚN"],"03BW020":["Pandemonio de Pólvora","Invoco 1 Mono Explosivo por cada vez que hayas activado Pillaje en esta partida.","","''Ah, esas bolas de hollín no son tan malas. Un consejo: adoran los fuegos artificiales. Solo debes conseguir las reservas de pólvora de tus enemigos y los pequeñitos harán el resto''. —Miss Fortune","Hechizo",[],["Aguasturbias"],"ÉPICA"],"03BW009":["Chantaje","Inflijo 2 de daño a un aliado para darle Vulnerable a 2 enemigos.","","''¿Me dirás dónde conseguiste estos 'barriles extra', Slim? ¿Eh? De lo contrario, podríamos jugar a 'tirar la soga' con tu lengua y el brazo de Jimbo. Por cierto... no apostaré a tu favor''. —Alevín el Sabiondo","Hechizo",[],["Aguasturbias"],"RARA"],"03DE010":["La Gran Plaza","Cuando invocan a un aliado, le doy +1|+1 y Desafío en esta ronda.","","Tianna contempló la asamblea y pasó revista a las tropas reunidas. El único sonido en la plaza era el ondear de su estandarte con el viento. Dio una brusca señal de aprobación, levantó el estandarte y gritó: ''¿Quiénes entre ustedes están listos para luchar por Demacia?''. La multitud allí reunida sacudió las montañas con su grito. ","Hito",[],["Demacia"],"ÉPICA"],"03FR009":["El Abismo de los Lamentos","Inicio de la ronda: Creo 1 campeón aleatorio de nivel 2 que no esté en la mano, en el mazo o en juego.","","Los héroes vienen al puente, atraídos por algo desconocido. Le hacen frente a su amargo frío y su ruinosa plataforma para ver lo que yace más allá: la victoria... o la muerte.","Hito",[],["El Fréljord"],"ÉPICA"],"03MT005":["Caminos Bifurcados","Roba o destruye un Hito.","","Targón es un lugar caprichoso donde los invencibles son vencidos, y los vencidos se fortalecen.","Hechizo",[],["Targón"],"COMÚN"],"03SI009":["Criptas de Helia","Inicio de la ronda: Si puedes, mata a tu aliado más costoso para invocar un aliado de tu mazo que cueste 1 más.","","¿Qué podría ser más efectivo para atraer un alma a este desdichado lugar que la promesa de vida eterna y riquezas inagotables?","Hito",[],["Islas de la Sombra"],"ÉPICA"],"03IO006":["Monasterio de Hirana","Inicio de la ronda: Creo 1 Santuario en la mano.","","Las montañas de Jonia esconden un puñado de santuarios para aquellos que buscan meditar y calmar sus espíritus.","Hito",[],["Jonia"],"ÉPICA"],"03NX013":["Tierra Calcinada","Mato a una unidad herida o destruyo un Hito.","","''Los dragartos captaron su aroma. La encontrarán y acabaremos con esto. No existe otra manera''. —Arrel la Rastreadora","Hechizo",[],["Noxus"],"COMÚN"],"03NX004":["Arena Noxkraya","Fin de la ronda: Tu aliado Más fuerte y tu enemigo Más débil se Golpean entre ellos.","","''Saludos, fanáticos de los duelos. ¡¿Están listos para una noche de intensas EMOCIONES en la ARENA DE FUEGO?! Cielos, parece que la pequeña Trik no tuvo suerte hoy: ¡su oponente será el fiero y poderoso GRANAAAAK el Grande! Que los médicos entren a la arena de una vez, ¡pues esta batalla será muy corta!''. —Cantabatallas de la Arena","Hito",[],["Noxus"],"ÉPICA"],"03DE004":["Capitana Arrika","Al jugar: Capturo una unidad o Hito.","","En su niñez, Arrika vio de primera mano la devastación que Noxus podía infligir mientras arrasaba su hogar. Cuando se enlistó en la milicia, juró que jamás permitiría que la bandera noxiana ondeara sobre Demacia, ni que más niños quedaran huérfanos.","Unidad",["ÉLITE"],["Demacia"],"RARA"],"03IO005":["Regreso a Casa","Lanzo Retirada a una unidad o Hito aliados para lanzar Retirada a una unidad o Hito enemigos.","","''¡Trevooor! ¡Regresaaa...!''. —Casa de Trevor","Hechizo",[],["Jonia"],"COMÚN"],"03MT052":["Manantial Estelar","Fin de la ronda: Curo 1 a los aliados heridos. Luego, si te he visto curar 22+ de daño a los aliados, gano la partida.","","''Hasta la sagrada circulación de fluido,\nen lo profundo de los estanques, las aguas sanadoras\nirradian luz; el agua es radiante.\nEscucha el canto del río\nen lo alto de la montaña de cristal''.\n—Verso ottrani","Hito",[],["Targón"],"ÉPICA"],"03MT064":["La Cima de Targón","Inicio de la ronda: Reduzco a 0 el costo de una carta aleatoria en la mano de TODOS los jugadores en esta ronda.","","El guardián cristalino de Targón custodia la puerta del reino celestial. Esperanza, dudas, miedos... todo eso se desvanece ante su presencia. Sus pruebas liberan a los mortales de sus preocupaciones y desnudan la esencia de las almas que ascienden la montaña. Es aquí donde el guardián juzga a estas almas, pues él es el gran juez. ","Hito",[],["Targón"],"ÉPICA"],"03SI008":["Desmoronar","Mato a un aliado para matar a una unidad o destruir un Hito.","","Nada dura en estas islas malditas. Todo morirá.","Hechizo",[],["Islas de la Sombra"],"RARA"],"03PZ001":["La Universidad de Piltóver","Inicio de la ronda: Descarto tu mano, creo 3 cartas aleatorias en la mano y les otorgo Fugaz.","","Los inventos del profesor Cecil B. Heimerdinger le dieron fama, pero fueron sus animadas lecciones e impredecibles demostraciones en el aula de clase lo que lo hicieron conocido como una de las mentes más brillantes de Piltóver.","Hito",[],["Piltóver y Zaun"],"ÉPICA"],"03FR003":["Aquel que Observa","Al jugar: Lanzo Aniquilar a TODOS los Hitos, o inflijo 3 de daño a TODAS las demás unidades.","","''No hubo tiempo de recoger nuestras cosas ni de advertir a los demás. Todo lo que pudimos hacer fue huir al bosque y observar mientras destruía nuestros hogares''. —Guardapatrias Avarosano","Unidad",[],["El Fréljord"],"RARA"],"03MT026":["Rahvun, la Lanza Diurna","Amanecer: Creo una carta Amanecer aleatoria en tu mano.\nPara nosotros siempre es de día.","","''¡Si conservas tu fe, Ra-Horak, nuestra luz jamás decaerá!''.","Unidad",[],["Targón"],"RARA"],"03MT067":["Íbice de Cristal","Al jugar: Otorgo Arrollar a un aliado.","","Aquellos que buscan ascender a Targón harían bien en hacer amistad con la fauna local. Ninguna otra criatura conoce mejor los peligros de la montaña ni puede viajar a través de sus helados terrenos.","Unidad",[],["Targón"],"COMÚN"],"03MT084":["Formación de Estrellas","Convoco una carta Celestial que cueste 7 o más. Después curo 5 a un aliado o a tu nexo.","","''Mira a las estrellas. Si tienes suerte, yo te miraré a ti''. —Aurelion Sol","Hechizo",[],["Targón"],"COMÚN"],"03MT221":["Los Colmillos","Al jugar: Convoco una carta Celestial que cueste 3 o menos.","","''Madre Luna, muéstrame el camino,\nabre los cielos\ny muéstrame lo que yace más allá''.\n—Oración Lunari","Unidad",[],["Targón"],"ÉPICA"],"03MT093":["Estrella Saltarina","Inflijo 5 de daño a un enemigo que haya atacado en esta ronda o que esté Aturdido.","","''¡KaPUMmi!''. —Zoe","Hechizo",[],["Targón"],"COMÚN"],"03MT073":["Portadora del Ocaso Lunari","Cuando me invocan, creo 1 Polvo de Pétalo del Ocaso en la mano.","","''Los pétalos del ocaso florecen solo en las noches de luna llena. Son un símbolo del orgullo Lunari y hemos usado su polvo durante siglos, pues solo nosotros sabemos cómo cosecharlos de forma segura''.","Unidad",[],["Targón"],"COMÚN"],"03MT002":["Los Cielos Descienden","Cuesto 2 menos por cada aliado Dragón o Celestial que tengas. Inflijo 15 de daño a todos los enemigos.","","''Cuando llegue el momento, creo que destruiré Runaterra para que sirva de ejemplo. Quizá arrastre sus humeantes restos conmigo durante la eternidad. Como un juguete, uno que no es digno ni de mi tiempo. No lo sé. No he pensado mucho al respecto''. —Aurelion Sol","Hechizo",[],["Targón"],"ÉPICA"],"03MT217":["Aphelios","Anochecer: Elige un Arma Lunar para crearla en la mano.\nEn cada ronda, cuando hayas jugado otras 2 cartas por primera vez, creo el Arma Lunar de Fase en la mano si no la tienes.","Si jugaste 4+ Armas Lunares.","''En cada conflicto, les demostramos a los Solari que somos dignos de respeto. Les enseñamos que la luz de la luna está a la altura de la de su sol, y a no despreciar aquello que no entienden, pero aún faltan otras lecciones que deben aprender...''. —Orador menguante","Unidad",[],["Targón"],"Campeón"],"03MT044":["Guardián Solar","Si Amanecer está activado o cuando activas otro Amanecer: Recibo +1|+1.","","''Guardián radiante, tu ira arde como el sol de mediodía. Da un paso al frente y castiga a quienes osan profanar este lugar sagrado''. —Inscripción del Guardián Solar","Unidad",[],["Targón"],"ÉPICA"],"03MT056":["Diana","Anochecer o cuando activas otro Anochecer: Recibo Desafío en esta ronda.","Si activaste Anochecer 4+ veces.","Irradiando luz, se alzaba entre ellos y se preparaba para la batalla, ataviada de azul y plata y con la mirada resplandeciente como las estrellas. Al anochecer, la luna se elevó y brilló sobre ella; cada uno de los Lunari presentes cerró los ojos y, en gratitud, profirieron silenciosas plegarias por su seguridad.","Unidad",[],["Targón"],"Campeón"],"03MT020":["Estelacornio Resplandeciente","Al jugar: Curo 3 a un aliado y a tu nexo.","","''¿Ves esa estrella que se mueve en la oscuridad de la noche? Es un estelacornio adulto. Mientras que los ejemplares jóvenes nos confieren su magia curativa hasta que puedan volver a los cielos, los estelacornios adultos son capaces de blandir tal poder por su cuenta. Se debe tener mucha suerte para contemplar uno y entender su relevancia, pero se debe tener mucha más suerte para poder cuidar de uno''. —Lidari, Guardiana de las Estrellas.","Unidad",[],["Targón"],"COMÚN"],"03MT091":["Mapa Estelar Retechévere","Convoco una carta Celestial que cueste 3 o menos.","","''¡Y a estas tres estrellas SÚPER radiantes las llamo... 'la soga celestial'! ¿O parece más una carita feliz al revés?''. —Zoe","Hechizo",[],["Targón"],"RARA"],"03MT047":["Cygnus, el Acechador Lunar","Anochecer: Doy Evasión a un aliado en esta ronda.","","Los Lunari esperaron a que el manto de la noche los protegiera. El camino lucía desierto, pero Cygnus sabía que el campamento Solari yacía adelante, en algún lugar. Con una señal, los demás se alinearon detrás de él, en silencio.","Unidad",[],["Targón"],"ÉPICA"],"03MT094":["Acechadora de las Sombras Lunari","Anochecer: Recibo Evasión.","","''Elevemos nuestros ojos hacia los cielos, hacia el sol, hacia la luz de nuestra dam... Un momento... Qué... ¿qué es eso...?'' —Sacerdote Solari","Unidad",[],["Targón"],"COMÚN"],"03MT036":["Bendición de Targón","Otorgo +3|+3 a un aliado.","","''Un regalito de Targón''. —Taric","Hechizo",[],["Targón"],"RARA"],"03MT092":["Cabra Montés","Al golpear: Creo 1 Gema en la mano.","","Las cabras que habitan el Monte Targón son aún más peligrosas que sus primas más comunes, pues las gemas que adornan sus cuernos incrustan esquirlas dolorosas tras el impacto. ","Unidad",[],["Targón"],"RARA"],"03MT060":["Protector Robusto","Inicio de la ronda: Curo 3 a tu nexo y me inflijo daño equivalente a la cantidad curada.","","''Nadie conoce los caminos de Targón como yo, por lo que tuve que cuidar algunos estelacornios algo... tercos. ¡Tienen suerte de que sea yo quien los cuide!''. ","Unidad",[],["Targón"],"ÉPICA"],"03MT001":["Furritos Sigilosos","Al jugar: Lanzo Aturdir a enemigos con 2 o menos de poder.","","El silencio diáfano de la ladera de la montaña trae consigo los tintineos del hielo a la deriva y, por encima de ellos, lo que los viajeros juran haber escuchado... carcajadas.","Unidad",[],["Targón"],"COMÚN"],"03MT055":["Soraka","Al apoyar: Me curo 4 a mí y al aliado que apoyo.","Si curaste 4+ veces a los aliados heridos.","''La curación es, por definición, un acto de altruismo. No tiene que arrebatarles el poder a otros; ellos están dispuestos a entregarlo. Muéstrales compasión y verás cómo brillan''.","Unidad",[],["Targón"],"Campeón"],"03MT048":["Dadora de Obsequios","Cuando me invocan, creo 1 Gema en la mano.","","''Se dice que el Protector bendijo estas gemas. Pórtalas y su espíritu estará contigo''.","Unidad",[],["Targón"],"COMÚN"],"03MT082":["Luz del Amanecer","Doy +1|+1 a los aliados en esta ronda.\nActivo el efecto Amanecer de un aliado.","","''¡Nos alzaremos con el alba! ¡Marchemos hacia la luz!''. —Leona","Hechizo",[],["Targón"],"RARA"],"03MT058":["Taric","Al apoyar: El aliado que apoyo y yo recibimos Dureza en esta ronda. Copio el último hechizo que me hayas lanzado solo a mí en esta ronda y se lo doy a ese aliado (no se puede copiar de nuevo).","Si te he visto fijar como objetivo o Apoyar aliados 7+ veces.","''La gentileza de Taric inspira a todos aquellos que lo conocen y los impulsa a encontrar la calidez en su interior para fortalecerse incluso en la noche más fría''. —Vidente de la Montaña","Unidad",[],["Targón"],"Campeón"],"03MT062":["Chispóloga Atolondrada","Al jugar: Si Contemplas una carta Celestial, otorgo +1|+1 y Escudo Antihechizos a un aliado.","","''... y una chispiérnaga es como polvo estelar que cae al suelo y vuelve a alzar el vuelo y son increíbles; y vi una de ellas la otra noche que era realmente hermosa, y tengo mucha hambre, y voló hasta las ESTRELLAS y luego...''.","Unidad",[],["Targón"],"RARA"],"03MT040":["Chispiérnaga","","","''La esperanza es un ente delicado que vuela muy alto... y jamás se le debe atrapar''. —Sacerdotisa Lunari","Unidad",[],["Targón"],"COMÚN"],"03MT086":["Artista Soñadora","Al jugar: Descarta 1 para Convocar una carta Celestial de costo 3 o menos.","","''¡Este es mi favorito! Lo llamo 'Identidad metafísica de la psique consciente'. Eso hasta que inclinas tu cabeza de esta manera... Entonces parece tener la forma de dos cucharas''.","Unidad",[],["Targón"],"RARA"],"03MT016":["Pisador Sobresaltado","","","''Vaya... Así que el pisador grandote no quiere cruzar el pequeño portal. No hay problema, podemos... ¡Ja, ja, ja! Solo bromeaba. ¡ALLÁVAS!''. —Zoe","Unidad",[],["Targón"],"COMÚN"],"03MT054":["Leona","Amanecer: Lanzo Aturdir al enemigo Más fuerte.","Si activaste Amanecer 5+ veces.","Irradiando luz, se alzaba entre ellos y se preparaba para la batalla, ataviada de dorado y carmesí y con la mirada resplandeciente como las brasas. Conforme el sol naciente la coronaba con su luz, cada uno de los Solari presentes bajaron la mirada, no por vergüenza, sino en señal de respeto a su resplandeciente líder.","Unidad",[],["Targón"],"Campeón"],"03MT220":["La Vía Cuarteada","Anochecer: Aturdo a un enemigo y, si es un seguidor, lo Aturdo de nuevo en el siguiente Inicio de la ronda.","","''Madre Luna, nuestra noche está aquí.\nPermítenos detener a aquellos que buscan herirnos\ny hacer que lo lamenten''.\n—Oración Lunari","Unidad",[],["Targón"],"RARA"],"03MT021":["El Cortamentes Infinito","Al jugar: Elige 2 enemigos.\nInicio de la ronda: Lanzo Aturdir sobre ellos.","","Se dice que aquellos viajeros que posan sus ojos sobre la criatura obtienen un conocimiento tan vasto y formidable que sus mentes sucumben a la sombra de su mirada.","Unidad",["DRAGÓN"],["Targón"],"ÉPICA"],"03MT006":["Inviolus Vox","En cada ronda, cuando un aliado con Furia mata a un enemigo por primera vez, creo un seguidor Dragón aleatorio en tu mano.","","''¡Mira hacia el cielo y verás lo que yo veo! Primero, las señales, pues de noche brillarán. Luego, la furia, pues de día todo arderá. ¡Ya lo verás! ¡Todos lo harán!''. —Heraldo de Dragones","Unidad",["DRAGÓN"],["Targón"],"ÉPICA"],"03MT015":["Contempla el Infinito","Lanzo Convocar.","","Los cielos que se yerguen sobre ti son un entretejido de estrellas y oscuridad. Tu existencia es tenue e irrelevante comparada con su inmensidad. ¿A dónde apuntarán tus ojos primero?","Hechizo",[],["Targón"],"COMÚN"],"03MT013":["Aflicción de Luz Lunar","Lanzo Silenciar a 2 unidades enemigas en esta ronda.\nAnochecer: No pueden bloquear en esta ronda.","","''Quienes no están acostumbrados a la luz lunar deben aprender a ver con ella... o no verán nada''. —Diana","Hechizo",[],["Targón"],"COMÚN"],"03MT009":["Zoe","Golpe al Nexo: Creo 1 Mapa Estelar Retechévere en la mano o, si ya tienes una igual, reduzco en 1 su costo.","Si te he visto jugar 10 cartas con diferentes nombres.","''¡Holaaaaa! ¿En qué andas? ¿Eso es un JUEGO DE CARTAS? ¿Puedo jugar? ¿Acaso estoy DENTRO de TU partida? Qué dimensión tan chistosa...''.","Unidad",[],["Targón"],"Campeón"],"03MT087":["Aurelion Sol","Al jugar: Convoco una carta Celestial que cueste 7 o más.\nInicio de la ronda: Creo una carta Celestial aleatoria en tu mano.","Si al Fin de la ronda tus aliados tienen 20+ de poder total.","''¡Me tiene sin cuidado lo que escribas sobre mí, criatura patética! Solo asegúrate de describir lo apuesto que soy. Y grandioso. Y también muy, muy inteligente. A ver, ¿te lo deletreo?''.","Unidad",["DRAGÓN"],["Targón"],"Campeón"],"03MT019":["Bastión","Otorgo +1|+1 y Escudo Antihechizos a un aliado.","","''Honra la Montaña''. —Taric","Hechizo",[],["Targón"],"COMÚN"],"03MT214":["El Vuelo","Golpe al Nexo: Roba 1 carta y colócame en las 3 cartas de arriba de tu mazo.","","''Madre Luna, dame determinación.\nCólmame con la convicción de El Vuelo\ny muéstrame mi sendero''.\n—Oración Lunari","Unidad",["AVE"],["Targón"],"RARA"],"03MT071":["Tyari, el Viajero","Al apoyar: Otorgo +0|+2 al aliado que apoyo.","","Debes tener tu mente abierta en tus viajes, pues estas aventuras, quieras o no, te cambiarán. Cuando viajas, siempre traes algo nuevo contigo... y un poco de tu ser se queda en los lugares que visitas. ","Unidad",[],["Targón"],"COMÚN"],"03MT008":["Deseo","Curo por completo a los aliados heridos.","","''¡Por la vida!''. —Soraka","Hechizo",[],["Targón"],"RARA"],"03MT023":["Ráfaga de Sol","Inflijo 6 de daño a una unidad.\nAmanecer: A cambio, le lanzo Silenciar en esta ronda y le inflijo 6 de daño.","","Pocos seres sobreviven a una mirada tan inquebrantable como la del sol.","Hechizo",[],["Targón"],"RARA"],"03MT045":["Protección Astral","Curo 4 a un aliado y le otorgo +0|+4.","","''¿Creíste que nos derrotarías? ¡Ja! Esto apenas comienza''. —Protector Robusto","Hechizo",[],["Targón"],"COMÚN"],"03MT080":["Guardián del Manantial","Cuando me invocan, creo 1 Dones del Manantial en la mano.","","''Mi labor es cuidar de los manantiales; sin embargo, la principal responsabilidad de los pastores es cuidar de sus rebaños. Pero las prioridades a veces entran en conflicto''.","Unidad",[],["Targón"],"COMÚN"],"03MT042":["Ladrona de Hechizos","Manifiesto un hechizo enemigo que se haya lanzado en esta partida.","","''¡Eso estuvo FENOMENAL! Pero, ¿qué tanto más grandioso hubiera sido si yo lo hubiera hecho? ¡Buenograciasyadiós!''. —Zoe","Hechizo",[],["Targón"],"RARA"],"03MT057":["Forjador Solar Solari","Amanecer: Recibo Robo de Vida en esta ronda.","","El forjador solar se concentraba mientras la luz inundaba la habitación. El artefacto Solari absorbía los luminosos rayos del sol y los convertía en un poderoso encantamiento para su arma.","Unidad",[],["Targón"],"COMÚN"],"03MT041":["Mentor de las Rocas","Al apoyar: Otorgo +2|+2 al aliado que apoyo.\nÚltimo Aliento: Creo 3 Gemas en la mano.","","''¿Entendiste algo de lo que dijo ahí dentro?''\n''Ni una palabra, pero parecía un tipo agradable''.\n—Emir y Haley, Visitantes de la Montaña","Unidad",["YORDLE"],["Targón"],"ÉPICA"],"03MT027":["Espada del Cénit","Otorgo +1|+2 a un aliado. Le doy Arrollar en esta ronda.\nAmanecer: Roba 1 Espada del Cénit.","","''¡Que el sol te impregne con su fuerza!''. —Sacerdote Solari","Hechizo",[],["Targón"],"COMÚN"],"03MT096":["Sacerdotisa Solari","Amanecer: Convoco una carta Celestial de costo 4, 5 o 6.","","Los Solari miran a las estrellas y piden su guía tanto como cualquier otro targoniano, y la estrella más querida por ellos es el sol.","Unidad",[],["Targón"],"RARA"],"03MT028":["Portaescudos Solari","Amanecer: Recibo +0|+4 en esta ronda.","","''Fue una torpeza no venir bajo la protección de la noche''. La Portaescudos se enderezó. ''Arroja tus armas y entrégate de forma pacífica''.\nLa Lunari se agachó en silencio mientras preparaba una vez más sus cuchillas curvas. \nQue así sea. \nLa Solari, en respuesta, levantó su escudo para reflejar los rayos del sol naciente. ","Unidad",[],["Targón"],"COMÚN"],"03MT089":["Guardián Lunar","Anochecer: Recibo +2|+0.","","''Guardián estoico, el delicado toque de la luna llena restaura tu fuerza. Despierta y protégenos de quienes osan profanar este lugar sagrado''. —Inscripción de Guardián Lunar","Unidad",[],["Targón"],"RARA"],"03MT051":["Toque Guiador","Curo 2 a un aliado o a tu nexo. Roba 1.","","Los estelacornios brillan con más intensidad cuando están contentos.","Hechizo",[],["Targón"],"COMÚN"],"03MT003":["Agarre de Dragón","Roba 2 Dragones distintos u otorgo +1|+1 y Arrollar a los Dragones aliados.","","''Su llanto suena como un gato ronco. Si alguna vez lo escuchas, da media vuelta y busca al guardia más cercano. ¿Entiendes? Porque donde hay huevos de dragón, siempre hay dragones cerca''. —Explorador targoniano","Hechizo",[],["Targón"],"RARA"],"03MT098":["Vigor Bendito por el Sol","Otorgo +0|+2 a un aliado.","","''Nuestro escudo es nuestra convicción. Nuestra determinación. ¡Es nuestra confianza en la luz!''. —Portaescudos Solari","Hechizo",[],["Targón"],"COMÚN"],"03MT215":["Obsequios del Más Allá","Elige un Arma Lunar para crearla en la mano.","","''Dame tu mano, Aphelios...'' —Alune","Hechizo",[],["Targón"],"COMÚN"],"03MT063":["Soñadora Lunar","Al jugar: Lanzo Convocar.\nAnochecer: Reduzco el costo de esa carta en 1.","","''¡Mira a todos nuestros amigos en el cielo nocturno! ¿Ves esa estrella que brilla un poco más que las demás? ¡Ese es el ojo del Mensajero, mirándonos! ¿Y ese tenue cúmulo tan alejado? ¡Es el Bromista, ocultándose tras las nubes! Y por allá está... ¡SILENCIO, KULUN! ¡No puedes bajarlos con tu pata...!''.","Unidad",[],["Targón"],"COMÚN"],"03MT100":["Dragón del Eclipse","Amanecer: La siguiente unidad Dragón o Celestial que uses costará 2 menos.\nAnochecer: Creo un seguidor Dragón y uno Celestial aleatorios en la mano.","","Escama de Dragón (Dragón del Eclipse, draco obscuratus)\nNotas: Esta escama tiene propiedades ópticas formidables. Posee una elevada capacidad reflectante de la luz solar.\nGarabatos: ¡TAMBIÉN BRILLA DE NOCHE!\n—Notas de Anden Mayne, ovólogo","Unidad",["DRAGÓN"],["Targón"],"RARA"],"03MT076":["Vidente de la Montaña","Tus cartas Celestiales cuestan 1 menos.\nAlianza: Convocar.","","''Tenemos mucho que aprender de las estrellas y de su guía. Para nosotros, ellas son una constante; una forma de mapear nuestro camino''.","Unidad",[],["Targón"],"RARA"],"03MT029":["Pastora de Estrellas","Cuando curas a un aliado herido, recibo +2|+0.","","''Adoro los estelacornios desde el primer momento que vi a uno cruzar el cielo nocturno. ¡Si tan solo hubiera sabido que llegaría a conocer a tantos ejemplares!''.","Unidad",[],["Targón"],"RARA"],"03MT219":["El Templo del Velo","En cada ronda, cuando hayas jugado otras 2 cartas por primera vez, restablezco 2 de maná y le otorgo +1|+0 a tu aliado Más fuerte.","","Es aquí, en el Reino Espiritual, donde Alune se comunica con su hermano Aphelios. Es ella quien expresa palabras de aliento al asesino silencioso, y quien atraviesa el velo para otorgarle sus armas de la venganza.","Hito",[],["Targón"],"RARA"],"03MT079":["Granuja Estelar","Si Contemplas una carta Celestial, cuesto 2 menos.","","''Los adultos son PATÉTICOS. Los únicos chicos que son divertidos por aquí son Zoe y sus amigos. Aprendo mucho de ellos, lo que no sucede con esa alta sacerdotisa de pacotilla. Esa tipa me da NÁUSEAS''.","Unidad",[],["Targón"],"COMÚN"],"03MT007":["Estelacornio Bebé","","","''Tarde o temprano, los jóvenes estelacornios deben realizar su primer vuelo. En eso son similares a cualquiera de las estrellas en el cielo nocturno, pues pueden caer con la misma facilidad. Por suerte, nosotros estamos aquí para atraparlos y, cuando estén listos, devolverlos a donde pertenecen''. —Lidari, Guardiana de las Estrellas","Unidad",[],["Targón"],"COMÚN"],"03MT038":["Protector Albígneo","","","Fueron los niños de Targón quienes por primera vez hicieron amistad con los dragones más jóvenes y pacíficos. Puede que estas criaturas sintieran la curiosidad inocente de los más pequeños y que esto, en lugar de dañarlos, los motivara a protegerlos. ","Unidad",["DRAGÓN"],["Targón"],"COMÚN"],"03MT014":["Heraldo de Dragones","Los Dragones aliados cuestan 1 menos.","","Las nubes se abrieron al roce de sus colosales formas. El cielo parecía temblar con la intensidad de su llanto. Ella sabía lo que estaba por llegar; sin embargo, lejos de sentir temor, sintió el cálido abrazo del destino.","Unidad",[],["Targón"],"RARA"],"03MT110":["Out Of The Way","Durante el resto de la partida, las mejoras de aliado para \"esta ronda\" (excepto Barrera) son permanentes. Roba 1.","","''You know I mean everything that I say\nWhen you see me coming get out of the way\nI came to slay I came to slay\nBack and I'm better and ready to stay.''\n—Kai'Sa, 'THE BADDEST'","Hechizo",[],["Targón"],"ÉPICA"],"03MT017":["Sello del Mensajero","Creo 5 Mensajeros en tu mazo.","","''El tiempo transcurre; los cielos vuelven a rotar. La Serpiente se hace a un lado y el Mensajero toma su lugar en las alturas. Una temporada de abundancia nos espera...'' —Sacerdotisa Lunari","Hechizo",[],["Targón"],"RARA"],"03MT025":["Fragmentos de la Montaña","Lleno tu mano con Gemas.","","''Si giras una gema de la forma adecuada, resplandecerá bajo la luz. Como la vida de los mortales, cada una tiene su propio fuego interior''. —Taric","Hechizo",[],["Targón"],"ÉPICA"],"03MT216":["Sombras Celestiales","Cuando me invocan, restablezco 2 de maná de hechizos si Contemplas una carta con Anochecer.","","''Madre Luna, permíteme recordar que,\naunque no haya nadie conmigo,\ntus hijos bailan en las alturas,\ny que no estoy en soledad''.\n—Oración Lunari","Unidad",[],["Targón"],"COMÚN"],"03MT012":["Juez de la Cima","Cuesto 1 menos por cada vez que hayas fijado como objetivo o apoyado a aliados en esta partida.","","El Juez es la prueba final de la montaña, pues solo el guardián puede ver más allá de las acciones y del espíritu de aquellos que osan escalarla.","Unidad",[],["Targón"],"ÉPICA"],"03MT085":["Silencio","Silencio a una unidad en esta ronda.","","''Conocerán la serenidad''. —Soraka","Hechizo",[],["Targón"],"RARA"],"03MT081":["Visitantes de la Montaña","Al apoyar: Otorgo +2|+2 al aliado que apoyo. Si tiene Apoyo, le otorgo +2|+2 al aliado al que apoya y continúo por cada aliado que apoyo en sucesión.","","Toda persona que se aventura a escalar el Monte Targón tiene sus motivos para hacerlo. Algunos lo hacen para probarse ante los ojos de sus camaradas. Otros, para probarse algo a sí mismos.","Unidad",[],["Targón"],"ÉPICA"],"03MT030":["Miraestrellas","Cuando curas a un aliado herido, le doy Evasión en esta ronda.","","''Las estrellas permanecen a nuestro lado por mucho tiempo. Luego de que las cuidamos, las regresamos a los cielos en un repentino resplandor de luz de estrellas... y tambaleantes pezuñas''.","Unidad",[],["Targón"],"RARA"],"03MT088":["Soldado Solari","Amanecer: Recibo +1|+1 en esta ronda.","","A medida que el sol lo calentaba, mantuvo vigilancia en la prisión de los herejes, ignorando las suaves plegarias que rápidamente se transformaban en un amargo silencio.","Unidad",[],["Targón"],"COMÚN"],"03MT033":["Abuelo Rumul","Al jugar: Otorgo +0|+4 a 2 aliados.","","''¿Oyes eso, Osu? ¡Son campanas! ¡El abuelo volvió!''. —Illi, Pastora de Estrellas","Unidad",[],["Targón"],"RARA"],"03MT035":["Cascada Pálida","Doy +1|+1 a un aliado en esta ronda.\nAnochecer: Roba 1.","","''Bajo el manto de la noche y protegida por la pálida luna''. —Diana","Hechizo",[],["Targón"],"COMÚN"],"03MT075":["Sacerdotisa Lunari","Anochecer: Convoco.","","''Oh, estrellas en el firmamento... viajando como multitudes de peregrinos por la inmensidad de la noche. Quédense un rato con nosotros, cuéntennos lo que han vivido''. —Los elogios de la noche","Unidad",[],["Targón"],"RARA"],"03MT218":["Hueso Estelar","Si Contemplas una carta Celestial, creo 1 El Mensajero en tu mazo y le otorgo +1|+1 a los aliados Celestiales en todas partes.","","''Que el Mensajero juegue,\ny que su alegría\nilumine las estrellas''.\n—Oración Lunari","Hechizo",[],["Targón"],"ÉPICA"],"03MT074":["Burbuja Dormilona","Lanzo Aturdir a un enemigo y creo 1 Estrella Saltarina con Fugaz en la mano.","","''¡Es hora de la siesta! Una chispiérnaga, dos chispiérnagas, tre... ¡¿Qué es eso de por allá?!''. —Zoe","Hechizo",[],["Targón"],"RARA"],"03MT072":["Tizón Fundido","","","Incontables desafíos esperan a quienes ascienden el Monte Targón. Mientras algunos de ellos, como el ascenso infinito, drenan la fuerza de los aspirantes, otros peligros actúan de forma mucho más inmediata.","Unidad",["DRAGÓN"],["Targón"],"COMÚN"],"03MT039":["Poróptero","","","En el espacio, nadie puede oír tus grititos.","Unidad",["PORO"],["Targón"],"COMÚN"],"03PZ019":["Porobot Parchado","Mientras estoy en la mano, tengo una palabra clave aleatoria que cambia en cada ronda. Cuando me invocan, recibo esta palabra clave.","","No es tan apapachable como el real, pero es IGUAL de lindo.","Unidad",["PORO"],["Piltóver y Zaun"],"RARA"],"03PZ005":["Bot Balístico","Al Inicio de la ronda: Creo 1 Ignición en la mano.","","El sujeto pidió que solo dejáramos intacta su mente pues, según dijo, ''es allí donde conservo todos mis rencores''.\n—Registro del aumentador, entrada 1011","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"03PZ004":["Rayo Mortífero - Mk1","Inflijo 1 de daño a una unidad y creo 1 Rayo Mortífero - Mk2 en las primeras 3 cartas de tu mazo.","","''¡Hoy demostré con éxito que la energía radiante se puede concentrar en un rayo único y poderoso! Con las mejoras adecuadas, este rayo puede ser una herramienta de precisión incomparable, pero aún queda mucho por hacer''.\n—Anotaciones de diseño de Viktor","Hechizo",[],["Piltóver y Zaun"],"RARA"],"03PZ003":["Viktor","Cuando me invocan o al Inicio de la ronda: Creo 1 Mejora HexCore en la mano.","Si jugaste 7+ cartas creadas.","''Ya presenciaste suficientes desgracias, querida ciudad de Zaun, y llegó la hora de cambiar eso. Y al igual que con todos los grandes avances, este comenzará contigo''.","Unidad",[],["Piltóver y Zaun"],"Campeón"],"03PZ010":["Imitador Mecanizado","Al atacar: Recibo todas las palabras claves de los aliados.","","''Soy igual a ti... pero mejor''.","Unidad",[],["Piltóver y Zaun"],"ÉPICA"],"03PZ022":["Give It All","Aumento el poder y la vida de todos los aliados al del aliado con mayor poder o vida.\nOtorgo las palabras clave de aliado a todos los aliados.","","''I know I know\nYou want some more\nIf you ready let's go\nGiving it all.''\n—Seraphine, 'MORE'","Hechizo",[],["Piltóver y Zaun"],"ÉPICA"],"03PZ014":["Creaciones Deliberadas","Creo 1 Mecainventor Armado, Bot Balístico o Miaudroide en la mano y le otorgo +1|+1.","","''La racionalidad y la elección separan a la humanidad de sus instintos animales más básicos''. —Viktor","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"03PZ013":["Mejora Iterativa","Elige un seguidor y creo una copia suya en la mano con +1|+1.","","''La automejora es un juego donde eres el héroe y el villano: debes esforzarte mucho y puede que hasta pienses que ya ganaste. Sin embargo, al final, siempre serás tú quien se interponga en tu camino''. —Imitador Mecanizado","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"03PZ025":["Pruebas de Estrés","Elimino Fugaz de todas las cartas en tu mano. Cuando me descartan, roba 1 carta con Fugaz.","","''De hecho, es muy sencillo: reemplacé el marco de acero por una aleación más resistente que yo misma inventé y alejé los circuitos de las articulaciones para evitar que los sistemas hicieran cortocircuito. Facilito''. —Jefa Mecánica Zevi","Hechizo",[],["Piltóver y Zaun"],"RARA"],"03PZ012":["Mecainventor Armado","","","''¡Muy bien! ¡Un nuevo brazo! Siempre quise uno de esos. ¿Qué me pongo después? ¿Ruedas gravitacionales en vez de piernas? ¿Electrocinturones? ¿DIENTES METÁLICOS? De hecho, deja intacto mi rostro. Me gusta mi rostro''.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"03PZ020":["Fundición HexCore","Inicio de la ronda: TODOS los jugadores roban 1.","","''Que digan lo que quieran sobre mis métodos, pero mi progreso es innegable... ¡La luz del conocimiento es un faro que ilumina la oscuridad de la ignorancia!''. —Viktor","Hito",[],["Piltóver y Zaun"],"RARA"],"03PZ002":["Miaudroide","","","''¡Pasé años en la Academia de Piltóver solo para que mi tecnología fuera catalogada como 'demasiado peligrosa', y mi mera presencia tildada de 'demasiado tierna'! Miauré a Zaun, el único lugar donde al menos una mente excelsa comparte mis ambiciones...''.","Unidad",["GATO"],["Piltóver y Zaun"],"RARA"],"03PZ011":["Réplica","Inflijo 3 de daño a una unidad o destruyo un Hito.","","''Este rayo de luz guiará nuestra marcha hacia Piltóver. ¡Nada se interpondrá en nuestra gloriosa evolución!''. —Viktor","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"03PZ017":["Improbulador Trirrayo","Inflijo 1 de daño a una unidad e invoco un seguidor aleatorio de costo 1. Cuando estoy en tu mano, aumentan ambos en 1 si juegas una carta de costo 3.","","''... a la una... a las dos... ¡¡Y A LAS TRES!! Santas tuercas... ¡¿otro resultado imprevisible?!''. —Heimerdinger","Hechizo",[],["Piltóver y Zaun"],"ÉPICA"],"03PZ018":["Cañón Poro","Para usarme, descarta 1.\nCreo 2 Poros Audaces en tu mano.","","Dos suaves formas arqueadas caen grácilmente sobre la multitud emocionada, dejando a su paso una nube de pelo y el tenue aroma de pan recién horneado.","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"03SI004":["Sombras al Acecho","Elige un seguidor de las primeras 4 cartas de tu mazo.\nRóbalo y coloca el resto en tu mazo para crear una copia idéntica con Endeble en tu mano.","","''Vayan... rodéenlos...''. —Nocturne","Hechizo",[],["Islas de la Sombra"],"RARA"],"03SI001":["Acechadora Sempioscura","Anochecer: Creo una copia mía en la mano.","","''Al principio solo eran un par de ojos y una voz solitaria, chillando en las sombras. Pero cada vez que volvía a ver eran más. Más irritados, más ruidosos. Tan pronto como vi el Colmillo, eché a correr''. —Saqueador de Colmillo Ballena","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"03SI018":["Gula","Mato a un aliado con Último Aliento para invocar un seguidor de tu mazo que cueste 1 más.","","''¡HORA DE LA CENAAA!'' —Carnicero voraz","Hechizo",[],["Islas de la Sombra"],"RARA"],"03SI012":["Pasaje Inmerecido","Lanzo Aniquilar a todas las unidades que hayan sido invocadas, pero no usadas, en esta ronda.","","''Por supuesto, la muerte está presente en Demacia. Vemos cómo se lleva a quienes amamos y sabemos que, algún día, nos llevará a nosotros. Pero en estas islas... casi puedo saborearla. La siento colmar mis pulmones con cada respiro; la siento susurrarme al oído. No es una mera abstracción: está aquí y ahora, sentada a mi lado... y nos llevará a todos''.\n—Notas del historiador Jens Tommen","Hechizo",[],["Islas de la Sombra"],"RARA"],"03SI014":["Sombras Invasivas","Otorgo +2|+2 y Endeble a TODOS los aliados en tu mazo y en tu mano.","","''Ya sea mental o físicamente, me temo que las pesadillas que habitan las Islas de la Sombra nos quebrarán a todos, y harán que la locura reine en el mundo... para siempre''.\n—Notas del historiador Jens Tommen","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"03SI016":["Go Hard","Dreno 1 de una unidad y creo 2 copias de Go Hard en tu mazo. Cada tercera vez que esto pase, transformo todas las copias de mí en todas partes en Pack Your Bags.","","''We go hard, 'til we get it, get it\nWe go hard, we so in it, in it\nWe Pop Stars (Pop Stars), only winning, winning now\nAin't nobody bringing us down, down, down, down.''\n—Evelynn, 'POP/STARS'","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"03SI007":["Manto de Oscuridad","La próxima vez que invoques a un aliado en esta ronda, le doy +1|+0 y Escudo Antihechizos en esta ronda.","","''Tan pronto como abandones Colmillo, sentirás esos dedos ligeros como la lluvia rozando tu nuca. Estas criaturas ni se mueven cuando te les acercas. No le temen ni a mi antorcha ni a mi espada. No le temen a nada. Son unas cosas horrendas''. —Saqueador de Colmillo Ballena","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"03SI005":["Nocturne","Anochecer: Otorgo Vulnerable a un enemigo y doy -1|-0 a los enemigos en esta ronda.","Si atacaste con 5+ aliados con Anochecer o Temible.","''Parece que, cuando suficientes almas se agitan, es capaz de cruzar a nuestro plano. Solo la esperanza puede enviar aquella monstruosidad de vuelta a su reino... pero la esperanza aquí murió hace mucho tiempo, con el aliento final de una reina, y con el grito eterno de un rey''.\n—Notas del historiador Jens Tommen","Unidad",[],["Islas de la Sombra"],"Campeón"],"03SI006":["Bestia Apocalíptica","Anochecer: Dreno 2 del nexo enemigo.","","Con cada noche que pasaba, la extenuación de los viajeros era mayor. Dormir no les traía reposo y sus sueños eran vívidos; lejos de brindar un descanso, el sueño succionaba cada gota de vida de sus huesos.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"03SI015":["Espectro Fastidioso","Último Aliento: Creo 2 copias mías en el mazo enemigo.","","Aunque la mayoría de los espíritus en las Islas de la Sombra son criaturas horrendas y malsanas, un puñado de ellos solo son... bueno... bastante molestos.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"03SI003":["Observador Estigio","Anochecer: Recibo +2|+0 y Temible en esta ronda.","","Conforme el sol se oculta, los horrores de este lugar despiertan... Espera y verás...","Unidad",["AVE"],["Islas de la Sombra"],"COMÚN"],"03SI002":["Horror Inenarrable","Lanzo Drenar y absorbo 1 de cualquier objetivo.\nAnochecer: Creo una carta aleatoria con Anochecer en tu mano.","","''Cada día que pasa drena mi espíritu; el vigor que me hizo buscar este lugar se esfuma. La taberna Colmillo Ballena está llena de individuos con el semblante cadavérico, sin más ánimo que el de seguir existiendo. Y temo que, mientras más tiempo permanezca aquí, más similar a ellos me volveré''.\n—Notas del historiador Jens Tommen","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"03SI010":["Jinete del Ocaso","Anochecer: Recibo +1|+0 por cada vez que hayamos activado Anochecer en esta partida.","","Cuando el sol se pone, la noche despliega sus oscuras alas y drena los últimos rastros de esperanza del día.","Unidad",[],["Islas de la Sombra"],"RARA"],"03SI013":["Nieblas Etéreas","Invoco 1 Espectro de la Niebla.","","Los Espectros de la Niebla se mueven a través de los planos de la realidad. Su presencia pasa desapercibida a los ojos de los mortales, pero traen penurias a todo aquel que se cruce en su camino.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"03IO025":["Ráfaga de Puños","Otorgo +1|+0 y Ataque Rápido a un aliado. Si ya lo tiene, le otorgo Ataque Doble.","","''Golpea mucho, golpea rápido y golpea fuerte''. —Cuernos del Dragón","Hechizo",[],["Jonia"],"RARA"],"03IO017":["¡Pix!","Al apoyar: Doy +2|+1 al aliado que apoyo en esta ronda.","","''Pix es GRANDIOSO, es pequeño, genial y maravilloso.\n¡Le encantan las zarigüeyas y le gusta todo lo... sensageniagüeyanial!'' —Lulu","Unidad",["FEÉRICO"],["Jonia"],"COMÚN"],"03IO008":["¡Capricho!","Transformo a un seguidor en Ardilla con 1|1 y le lanzo Silenciar en esta ronda.","","''¡Adoribus!''. —Lulu","Hechizo",[],["Jonia"],"COMÚN"],"03IO001":["Niña de las Flores","Cuando recibo apoyo, recibo +2|+0.","","Todos quieren un familiar, pero nadie está preparado para la responsabilidad que eso conlleva. Tienes que llevarlos de paseo, cerciorarte de que tengan una dieta balanceada, que hagan ejercicio... Es mucho trabajo.","Unidad",["FEÉRICO"],["Jonia"],"COMÚN"],"03IO019":["Voluntad Singular","Elige un aliado. Lanzo Retirada a TODAS las demás unidades e Hitos.","","''Mi camino es solitario''. —Monja Solitaria","Hechizo",[],["Jonia"],"ÉPICA"],"03IO002":["Lulu","Al apoyar: El aliado que apoyo aumenta hasta 4|4 en esta ronda.","Si todos los aliados han recibido Apoyo 3+ veces.","''¡No te preocupes, Pix! ¡Saldremos del claro y haremos que TODO sea adoribus! ¡¿Estás listo?!''.","Unidad",["YORDLE"],["Ciudad de Bandle","Jonia"],"Campeón"],"03IO011":["Ardilla Musculosa","Al golpear: Duplico mi poder.","","Su secreto es beber batidos de polvo de bellota cuatro veces al día.","Unidad",["FEÉRICO"],["Jonia"],"RARA"],"03IO009":["Hadosos Sabrosos","","","Energía: 104 kJ (25 kcal), Carbohidratos: 5.88 g, Azúcares: 3.53 g, Fibra dietética: 3 g, Grasa: 0.18 g, Proteína: 0.98 g, Agua: 92 g...","Unidad",["FEÉRICO"],["Jonia"],"COMÚN"],"03IO003":["Guía Feérico","Al jugar: Otorgo Evasión a un aliado.","","''¡Silencio! ¡Por aquí! Hay que ir por la izquierda tras pasar la casa del árbol caminante, y por la derecha tras pasar las flores parlantes. ¿Me escuchaste, Lulu? ¿Lulu? ¡LULU! NO... les des... de... comer. No lo hagas''.","Unidad",["YORDLE"],["Jonia"],"RARA"],"03IO007":["Trevor Sueñoprofundo","Al apoyar: Creo 1 Murmuduende atacante con las estadísticas del aliado que apoyo.","","Se supone que debes seguir tus sueños, no manifestarlos mediante conjuros fortuitos murmurados mientras flotas durmiente por un antiguo bosque mágico. Es decir, ¡VAMOS!","Unidad",["YORDLE"],["Jonia"],"ÉPICA"],"03IO010":["Bruja Joven","Al apoyar: Doy Ataque Rápido y +1|+0 al aliado que apoyo en esta ronda.","","Sir Ribery Montague dejó su hogar atrás con la esperanza de lograr una gran hazaña o congraciarse con una casa reconocida. Sin embargo, el destino lo llevó a un bosque bandleciano donde la joven Bri rápidamente lo transformó en una rana. Desde entonces, es ELLA quien lo lleva a él en SUS aventuras. ¡Pobre Sir Ribery!","Unidad",[],["Jonia"],"COMÚN"],"03IO020":["¡Refutizar!","Detengo un hechizo Rápido o Lento que cueste 3 o menos.","","''No hagas eso, ¡torpe esponjoso! ¡Le harás daño a los antílopes!''. —Lulu","Hechizo",[],["Jonia"],"RARA"],"03IO022":["Go Get It","Lanzo Retirada a un aliado para invocar una copia idéntica con Endeble en su lugar. Reduzco su costo a 0 en esta ronda.","","''More\nKnow I got it,\nSo here you go,\nYou look like you could use some more.''\n—Akali, 'MORE'","Hechizo",[],["Jonia"],"ÉPICA"],"03IO018":["Cuidador Peludo","Cuando recibo apoyo, recibo +0|+3 en esta ronda.\nAl apoyar: Doy +3|+0 al aliado que apoyo en esta ronda.","","Las hadas moradas son criaturas encantadoras y todos los que las encuentran quieren cuidar de ellas. Bueno, casi todos.","Unidad",["YORDLE"],["Jonia"],"RARA"],"03DE008":["Teniente de la Guardia Dracónica","Cuando me invocan, si Contemplas un Dragón, recibo Desafío.","","''Cuando perdí a mis compañeros de armas en Wrenwall, creí que también había perdido mi determinación... Sin embargo, parece que no hay nada que una pelea no pueda agitar en un viejo soldado''.","Unidad",[],["Demacia"],"COMÚN"],"03DE001":["Confrontar","Otorgo Desafío a un aliado.\nSi es un Dragón, roba 1.","","''¡Nadie se nos escapará!''. —Shyvana","Hechizo",[],["Demacia"],"COMÚN"],"03DE015":["Protector Pétreo","TODOS los hechizos cuestan 1 más.","","Lo que comenzó siendo un burdo y amorfo bloque de petricita, se transformó en algo más en las hábiles manos de quien lo esculpió. Es entonces cuando una obra de arte comienza a cobrar vida.","Unidad",[],["Demacia"],"RARA"],"03DE006":["Dragón Chirriante","","","Todas las criaturas cuidan con uñas y dientes a sus crías; sin embargo, muy pocas están tan bien equipadas para lidiar con potenciales amenazas como los dragones.","Unidad",["DRAGÓN"],["Demacia"],"COMÚN"],"03DE025":["Aliento Fundido","Un aliado con Furia Golpea a los 2 enemigos Más débiles uno después del otro.","","Durante siglos, los demacianos solo supieron de la furia de los dragones por medio de las leyendas. Pero eso cambió en Wrenwall.","Hechizo",["ELEMENTAL"],["Demacia"],"RARA"],"03DE002":["Golpe Metralla","Un aliado y un enemigo se Golpean entre sí. Luego, si el aliado es un Dragón, lo curo 5.","","Cuando el caballero y el dragón se separaron, el jadeante y herido lagarto pareció recobrar el vigor. Ya había olido la sangre, y quería más.","Hechizo",[],["Demacia"],"RARA"],"03DE011":["Shyvana","Al atacar: Recibo +1|+1 en esta ronda.","Si los dragones aliados infligieron 16+ de daño.","''Su naturaleza la convierte en nuestro enemigo más odiado; su raza solo ha traído sufrimiento a Demacia. Por otro lado, el Príncipe confía en ella y parece que tiene todas las características de un soldado decidido y un aliado valioso. Solo espero que no traicione la confianza que depositamos en ella''.\n—Página de los relatos del teniente Jerik sobre Wrenwall.","Unidad",["DRAGÓN"],["Demacia"],"Campeón"],"03DE003":["Vigilante de la Guardia Dracónica","Cuando me invocan, si Contemplas un Dragón, lanzo Preparar.","","''¿Qué es eso en la distancia? ¿Acaso es...?''.\n''Eso parece''.\n''¿Cómo puedes saberlo?''.\n''Oh, es imposible no reconocerlos. Cubre tus oídos, porque habrá mucho ruido''. —Anden y Yessenia","Unidad",[],["Demacia"],"RARA"],"03DE013":["Mamá Dragón al Acecho","","","''¡Cuidado, soldados! Si tenemos cuidado al pisar y no perturbamos el nido, haremos que la mamá dragón se quede a la defensiva. Si la hacemos enojar más... mejor prepárense para correr''. —Anden Mayne, ovólogo","Unidad",["DRAGÓN"],["Demacia"],"COMÚN"],"03DE005":["Ovólogo","Cuando me invocan, creo un Dragón aleatorio en la mano.","","Huevo de dragón (Dragón Chirriante, draco murmurationis) \nUbicación: El investigador Anden Mayne lo recuperó en una expedición. \nNotas: Periodo de gestación desconocido. El proceso de incubación continúa. Se observaron movimientos recientes dentro del cascarón. El huevo responde al calor, la luz y los golpes de martillo. \n—Notas de Anden Mayne, ovólogo","Unidad",[],["Demacia"],"COMÚN"],"03DE007":["Kadregrin el Infernal","Cuando me invocan, otorgo +4|+4 a otros Dragones aliados en todas partes.","","Cuando Demacia soportó una repentina oleada de ataques de dragones, Shyvana sabía que Kadregrin el Infernal era el responsable. Otros dragones, inspirados por su naturaleza astuta y poderosas flamas, aterrorizaron a los demacianos. ","Unidad",["DRAGÓN"],["Demacia"],"ÉPICA"],"03DE012":["Por los Caídos","Cuando invocas una carta Élite, cuesto 1 menos.\nInvoco 1 Vanguardia Valerosa por cada aliado que haya muerto en esta ronda.","","''Si un soldado cae, otro debe tomar su lugar. Nuestro estandarte jamás debe tocar el suelo''. —Garen","Hechizo",[],["Demacia"],"ÉPICA"],"03DE014":["Visión Aguda","Doy +1|+2 y Visión Aguda a un aliado en esta ronda.","","Todo aquel que se atreva a atravesar los muros de Demacia será recibido por sus tropas... cautas y bien armadas.","Hechizo",[],["Demacia"],"COMÚN"],"03FR020":["Tierras Pielmarcadas","Cuando un aliado sobrevive al daño, le otorgo +1|+0 y Dureza.","","Existen muchos sitios de honor para la Garra Invernal, pero uno de los más importantes son las Tierras Pielmarcadas. Allí convierten los navíos de guerra dañados que regresaban de sus incursiones en salones de reunión para sus guerreros y su gente. Estos barcos representan muy bien a la tribu que los construyó: son resistentes y adaptables.","Hito",[],["El Fréljord"],"ÉPICA"],"03FR007":["Trol Carroñero","Cuando me invocan, si Contemplas una carta de costo 8+, recibo +3|+0.","","El explorador se arrodilló junto a un trozo de tela enterrado en la nieve. El olor a humo y sudor humano y aún se sentía en el aire frío.\nDesenterró aquel andrajo y observó uno de sus extremos: tenía un talismán colgando, opacado por el cielo tormentoso. Avarosano. ","Unidad",[],["El Fréljord"],"COMÚN"],"03FR004":["Rugido Revitalizador","Elige una unidad en la mano para revelarla. Curo tu nexo el equivalente a su poder.\nCon Iluminación: Reduzco su costo a 0.","","''Los troles adultos poseen pieles gruesas y huesos anchos que sanan a una gran velocidad, características que los hacen terribles e incansables adversarios. Se deben abatir rápido o se recuperan y vuelven por más''. —Arquero Avarosano","Hechizo",[],["El Fréljord"],"RARA"],"03FR017":["Augurio de los Antiguos","Al jugar: Si Contemplas una carta de costo 8+, otorgo Arrollar y Regeneración a un aliado.","","Se dice que a muy pocos troles se les enseñan los cantos de los Antiguos; sin embargo, aquellos que los aprenden pueden invocar a sus antepasados para otorgarle a sus hermanos una fuerza excepcional.","Unidad",[],["El Fréljord"],"RARA"],"03FR006":["Trundle","Cuando me invocan, creo 1 Columna de Hielo en tu mano.","Si te he visto jugar Columna de Hielo.","Una a una, las antorchas se encendieron por el camino, revelando lo que allí se escondía. Había decenas de troles, quizá cientos. Cada uno de ellos era corpulento, imponente y letal.\n''Preguntaré una vez más'', gruñó Trundle, mientras Hueso Gélido reposaba sobre su hombro. ''¿Se rendirán o tendré que partirles el cráneo?''.","Unidad",[],["El Fréljord"],"Campeón"],"03FR008":["Derrumbe de Hielo ","Doy -3|-0 a todas las unidades en esta ronda. Inflijo 3 de daño a TODAS las unidades.","","''¡Entiérrenlos vivos!''. —Trundle","Hechizo",["ELEMENTAL"],["El Fréljord"],"ÉPICA"],"03FR002":["Canto de Trol","Doy +0|+2 a un aliado para dar -2|-0 a un enemigo en esta ronda.","","Los cánticos de los troles varían según el grupo que los cante y, aunque son ininteligibles, todos son terroríficos cuando los escuchas. ","Hechizo",[],["El Fréljord"],"COMÚN"],"03FR011":["Uzgar, el Antiguo","","","Lo sintieron antes de oírlo. El suelo retumbó bajo sus pies. Luego, lo escucharon: era como un trueno a la distancia, acercándose.\nCon sus ojos muy abiertos, Meyrick alzó la cabeza y escuchó.\n''¿Qué es eso?'', susurró Anya en tono acuciante. Sacó su arco, pero Meyrick ya estaba corriendo a toda prisa de vuelta al camino. \n''¡CORRE!''","Unidad",[],["El Fréljord"],"RARA"],"03FR005":["Trol Asolador","Cuando me invocan, si Contemplas una carta de costo 8+, recibo Regeneración.","","Cuando estuvieron entre las chozas avarosanas, llamaron a Hgar. Con una carcajada, alzó su arma, Cortahielo, mostrando que estaba lista para reducir sus casas de madera a astillas.","Unidad",[],["El Fréljord"],"COMÚN"],"03FR018":["Llamado de la Naturaleza","Roba todos los Yetis, Poros y Elnuks de las primeras 4 cartas de tu mazo. Después, coloco el resto en tu mazo.","","''... fue entonces cuando un ELNUK ENORRRME llegó VOLANDO desde unos árboles con un porito chiquitito en su lomo. También había un YETI, que era bastante AMIGABLE porque solo quería jugar con sus amigos. Todos bajaron de la montaña corriendo, GRUÑENDO y RUGIENDO. Fue entonces cuando...''. —Ingvar la Joven","Hechizo",[],["El Fréljord"],"COMÚN"],"03FR010":["Rostros de los Antiguos","Inicio de la ronda: Si Contemplas una carta de costo 8+, doy una gema de maná adicional en esta ronda.","","''Levántense, Antiguos. Levántense.\nGobiernen el hielo; sometan los cielos.\nLevántense, Antiguos. Levántense.\nDennos vigor, y a ellos, extinción''.\n—Canto de Trol","Unidad",[],["El Fréljord"],"COMÚN"],"03FR019":["Voces de los Antiguos","Doy 2 gemas de maná vacías.\nRoba cada carta que cueste 8+ de las primeras 5 cartas de tu mazo. Después, coloco el resto en tu mazo.","","Por generaciones, los pobladores avarosanos oyeron extraños e inexplicables sonidos entre el bullicio de las blancas tormentas. Con el tiempo, tras aventurarse mucho más al norte, por fin descubrieron la fuente: antiguos monolitos de troles, los cuales susurraban en antiguas lenguas conforme el viento soplaba a través de sus enormes fauces.","Hechizo",[],["El Fréljord"],"COMÚN"],"03FR025":["Obsequios de Trol","Otorgo Regeneración a un aliado. Si ya lo tiene, le otorgo +2|+2.","","Apiádate de aquellos que ven la promesa de la victoria en la sangre de un trol.","Hechizo",[],["El Fréljord"],"RARA"],"03FR022":["Feel The Rush","Invoco 2 campeones distintos aleatorios de tu mano y mazo. Aumento sus estadísticas hasta 10|10.","","''We got it all in our hands now\nSo can you handle what we're all about?''\n—Ahri, 'POP/STARS'","Hechizo",[],["El Fréljord"],"ÉPICA"],"04PZ001":["Ekko","Al golpear: Creo 1 Truco Temporal con Fugaz en la mano.","Si usaste Predecir 4+ veces. Cuando subo de nivel, creo 3 Cronorrupturas en tu mazo.","No se trata de cuánto tiempo tienes, sino de cómo lo usas.","Unidad",[],["Piltóver y Zaun"],"Campeón"],"04PZ005":["Cloaquero Chireano","Cuando invocas otra copia de Cloaquero Chireano, lanzo Aniquilar sobre mí y transformo a los Cloaqueros Chireanos aliados en Pandillas del Sumidero en todas partes.","","Los primeros mineros zaunitas en descubrir a los chireanos creyeron que eran criaturas simples y tímidas; pero al pasar de los años, y a medida que se fueron sintiendo cómodos con los humanos, lentamente fueron revelando sus estrechos vínculos sociales y su entendimiento nato de la tecnología.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"04PZ014":["Sobrecarga Productiva","Para usarme, gasta todo tu maná. Invoco Torretas aleatorias, cuyo costo total es igual al del maná que gastaste.","","''¡¿Que no hay recursos suficientes?! Yo armé mi primer artilugio mecánico con partes de chatarra de reloj y un capacitador térmico oxidado. ¡Uno siempre debe aprovechar lo que tiene a la mano!''. —Heimerdinger","Hechizo",[],["Piltóver y Zaun"],"RARA"],"04PZ003":["Rebobinador de Tiempo","Para jugarme, descarta 1.\nInflijo 1 de daño a un enemigo o al nexo enemigo. Luego, inflijo 1 de daño a otro.","","''¡Cuidado!''. —Ekko","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"04PZ011":["Decisión Tomada","Roba 1.\nCreo 1 Convergencia Paralela en tu mazo.","","''Dividiendo las líneas temporales...''. —Ekko","Hechizo",[],["Piltóver y Zaun"],"ÉPICA"],"04PZ002":["Felino Fallido","Cuando me invocan, creo 1 Cristal Hexite en las últimas 10 cartas de tu mazo.","","''PERO MI PLAN... ¡MIAUUUU!''.","Unidad",["GATO"],["Piltóver y Zaun"],"RARA"],"04PZ020":["Cambiabot Defectuoso","Al jugar: Intercambio mis estadísticas con las de otra unidad.","","''¿Un nuevo bot tragamonedas? Creí que la planta donde los fabricaban había cerrado hace varios años''.\n''Eso creía yo también. Escuché algo sobre 'bombas de rebote' y una 'conflagración imprevista''.\n''Ah''.\n''... ¿Jugamos?''\n''Por supuesto''.\n—Mecenas Zaunitas","Unidad",[],["Piltóver y Zaun"],"RARA"],"04PZ013":["Elnuk Voluntario","Cuando me invocan, creo un elnuk aleatorio en las primeras 6 cartas de tu mazo.","","''DE ACUERDO, PEQUEÑÍN, QUÉDATE SENTADO MIENTRAS LE DOY VUELTA A ESTA BARATIJA. ¡BUM! ¡JA! ¡LOS ELNUKS MANDAN! Vamos a necesitar más césped... y más espacio''. —Perfeccionista Pragmática","Unidad",["ELNUK"],["Piltóver y Zaun"],"RARA"],"04PZ010":["Líneas Temporales Concurrentes","Otorgo seguidores en tu mano \"Cuando me juegues, elige 1 de 3 seguidores de mi costo y me transformo en él\".","","''Jugaremos bajo MIS reglas''. —Ekko","Hechizo",[],["Piltóver y Zaun"],"ÉPICA"],"04PZ016":["Babúm Babuino","Cuando me invocan, creo 1 ¡Mascafuegos! en la mano.","","Jinx solía trabajar con un proveedor más convencional... hasta que ambos tuvieron un pequeño desacuerdo: él creía que ser lanzado por la ventana no era buena idea, pero Jinx decidió que sí.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"04PZ007":["Truco Temporal","Lanzo Predecir. Luego, roba 1.","","''El futuro es mi creación...''. —Ekko","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"04PZ012":["Perfeccionista Pragmática","Al jugar: Lanzo Predecir. Creo 3 copias de la carta elegida en tu mazo.","","''Kay es increíble. Es una firme creyente de que la práctica hace al maestro... ¡y vaya que le encanta practicar!''. —Shomi","Unidad",[],["Piltóver y Zaun"],"RARA"],"04PZ017":["Evolución Gloriosa","Tus cartas cuestan -1, tienen Aumento, son creaciones de Evolución Gloriosa y ahora son Tecnología.","","''El progreso lo es todo. Traeré el futuro a esta ciudad, esté lista o no''. —Viktor","Hechizo",[],["Piltóver y Zaun"],"ÉPICA"],"04PZ015":["Adaptatrón 3000","Cuando invocas una Tecnología, compartimos palabras clave.","","\"'¡Ah, sí! ¡El Adaptatrón 3000! ¡Adaptable, ingenioso Y con un aspecto genial! Si pudiera hablar, seguro que compartiríamos MUCHAS COSAS''. —Heimerdinger  ","Unidad",["TECNOLOGÍA"],["Piltóver y Zaun"],"ÉPICA"],"04PZ004":["Tablista","Si me ves en una Predicción, invócame.","","''Shomi es GENIAL con ese deslizador. Una vez vi cómo pasó de un deslizamiento de lado a uno trasero, y luego, ¡se lanzó por el aire y realizó una voltereta triple de tres puntos! O algo así. Mira, el punto es que es excepcional, ¿sí?''. —Perfeccionista Pragmática","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"04BW002":["Mondahuesos","Un aliado Golpea a un enemigo. Luego, se posiciona como la primera carta de tu mazo.","","''Un regalito de despedida...''. —Pyke","Hechizo",[],["Aguasturbias"],"ÉPICA"],"04BW007":["Pez Jaull","Al jugar: Cada aliado Acechante Golpea a un enemigo aleatorio.","","''No hay nada mejor que un pez jaull para mostrarte en quién puedes confiar... y a quién puedes matar''. —Pyke","Unidad",["ACECHANTE"],["Aguasturbias"],"ÉPICA"],"04BW001":["Nariz de Martillo Aletarroja","Al jugar: Otorgo Vulnerable a un enemigo.","","Cuando los nariz de martillo rompen la quilla de un barco, parecen hacerlo por pura diversión. Si bien casi nunca devoran a los miembros de la tripulación que caen al agua, son las criaturas que llegan después las que se dan el festín.","Unidad",["ACECHANTE"],["Aguasturbias"],"COMÚN"],"04BW005":["Pyke","Si Acecho, me transformo en Muerte desde lo Profundo.","Si Pykes aliados infligieron 15+ de daño.","''... las visiones volvieron. Veo la desesperación en sus ojos mientras el pez jaull cierra sus fauces con su cuerpo dentro. Tratamos de jalar, pero el barco era muy pequeño... y la bestia era enorme. No tenía opción, así que corté su soga. Tenía que hacerlo''.\n—Carta ensangrentada","Unidad",["ACECHANTE"],["Aguasturbias"],"Campeón"],"04BW010":["Arpón Cazamonstruos","Pillaje: Cuesto 2 menos.\nInflijo 5 de daño a una unidad.","","''¡Ya golpeamos a la bestia, compañeros! Ahora, ¡apuñálenla hasta que deje de moverse y las aguas se tiñan de sangre!''. —Capataz Cercenadora","Hechizo",[],["Aguasturbias"],"COMÚN"],"04BW014":["En Fila","Invoco 1 Barril de Pólvora.\nCreo 1 Derríbenlos en la mano.","","''Se hizo como lo pidió, capitán. La chispita que le di hará que responda seguro\". —Grumete del Heraldo","Hechizo",[],["Aguasturbias"],"COMÚN"],"04BW011":["Dados Trucados","En la siguiente ronda, si dañas el nexo enemigo, Hurta 1.","","''¿Qué estás dispuesto a apostar?''. —Tahm Kench","Hechizo",[],["Aguasturbias"],"ÉPICA"],"04BW015":["Tiburoncito","","","''Puede que no parezcan la gran cosa, pero adoran el sabor de la sangre. Si están cerca de ti, sabrán dónde buscarla tan pronto crezcan. Mejor usa tus guantes''. —Cazadores de jaulls","Unidad",["ACECHANTE"],["Aguasturbias"],"COMÚN"],"04BW003":["Cardumen de Quijafortes","Al jugar: Inicio un ataque gratis.","","''Gota a gota, la sangre salpica y se esparce.\nEntre nado y nado, la horda llega hambrienta. Ahogarse es mejor.\nÑam, ñam, los dientes aparecen. ¡Todos a gritar!\nA las profundidades vamos, a dormir ¡y por siempre soñar!''.\n—Canción de cuna de Aguasturbias","Unidad",["ACECHANTE"],["Aguasturbias"],"COMÚN"],"04BW009":["Bahía del Destripador","Cuando los aliados atacan, antes de activar Acechar, otorgo Acechar al primer aliado de tu mazo y se convierte en un Acechante.","","Las caletas más peligrosas de Aguasturbias pronto se convirtieron en el hogar de toda clase de bestias marinas. Allí yacen, esperando a la próxima tripulación lo suficientemente insensata para ignorar las advertencias del vigía.","Hito",[],["Aguasturbias"],"RARA"],"04BW008":["Riquezas Perdidas","Roba un Tesoro. Si no hay ninguno disponible, creo 2 Tesoros en tu mazo.","","''¡Somos ricos!''. —Carnicero Cercenador","Hechizo",[],["Aguasturbias"],"RARA"],"04BW013":["Bahía del Saqueo","Cuando activo Cuenta regresiva, invoco un seguidor aleatorio de costo 1.\nCuenta regresiva 2: Otorgo +2|+1 y Temible a los aliados de costo 1.","","''Crees que tienes lo que se necesita para llamarte Gancho, ¿no? Ya veremos, pequeño pillo. Cuando terminemos contigo, vas a valer lo que pesas, o te hundirás bajo las olas por tu propio peso... ¡como carnada para las bestias!''. —Suboficial","Hito",[],["Aguasturbias"],"RARA"],"04BW004":["Carnada Sangrienta","Creo 1 Cardumen de Quijafortes arriba de tu mazo.","","''Si fuera por mí, dejaría que un pez jaull me devorara antes que esos seres despreciables. Es mejor morir rápido que gritar para que mis amigos me maten mientras me devoran vivo''. —Carnicero Cercenador","Hechizo",[],["Aguasturbias"],"COMÚN"],"04BW016":["Rex Arruinado","Al jugar: Juego Descarga de Cañones contra enemigos aleatorios por cada carta que hayas robado en esta ronda. Hasta 6 veces.","","''... ¿Rex?''. —Suboficial","Unidad",[],["Aguasturbias"],"RARA"],"04BW006":["La Lista","Otorgo Vulnerable a un enemigo. Si este ya tiene Vulnerable, el aliado Más fuerte inicia un ataque gratis al lanzar Desafío sobre este.","","''Tú tienes un nombre... y yo tengo una lista''. —Pyke","Hechizo",[],["Aguasturbias"],"RARA"],"04IO008":["Danza Desafiante","Retira una unidad.\nDanza de Cuchillas 1.","","\"¡Retirada! ¡Dejemos que alguien más tome el protagonismo!\". —Zinneia, Crescendo De Acero","Hechizo",[],["Jonia"],"COMÚN"],"04IO005":["Irelia","Cuando me invocan o al Inicio de la ronda: Si tienes la ficha de ataque, creo 1 Dueto Perfecto en la mano.","Si atacaste con 14+ aliados.","''Nuestros corazones se elevaron cuando estudiamos el arte y la belleza; pero cuando rompieron nuestros muros y derramaron nuestra sangre, volvimos a poner los pies en la tierra...''.","Unidad",[],["Jonia"],"Campeón"],"04IO020":["Manada Dispersa","Al jugar: Roba un hechizo Lento, Rápido o de Ráfaga.\nIluminación: Tengo Evasión.","","Las extrañas y bellas canciones celestes de los Sorbenubes mantenían a raya a la Niebla Negra... pero no por mucho tiempo.","Unidad",[],["Jonia"],"RARA"],"04IO004":["Espadachina en Flor","Al jugar: Danza de Cuchillas 2.","","''Existen aquellos que piensan que una flor es algo frágil y delicado; pero olvidan la fuerza que se necesita para aferrarse a la humilde tierra y dar esperanza cada vez que florece''.\n—Zinneia, Crescendo de acero","Unidad",[],["Jonia"],"COMÚN"],"04IO003":["Filo de la Vanguardia","Elige un aliado para atacar con Cuchillas. Después, Danza de Cuchillas 3.","","''¡Detengan su retirada! Los noxianos comenzaron esta guerra, pero nosotros la terminaremos''. —Irelia","Hechizo",[],["Jonia"],"RARA"],"04IO015":["Gotita Bailarina","Cuando me lanzan Retirada, roba 1.","","''El agua es flexible, se adapta... Toma la forma más adecuada para el momento, ya que fluye hacia adelante o se retira de la costa''. —Monje jonio","Unidad",[],["Jonia"],"COMÚN"],"04IO014":["Aprendiz Sombrío","Cuando invocas 1 aliado con Endeble, recibo +1|+0 en esta ronda.","","''Eres humo... un susurro al aire. Tus puños deben unirse a la oscuridad como la sombra. Anda... ¡una vez más!''. —Maestra Shi","Unidad",[],["Jonia"],"COMÚN"],"04IO002":["Zinneia, Crescendo de Acero","Si lanzas Danza de Cuchillas, ataco con Cuchillas.\nAl jugar: Danza de Cuchillas 1.","","''Reúnanse, queridos míos. Hoy nuestros pies se deslizarán por la tierra que nos nutrió con los movimientos que nos enseñaron nuestras familias. ¡Somos hijos de Jonia y hoy bailamos por el arte, por la libertad y por nosotros mismos!''.","Unidad",[],["Jonia"],"ÉPICA"],"04IO007":["Síncopa","Intercambio 2 aliados.","","''Bailar es moverse en armonía con el vaivén de todas las cosas''. —Zinneia, Crescendo de Acero","Hechizo",[],["Jonia"],"RARA"],"04IO011":["Guiar y Seguir","Lanzo Retirada a un aliado para crear 1 Dueto Perfecto en la mano.","","''Nuestra interpretación será... inolvidable''. —Zinneia, Crescendo de Acero","Hechizo",[],["Jonia"],"COMÚN"],"04IO013":["Protector Sagrado","Al jugar: Doy Barrera a un aliado en esta ronda. Roba 1 Shen.\nLos aliados con Barrera tienen Ataque Doble.","","''Así como luchamos para protegerla, la tierra misma se alza para protegernos a nosotros. Nuestra fuerza emana de la ira del terreno, y con ella alejamos a nuestros enemigos. Es así como el balance prevalece''. —Sacerdote de Jonia","Unidad",[],["Jonia"],"ÉPICA"],"04IO012":["Sombras del Pasado","Lanzo Retirada a cada aliado e invoco 1 Sombra Viviente en su lugar.","","'”Que lancen golpes a las sombras, donde sus armas serán infructuosas''. —Zed","Hechizo",[],["Jonia"],"RARA"],"04IO009":["Bailarina del Listón","Al jugar: Danza de Cuchillas 1.","","''¡Qué pena, chicos! Todo ese poder y sin un ritmo que lo acompañe. ¡Supongo que no TODOS podemos ser estrellas...!''.","Unidad",[],["Jonia"],"RARA"],"04IO001":["Músicos de Batalla","En cada ronda, una vez que hayas invocado 3 aliados más, restablece tu maná de hechizos y roba 1.","","Para algunos, la música es un refugio colectivo contra las dificultades y la violencia; para otros, la música es resistencia.","Unidad",[],["Jonia"],"ÉPICA"],"04IO006":["Defensor Costero","Cuando invocas a otro aliado, recibo +2|+0 en esta ronda.","","Mi queridísima Kay:\nLlegaron esta mañana en una línea de barcos que irrumpió en el horizonte y ocultó el amanecer. Sus máquinas prendieron fuego a las Planicies Plateadas y un humo espeso se arrastra por el aire de verano. No podemos quedarnos más tiempo al margen. Rastrillo o pala, guadaña o espada, hoy debemos ir al encuentro de nuestro destino. \nDebes saber que no tengo palabras para expresar cuánto te amo a ti y a nuestro hogar.\n—Carta chamuscada","Unidad",[],["Jonia"],"COMÚN"],"04SH100":["Preparativos Minuciosos","Para usarme, coloca una carta de tu mano en tu mazo.\nLanzo Predecir y, luego, creo una copia idéntica de la carta elegida en la mano.","","''Las acciones que tomamos hoy son las semillas del futuro''. —Tai, Cronomante Aspirante","Hechizo",[],["Shurima"],"COMÚN"],"04SH070":["Indignos","Doy -4|-0 a un seguidor enemigo en esta ronda.\nLo mato si el oponente tiene más gemas de maná que tú.","","''El sol brillará de nuevo sobre Shurima''. —Voz de los Resucitados","Hechizo",[],["Shurima"],"ÉPICA"],"04SH081":["Tejearena Baccai","Al jugar: Otorgo -1|-0 y Vulnerable a un enemigo.","","Cada grano que derrama roba un segundo de sus vidas, erosionándolas como el viento.","Unidad",[],["Shurima"],"RARA"],"04SH077":["Voz de los Resucitados","Si un campeón Subió de nivel, los aliados obtienen +2|+0.","","''La vi hablar, hace mucho tiempo''. El viejo soldado sonrió y, por un instante, su nieta lo imaginó: Shurima, dorada y resplandeciente, y a Azir, parado con orgullo sobre la ciudad que había sido prometida por la Voz de los Resucitados. ''Agitó una pasión en nuestro interior que creíamos extinta''.","Unidad",[],["Shurima"],"ÉPICA"],"04SH019":["Rek'Sai","Cuando Acecho o Al atacar: Otorgo +1|+0 a los aliados Acechantes en todas partes.\nFin de la ronda: Colócame en tu mazo.","Si ataco con 10+ de Poder.","''Durante una de sus acostumbradas salidas de exploración, el joven Jhuraa se topó con una pequeña caverna oculta en cuyo interior encontró varios textos antiguos. El traductor en Marrowmark a quien le llevamos los pergaminos dijo que estos cuentan la historia de un horror antiguo que acechaba a nuestros ancestros... ¡una reina xer'sai!''. —Fezhaur, anciano vekaurano","Unidad",["ACECHANTE"],["Shurima"],"Campeón"],"04SH138":["La Redentora","Doy +2|+1 a un aliado en esta ronda. Si un campeón subió de nivel durante la partida, creo 1 El Regreso de la Redentora en tu mano.","","''Todos me dijeron que no la usara. 'Nadie debe blandir un arma tan poderosa', dijeron''. —Akshan","Hechizo",[],["Shurima"],"COMÚN"],"04SH089":["Naturalista del Desierto","Al jugar: Destruyo un Hito. Si es un aliado, invoco 1 Rocoso Gruñón.","","''¡Kadira rompió algo hoy! ¡De nuevo! Fue un simple muro de piedra esta vez, pero lucía antiguo y probablemente fue importante para el ancestro de alguien. Su excusa es que los muros son más resistentes en Tereshni. ¡Esto sí que me enfada!''.\n—Diario de Zaifa","Unidad",[],["Shurima"],"RARA"],"04SH015":["Raz Melena Sangrienta","Al atacar: Doy -2|-0 a los enemigos en esta ronda.","","''Cuando nació este cocodrilo de aquí, los demás apostaron por cuánto tiempo viviría, porque asumieron que era el pequeño y el fenómeno de la camada. Nadie pensó en apostar a que se comería a todos sus hermanos. Je''.","Unidad",[],["Shurima"],"ÉPICA"],"04SH058":["Moldearenas","Al atacar: Invoco 1 Soldado de Arena atacante.","","Solo a unos pocos se les enseñan las costumbres del desierto, y solo a un número aún menor se les da la habilidad de comandar las arenas como lo hace Azir. Blandir este poder y conocer los secretos del desierto es un regalo que solo se le otorga a los más fieles y diestros seguidores del Emperador de las Arenas.","Unidad",[],["Shurima"],"COMÚN"],"04SH080":["Llamado Alfa","Para usarme, pon una carta de la mano arriba de tu mazo.\nCreo 2 seguidores Acechantes aleatorios en la mano.","","''Que el sol brille y los xer'sai duerman''.\n—Plegaria comerciante.","Hechizo",[],["Shurima"],"COMÚN"],"04SH035":["Día de Pago","Creo 1 Hallazgo Fortuito en la mano.","","''He tenido días buenos y días malos, como todos. En este trabajo, los días malos pueden ser bastante malos, y los días buenos pueden ser muy provechosos''. —Sivir","Hechizo",[],["Shurima"],"COMÚN"],"04SH028":["Preparativos Ancestrales","Al jugar: Predecir.\nCuenta regresiva 2: Invoco 1 Relojito.","","Aunque se podría pensar que estaban perdidos en el tiempo, enterrados bajo años de arena, los autómatas estaban en ubicaciones precisas, esperando a que los despertaran.","Hito",[],["Shurima"],"COMÚN"],"04SH054":["Buscatesoros","Cuando me invocan, creo 1 Arenas Evocadoras en la mano.","","''De acuerdo, Davu. Entrarás, tomarás eso... sea lo que sea, y nos bañaremos en riquezas. Yo me bañaré en riquezas. Harás que yo me bañe en riquezas. ¿Entendiste? Por cierto, si se trata de alguna criatura atrapada ahí, me disculpo por adelantado''.","Unidad",[],["Shurima"],"COMÚN"],"04SH002":["Segador Baccai","Cuando Matas a una unidad, recibo +1|+0.","","''Todos los baccai huyeron o fueron perdonados tras su Ascensión fallida, y nadie los ha visto desde entonces. ¿Cuánto tiempo han estado escondidos en esas tumbas oscuras con la marca de su vergüenza?''. —Escriba Kah'nir, Historia de la Hueste Ascendida","Unidad",[],["Shurima"],"RARA"],"04SH042":["Rocoso en Hibernación","Cuenta regresiva 3: Invoco 1 Rocoso Gruñón.","","''MI NOMBRE ES ZAIFA. ME GUSTA ESCRIBIR TONTERÍAS EN MI TONTO CUADERNO CUANDO CREO QUE TODO EL MUNDO ESTÁ DORMIDO... INCLUSO SAMI''.\n—Diario de Zaifa","Hito",[],["Shurima"],"COMÚN"],"04SH032":["Aplastahuesos Cruel","Reputación: Cuesto 1 menos. Cuando me invocan, recibo Arrollar.","","Ella se apoyó con más fuerza sobre el pecho del soldado hasta que este, quien se esforzaba por alcanzar su lanza, dejó de moverse. ''No, no'', lo reprendió mientras mostraba sus afilados colmillos y su malvada sonrisa. ''Este es mío ahora''.","Unidad",[],["Shurima"],"COMÚN"],"04SH055":["Saquearruinas","","","Antes de las bóvedas, los mercenarios y asaltatumbas de Shurima deben aprender a sobrevivir a los peligros más comunes del desierto: el inclemente calor y las hordas de saqueadores que disfrutan las masacres.","Unidad",[],["Shurima"],"COMÚN"],"04SH039":["Zilean","Al jugar: Creo 4 Bombas de Tiempo en tu mazo. Luego, lanzo Predecir.","Si te he visto destruir 2+ Bombas de Tiempo aliadas.","Durante muchos años, Zilean estableció una red de jóvenes magos prometedores de distintas épocas, los cuales eran capaces de encargarse del trabajo de su vida en caso de que sucediera lo impensable. Aunque era un mentor amable y alentador, una profunda tristeza arrugaba su frente cuando buscaba la soledad, y había un cansancio en sus ojos que solo alguien que ha vivido varias vidas podría comprender.","Unidad",[],["Shurima"],"Campeón"],"04SH073":["Taliyah","Al jugar: Invoco una copia idéntica de un Hito aliado.","Si invocaste 5+ Hitos.","''El sendero del nómada es el de la luz, pues está libre del peso de las raíces, y su hogar siempre yacerá más allá del horizonte''.\n—Las Sociedades de Shurima","Unidad",[],["Shurima"],"Campeón"],"04SH091":["Khahiri, el Estudiante","Cuando me invocan, recibo +1|+1 si usaste Predecir en esta partida.","","''Recuerda lo que aprendimos'', dijo Zilean. Su voz era inusualmente suave... con un tono casi solemne. ''¿De verdad estás listo?''. Khahiri le dio una sonrisa tranquilizadora a su mentor. ''Volveré pronto. Además, he pasado años preparándome para este momento. Si no es ahora, ¿entonces cuándo?''.","Unidad",[],["Shurima"],"COMÚN"],"04SH024":["Espira de Sal","Cuenta regresiva 2: Invoco 1 Rocoso Gruñón. Luego, si invocaste 4+ Hitos en esta partida, le otorgo +2|+2 al aliado Más fuerte.","","Un trabajador salinero de Shurima aprende rápidamente cuáles depósitos son adecuados para recolectar y cuáles se deben dejar en paz.","Hito",[],["Shurima"],"COMÚN"],"04SH003":["Azir","Cuando los aliados atacan, invoco 1 Soldado de Arena atacante.","Si invocaste 12+ aliados o Hitos.","''Cuando Azir se convirtió en el emperador de Shurima, era arrogante. Ciego. Acumuló poder y planeó su Ascensión para poder ser el gobernante no solo de Shurima, sino del mundo entero''. —Escriba Kah'nir, Historia de la Hueste Ascendida","Unidad",["ASCENDIDO","AVE"],["Shurima"],"Campeón"],"04SH011":["Investigadoras Xenotípicas","Cuando me invocan, otorgo +3|+3 a 3 aliados aleatorios en tu mazo.","","El Vacío está lleno de sorpresas, crece cada día y encuentra nuevas formas de infiltrarse en la torre, tan intrusivo como un matorral espinoso, pero infinitamente más letal. En esta medida, su estudio resulta difícil, ya que requiere investigadores igualmente inteligentes e ingeniosos para anticipar y comprender la amenaza.","Unidad",[],["Shurima"],"RARA"],"04SH130":["Akshan","Cuando me invocan o al Golpear: Invoco 1 Palacio del Señor de la Guerra o hago que Avance 1 ronda.","Palacio del Señor de la Guerra terminó su Cuenta regresiva. Cuando subo de nivel, invoco 1 Reserva del Señor de la Guerra.","''El código de los centinelas está lleno de restricciones bastante complicadas. Cosas como: 'Jamás matar por venganza', 'luchar en beneficio del mundo, no de tu persona'. En lo que a mí respecta...''.","Unidad",[],["Shurima"],"Campeón"],"04SH114":["Furia del Desierto","Otorgo +1|+0 a Soldados de Arena aliados en todas partes.\nInvoco 2 Soldados de Arena.","","No descansan ni titubean. Son implacables, indiferentes e indomables.","Hechizo",[],["Shurima"],"RARA"],"04SH067":["Renekton","Cuando lanzo Desafío a un enemigo, recibo +2|+1 en esta ronda.","Si infligí 10+ de daño.","''Es fácil olvidar que alguna vez fue humano, pues el semblante del cocodrilo combina muy bien con su amor por las batallas sangrientas...''. —Escriba Kah'nir, Historia de la Hueste Ascendida","Unidad",["ASCENDIDO","REPTIL"],["Shurima"],"Campeón"],"04SH120":["Posibilidades Concebidas","Creo un Hito aleatorio con Cuenta regresiva en la mano o Avanzo tus Hitos 1 ronda.","","''El tiempo es efímero''. —Zilean","Hechizo",[],["Shurima"],"RARA"],"04SH119":["Rebote","Reputación: Cuesto 3 menos.\nInflijo 1 de daño a un enemigo aleatorio o al nexo enemigo 5 veces.","","''Esto se pondrá caótico''. —Sivir","Hechizo",[],["Shurima"],"COMÚN"],"04SH068":["Invocador Xer'sai","Al jugar: Lanzo Predecir.","","No todos los xer'sai nacen para asesinar. Algunos pueden invocar a otros de su especie mediante penetrantes chillidos que sacuden las arenas y los sentidos.","Unidad",["ACECHANTE"],["Shurima"],"COMÚN"],"04SH093":["Roca Moldeada","Doy +1|+1 a un aliado en esta ronda.\nSi invocaste un Hito en esta partida, le doy +2|+1.","","''Con la ayuda de la tierra, ¡NOS DEFENDEREMOS!''. —Taliyah","Hechizo",[],["Shurima"],"COMÚN"],"04SH079":["Arenas Agoreras","Lanzo Predecir.\nDoy -2|-0 a un enemigo en esta ronda.","","''Vi mi destino, y esta vez nadie me detendrá''. —Azir","Hechizo",[],["Shurima"],"RARA"],"04SH038":["Saltarrocas","Cuando me invocan, invoco 1 Arenas Agitadas.","","''¡Hoy comenzamos nuestro viaje hacia Nashramae! Samir quiere cruzar el Gran Sai antes de la próxima luna llena... ¡y VAYA que se lo está tomando en serio! Ni Sami ni yo sabíamos que una simple tabla de arena pudiera derribar una duna entera. Él está bien, por cierto''.\n—Diario de Zaifa","Unidad",[],["Shurima"],"COMÚN"],"04SH104":["Conservacionista","Al jugar: Avanzo un Hito aliado 3 rondas.","","Cuando requiere un momento de tranquilidad, Zilean regresa al último jardín de Icathia, justo como él lo recuerda.","Unidad",[],["Shurima"],"RARA"],"04SH128":["Vagabunda Vekaurana","Cuando me invocan, invoco 1 Palacio del Señor de la Guerra o hago que Avance 2 rondas.","","Viendo a Akshan bajo la ventana del cuarto piso, Najah lanzó algunos improperios en voz baja. El chico bonito se le había adelantado... de nuevo. Giró la daga que sostenía en la mano y meditó lo que le diría. Tal vez, esta vez él le daría el reconocimiento apropiado.","Unidad",[],["Shurima"],"COMÚN"],"04SH109":["Arena Movediza","Doy -4|-0 a un enemigo o -1|-0 a 2 enemigos en esta ronda. Anulo sus palabras clave positivas en esta ronda.","","Existen ruinas sepultadas en ciertas zonas del desierto, lo que crea huecos en la arena donde los viajeros incautos pueden caer y perecer. ","Hechizo",["ELEMENTAL"],["Shurima"],"COMÚN"],"04SH043":["Arenas Inestables","Inflijo 4 de daño a una unidad.\nInvoco 2 Soldados de Arena.","","''Rodéenlos. No pueden luchar contra la tierra misma''. —Azir","Hechizo",[],["Shurima"],"RARA"],"04SH099":["¡Levántense!","Invoco 1 Soldado de Arena.\nCreo 1 ¡Levántense! con Fugaz en la mano.","","''Así lo ordeno''. —Azir","Hechizo",[],["Shurima"],"RARA"],"04SH048":["Santuario Interno","Reputación: Cuesto 3 menos.\nCuenta regresiva 1: Creo 2 Hallazgos Fortuitos en la mano.","","''Hay mapas que tardan años en ser descifrados; hay trampas que tardan meses en ser desactivadas; y hay bóvedas que tardan semanas en explorarse... Pero cuando lo logras, vale cada maldito segundo''. —Sivir","Hito",[],["Shurima"],"COMÚN"],"04SH056":["Usurera","Cuando me invocan, creo 1 Hallazgo Fortuito en la mano.","","''Amigo mío, obtuve para ti esta belleza incomparable directamente de la legendaria Tumba de los Emperadores. La arrebaté de la mano del gran Renekton en persona y, mientras salía, ¡me vi rodeado por diez o veinte jinetes de lagartos sedientos de sangre! En verdad es un milagro que un tesoro así haya llegado a tus manos''.","Unidad",[],["Shurima"],"COMÚN"],"04SH020":["Sivir","","Si infligiste 30+ de daño.","Sivir se abrió paso en la vida como mercenaria y cargó con todos los riesgos y recompensas que conllevaba su decisión. Una expedición fatídica casi le costó todo, pero cuando su sangre se derramó en las arenas de Shurima, despertó un poder ancestral que devolvería la grandeza a su tierra natal, y también a ella.","Unidad",[],["Shurima"],"Campeón"],"04SH057":["Mariscal Inspiradora","Cuando invocas otro aliado, le doy +2|+0 en esta ronda.","","Recibir la bendición de Azir es un gran honor, mientras que dar una bendición en su nombre es un honor aún mayor.","Unidad",[],["Shurima"],"RARA"],"04SH103":["Cazadora Despiadada","Al jugar: Otorgo Vulnerable a un enemigo.","","''Y... listo. Bien amarrado. A Renekton le gusta que le entreguen sus alimentos vivitos y coleando''.","Unidad",[],["Shurima"],"COMÚN"],"04SH065":["Xerxa'Reth, El Titán Subterráneo","Al atacar: Si tengo 8+ de Poder, recibo Temible, Arrollar y Escudo Antihechizos en esta ronda.","","''Se dice que hace cientos de años, a orillas del río Khaleek, se erigía un gran puesto de comercio llamado Taraleek. Un fatídico día, una poderosa bestia salió de la tierra y arrasó el lugar y con todos los que vivían allí. ¿Qué clase de monstruo podría haber hecho tal cosa?''. —Historiador shurimano","Unidad",["ACECHANTE"],["Shurima"],"ÉPICA"],"04SH034":["La Manecilla del Reloj","Cuando me invocan, creo 2 Siglos al Instante en la mano.","","Los constantes ruidos en los niveles más bajos de la torre se deben a la Manecilla del Reloj, el guardián que constantemente le da cuerda a los engranes.","Unidad",[],["Shurima"],"ÉPICA"],"04SH082":["Camino Ruinoso","Roba 1.\nSi Mataste a una unidad en esta ronda, Dreno 2 del nexo enemigo.","","Los Azotadores de las Arenas reclutan a sus miembros de entre los ejércitos enemigos. Cualquiera que sobreviva a su ataque inicial puede unírseles... o morir.","Hechizo",[],["Shurima"],"RARA"],"04SH075":["División Imperial","Doy Vulnerable a los enemigos en esta ronda e invoco 6 Soldados de Arena.","","''Mis soldados siguen marchando''. —Azir","Hechizo",[],["Shurima"],"ÉPICA"],"04SH018":["Rito de Dominio","Mato a un aliado o destruyo una de tus gemas de maná para dar -2|-0 a todos los enemigos en esta ronda.","","''¡Nosotros peleamos, ellos sangran!''. —Renekton","Hechizo",[],["Shurima"],"RARA"],"04SH009":["Baccai Iracundo","Al jugar: Si Mataste a 4+ unidades en esta partida, un enemigo y yo nos Golpeamos.","","El resentimiento de quien guarda rencor solo se profundiza, incluso si los objetos de dicho rencor llevan tiempo muertos.","Unidad",[],["Shurima"],"RARA"],"04SH049":["Poro Destinado","Inicio de la ronda: Si un campeón Subió de nivel, me transformo en Poro Eminente.","","No sabía con exactitud lo que había encontrado... pero brillaba y parecía un delicioso bocadillo.","Unidad",["PORO"],["Shurima"],"COMÚN"],"04SH045":["Extenuación","Doy -2|-0 y Vulnerable a un enemigo en esta ronda.","","Los moradores del desierto saben cómo evitar el ardiente e implacable calor del sol; sin embargo, aquellos que no estén preparados para soportarlo, descubrirán que su fuerza y energía desaparece a una gran velocidad.","Hechizo",[],["Shurima"],"COMÚN"],"04SH037":["Tierra Desatada","Invoco 2 Arenas Agitadas.\nRoba 1.","","Por más hermoso que sea, el Gran Sai no es lugar para los débiles. Muchos han perdido la vida en sus ondeantes dunas, y si bien los xer'sai matan a muchos, el terreno mismo cobra lo suyo.","Hechizo",["ELEMENTAL"],["Shurima"],"RARA"],"04SH107":["Despertar de los Ascendidos","Subo de nivel a todos los aliados Ascendidos de nivel 1.","","''¡Los Ascendidos son quienes escribirán el futuro!''. —Azir","Hechizo",[],["Shurima"],"ÉPICA"],"04SH047":["Nasus","Tengo +1|+1 por cada unidad que hayas Matado en esta partida.","Si Golpeé e infligí 10+ de daño de un Golpe.","''La bendición recién ganada de Nasus le permitió estudiar y contemplar la naturaleza de la vida y la muerte. Sin embargo, tras la caída de Shurima, esta prolongada longevidad también demostraría ser su maldición''. —Escriba Kah'nir, Historia de la Hueste Ascendida","Unidad",["ASCENDIDO","PERRO"],["Shurima"],"Campeón"],"04SH097":["Conservadora del Santuario","Al jugar: Mato a un seguidor enemigo. Si mataste a 13+ unidades en esta partida, asesino a todos los seguidores enemigos. Luego, invoco una copia mía.","","Los baccai tienen la tarea de proteger el santuario interno y salvaguardar los tesoros antiguos que yacen ahí y, por el bien de los mortales que creen ser lo suficientemente astutos o poderosos, resistir el peso del juicio del Curador.","Unidad",[],["Shurima"],"ÉPICA"],"04SH026":["Guardián de las Dunas","Cuando me invocan, invoco 1 Soldado de Arena.","","''El emperador ordena. La arena y yo obedecemos''.","Unidad",[],["Shurima"],"COMÚN"],"04SH102":["Embajadora Dorada","Alianza: Roba un campeón y le otorgo +2|+2.","","''Nuestro brillante futuro yace bajo las arenas, y depende de nosotros allanar el camino para Azir. ¡El imperio dorado del desierto se alzará de nuevo!''.","Unidad",[],["Shurima"],"COMÚN"],"04SH001":["Cronomante Aspirante","Al jugar: Predecir.","","A lo largo de su estancia como estudiante de cronomancia, Tai tuvo que reconciliar su incertidumbre con su determinación. Era mejor tener esperanza en una potencial victoria que obsesionarse con lo que pudo haber salido mal.","Unidad",[],["Shurima"],"COMÚN"],"04SH022":["Rompedunas Xer'sai","","","Si bien todos los xer'sai son hábiles excavadores de túneles, solo los rompedunas tienen el tamaño y la fuerza para penetrar el lecho de roca que atraviesa el subsuelo del Gran Sai, y extender la cacería hacia las tierras que yacen más allá de sus fronteras.","Unidad",["ACECHANTE"],["Shurima"],"RARA"],"04SH030":["Cronoviaje","Doy ''La próxima vez que muera en esta ronda, me curo por completo y recibo +3|+3'' a un campeón aliado.","","''No podemos parar lo imparable... pero podemos posponerlo''. —Zilean","Hechizo",[],["Shurima"],"RARA"],"04SH013":["Preservarium","Cuando me invocan, roba 1.\nCuenta regresiva 2: Roba 1.","","Zilean le muestra a aquellos que trae a la torre precisamente lo que buscan restaurar. Es lo que el Conservacionista es capaz de mostrarles, aunque solo sea un vistazo a la vez.","Hito",[],["Shurima"],"RARA"],"04SH062":["Disco Solar Enterrado","Inicio de la partida: Si todas tus cartas son de Shurima, invoco 1 copia mía de tu mazo.\nCuenta regresiva 25: Restaura el Disco Solar.\nAvanzo 9 rondas por cada vez que un aliado Ascendido haya subido de nivel en esta partida.","","Cuando Azir sostuvo el Disco Solar de la capital de Shurima, vio el objeto no por lo que era, sino por lo que podía ser: la clave para devolverle a Shurima su antigua gloria.","Hito",[],["Shurima"],"ÉPICA"],"04SH016":["Golpe Absorbente","Un aliado Golpea a una unidad.\nSi esta muere, los campeones aliados reciben +2|+2 en todas partes.","","''Pesaremos tu alma''. —Nasus","Hechizo",[],["Shurima"],"RARA"],"04SH125":["Asaltabóvedas Vekaurana","Al jugar: Doy +2|+0 a un aliado para dar -2|-0 a un enemigo en esta ronda.","","Tena esperó pacientemente mientras la saliva cáustica de su mascota derretía las barras doradas de la puerta trasera del palacio. A la vuelta de la esquina, pronto encontraría tesoros de un valor incalculable... más que suficiente para devolverle su antigua gloria a Vekaura.","Unidad",[],["Shurima"],"RARA"],"04SH108":["Cuchilla Búmeran","Un aliado Golpea al enemigo Más fuerte y al Más débil uno después del otro.","","''Mejor agáchate''. —Sivir","Hechizo",[],["Shurima"],"RARA"],"04SH066":["Tiempo Embotellado","Lanzo Predecir y Avanzo un Hito aliado 2 rondas.","","''Si solo vieras el tiempo como yo, sabrías que no es inmutable''. —Zilean","Hechizo",[],["Shurima"],"COMÚN"],"04SH021":["Khahiri, El Que Volvió","Cuando me invocan, creo una copia mía en tu mazo. Cuando me veas en una Predicción, otorgo +2|+2 a todas mis copias en todas partes.","","Khahiri solo se había ido un momento cuando reapareció de repente. Era casi una década más viejo y empuñaba un arma extraña y de aspecto letal. Lo recibieron con sonidos de asombro y preocupación.","Unidad",[],["Shurima"],"RARA"],"04SH101":["Consejo Devoto","Inicio de la ronda: Si un campeón Subió de nivel, curo 2 a tu nexo y a tus campeones.","","''Le juré mi lealtad a Azir y a Shurima, ¡mi hogar! ¿Tú no harás lo mismo?''.","Unidad",[],["Shurima"],"RARA"],"04SH012":["Hierofante Venerado","Cuando me invocan, Avanza a tu Disco Solar Enterrado 3 rondas.","","''¡Ah! ¡Es Padjuman, uno de los ancianos de Nashramae! ¡Como que hoy vino todo el mundo a nuestra ciudad, papá!''. —Mirón emocionado","Unidad",[],["Shurima"],"COMÚN"],"04SH031":["Futuro Prometedor","Otorgo ''Mi efecto al completar la Cuenta regresiva se activa dos veces'' a un Hito aliado.","","''Los mortales desperdician mucho tiempo esperando. Es mi deseo de corazón que todos reciban la recompensa por su paciencia''. —Zilean","Hechizo",[],["Shurima"],"ÉPICA"],"04SH004":["El Peso del Juicio","Inflijo 2 de daño a un campeón o 4 de daño a un seguidor.","","''Una vida por la de muchos. Una vida para que muchos gocen de prosperidad''. —Nasus","Hechizo",[],["Shurima"],"COMÚN"],"04SH059":["Rito de Negación","Mato a un aliado o destruyo una de tus gemas de maná para detener todos los hechizos Rápidos, hechizos Lentos y Habilidades del enemigo.","","El análisis es una parte fundamental de la cronomancia, ya que muchas acciones se deben detener para considerar futuras soluciones.","Hechizo",[],["Shurima"],"ÉPICA"],"04SH044":["Curador del Reloj","Al jugar: Avanzo un Hito aliado 2 rondas.","","Las construcciones que protegen la torre de Zilean son capaces de resistir el rudo desierto durante milenios, y no solo por su construcción bien planeada.","Unidad",[],["Shurima"],"COMÚN"],"04SH076":["Reloj Ancestral de Arena","Lanzo Aniquilar a un aliado para invocar 1 Estatua en Estasis en el lugar con el aliado almacenado adentro.","","''¡Tai! ¡Ven aquí! Necesitamos tu ayuda para resolver un asunto''.\n—Xetsa, Investigadora del Vacío","Hechizo",[],["Shurima"],"RARA"],"04SH118":["Arenas Evocadoras","Invoco 1 Caballería de Arenisca.","","''Puede que la caja sea algo valiosa, pero estoy segura de que el contenido no lo es. Me refiero a que no vale la pena abrirla... y lo digo por experiencia''. —Sivir","Hechizo",[],["Shurima"],"COMÚN"],"04SH072":["Augur","Cuando me invocan, otorgo Escudo Antihechizos a los campeones e Hitos aliados.","","''Ah, no esperabas ver agua en medio del desierto. No te preocupes. Ven, bebe hasta saciarte y lávate los pies. Descansa a la sombra un rato. Esta es la nueva Shurima de Azir, y es un oasis''.","Unidad",[],["Shurima"],"COMÚN"],"04SH041":["Exploradora del Sai","Al jugar: Predecir. Si eliges un Hito, recibo Evasión.","","''¡Tuvimos problemas! Una gran tormenta se acercaba desde el oeste, y Taliyah cruzó los túneles de los xer'sai hacia el sur. Vi un templo hacia el norte; ahora estamos a salvo dentro de sus muros de terracota. Los demás están dormidos, y mi flama, al igual que yo, comienza a menguar. Espero tener dulces sueños''.\n—Diario de Zaifa","Unidad",[],["Shurima"],"COMÚN"],"04SH005":["Merodeador Sanguinario","","","Los Azotadores de las Arenas hacen todo con sus compañeros: pelean, cazan, matan... y comen juntos.","Unidad",[],["Shurima"],"COMÚN"],"04SH083":["Clarividencia Feral","Predecir.","","''La aleta causa miedo, pero los dientes causan muerte''. —Dicho shurimano","Hechizo",[],["Shurima"],"RARA"],"04SH092":["Llegó la Hora","Invoco 1 Relojito.\nSi lanzaste Predecir en esta partida, invoco 2.","","''¡Deja de causar problemas y ven! Tienes arena en tus engranes''. —Tai, Cronomante Aspirante","Hechizo",[],["Shurima"],"COMÚN"],"04SH046":["Quimera de Arenisca","Cuesto 1 menos por cada vez que un aliado haya atacado en esta partida.","","Tras el regreso de Azir, los shurimanos vieron antiguas y legendarias bestias que, si bien estaban hechas de arena, eso no las hacía menos impresionantes.","Unidad",[],["Shurima"],"RARA"],"04SH105":["Tumba Erosionada","Cuando los aliados atacan, invoco 1 Caballería de Arenisca atacante.","","Conforme pasaban por el desfiladero, el Moldearenas pronunció palabras de magia. De pronto, una ráfaga de viento resonó por el cañón y se convirtió en un estruendo de cascos que se aproximaban.","Hito",[],["Shurima"],"RARA"],"04SH131":["Gancho de Agarre","Un aliado que hayas seleccionado en esta ronda Golpea a un enemigo.","","''¡El gancho siempre los sorprende!''. —Akshan","Hechizo",[],["Shurima"],"RARA"],"04SH074":["Cría de Xer'Sai","","","Tan pronto inhabilitan una caravana, los cazadores por lo general se retiran y permiten que sus crías vayan a explorar. Es entonces cuando los xer'sai jóvenes afinan sus instintos y aprenden a diferenciar los sonidos del desierto de las señales de sus presas.","Unidad",["ACECHANTE"],["Shurima"],"COMÚN"],"04SH137":["Enjambre Zumbante","Cuando me invocan, creo una copia de mí en tu mano si un campeón subió de nivel durante la partida.","","Se creía que los escarabajos gigantes habían perecido tras la caída del imperio shurimano. Sin embargo, los zarcillos rastreros de la niebla penetraron muy profundo en las arenas y pusieron a las criaturas al servicio de Viego.\n","Unidad",[],["Shurima"],"ÉPICA"],"04SH069":["Depredador Implacable","Doy +2|+0 a un aliado y Vulnerable a un enemigo en esta ronda.","","''¡Háganlos trizas!''. —Renekton","Hechizo",[],["Shurima"],"COMÚN"],"04SH121":["Rito de Llamado","Mato a un aliado o destruyo una de tus gemas de maná para que robes un campeón.","","''Un sacrificio necesario''. —Nasus","Hechizo",[],["Shurima"],"COMÚN"],"04SH110":["Tejepiedras","Manifiesto un Hito que puedas costear.","","''¡Vamos! ¡Hay muchas cosas que ver!''. —Taliyah","Hechizo",["ELEMENTAL"],["Shurima"],"ÉPICA"],"04SH051":["Estrado del Emperador","Cuando los aliados atacan, invoco 1 Soldado de Arena atacante.","","Los Moldearenas alzaron sus manos y dieron forma a los usuales soldados acorazados sin rostro, un ejército de arena infatigable, listo para luchar por su dios-emperador. ","Hito",[],["Shurima"],"RARA"],"04SH106":["Fuego Espiritual","Doy -2|-0 y ''Fin de la ronda: Me inflijo 2 de daño'' a los enemigos en esta ronda.","","''Sus espíritus arderán''. —Nasus","Hechizo",[],["Shurima"],"RARA"],"04SH129":["Matón Vekaurano","Al golpear: Creo 1 Hallazgo Fortuito en la mano.","","''Muy bien, Barb. Acabamos con el último de los guardias que custodiaban este piso, pero todavía debemos mantener un perfil bajo''.\n''¡BLARGH-BLAAA!''.\n''Baja la voz, Bárbara''.\n''Blarb''.\n''Esa es mi chica''.","Unidad",[],["Shurima"],"RARA"],"04FR006":["Inquisidor Draklorn","Cuando me invocan, invoco 1 Siervo Congelado.\nFin de la ronda: Si la Cuenta regresiva de cualquiera de tus Siervos Congelados es de 4 o menos, Avanzan a 0.","","''Mi señora se aparece en mis sueños y su voz es un mero susurro. 'Sígueme', me ordena. No me atrevo a desobedecerla''.","Unidad",[],["El Fréljord"],"ÉPICA"],"04FR012":["Tumba Helada","Lanzo Aniquilar a cada enemigo para invocar 1 Tumba Congelada en el lugar con el enemigo almacenado adentro.","","''Al final, el frío lo superará todo''. —Lissandra","Hechizo",["ELEMENTAL"],["El Fréljord"],"ÉPICA"],"04FR016":["Botín de Guerra","Otorgo +1|+2 a un aliado.\nPillaje: Otorgo +2|+4.","","''Ustedes los avarosanos son cada vez más débiles y se regodean en sus tierras fértiles. Descansen esta noche, debiluchos miserables, y mientras sueñan con la cosecha de mañana, nosotros la reclamaremos''. —Vrynna Madre Pielmarcada","Hechizo",[],["El Fréljord"],"COMÚN"],"04FR013":["Resistencia al Frío","Doy una gema de maná vacía y otorgo +0|+2 a un aliado.","","''Cuídate del hielo... pero lo más importante... ¡cuídate de aquello que yace en su interior!''. —Garabatos en el muro de una posada del Fréljord","Hechizo",["ELEMENTAL"],["El Fréljord"],"COMÚN"],"04FR005":["Lissandra","Cuando me invocan, invoco 1 Siervo Congelado y hago que Avance 2.","Si invocaste 2+ aliados de costo 8+. Cuando Subo de nivel, creo 1 Vigilante en la mano.","''Los Vigilantes moran más allá de estos muros, suspendidos en el hielo, congelados en el tiempo... Y mientras esperan, yo tengo planes que debo poner en movimiento...''.","Unidad",[],["El Fréljord"],"Campeón"],"04FR011":["Sucumbir al Frío","Lanzo Helar a un enemigo.\nInvoco 1 Siervo Congelado.","","''El frío provoca distintas reacciones. Veamos cómo reaccionas tú''. —Lissandra","Hechizo",["ELEMENTAL"],["El Fréljord"],"COMÚN"],"04FR001":["Siervo Congelado","Cuenta regresiva 9: Invoco 1 Siervo de la Guardia de Hielo.","","Era claro que había suficientes guerreros estúpidos en las filas del desordenado ejército de Trundle para usar como carne de cañón en la primera línea. Sin embargo, Lissandra quería algo mucho más leal... algo que la sirviera únicamente a ella.","Hito",[],["El Fréljord"],"COMÚN"],"04FR007":["Entierro","Lanzo Aniquilar a una unidad para invocar en su lugar 1 Tumba Congelada que la almacene.","","''Arrodíllense o los congelaré''. —Lissandra","Hechizo",["ELEMENTAL"],["El Fréljord"],"RARA"],"04FR017":["Bendición Ancestral","Otorgo +2|+2 al primer aliado de tu mazo.\nIluminación: Otorgo +2|+2 a todos los aliados de tu mazo.","","Las implacables tormentas frías y castigadoras del Fréljord matan a la mayoría de los que osan entrar en sus tierras estériles. Sin embargo, aquellos que sobreviven encuentran en su interior una fuerza que los impulsa a seguir adelante por el resto de sus vidas.","Hechizo",[],["El Fréljord"],"COMÚN"],"04FR014":["Desfiladero Asolado","Cuando me invocan, curo 2 a tu nexo.\nCuenta regresiva 1: Inflijo 2 de daño a TODAS las unidades.","","Del hielo oscuro brotan formas extrañas en todas las superficies a lo largo del desfiladero, y sus picos sobresalientes disuaden a cualquier intruso.","Hito",[],["El Fréljord"],"RARA"],"04FR009":["Fragmento de Hielo","Inflijo 1 de daño a TODO.","","''Enterraré el mundo en hielo''. —Lissandra","Hechizo",["ELEMENTAL"],["El Fréljord"],"COMÚN"],"04FR015":["Poro Mítico","Cuando me invocan, otorgo una palabra clave aleatoria a los poros aliados.","","Se dice que existe una figura que es legendaria para todos los poros. Cuentan que, a lo largo de sus viajes, les otorga a sus amigos peludos que sean dignos toda clase de dones forjados por la magia.","Unidad",["PORO"],["El Fréljord"],"RARA"],"04FR019":["Matriarca Dientescarcha","Cuando me invocan, invoco 1 Jauría Dientescarcha.","","Los lobos dientescarcha rodearon al drüvask. Este yacía agachado, en guardia. El áspero y apabullante hedor a muerte lo seguía a donde iba.","Unidad",["PERRO"],["El Fréljord"],"RARA"],"04FR018":["Guardián Abominable","Mientras estoy en tu mano, al Inicio de la ronda: Si tienes 2+ yetis, invócame para crear una copia mía en tu mazo.\nAl jugar: Roba un yeti.","","''... ¡y también son sigilosos! La última vez que estuve en el exterior, encontré refugio en una cueva. Sin embargo, el lugar estaba lleno de potrillos durmientes. Traté de mantenerme alejado, pero el más grande regresó. ¡Era alto como una montaña y estaba cubierto de hielo! Ahora escúchame, porque...''. —Bjerg Balbuceante","Unidad",["YETI"],["El Fréljord"],"ÉPICA"],"04FR010":["Tres Hermanas","Creo 1 Helada Centelleante, Furia del Norte o Entierro con Fugaz en la mano.","","Las hermanas del Fréljord Avarosa, Serylda y Lissandra tenían un poder inmenso, aunque cada una decidió utilizarlo de formas distintas: misericordiosa, marcial o maliciosamente.","Hechizo",[],["El Fréljord"],"RARA"],"04NX002":["Palabras Susurrantes","Reputación: Cuesto 2 menos.\nRoba 2.","","Los rumores siempre llegan antes que las noticias. Y antes de los rumores, la jugada. Y antes de la jugada, la trama.","Hechizo",[],["Noxus"],"RARA"],"04NX010":["Espina de la Rosa","Cuando me invocan, creo 1 Astucia en la mano.","","''¡Aelana, mi querida amiga y colega! ¿Has visto a Lord Duin? Ah, qué pena. Tenía muchas ganas de ponerme al día con él. Espero que se lo esté tomando con calma. Odiaría que le pasara algo al viejo...''. —Lady Auvray, espía de la Rosa Negra","Unidad",[],["Noxus"],"COMÚN"],"04NX021":["Justiciero Jubilado","Cuando me seleccionas, recibo +1|+0.","","Tras un sinfín de batallas, Beryn juró que no volvería a levantar su espada incluso si su vida dependiera de ello. Sin embargo, cuando la extraña niebla arrasó con Noxus y se apoderó de Thea, supo que debía romper aquel juramento. Tenía que liberarla a como diese lugar.","Unidad",[],["Noxus"],"RARA"],"04NX022":["Duelista Arruinada","Cuando me invocan, creo 1 Asalto de Medianoche en la mano.","","Cuando su sentencia finalizó, Thea supo que jamás podría volver a reunirse con su pueblo. La guerra (y Noxus) la habían convertido en una asesina. Sabía que no volvería a conocer la paz, así que aprovechó sus nuevas habilidades para ganarse la vida en las arenas.","Unidad",[],["Noxus"],"RARA"],"04NX015":["Asuntos Sangrientos","Reputación: Cuesto 2 menos.\nUn aliado con 5+ de poder Golpea a un enemigo.","","''Las amenazas más grandes siempre pasan desapercibidas''. —LeBlanc","Hechizo",[],["Noxus"],"COMÚN"],"04NX019":["Mordelón Golpeador","Cuando un enemigo me bloquea, recibo +3|+0 en esta ronda.","","Impactado por la resiliencia de la criatura que habían encontrado en la costa de Jonia, el joven general insistió en llevársela a casa con el propósito de descubrir su verdadera fuerza.","Unidad",["REPTIL"],["Noxus"],"ÉPICA"],"04NX008":["Estratega Mordaz","Reputación: Cuesto 2 menos.\nCuando me invocan, lanzo Preparar.","","Dentro de las cámaras secretas de la Rosa Negra, los nobles noxianos hacen sus jugadas, y la muerte cae sobre víctimas lejanas.","Unidad",[],["Noxus"],"RARA"],"04NX006":["Espía de la Rosa Negra","Reputación: Cuando me invocan, me transformo en una copia idéntica del aliado Más fuerte que haya Golpeado en esta ronda.","","''El valor de un secreto yace en lo que cuesta guardarlo''.","Unidad",[],["Noxus"],"ÉPICA"],"04NX001":["Mímica","Reputación: Cuesto 3 menos.\nCuando juegues tu siguiente hechizo en esta ronda, lo copio con los mismos objetivos.","","Imitar es una forma de halagar. Y un halago puede ser letal.","Hechizo",[],["Noxus"],"RARA"],"04NX004":["LeBlanc","","Si te he visto infligir 15+ de daño. Cuando subo de nivel, creo 1 Imagen Especular en la mano.","''Calma, calma, no hay necesidad de pelear entre nosotros. Por el momento, debemos evitar cualquier acción precipitada. Volvamos a reunirnos cuando recibamos noticias de nuestro emisario. Después de todo...''.","Unidad",[],["Noxus"],"Campeón"],"04NX016":["Hilandera Aulladora","Al atacar: Doy +2|+0 a otros aliados araña en esta ronda.","","''Ve, querida. Que las demás escuchen tu llamado. Ya sabes cómo se emocionan. Ya sabes cuánto me complace''. —Elise","Unidad",["ARAÑA"],["Noxus"],"RARA"],"04NX007":["Atakhan, Heraldo de la Ruina","Al jugar: Revivo al aliado muerto más fuerte.\nAl atacar: Recibo poder equivalente al poder total de todos los aliados.","","Una aberración sin nombre se alzó sobre ellos en una cámara llena de humo. Los magos profirieron cánticos disonantes hasta que sus voces alcanzaron tonos tensos y febriles. La criatura se hacía más fuerte con cada bocanada de miedo que respiraba de los individuos.","Unidad",[],["Noxus"],"ÉPICA"],"04NX018":["Sangría Carmesí ","La próxima vez que invoques otro aliado, le inflijo 1 de daño y recibo +1|+1.","","''¿Sabes? Casi nadie los tiene de mascota. Un rasguñito con esas garras y fácilmente te abren una arteria... pero a mí no me importa''. —Clara, Discípula Carmesí","Unidad",["GATO"],["Noxus"],"COMÚN"],"04NX003":["Sello de la Maldad","Reputación: Cuesto 2 menos.\nInflijo 2 de daño a cualquier objetivo.","","Una vez que se gana la batalla, no se debe titubear, sino seguir presionando al enemigo, perseguirlo y acabar con él por completo.","Hechizo",[],["Noxus"],"COMÚN"],"04NX017":["Ventaja Numérica","Invoco 2 Merodeadores Legionarios.","","Se sabe que los soldados de Noxus dejan pocos sobrevivientes... y los merodeadores dejan menos.","Hechizo",[],["Noxus"],"COMÚN"],"04NX009":["Cuchilla Espinosa","Doy +5|+0 a un aliado en esta ronda.","","''Te comportarás con gracia y gentileza. Los halagarás y los sorprenderás; los escucharás y aprenderás. Y cuando llegue el momento, atacarás y ASESINARÁS\". —LeBlanc","Hechizo",[],["Noxus"],"COMÚN"],"04SI005":["Kindred","En cada ronda, la primera vez que Mates a una unidad, marco al enemigo Más débil.\nFin de la ronda: Mato a las unidades con mi marca.","Si te he visto Matar a 2+ unidades con mi marca.","Hubo un hombre solitario\nQue se partió a la mitad\nDe uno nacieron dos\nY jamás volverán a estar solos.","Unidad",[],["Islas de la Sombra"],"Campeón"],"04SI055":["Viego","Cuando muera otro aliado por primera vez en cada ronda, invoco 1 Niebla Invasiva.","Si he visto morir aliados con 20+ de Poder total.","''Hay algo sobre el joven rey que me pone los nervios de punta. Algo en lo profundo de su ser... un apetito que no se puede calmar; un deseo que es imposible satisfacer''. —De los registros de Nunyo Necritos de Camavor","Unidad",[],["Islas de la Sombra"],"Campeón"],"04SI016":["Sanguijuela Espiritual ","Al jugar: Mato a un aliado para que robes 2.","","Acechan en las sombras, esperando un alma cansada o una mente distraída. Verás sus garras, sus enormes fauces y, por último, la oscuridad eterna.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"04SI007":["El Demonio Etéreo","Al jugar: Mato a un aliado para matar a un enemigo.","","''Conforme mi tiempo en este lugar termina, comienzo a reflexionar sobre mi segunda muerte. ¿Cuál será la última alma que recuerde mi nombre? Y cuando su tiempo aquí también termine... ¿qué sucederá conmigo?''. —Benefactor Eminente","Unidad",["AVE"],["Islas de la Sombra"],"RARA"],"04SI011":["Hacia el Ocaso","Roba 1.\nAnochecer: Activo el efecto de Anochecer de un aliado e ignoro cualquier porción que requiera un objetivo.","","''Ven, cariño. No hay nada que temer''. —Madre Máscara","Hechizo",[],["Islas de la Sombra"],"RARA"],"04SI018":["El Bosque Retorcido","Cuando haya visto atacar a 3+ aliados con Temible o Anochecer, destrúyeme para invocar 1 Vilemaw.","","Sus altares pueden estar dormidos y sus caminos pueden parecer extraños,\npero, en la penumbra, aún se desliza la bestia que los tontos olvidaron.","Hito",[],["Islas de la Sombra"],"ÉPICA"],"04SI015":["Escarabajo de Mar","Cuando otro aliado muere o se activa Último Aliento: Desecho 1.","","''Muy bien, ¡preparen esas trampas! Y recuerden: si ven alguno de esos escarabajos de mar, ignórenlos. No pondré en riesgo la integridad de la quilla por lo que sea que se hayan estado comiendo, ¿entendieron?''. —Capitán de Aguasturbias","Unidad",["MONSTRUO MARINO"],["Islas de la Sombra"],"RARA"],"04SI004":["Las Alas y la Ola","Al jugar: Puedo ser Primera Ola o Viento Final.","","Los Kinkou solo hablan de dos dioses: la primera ola, quien acuna la vida en sus aguas tibias, y el viento final, quien roba la vida en sus últimos suspiros frígidos.","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"04SI017":["Canción de las Islas","Otorgo Robo de Vida, Temible y Endeble a un aliado.","","''Ven, pequeñín. Ve lo que yo veo; siente lo que yo siento. No temas a la oscuridad''. —El Prendevelas","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"04SI054":["Soldado Camavorana","Cuando me invocan, invoco 1 Niebla Invasiva.","","Los soldados de Camavor marcharon con Viego en la vida y de nuevo en la muerte. Su lealtad es inquebrantable.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"04SI001":["Alivio de Cordero","Doy ''No me pueden dañar ni matar'' al aliado Más débil en esta ronda.","","''Brilla una vez más antes del final''. —Oveja","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"04SI056":["Niebla Devastadora","Dreno 2 a 2 enemigos.","","''Tomaré lo que quiera y prescindiré de lo que no''. —Viego","Hechizo",[],["Islas de la Sombra"],"RARA"],"04SI012":["Raposa Astral","Al jugar: Mato a un aliado para infligir 3 de daño al nexo enemigo.","","Un gran cantidad de tribus targonianas hablan de la Raposa, una diosa de la muerte que aparece como una estrella solitaria en el cielo nocturno. Según reza la leyenda, la Raposa desciende sobre la montaña cada vez que alguien muere y se lleva su alma a los cielos para crear su propia constelación oscura.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"04SI029":["Desesperación","Elige una unidad para Golpear tu nexo. Luego, mátala.","","''Di todo de mí para encontrarla... pero no fue suficiente''. —Viego","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"04SI009":["Tejealmas","Cuando me invocan, recibo +1|+1 y Temible si un aliado murió en esta ronda.","","''Había una vez un joven desafortunado que se animó a cortejar a una araña; sin embargo, nunca se imaginó que terminaría atrapado en su telaraña...''.","Unidad",["ARAÑA"],["Islas de la Sombra"],"COMÚN"],"04SI013":["Madre Máscara","Al jugar: Mato a un aliado para recibir sus estadísticas y palabras clave.","","Dicen que la Madre Máscara creó a Kindred, así como creó a todas las encarnaciones de la muerte. Pero ¿quién más podría haber creado su máscara, sino ella misma?","Unidad",[],["Islas de la Sombra"],"COMÚN"],"04SI021":["Serpiverno Rastrero","Para usarme, Golpeo a un aliado o inflijo 3 de daño a tu nexo.","","Al principio, los soldados demacianos creyeron oír docenas de garras rozando las baldosas de la plaza. Y no fue sino hasta que irrumpió en la atalaya que entendieron que todas aquellas extremidades eran parte de la misma criatura.","Unidad",["DRAGÓN"],["Islas de la Sombra"],"COMÚN"],"04SI002":["Viaje Espiritual","Mato a una unidad y luego la revivo.","","''Esto es solo un interludio''. —Oveja","Hechizo",[],["Islas de la Sombra"],"RARA"],"04SI053":["Hidravid Invasora","Cuando me invocan o al Inicio de la ronda: Invoco 1 Niebla Invasiva.","","Maokai trabajó arduamente para cultivar la vida en las Islas de la Sombra. La ambivalencia de la niebla hace que sus ironías no sean menos crueles.","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"04SI003":["Ícono Borroso","Cuando me invocan, invoco 1 Presa.","","¿Quién podría olvidar a su propio dios de la muerte, sino aquellos que fueron maldecidos con la inmortalidad? ¿Y qué mayor temor puede sentir un dios, si no es el temor al olvido? ","Unidad",[],["Islas de la Sombra"],"COMÚN"],"04SI028":["Dragón Camavorano","Para usarme, Golpeo a un aliado o inflijo 3 de daño a tu nexo.\nSi mato a una unidad, Dreno 1 del nexo enemigo.","","Por siglos, la Niebla Negra buscó criaturas por todo el mundo para retorcerlas y convertirlas en versiones de pesadilla de sus antiguas existencias.","Unidad",["DRAGÓN"],["Islas de la Sombra"],"RARA"],"04MT014":["Ojo del Ra-Horak","Cuenta regresiva 1: Lanzo Aturdir a los 2 enemigos Más débiles.\nAmanecer: Invoco una copia mía con Cuenta regresiva 2.","","''Que el sol vierta Su luz sobre nosotros. ¡Aquellos que sean débiles e indignos se esconderán de Su mirada!''. —Sacerdotisa Solari","Hito",[],["Targón"],"RARA"],"04MT008":["Malphite","Al jugar: Lanzo Aturdir a un enemigo.","Si gastaste 10+ de maná en invocar Hitos. Cuando subo de nivel, si tienes la ficha de ataque, creo 1 Fuerza Imparable en la mano.","''¡Y ahí está la última parada del tour de Targón de Chip! ¡Es PAPÁ! Es el MÁS GRANDOTE de los gigantes de Targón y déjenme decirles que tiene un humor muy feo. ¡No intenten escalarlo! ¡Los picos le hacen cosquillas y no querrán que estornude a medio camino!''.\nAventuras con Chip, parte 6","Unidad",[],["Targón"],"Campeón"],"04MT010":["Pico de Estrella","Cuenta regresiva 2: Creo 2 cartas Celestiales aleatorias de costo 3 o menos en la mano.","","Aquellos que se disponen a escalar el Monte Targón pronto disfrutan de las vistas más gloriosas de todo Runaterra... Y, a medida que van subiendo, así también mejoran las recompensas.","Hito",[],["Targón"],"RARA"],"04MT005":["Chip","Cuando hayas invocado un Hito en esta partida, recibo +2|+2.","","''Hola, pues soy Chip y estoy aquí para enseñarles el Monte Targón. ¡Es bien, bien grandote, así que espero que traigan buen calzado para caminar! ¡ANDANDO!''.\n—Las Aventuras con Chip, parte 1","Unidad",[],["Targón"],"COMÚN"],"04MT009":["Escalera de Caracol","Cuenta regresiva 3: Creo 1 Semilla de Fuerza en la mano.","","''¡Esta es la primera parada del tour! Le llamo el doblapiernas porque UY, UY, UY, ¡son muchos escalones! La vista también es genial y es una de las mejores cosas de Targón. Bueno, ¡SIGAMOS!''.\n—Aventuras con Chip, parte 2","Hito",[],["Targón"],"RARA"],"04MT001":["Ruta de Derrumbes","Cuenta regresiva 2: Lanzo Aniquilar al enemigo Más débil.","","''Muy bien, ¡TODOS tengan cuidado porque soy una GOTA GRANDE y he caído por aquí un par de veces y DÉJENME DECIRLES que es un largo camino hasta abajo! Y estoy hecha de wok, así que solo reboto, pero eso no aplica para ustedes... así que tengan cuida... ¡Ah, ahí está Roco! ¡Vamos a saludar!''.\n—Aventuras con Chip, parte 3","Hito",[],["Targón"],"COMÚN"],"04MT018":["Íbice Asustado","Cuando recibo apoyo, el aliado que me apoya y yo recibimos +1|+1 en esta ronda.","","''No le temas al vendaval.\nSus aullidos cruzan la montaña y viajan a través del valle\nJamás te inquietes, pues no tienes nada que temer\nDescansa, cariño, porque mamá está cerca''. —Canción de cuna targoniana","Unidad",[],["Targón"],"COMÚN"],"04MT004":["Guardián Azul","Último Aliento: Invoco 1 Blasón de Perspicacia.","","''Vamos, TODOS, díganle hola a Azul: '¡HOLA, AZUL!'. Una vez creí que me estaba contestando, pero ahora que lo pienso, tal vez fue mi voz rebotando en las paredes. QUÉ HACER, es todo mágico y así y es azul, así que si me preguntan, ¡no NECESITA hablar! ¡BUENO, ADIÓS, AZUL, NOS VAMOS!''.\n—Aventuras con Chip, parte 5","Unidad",[],["Targón"],"COMÚN"],"04MT013":["Halcón Solar Solari","Amanecer: Lanzo Aturdir al enemigo Más fuerte.","","Los solari creen que fueron los halcones solares de Targón, con su intenso brillo, quienes llamaron la atención de la Llama Inmortal y la inspiraron a iniciar su ciclo de muerte y resurrección.","Unidad",["AVE"],["Targón"],"COMÚN"],"04MT003":["Elemental de Tierra","Cuando hayas invocado 4+ Hitos en esta partida, recibo +3|+0.","","''¡Él es ROCO! Es un tipo grandote que ha estado por aquí BASTANTES VECES, les digo. Y sé que tiene un aspecto genial y sé que parece un buen tipo, pero anda cargando cosas bastante pesadas y a veces se cae sobre la gente, así que TENGAN CUIDADO, ¿bueno? ¡Gracias! ¡Sigamos!''.\n—Aventuras con Chip, parte 4","Unidad",[],["Targón"],"COMÚN"],"04MT002":["Rompepiedras","Al jugar: Si invocaste 4+ Hitos en esta partida, inflijo 4 de daño a un enemigo y 2 de daño al nexo enemigo.","","De vez en cuando, los grandes colosos de Targón despiertan de su sueño y avanzan a terrenos nuevos sobre la gran montaña. Estos eventos nunca transcurren en silencio, y pocas veces son seguros.","Unidad",[],["Targón"],"ÉPICA"],"04MT006":["Epifanía Astral","Convocar.\nSi tienes un aliado Celestial, reemplazo tu mazo con 20 copias de Contempla el Infinito.","","''¡Mira, Kulun! ¡Las estrellas tienen muchas historias que contar! ¿Cuál de todas ellas disfrutaremos esta noche?''. —Soñadora Lunar","Hechizo",[],["Targón"],"ÉPICA"],"04MT012":["Llamado del Destino","Otorgo +8|+8 a un aliado en la mano.","","''Acepta tu destino y brilla con más fuerza de la que nadie jamás haya conocido''. —Taric","Hechizo",[],["Targón"],"ÉPICA"],"04MT007":["Golpe en el Suelo ","Lanzo Aturdir a un enemigo. Inflijo 3 de daño a esa unidad si invocaste un Hito en esta partida.","","''Ups, sí, eso es solo la tierra estremeciéndose, definitivamente no es papá haciendo algo con sus manos. NOP. BUENO. ¡Adelante y PARA ARRIBA!''. —Chip","Hechizo",["ELEMENTAL"],["Targón"],"RARA"],"04MT015":["Cielos Alineados","Amanecer: Creo una carta aleatoria con Anochecer en la mano.\nAnochecer: Creo una carta aleatoria con Amanecer en la mano.","","Así funciona el ciclo del día y la noche: uno siempre sigue al otro.","Hechizo",[],["Targón"],"COMÚN"],"04DE004":["Rastreadora Ferviente","Cuando invocas una carta Élite, cuesto 1 menos.","","Aunque los noxianos habían colocado bien su trampa, nadie conocía el bosque mejor que los exploradores de Demacia. Cada rama rota, cada huella era una pista que los acercaba más a su príncipe.","Unidad",["ÉLITE"],["Demacia"],"RARA"],"04DE014":["Botana de Dragón","Cuando juegas un Dragón, me Golpea y robas 1.","","''¿Oyes ese grito que viene de muy arriba? No es un ave, chico. Es el grito de un dragón cazando''. —Granjero demaciano","Unidad",[],["Demacia"],"COMÚN"],"04DE001":["Lord Distinguido","La primera vez que lance Desafío a un enemigo, recibo Barrera en esta ronda.","","Después de enterarse de la desaparición de su hijo, el rey Jarvan III le encargó a Lord Barrett Buvelle, su amigo de confianza, que organizara un grupo de búsqueda. Por fortuna, el príncipe regresó sano y salvo, pero para desgracia del rey, Lord Buvelle no.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"04DE012":["Promoción de Campo","La próxima vez que uses una unidad en esta ronda, le otorgo Explorar. Ahora es una unidad de Élite.","","Cuando se pone a prueba a los demacianos, demuestran que están a la altura.","Hechizo",[],["Demacia"],"COMÚN"],"04DE003":["Cataclismo","Un aliado inicia un ataque gratis al lanzar Desafío a un enemigo.","","''¡Por el rey!''. —Jarvan IV","Hechizo",[],["Demacia"],"RARA"],"04DE002":["Égida Dorada","Doy Barrera a un aliado en esta ronda. Lanzo Preparar.","","''¡Una vez más, soldado de Demacia!''. —Jarvan IV","Hechizo",[],["Demacia"],"RARA"],"04DE006":["Destreza Bélica","Otorgo +1|+1 a un aliado.","","''Tengo una que otra cosa que podría enseñarte''. —Lord Buvelle","Hechizo",[],["Demacia"],"COMÚN"],"04DE008":["Jarvan IV","Cuando atacas, paga mi costo para invocarme. Luego, lanzo Desafío al enemigo Más fuerte.","Si los aliados sobrevivieron a 3+ Golpes de unidades defensoras enemigas.","Los noxianos sabían a dónde llevaría la cacería al príncipe Jarvan. Sabían cuántos demacianos estarían a su lado, y sabían que su honor no le permitiría huir. La trampa estaba lista.","Unidad",["ÉLITE"],["Demacia"],"Campeón"],"04DE005":["Cithria, Dama de las Nubes","Cuando me invocan, duplico el Poder y la Vida de los otros aliados y les otorgo Desafío.","","''¿A quién más podía enviar Demacia a salvar a su príncipe que a la mismísima Dama de las Nubes?''. —Rey Jarvan III","Unidad",["ÉLITE"],["Demacia"],"ÉPICA"],"04DE020":["Guardia Dracónico Arruinado","Cuando un aliado con Furia mata a una unidad, le otorgo +1|+1 adicional.","","La niebla alteró la mente de Gregem al punto en el que se vio forzado a recordar una y otra vez lo ocurrido en Wrenwall. La amargura y furia que yacían dormidas durante muchísimo tiempo en su interior lo llevaron a traicionar a sus antiguos camaradas.","Unidad",[],["Demacia"],"COMÚN"],"04DE010":["Rey Jarvan III","Cuando me invocan, roba 1 Jarvan IV.\nSi ya se encuentra en juego, doy Desafío y Explorar a los aliados en esta ronda.","","''¿Serías tan amable de decirme qué sacrificaría un padre por salvar a su hijo? Mejor aún: ¿qué sacrificaría un rey?''. —LeBlanc","Unidad",["ÉLITE"],["Demacia"],"ÉPICA"],"04DE016":["Kadregrin, el Arruinado","Al jugar: Otorgo Desafío y +1|+1 a un aliado.","","Kadregrin sembró el caos y el miedo mucho antes de que la Niebla Negra llegara a Demacia. Sin embargo, bajo el mando de Viego, sus habilidades vigorizaron a todas las fuerzas del Rey Arruinado.","Unidad",["DRAGÓN"],["Demacia"],"RARA"],"04DE013":["Cornupétreo Imponente","No recibo daño de hechizos ni Habilidades de enemigos.","","Se dice que los asombrosos Cornupétreos vienen de un tiempo en el que el bosque de petricita era joven, y que sus cuernos están hechos de un material similar al que conforma a aquellos árboles ancestrales.","Unidad",[],["Demacia"],"COMÚN"],"04DE015":["Vuelo de los Aliveloces","Al jugar: Creo 1 Aliplata de la Vanguardia, Ataque Cegador o Rastreadora Plumaveloz en la mano.\nAl atacar: Doy +1|+1 en esta ronda a los aliados que estén lanzandoDesafío.","","Ver sobrevolar a los Aliveloces inspira a los soldados de Demacia que luchan en los campos más profundos. Cuando se les ve cruzar las nubes y descender, aquellos en tierra recobran sus fuerzas y continúan luchando.","Unidad",["ÉLITE","AVE"],["Demacia"],"ÉPICA"],"04DE007":["Escudera Penitente","Cuando me invocan, si Contemplas una carta Élite, creo 1 Estandarte Raído en la mano.","","Fue cuando cruzó los muros de la ciudad que sus piernas finalmente se rindieron. La Vanguardia Valerosa llevaría su mensaje al rey y este salvaría al príncipe. De esta forma, se corregiría su error y su honor se preservaría intacto.","Unidad",[],["Demacia"],"COMÚN"],"04DE009":["Jinete Gallardo","La primera vez que lance Desafío a un enemigo, me transformo en Caballería de la Vanguardia.","","Una vez que se hizo el llamado, todos y cada uno de los soldados de Demacia se unieron a la búsqueda del príncipe. La premura era de extrema importancia.","Unidad",["ÉLITE"],["Demacia"],"RARA"],"05BC058":["Kennen","Cuando me invocan, creo 1 Marca de la Tormenta en la mano.","Si invocaste al mismo aliado 5+ veces.","Kennen también había escuchado el rugido de... algo invisible. No importaba si era hombre o monstruo, los Kinkou protegerían su tierra a cualquier costo.","Unidad",["YORDLE"],["Ciudad de Bandle","Jonia"],"Campeón"],"05BC010":["Entrenador de Tiburones","Cuando los aliados atacan, invoco 1 Dientecorto atacante.","","La rutina del entrenador es la misma cada noche: pescado y cerveza para cenar, una pitada a su pipa de burbujas, seguida de besos en el hociquito y un cuento para dormir a sus tiburones.","Unidad",["YORDLE"],["Ciudad de Bandle","Aguasturbias"],"RARA"],"05BC102":["Mago Sabihondo","Inicio de la ronda: Restablezco 1 de maná de hechizos.","","Si no existe mayor dolor que cortarse con una hoja de papel, no existe nadie que comprenda mejor el dolor que un bibliotecario.","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC230":["Portal Espiritual","Para usarme, descarta 1. Otorgo +1|+1 a los aliados.","","''Siempre olvido cómo funcionan estas cosas''. —Poppy","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC099":["Explorador Fortachón","Cuando me invocan, recibo +1|+1 por cada aliado yordle adicional que tengas.","","''¿Mi secreto? Tendrás que preguntárselo a mis bíceps. Ellos hablan por sí solos''.","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC133":["Tristana","Gano +1|+0 por cada aliado multirregión invocado en esta partida.\nCuando invocas un aliado multirregión, le otorgo +1|+0.","Si invocaste 5+ aliados multirregión.","''Plan A: creamos un agujero con explosivos para entrar y empezamos a disparar. Si no funciona, pasamos al plan B: creamos un agujero con explosivos para salir y seguimos disparando. Luego, nos reagrupamos y pasamos al plan C, que es básicamente el Plan A de nuevo...''.","Unidad",["YORDLE"],["Ciudad de Bandle"],"Campeón"],"05BC023":["Minití","Fin de la ronda: Si dañaste al nexo enemigo en esta ronda, me transformo en Megatí.","","A los minitís les gusta: tomar la siesta sobre las cálidas rocas al lado de las tierras tribales de Nakotak. A los minitís no les gusta: que yordles descarados los quiten a empujones de dichas rocas...","Unidad",[],["Ciudad de Bandle"],"ÉPICA"],"05BC029":["Yuumi","Inicio de la ronda: Otorgo +1|+1 a la unidad a la que estoy Unida. De lo contrario, yo recibo +1|+1.","Si yo o la unidad a la que estoy Unida atacamos 3 veces.","Yuumi admitió que, a pesar de todos los problemas que causaba, Libro le caía bastante bien. ¡Le gustaba oler su aroma, ver sus ilustraciones y hasta saltar a través de sus portales! Pero nada le gustaba más que tener a Norra de vuelta en casa, sana y salva.","Unidad",["FEÉRICO","GATO"],["Ciudad de Bandle","Targón"],"Campeón"],"05BC078":["Arpón Eléctrico","Para usarme, descarta 1. Inflijo 2 de daño a una unidad y 2 de daño al nexo enemigo.","","''¡Vamos a darles un espectáculo!''. — Rumble","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC106":["Babosa Gruñona","","","''A pesar de ser bastante pequeña, la babosa gruñona tiene un apetito bastante grande y lo que solo puedo describir como 'un verdadero problema de actitud'''.\n— Registro ecológico del Caracolista, día 17","Unidad",[],["Ciudad de Bandle","Aguasturbias"],"COMÚN"],"05BC161":["Gnar","Al golpear: Creo 1 Palito Pinchador en la mano o, si ya tienes una igual, reduzco en 2 su costo.","Si al Fin de la ronda dañaste al nexo enemigo en esta ronda.","Hace mucho tiempo, Gnar y los suyos prosperaron en el Valle de Nakotak. Era un lugar sencillo y alejado de todo signo de modernidad. Fue una desventura que Gnar perdiera este territorio debido al paso del tiempo, pero fue una bendición que el tiempo no funciona como siempre en la Ciudad de Bandle.","Unidad",["YORDLE"],["Ciudad de Bandle","El Fréljord"],"Campeón"],"05BC073":["Química Ingeniosa","Cuando me invocan, invoco 1 Bomba Destartalada.","","Giselle era una de las mejores alumnas del profesor Heimerdinger, hasta que escuchó sobre los extraños experimentos que Ziggs realizaba en Zaun. A partir de entonces, todo fue que si los ''hexplosivos'' esto, que ''¿cuándo me vas a recomendar para la pasantía?'' lo otro. ","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC039":["Granadero Huraño","Alianza: Invoco un seguidor yordle aleatorio que cueste 3 o menos.","","''Alice tiene dos tiros: uno te da la bienvenida, y el otro te despide. ¿Quieren conocerse?''.","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC148":["Hadosos Furiosos","Cuando me invocan, si infligiste daño al nexo enemigo +4 veces en esta partida, recibo 4 de Impacto.","","Correoso por fuera, duro y arenoso por dentro.","Unidad",["FEÉRICO"],["Ciudad de Bandle","Piltóver y Zaun"],"COMÚN"],"05BC119":["Súbdito","Último Aliento: Creo una copia mía en la mano al siguiente Inicio de la ronda.","","''¡Un verdadero supervillano nunca tiene demasiados súbditos! Esos pequeños monitos que conocen su lugar, obedecen cada una de tus palabras y siempre vienen en busca de más órdenes''.\n— Extracto del cap. 2 del ''Manual para ser un supervillano'', por Lord Veigar","Unidad",[],["Ciudad de Bandle","Islas de la Sombra"],"COMÚN"],"05BC019":["Pez Arcoíris","","","El pez arcoíris se alegró de hacer un poco de reconocimiento aéreo, incluso si eso significaba dar un salto mayor a cualquiera que hubiera dado en su vida. Haría cualquier cosa, por mínima que fuera, por alejarse de la hambrienta mirada de Yuumi.","Unidad",["FEÉRICO"],["Ciudad de Bandle"],"COMÚN"],"05BC093":["Veigar","Cuando me invocan, creo 1 Oscuridad en la mano si no la tienes. Inicio de la ronda: Otorgo 1 de daño adicional a tus copias de Oscuridad en todas partes.","Si infligiste 12+ de daño con Oscuridad.","''Este mundo va a temerme. Van a llevar consigo mis cicatrices por toda la eternidad. Van a sufrir aplastados por el peso de mi poder. ¡Van a temblar bajo la sombra de mi inmensidad!''. \n— Extracto del cap. 1 del ''Manual para ser un supervillano'', por Lord Veigar","Unidad",["YORDLE"],["Ciudad de Bandle","Islas de la Sombra"],"Campeón"],"05BC007":["Apiladores de Piedras","","","Los yordles aún no logran comprender qué es la gravedad, aunque la gravedad tampoco ha logrado comprender a la Ciudad de Bandle.","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC174":["¡Amistad!","Doy Barrera o Escudo Antihechizos a un aliado en esta ronda.","","''¡Te protegeré con mi feroz y colérico... maullido!''. —Yuumi","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC185":["Juego de Caparazones","Restablezco tu maná de hechizos. Doy Evasión y +1|+1 a un aliado en esta ronda.","","''Los VEO entrar en el caparazón de la izquierda, pero cuando ELIJO ese caparazón: está vacío. Ya empiezo a sospechar que este juego está arreglado...''.\n —Registro ecológico del caracolista, día 14","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC096":["Tenor del Terror","Cuando me invocan, si jugaste una carta creada o mataste a una unidad con un hechizo en esta partida, invoco 1 Bajo del Agobio.","","Si Veigar necesitaba ayuda para inclinar la balanza de la justicia, nadie era más adecuado para el trabajo que esos dos. Sabían todo. Excepto el mixolidio.","Unidad",["YORDLE"],["Ciudad de Bandle","Islas de la Sombra"],"RARA"],"05BC088":["Rumble","Al jugar: Descarta hasta 3 cartas para otorgar Impacto a los Rumbles aliados en todas partes por la primera, Ataque Rápido por la segunda y Escudo Antihechizos por la tercera.","Si he visto a aliados Yordle Mecha infligir 12+ de daño.","''Yyyyyy eso es todo''.\n''ERROR''.\n''¿QUÉ? ¡Pero si acabo de arreglar eso!''.\n''FALLO INMINENTE DEL SISTEMA''.\n''Apágate, por favor. ¡APÁGATE!''.\n— Rumble y Tristy","Unidad",["MECHA","YORDLE"],["Ciudad de Bandle","Noxus"],"Campeón"],"05BC056":["Monje de la Ráfaga","Cuando me invocan, creo 1 Pose de Nube en la mano.","","''La técnica de nuestra escuela se deriva del control sobre la respiración. Al igual que una tempestad nace del viento''.","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC190":["Mechanalista de la Arena","Al atacar: Doy +2|+0 a otros aliados atacantes en esta ronda.","","''¿Que cómo lo hago? ¿Narrar partidas gritando noche tras noche? Pues hago gárgaras con aceite de motor. Cinco minutos en la mañana, cinco en la noche''.","Unidad",["YORDLE"],["Ciudad de Bandle","Noxus"],"ÉPICA"],"05BC042":["Batido Moritamorada","Aumento a un aliado a 3|3 en esta ronda.","","''Yo solía ser como tú: no levantaba ni un honguito. Pero entonces, encontré 'Batidos, por Moritamorada'. Tiene todo lo que un yordle necesita para convertirse en héroe. Así que, cuando hayas dado todo de ti en un entrenamiento, energízate con un 'batido' y conviértete en el bro más bro, ¡como yo!''. \n— Publicidad impresa","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC205":["Horizonte de Sucesos","Lanzo Aturdir a un enemigo y luego aturdo a todos los enemigos con 2 o menos de Poder.","","''Solo... quédate justo ahí...''. — Veigar","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC223":["Aprisionamiento","Elige 1 de 3 unidades o hechizos del mazo enemigo y planto 3 Hongos Venenosos en todas sus copias.","","''Regla 986: las trampas NO son juguetes... ¡pero son muy divertidas!''.","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC091":["Promotor de la Arena","Al jugar: Descarta 1 para Manifestar un Yordle Mecha y reduzco en 1 su costo.","","''¡BOLETOS! ¡COMPREN SUS BOLETOS! ¡A MITAD DE PRECIOOOOOOO! Me lleva, si no logro vender estos boletos, el jefe va a matarme... literalmente''.","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC163":["Ziggs","Al atacar: Inflijo 1 de daño a mi enemigo defensor y al nexo enemigo.","Si destruiste 4+ Hitos aliados.","''Es MUY IMPORTANTE que demos una buena impresión. El nuevo inspector de seguridad viene a visitarnos, ¡y ya sabes lo que eso significa!''.\n''¿No más explosiones?''.\n''¿¡QUÉ?! ¡No! ¡Significa que tienes que explotar cosas donde no te vea! ''No más explosiones''... ¡¿Estás loco?!''. —Ziggs y Otto","Unidad",["YORDLE"],["Ciudad de Bandle","Shurima"],"Campeón"],"05BC151":["Maga de Espejos","Cuando juegas un seguidor creado, invoco una copia exacta. Cuando juegas un hechizo creado, lo copio con los mismos objetivos.","","''Ah, sí, es toda una especialista en espejos. Hace que mis diseños parezcan aún más sublimes y, con un pequeño truco de iluminación, incluso consigue darle a cierta persona un toque de verticalidad muy necesario...''. —Alto Modisto ","Unidad",["YORDLE"],["Ciudad de Bandle"],"ÉPICA"],"05BC027":["Minas Hexplosivas","Cuando me invocan o tú me destruyes, lanzo Aturdir al enemigo Más fuerte.","","''¿Por qué dices que no parece del todo seguro?''. — Ziggs","Hito",[],["Ciudad de Bandle"],"COMÚN"],"05BC200":["Portal Yordle","Para usarme, descarta 1. Manifiesto un Yordle que cueste 3 o menos y lo invoco.","","''¡Jamás dejes a un artillero detrás!''. —Tristana","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC021":["Bomba Rebotante","Inflijo 2 de daño a una unidad o 1 de daño a dos enemigos.","","''¡Cúbranse todos!''. — Ziggs","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC167":["Comando de Bandle","Golpe al Nexo: Creo 1 Buhifelino Hambriento en la mano.","","''¡De día armados y de noche arropando niños para dormir!''.","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC179":["Comando Yordle","Al atacar: Otorgo +0|+1 a aliados con igual o menor Poder que yo.","","''¡Poppy! Excelente ejecución de nuestra última táctica. ¿Qué te parece si la llamamos ''Tormenta de pétalos de maní''?''.\n''Mmm, este... digamos que solo les pegué con mi martillo. ¿No podemos llamarla ''Martillo'' a secas?''.\n''¡Pero así le pusimos a las últimas tres!''. —Kip y Poppy","Unidad",["YORDLE"],["Ciudad de Bandle","Demacia"],"ÉPICA"],"05BC214":["Bomba Megainfernal","Inflijo 1 de daño a todos los enemigos. Repito la acción.","","''Tráiganme... ¡La Gigante!''. —Ziggs","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC221":["Círculo de Hongos","Cuando me invocan o al Inicio de la ronda: Recibo Poder en esta ronda equivalente a la cantidad del resto de otros aliados feéricos en juego o Unidos.","","Estos pequeños cabeza de alfiler son adorables... y hasta cultivan hongos por su cuenta.","Unidad",["FEÉRICO"],["Ciudad de Bandle","Jonia"],"RARA"],"05BC041":["Poppy","Al atacar: Otorgo +1|+1 a aliados con igual o menor Poder que yo.","Si ataqué 3 veces con aliados.","La humildad es una señal de heroísmo, pero muchos historiadores estarían de acuerdo en que Poppy se pasa de la raya.","Unidad",["YORDLE"],["Ciudad de Bandle","Demacia"],"Campeón"],"05BC176":["Proyectil Acechador","Otorgo +1|+0 a un aliado. Inflijo 1 de daño a un enemigo.","","''Fiummmmm!''. —Yuumi","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC105":["Artilleros de Bandle","Cuesto 1 menos por cada aliado multirregión que hayas invocado en esta partida.\nCuando me invocan, recibo 3 de Impacto.","","Objetivos de grupo.","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC066":["Plumita Rapidita","","","''¿D... ó... n... d... e... e... s... t... á... N... o... r... r... a...? Cielos, ¿qué le digo?''. —Mozotón","Unidad",["FEÉRICO"],["Ciudad de Bandle"],"COMÚN"],"05BC177":["Dragón de Papel","","","''Un doblez más y... ¡tenemos una jirafa! Su nombre es Medias''. \n''¿Por qué 'Medias'?''. \n\"Norra adora las medias. Y si a ella le gustan... ¡a mí también!''. —Mozotones","Unidad",["FEÉRICO"],["Ciudad de Bandle"],"ÉPICA"],"05BC136":["Montón de Chatarra","Para usarme, descarta 1.\nManifiesto un Yordle Mecha.","","''Basura. Restos. Desperdicios... Uy, ¡ESTO es a lo que me refería!''. — Rumble","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC164":["Dardo Venenoso","Inflijo 1 de daño a cualquier objetivo y planto 3 Hongos Venenosos en el mazo enemigo.","","''¡Ja, ja! ¡Justo en el blanco!''. —Teemo","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC194":["El Árbol de Bandle","Inicio de la ronda: Creo un seguidor de una nueva región en la mano. Luego, si he visto a aliados de 10 regiones diferentes, gano la partida.","","El Árbol de Bandle, el cual se extiende hasta una distancia desconocida en el cielo, es un elemento imperdible en el corazón de la ciudad. Bajo sus grandes y nudosas ramas, algunos yordles ven un rayo de esperanza y amistad, mientras que otros ven un monolito ominoso y lleno de misterios. Todos coinciden en que contemplar el Árbol de Bandle es como espiar el alma de algo muy antiguo y poderoso.","Hito",[],["Ciudad de Bandle"],"ÉPICA"],"05BC127":["Rissu, la Tormenta Silenciosa","Cuando me invocan, invoco 1 Nubetormenta.","","Entretejer una Nubetormenta tomaba su tiempo. Tiempo que Rissu no tenía. Sus manos trabajaban arduamente mientras la Aberración se acercaba. Un poco de nube aquí, algún relámpago por allá. Y entonces... ¡CRAC! ¡BUM! Lo había logrado, pero ¿sería suficiente?","Unidad",["YORDLE"],["Ciudad de Bandle"],"ÉPICA"],"05BC216":["Artilugio Yordle","Destruyo un Hito o creo 2 seguidores multirregión aleatorios en la mano.","","''¡Agárrense... allá vamos!''. —Gemelos Bombarderos","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC212":["Inspector de Seguridad","Inicio de la ronda: Creo 1 ¡Inspección Superada! en la mano.","","Al principio, Wilfred era escéptico. También continuó siendo escéptico durante todo el evento. De hecho, fue escéptico hasta el final, pero Ziggs y los otros expertos en hexplosivos demostraron saber muy bien cómo crear un heimermoso espectáculo de fuegos artificiales. ","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC141":["Estribillo Heroico","Doy +2|+1 a dos aliados en esta ronda.","","''Ahí estaban los héroes, espalda con espalda...''.\n''¡Trasero con trasero! ¡Je, je, je!''.\n''¡N-no! Peppy, si vas a opinar, hazlo en momentos menos críticos!''. \n—Historias para las fogatas yordle","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC209":["Defensa Antiestrés","Establece las estadísticas de una unidad a 1|6 en esta ronda.","","El halcotriz es una montura leal y confiable en circunstancias normales. Sin embargo, cuando se las somete a un estrés excesivo, pueden reaccionar de formas... inusuales.","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC210":["Escupellamas","Otorgo +2|+0 e Impacto a un aliado.","","''Si no están aullando de dolor, ¡debo subir aún más el calor! Je, je, je''. — Rumble","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC013":["Tentáculos Traviesos","Tu oponente desecha su carta de menor costo.","","''Recordatorio a mí mismo: en la próxima expedición, lleva los objetos de valor en los bolsillos DELANTEROS''. \n— Registro ecológico del caracolista, día 19","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC100":["Cachorrhongo","Al golpear: Planto 3 Hongos Venenosos en el mazo enemigo.","","''¿Qué dices, muchacho? ¿Dos de los reclutas estaban explorando en el bosque y se toparon con un temible monstruo de pasto, y ahora podrían tener una prolongada y dolorosa muerte? ¡Muéstrame el camino!''. — Teemo","Unidad",["PERRO"],["Ciudad de Bandle"],"COMÚN"],"05BC098":["Catalizador Retorcido","Al golpear: Otorgo 1 de daño adicional a tus copias de Oscuridad en todas partes.","","La oscuridad viene en muchas formas y tamaños, algunas son incluso SORPRENDENTEMENTE adorables.","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC122":["Yordle Novato","Cuando invocas otro yordle, recibo +2|+0 en esta ronda.","","''Pastitus gigantiferus. Estas terroríficas criaturas se camuflan como si fueran pasto y atacan a cualquiera que las pise. Si te las encuentras, ¡huye y no mires atrás!''. — Ava Sionada","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC120":["Capitán Yordle","Cuando invocas a otro aliado con el mismo poder o menos que el mío, le otorgo +1|+1.","","''¡Salir a una aventura implica encontrar malosos y convertirlos en tus amigos!''.","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC046":["Puño de Trueno","Cuando me invocan, si invocaste 1 Puño de Trueno en esta partida, me transformo en Masa, Rayo que Cae.","","Mientras Masa golpeaba el muñeco de práctica, un rayo de luz emanó del puño, partió la madera en dos y le chamuscó los pelitos de la mano. Jaló la cuerda para recoger la mano de bronce mientras pensaba en su entrenamiento... Por fin estaba listo. De repente, un rugido monstruoso hizo eco en la distancia.","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC018":["Caballero Pomposo","","","''Novecientos noventa y ocho... novecientos noventa y nueve... ¡mil! Ahora sí, Bawky, te ves mejor que nunca. Bueno, ¡ahora haz los míos!''.","Unidad",["YORDLE"],["Ciudad de Bandle","Demacia"],"RARA"],"05BC132":["Tiro Destructor","Cuesto 2 menos si tienes 1 Tristana o si has jugado cartas de 4+ regiones en esta partida.\nInflijo 3 de daño a una unidad.","","En cada ¡KAPLAM! hay un ¡KABUM! esperando por nacer.","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC168":["Sapo Moteado","Fin de la ronda: Si dañaste al nexo enemigo en esta ronda, me transformo en Gigagrompo.","","A lo largo de varias generaciones, los yordles del Valle Nakotak trataron de entender a sus vecinos grompos. Los jefes Hegabo y Babobu habían tratado de picarlos con una rama. Sin embargo, fue el jefe Nakotak quien quiso ensayar un plan nuevo: iba a picarlos con una rama.","Unidad",[],["Ciudad de Bandle"],"RARA"],"05BC014":["Chiquidáctilo","Fin de la ronda: Si dañaste al nexo enemigo en esta ronda, me transformo en Terrodáctilo.","","Las criaturas del Valle Nakotak son tan variopintas y vivarachas como el territorio que habitan... y con las mismas probabilidades de que exploten.","Unidad",["AVE"],["Ciudad de Bandle"],"COMÚN"],"05BC138":["Reparadores","La primera vez que descartes una carta o inflijas daño al nexo enemigo, recibo +2|+1.","","''Bien, bien, buena pelea. Qué buen espectáculo dieron. Ahora limpien todo este desastre y eh, ya saben qué hacer: si hay algo rescatable, arréglenlo, lo ponen en la tienda y ¡lo volvemos a vender a su dueño! ¡JA, JA, JA, JA!''. — Karl, Jefe de la Arena","Unidad",[],["Ciudad de Bandle"],"COMÚN"],"05BC198":["Foto Grupal","Inflijo 1 de daño a una unidad. Si tienes 4+ aliados, inflijo 2 de daño.","","''Bueno, esta va para el periódico. ¡Y esta vez acuérdense de sonreír! Uno... dos... ¡tres!''. —Tristana\n","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC181":["Pose de Nube","Doy +2|+0 y ''Fin de la ronda: Lanza Retirada sobre mí'' a un aliado en esta ronda.","","''Vuelve a respirar y descubre tu fuerza!'' — Monje de la Ráfaga","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC160":["Protoporo","","","Los poros de antaño tenían las cabezas mucho más duras que sus parientes contemporáneos, haciéndolos un poco más tontos y mucho más tercos.","Unidad",["PORO"],["Ciudad de Bandle","El Fréljord"],"COMÚN"],"05BC005":["Doncellas de las Algas","Golpe al Nexo: Creo 1 Broma en la mano.","","''Estimado yo: acabo de tener un sueño rarísimo. Por un momento, estoy revolviendo las algas mientras busco mi sombrero de caracola, cuando de repente escucho la más maravillosa melodía. Lo siguiente que recuerdo es que estoy aquí sentado, pluma en mano, escribiendo estas palabras. No recuerdo haberme echado a dormir una siesta...''.\n— Registro ecológico del caracolista, día 22","Unidad",[],["Ciudad de Bandle"],"RARA"],"05BC020":["Asistente de Biblioteca","Golpe al Nexo: Roba un hechizo de costo 3 o menos.","","''¡Jelly es mi MEJOR AMIGA! Bueno, solo por después de ti, Libro. Y de Norra. De acuerdo, Jelly es mi TERCER MEJOR AMIGA. Sigue siendo una muy buena posición, ¡¿no?!''. —Yuumi","Unidad",["FEÉRICO"],["Ciudad de Bandle"],"COMÚN"],"05BC049":["Caracolista","Al jugar: Manifiesto un hechizo de tus regiones con costo 3 o menos.","","''¡Hoy es, sin duda, un día para recordar! ¡Una exploración a las profundidades! Espero que las cosas... ¡fluyan! ¡Ju, ju, ju!''. \n— Registro ecológico del caracolista, día 1","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC001":["Minitransformación","Transformo a una unidad en 1 Miniminití con 3|3 y la Silencio.","","''¡Ju, ju, ju! ¡Qué tierno! ¡Qué adorable! ¡Qué MINÚSCULO!''. — Veigar","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC026":["Caminos Ocultos","Cuesto 2 menos si has creado 2+ cartas en esta partida. Roba 2.","","Muy pocos forasteros conocen el camino a la Ciudad de Bandle, pero marcas extrañas en las rocas y en los árboles de Runaterra ofrecen pistas a quienes saben qué buscar.","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC152":["Viajeros Apáticos","Cuando me invocan, TODOS los jugadores roban 1. Luego, tu oponente descarta su carta de costo más alto.","","''El peor viaje del mundo''. —Elle","Unidad",["YORDLE"],["Ciudad de Bandle","Piltóver y Zaun"],"COMÚN"],"05BC070":["Ava Sionada","Cuando me invocan o al Fin de la ronda: Planto 3 Hongos Venenosos en el mazo enemigo.\nLas trampas en las cartas enemigas se duplican al activarse.","","''Regla 378: una buena exploradora siempre es valiente, siempre está lista ¡y siempre es osada!''.","Unidad",["YORDLE"],["Ciudad de Bandle"],"ÉPICA"],"05BC015":["Lagartín","Fin de la ronda: Si dañaste al nexo enemigo en esta ronda, me transformo en Lavagarto.","","''¡Cómete el pimiento!'', gritó Nakotak... o quizá no. ''¡No, TÚ cómetelo!'', respondió Jojo... o quizá no. Mientras discutían, un pequeño lagarto pasó a su lado al tiempo que perseguía una mosca más pequeña que él. Los dos yordles miraron al lagarto; luego, miraron el pimiento y, por último, se vieron entre ellos. Si existieran las bombillas de luz, una se hubiera prendido sobre sus cabezas.","Unidad",["REPTIL"],["Ciudad de Bandle"],"COMÚN"],"05BC145":["Escudera Yordle","Al jugar: Creo 1 Lancita o 1 Escudito en la mano.","","''Mi lanza también perteneció a un gran héroe... ¡Le pedí a Poppy que la sostuviera por un minuto!''.","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC140":["Trineo Poro","Al atacar: Invoco un Poro atacante aleatorio de costo 1.","","''Y tonces ESE poro Bobjim dijo como '¡VAMO' AHÍ!' y se jueron todo' al horizonte con todo' lo' poro' coshiendo atrá', ¡tratando 'e seguirle el ritmo!''. — Ingvar la Joven","Unidad",["PORO"],["Ciudad de Bandle","El Fréljord"],"ÉPICA"],"05BC129":["Jefe de la Arena","","","''Cada minuto nace un tonto, voy a aprovecharme al máximo... Esta arena de mechas será una MINA DE ORO''.","Unidad",["YORDLE"],["Ciudad de Bandle","Noxus"],"COMÚN"],"05BC004":["Octolutrina","Cuando me invocan, creo 1 Broma en la mano.","","''Curiosas y juguetonas, las octolutrinas son una raza increíblemente alegre. ¿O son octolutrinae? Espera, ¿no traje un tercer sándwich?''. \n— Registro ecológico del caracolista, día 7","Unidad",[],["Ciudad de Bandle"],"COMÚN"],"05BC155":["Monje de las Ascuas","Cuando invocas a otro aliado, recibo +1|+0.","","''Unas cuantas chispas pueden crear un incendio. ¡Nosotros somos las ascuas de tu destrucción!''.","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC104":["Fuerza Primitiva","Otorgo +2|+2 e Impacto a un aliado.","","Sí, es muy lindo. Sí, tiene un temperamento fuerte. No, no quieres comprobarlo.","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC218":["Ayuda de Hada","Creo 1 Buhifelino Hambriento en la mano y, luego, otorgo +1|+1 a las unidades feéricas aliadas en la mano.","","''¿Quién sigue alimentando a estas cosas?''. —Poppy","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC192":["Gemelos Bombarderos","Cuando me invocan, creo un Hito aleatorio de costo 2 o menos en la mano.","","El Bomberador Pieslocos-X hizo exactamente lo que debía: sembrar el caos. Además, fue bastante fácil de estacionar. ","Unidad",["YORDLE"],["Ciudad de Bandle","Shurima"],"COMÚN"],"05BC162":["Jefe Nakotak","Cuando un aliado se transforma, lo curo por completo y le otorgo +1|+1 e Impacto.","","El jefe Nakotak se autoproclamó líder de la tribu después de encontrar un enorme hueso de dinosaurio en los ventisqueros que rodeaban sus tierras. Nadie sabía que los huesos de dinosaurio eran equiparables al liderazgo de la tribu, pero tampoco a nadie le molestaba demasiado el asunto. Así fue como Nanotak se alzó como jefe.","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC032":["Linterna Destellante","En cada ronda, la primera unidad feérica que juegues cuesta 2 menos.","","''¡La linterna sigue a Norra; las polillas lunares siguen a la linterna; los ratones siguen a las polillas lunares! ¡Seguir, seguir!''.","Unidad",["FEÉRICO"],["Ciudad de Bandle"],"RARA"],"05BC166":["Palito Pinchador","Inflijo 1 de daño a cualquier objetivo. Roba 1.","","La primera regla de los experimentos: pínchalo y observa qué sucede.","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC006":["El Arsenal","Cuando me invocan, recibo una palabra clave aleatoria por cada Hito aliado que hayas destruido en esta partida.\nCuando destruyas un Hito aliado, recibo una palabra clave aleatoria.","","Adondequiera que fuera Ziggs, Arnie lo seguía, y su serena personalidad era el complemento perfecto del caótico espíritu de Ziggs. Sus tareas iban desde asegurarse de que las municiones estuvieran abastecidas hasta apagar incendios, o incluso tapar los oídos de Ziggs con sus propias manos cuando este (inevitablemente) olvidaba la protección auditiva. ","Unidad",["YORDLE"],["Ciudad de Bandle"],"ÉPICA"],"05BC110":["Escalador Intelectual","","","''Sí, sí. Ya me dijiste lo mucho que le gusta el té, las medias, tú, los botones, y recolectar cosillas. ¡Lo que todavía no me dices es CÓMO LUCE!''. ","Unidad",["YORDLE"],["Ciudad de Bandle","Targón"],"COMÚN"],"05BC063":["Guerrera del Tornado","Cuando me invocan, recibo +1|+0 y una palabra clave aleatoria.\nCuando me lanzas Retirada, retengo las mejoras a mis estadísticas.","","El Tornado mantiene la calma con ejercicios de respiración... y al canalizar su caos interno en un huracán despiadado de cuchillas letales. ","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC217":["Retoño de Hada","Manifiesto una unidad feérica y le otorgo +1|+1.","","Toda forma de vida requieren sustento. Y las hadas también, pero no es fácil darse cuenta cómo es que lo usan.","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC180":["Prisa","Lanzo Retirada a una unidad con 3 o menos de Poder.","","''¡Somos rápidos! ¡Somos el viento!''. — Kennen","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC040":["Intercambio de Baratijas","Manifiesto 1 Octolutrina o uno de 2 hechizos de tus regiones que cuesten 3 o menos.","","''¡Saca tu manos de mi preciado sándwich en este instante!''. — Caracolista","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC213":["Aplastar","Inflijo 1 de daño a un enemigo y lo Aturdo.","","''¡Ahanga!''. —Gnar","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC208":["Carga Heroica","Un aliado Golpea a un enemigo. Si sobrevive, lo Aturde.","","''¡Rápido!''. —Poppy","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC085":["Bribón Rataturbia","Al jugar: Descarta 1 para Manifestar un Yordle Mecha y le otorgo Escudo Antihechizos.","","''Bájale a eso, ¡¿quieres?! ¡Apenas me escucho a mí mismo contar todo este dinero!''. —Karl, Jefe de la Arena","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC112":["Brote de Cono Explosivo","Al jugar: Recibo Barrera en esta ronda o Impacto.","","Los brotes de cono explosivo son criaturas tímidas, cuya primera reacción es retirarse. Sin embargo, si se sienten amenazadas...","Unidad",["FEÉRICO"],["Ciudad de Bandle","Jonia"],"COMÚN"],"05BC135":["Golpe Doble","Un aliado Golpea a un enemigo. Si el aliado es multirregión, Golpea al enemigo nuevamente.","","''El Bellota M1-85 es un rifle automático de calibre de roble con visor de madera de Bandle y un acabado de moritamorada. ¡Se está cocinando algo increíble para esta noche!''. — Comando Bandle","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC084":["Chillador","Al jugar: Descarta 1 para Manifestar un Yordle Mecha.","","Bajito pero de GRAN personalidad.","Unidad",[],["Ciudad de Bandle"],"COMÚN"],"05BC184":["Baladistas Balbuceantes","Cuando me invocan, creo 1 Buhifelino Hambriento en la mano.","","''Esta es una balada\n¡Sobre Poppy la forzuda!\nPoppy la inmaculada, la inigualada... ¡la bienaventurada!''. \n —Letra tachada del ''Cancionero de Reginaldáctil y Faltimisquéz, bardos extraordinarios''","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC116":["Alcalde de la Ciudad de Bandle","En cada ronda, la primera unidad multirregión que juegues cuesta 1 menos.\nAl jugar: Manifiesto un seguidor multirregión.","","No está claro si la Ciudad de Bandle eligió alcalde alguna vez, pero tener un enorme bigote sería un requisito obligatorio, sin duda.","Unidad",["YORDLE"],["Ciudad de Bandle"],"ÉPICA"],"05BC111":["Yordles en Armas ","Doy +2|+2 a los aliados en esta ronda. Si jugaste con cartas de 4+ regiones, les doy +3|+3.","","''Nos vemos... tan increíbles en este momento''. — Tristana","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC224":["Transposición","Lanzo Retirada a un aliado. El siguiente aliado con el que juegues en esta ronda y que tenga un costo equivalente o menor, costará 0.","","''Velocidad del cuerpo, ¡velocidad de la mente!''. —Kennen","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC130":["Impulsivo","Al atacar: Otorgo +1|+1 y una palabra clave aleatoria al campeón de hasta arriba de tu mazo.","","Las carnes asadas veraniegas de Otto tenían buena reputación. Si bien adoraba manejar el asador, sus invitados solo podían elegir dos opciones de cocción para la carne: ''bien cocida'' o ''extremadamente bien cocida''.","Unidad",["YORDLE"],["Ciudad de Bandle","Shurima"],"COMÚN"],"05BC191":["Veredicto de la Guardiana","Coloco una unidad enemiga encima del mazo enemigo.","","''¡Y no vuelvas!''. —Poppy","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC052":["Basura Preciada","Lleno tu mano con cartas aleatorias. Cuestan 0 y tienen Fugaz. Solo podrás jugar 3 cartas más en esta ronda.","","La basura de un mortal es la pila gigantesca de cachivaches de un yordle.\n","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC050":["Benémona","Cuando me invocan, creo 2 Bromas en la mano.","","''Quienes sean propensos a las náuseas deben acercarse a este gentil gigante con EXTREMA precaución. Sus entrañas se los agradecerán... Y, dicho sea de paso, no debí haber comido ese segundo sándwich de hongos...''. \n— Registro ecológico del caracolista, día 3","Unidad",[],["Ciudad de Bandle"],"COMÚN"],"05BC094":["Acólito Bulboscuro","Cuando me invocan, creo 1 Oscuridad en la mano si no la tienes.","","''Sí, estoy seguro de que el tipo ese del tejado tiene muchas historias para contar. Todos sabemos que tiene mucho que decir. El único problema es que no sabemos QUÉ está diciendo''. —Alto Modisto","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC146":["Pintora de Bandle","Al jugar: Descarto 1 para crear un seguidor multirregión en la mano y reduzco su costo en 1.","","''Pintar no se trata de copiar lo que ves, sino de expresar CÓMO ves el mundo a tu alrededor... Y, ahora mismo, veo que te volviste a mover. ¡No te muevas!''.","Unidad",["YORDLE"],["Ciudad de Bandle","Piltóver y Zaun"],"COMÚN"],"05BC235":["Herrero Yordle","Al atacar: Doy Ataque Rápido a aliados con igual o menor Poder que yo en esta ronda.","","''Poppy nunca me escucha, así que más te vale escucharme: no se trata del martillo, se trata del yordle que lo blande''.\n","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC175":["Telescopio Saltarín","Al jugar: Manifiesto un Celestial de costo 3 o menos, Épico o un seguidor multirregión.","","Lo más extraño no fue que el telescopio se levantara, se estirara y comenzara a caminar, sino que insistiera en vestirse acorde al clima, por lo que tuvo que buscarse una cómoda bufanda.","Unidad",["FEÉRICO"],["Ciudad de Bandle","Targón"],"RARA"],"05BC182":["Impulso Relámpago","Lanzo Retirada a un aliado para infligir 2 de daño a cualquier objetivo.","","''Primero viene el crujido, ¡luego el BUM!''. — Kennen","Hechizo",["ELEMENTAL"],["Ciudad de Bandle"],"RARA"],"05BC069":["Yordle Sermoneador","Al atacar: Creo 1 Dardo Venenoso con Fugaz en la mano.","","No le des cuerda.","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC057":["Alto Modisto","Cuando me invocan, reduzco en 1 el costo de tu Oscuridad en todas partes.","","''Es importante que, al crear la camarilla, cada miembro maniático aporte algo único a la mesa de los supervillanos. Uno de mis compañeros, por ejemplo, tiene un sentido del estilo para morirse...''.\n— Extracto del cap. 4 del ''Manual para ser un supervillano'', por Lord Veigar","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC108":["Explorador Yordle","Al invocar a otro Yordle, le otorgo +1|+0.","","''La gloria de la exploración no tiene costo; sin embargo, los más grandes descubrimientos siempre son... lucrativos''.","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC183":["Abuelo Hada","Cuando me invocan, creo 1 Buhifelino Hambriento en la mano.\nCuando invocas otra unidad feérica, le otorgo +1|+0.","","''Vengan y escuchen lo que les contaré.\nLa triste historia del Abuelo Hada.\nTodos los días, alimentaba a las aves hambrientas,\nUna rara mezcla de semillas y requesón...''.\n—Cuentos increíbles de la Ciudad de Bandle","Unidad",["FEÉRICO"],["Ciudad de Bandle","Jonia"],"RARA"],"05BC188":["Caracolitos Curiosos","Cuando eliges una carta que no sea de campeón con opciones de selección aleatorias, creo una copia en la mano y reduzco su costo en 1.","","Famosos por su timidez, los evasivos caracolitos se esconden en sus caparazones hasta que su curiosidad los supera. Una vez que emergen, se revela su personalidad juguetona y suelen ser propensos a realizar bromas imitando el sonido de otras especies marinas.","Unidad",[],["Ciudad de Bandle"],"ÉPICA"],"05FR001":["Chamán Lóbrego","Fin de la ronda: Si dañaste al nexo enemigo en esta ronda, me transformo en Lóbrego Rabioso.","","''¡Nosotros no morimos como cobardes! Nosotros caemos mostrando las garras y enseñando los colmillos. Así es como honramos al Lobo''. —Clarividente Hyara","Unidad",[],["El Fréljord"],"COMÚN"],"05FR002":["Chamán Mamut","Fin de la ronda: Si dañaste al nexo enemigo en esta ronda, me transformo en Mamut Rabioso.","","Al enfrentarse a depredadores, los rebaños de mamuts rodearán a sus crías y hembras preñadas. Es por eso que los chamanes no solo invocan la fuerza física del gran espíritu mamut, sino también la fuerza de aquella unidad con la que protege a su familia.","Unidad",[],["El Fréljord"],"RARA"],"05FR013":["Udyr","Cuando me invocan o al Golpear: Creo 1 Cambio de Posición en la mano o si ya tienes 1 igual, reduzco su costo a 0.","Si jugaste Cambio de Posición 3+ veces.","''Los espíritus dan forma a nuestro mundo, al igual que nosotros y nuestro mundo le damos forma a ellos. Al obtener poder de ellos, sacamos el poder de nuestro interior''.","Unidad",[],["El Fréljord"],"Campeón"],"05FR016":["Llamado Chamánico","Creo 2 Cambios de Posición de costo 0 con Fugaz en la mano.","","''Los verás... grandes espíritus de colmillos y garras, escamas y plumas. Y en aquel momento, temblarás de miedo y asombro. Y sabrás que los Antiguos Dioses no nos han olvidado''. —Clarividente Hyara","Hechizo",[],["El Fréljord"],"COMÚN"],"05FR012":["Clarividente Hyara","Cuando me invocan, creo 1 Cambio de Posición en la mano.\nCuando juegues Cambio de Posición por primera vez en cada ronda, costará 0.","","Hacía mucho tiempo que Clarividente Hyara, la gran y reverenciada chamana, había perdido su poder de adivinación. Ahora ve a través de los ojos de los halcones y águilas que anidan en su casa, en la cima de la montaña. Pero algunas noticias problemáticas hicieron que bajara de la montaña. Su esperanza es que los presagios sean meras visiones...","Unidad",[],["El Fréljord"],"RARA"],"05FR014":["Ira del Fréljord","Al jugar: Lanzo Helar a un enemigo.\nLos enemigos con 3 de poder o menos no pueden bloquear.","","''Estuve ahí hace muchos años... Primero llegó el frío, penetrante e implacable; luego llegó una tormenta, colérica e indolente; y por último, se oyó un rugido tan agudo que me caló hasta los huesos. Me arrodillé y comencé a rezar, con miedo de haber cometido un grave error. Invocar a un gran espíritu es pedir su venganza... y su misericordia''. —Clarividente Hyara ","Unidad",[],["El Fréljord"],"ÉPICA"],"05FR017":["Bestia Interior","Doy +1|+1 a un aliado en esta ronda y creo 1 Cambio de Posición en la mano.","","''Acérquense, espíritus. Acérquense...''. —Udyr","Hechizo",[],["El Fréljord"],"COMÚN"],"05FR006":["Orador del Colmillo","Al jugar: Inflijo 1 de daño a AMBOS nexos.","","Muy pocas familias de chamanes han servido a la tribu de la Garra Invernal por tanto tiempo como la de Chuluun. Como chamán de la Gran Morsa, él presagia los botines que hay en el mar... y sus peligros. ","Unidad",[],["El Fréljord"],"COMÚN"],"05FR015":["Espíritus Liberados","Otorgo +1|+1 a los aliados en todas partes. Después, inflijo 1 de daño a TODO.","","''Antiguos, potencien nuestra resistencia contra el invasivo frío y alejen a nuestros enemigos con tormentas de viento y hielo. No los hemos olvidado a ustedes ni a los honores que debemos rendirles''.\n—Plegaria del Chamán Lóbrego","Hechizo",[],["El Fréljord"],"RARA"],"05FR005":["Vidente de Huesos","Cuando sobrevivo al daño, inflijo 1 de daño al nexo enemigo.","","Pocos ven el futuro tan bien como lo hacen los chamanes que sirven al Alce de Huesos, y solo unos poquísimos pueden soportar ver la muerte de aquellos que buscaban sus visiones.","Unidad",[],["El Fréljord"],"COMÚN"],"05FR004":["Trotamundos Vulpina","Cuando me invocan, creo 1 Cambio de Posición en la mano.","","''Impaciente pero cauteloso. Rápido pero silencioso. El camino del zorro consiste en la dicha de ver sin ser visto. Al viajar y al hacer la guerra, un líder sabio honra a aquellos que siguen al espíritu del zorro, pues no hay batalla que se gane sin exploradores''. —Vrynna Madre Pielmarcada","Unidad",[],["El Fréljord"],"COMÚN"],"05IO003":["Errante Antiguo","Cuesto 2 menos por cada unidad a la que hayas lanzado Retirada en esta ronda.","","''Himon'she, es todo un honor viajar contigo. Los demás me dicen que tienes una sabiduría inconmensurable. ¿A dónde nos dirigimos?''.\n''Ay, no. ¡Yo te estaba siguiendo a ti!''. — Ahri y el Errante Antiguo","Unidad",[],["Jonia"],"COMÚN"],"05IO004":["Ahri","Al atacar: La primera vez que lance golpe de ataque, intercambio lugar con el aliado a mi derecha y le lanzo Retirada.","Has lanzado Retirada a 5+ unidades.","Se buscaba a sí misma en los secretos de los demás. Se veía a sí misma a través de los ojos de muchos. A medida que se acercaba al bosque se preguntó si este sería un lente más o sí, por esta única vez, encontraría un espejo.","Unidad",[],["Jonia"],"Campeón"],"05IO023":["Encanto","Lanzo Retirada a un aliado para darle Vulnerable a un enemigo en esta ronda.","","''Cuéntame un secreto''. — Ahri","Hechizo",[],["Jonia"],"COMÚN"],"05IO020":["Cantavientos","Al jugar: Lanzo Retirada a una unidad.","","El caos le otorga garras a los débiles. Un lobo que acecha a su presa se tropieza con una rama caída. Un halcón pierde el tino por una ráfaga súbita de viento. Nosotros somos la rama. Nosotros somos el viento.","Unidad",[],["Jonia"],"COMÚN"],"05IO007":["Sai'nen Milcolas","Cuando me invocan, roba 2 y doy +1|+1 a los aliados en esta ronda.","","El bosque ofrece sus secretos sin costo alguno... pero pocos tienen la valentía de preguntarle cosas.","Unidad",[],["Jonia"],"ÉPICA"],"05IO021":["Brote del Dios Sauce","Al jugar: Lanzo Retirada a un aliado para invocar 1 copia suya con Endeble. Cuenta regresiva 3: Invoco otra copia de ella con Endeble.","","Alguna vez, el Sauce Dios creció en Omikayalan. Tal vez los manantiales que brotaron de ahí ahora son más caudalosos o tal vez no. Lo que importó fue que nacieron.","Hito",[],["Jonia"],"RARA"],"05IO024":["Niños del Bosque","Lanzo Retirada a un aliado o gasto 8 de maná para invocar copias con Endeble de los 3 seguidores más fuertes a los que hayas lanzado Retirada en esta partida.","","Los recuerdos tienen colmillos.","Hechizo",[],["Jonia"],"ÉPICA"],"05IO001":["Guardiana del Bosque","Cuando me invocan, recibo +1|+0 y Evasión en esta ronda.","","''Dicen que no se debe hablar para evitarle a los demás el peso de tu conocimiento. Mmm... Apuesto a que solo te cansaste de responder preguntas''. — Ahri","Unidad",[],["Jonia"],"COMÚN"],"05IO025":["Matriarca Colamanto","En cada ronda, la primera vez que lances Retirada a un seguidor, invoco una copia suya con Endeble.","","El misterio es mucho más importante que su conclusión.","Unidad",[],["Jonia"],"RARA"],"05IO026":["Los Llorados","Golpe al Nexo: Lanzo Retirada sobre mí.","","Si uno quiere venerar la caza, debe primero detenerse a llorar por las presas.","Unidad",[],["Jonia"],"RARA"],"05IO006":["Nueve Vidas","Invoco 1 Guardián Liminar.","","El bosque necesitaba un guardián. Alguien que pudiera montar guardia en sus lindes durante años, tal vez siglos, sin moverse. Gai'sh era un ávido voluntario que rápidamente demostró su dedicación al echarse una siesta de diez años.","Hechizo",[],["Jonia"],"ÉPICA"],"05IO002":["Manto de la Memoria","Elige a un aliado que sea objetivo de hechizos Rápidos, Lentos o Habilidades de un enemigo con un solo objetivo aliado. Lo detengo.","","Una flecha no conoce la intención del cazador ni el valor de su presa.","Hechizo",[],["Jonia"],"COMÚN"],"05SH014":["Xerath","Cuando destruyes un Hito aliado, inflijo 1 de daño al enemigo Más débil.","Si destruiste 4+ Hitos aliados.","''Eran buenos amigos, pero el tiempo y el infinito los convirtieron en hermanos. Azir no habría podido lograr todo lo que logró sin la ayuda de Xerath''. \n —Escriba Kah'nir, Historia de la Hueste Ascendida","Unidad",["ASCENDIDO"],["Shurima"],"Campeón"],"05SH017":["Heraldo del Mago","Cuando me invocan, si destruiste 4+ Hitos aliados en esta partida, otorgo +2|+2 y Arrollar a tus campeones en todas partes.","","La heraldo extendió sus brazos mientras elevaba su rostro hacia el sol. El astro rey brillaba con un tono carmesí sobre Shurima. ''Aclamen al Mago Ascendido'', clamó beatíficamente. Su voz resonó en el interior del círculo de columnas ruinosas. ''¡Viva, Xerath!''.","Unidad",[],["Shurima"],"RARA"],"05SH011":["Devoto Eterno","Último Aliento: Invoco 1 Sarcófago.","","La tumba estaba exquisitamente decorada, pero eso no era consuelo para los muertos y desterrados.","Unidad",[],["Shurima"],"RARA"],"05SH022":["Duelo Desértico","Doy -2|-0 a un enemigo en esta ronda. Un aliado y dicho enemigo se Golpean entre sí.","","''Un viajero que no teme al desierto nunca lo ha recorrido''. —Proverbio shurimano","Hechizo",[],["Shurima"],"COMÚN"],"05SH003":["Obelisco de Poder","Cuenta regresiva 3 o cuando me invocan o tú me destruyes: Otorgo +2|+0 a tu aliado Más fuerte.","","Los pilares crujientes y fulgurantes surgieron de las arenas y alteraron los lugares de poder que reforzarían el ya poderoso ejército de Xerath.","Hito",[],["Shurima"],"COMÚN"],"05SH016":["Acólito Ruinoso","Al jugar: Destruyo un Hito aliado para otorgar +1|+1 a los Acólitos Ruinosos aliados en todas partes.","","Todos los acólitos de Xerath sacrificaban algo suyo a cambio de poder, pero sus devotos más poderosos eran meros cascarones de lo que solían ser. Estos personajes servían como conductores y fuente de poder para que su nuevo emperador recargara su energía.","Unidad",[],["Shurima"],"COMÚN"],"05SH018":["Servidumbre de la Desolación","Invoco 1 Estatua en Estasis para almacenar a todos los Hitos y unidades aliados que hayan muerto o hayan sido destruidos en esta ronda.","","La energía mágica no se disipa. Solo cambia su propósito.","Hechizo",[],["Shurima"],"ÉPICA"],"05SH012":["Altar Erigido","Cuenta regresiva 3 o cuando tú me destruyes: Invoco 1 Dami'yin, el Desatado.","","''Habrá de erigirse un obelisco en todo lugar de poder. Esta estructura sirve como un instrumento que le permite al Mago Ascendido canalizar el poder de las arenas''. —Heraldo del Mago","Hito",[],["Shurima"],"ÉPICA"],"05SH020":["Constructo de la Desolación","Creo 1 Acólito Ruinoso o 1 Obelisco de Poder en la mano.","","''¡Crearé Shurima a MI semejanza!''. —Xerath","Hechizo",[],["Shurima"],"COMÚN"],"05SH015":["Vidente de la Arena","Cuando me invocan, roba 1. Si robas un Hito, se repite el efecto.","","El horizonte ante ella rebosaba de energía. Donde otros solo vieron arena y fango, ella vio un lugar lleno de entramados deslumbrantes y mágicos; una beta de energía pura que sería solo para ella.","Unidad",[],["Shurima"],"ÉPICA"],"05SH004":["Energía Liberada","Doy +2|+1 a un aliado en esta ronda o destruyo un Hito aliado para darle +4|+2 a un aliado en esta ronda.","","''¡Arrancaré el poder del desierto y destruiré a aquellos que se opongan a mí!''. —Xerath","Hechizo",[],["Shurima"],"COMÚN"],"05SH002":["Caminante del Páramo","Cuando destruyes un Hito aliado, recibo +1|+1.","","Los acólitos ya eran muy hábiles antes de comenzar a buscar a Xerath. Ahora, tras haber estudiado lo que él ya había estudiado, eran imparables.","Unidad",[],["Shurima"],"COMÚN"],"05SH007":["Rito del Arcano","Destruyo un Hito aliado o una de tus gemas de maná para infligir 4 de daño a una unidad.","","''Un pequeño desafío a cambio de un gran poder''. —Xerath","Hechizo",[],["Shurima"],"RARA"],"05NX009":["Alma Perdida","Cuando me invocan o me descartan, creo 1 Espectro de las Cuchillas Gemelas en la mano.","","Los demacianos se arrastraron hasta sus murallas solo para ver a la muerte descender sobre sus muros. Aunque lograron acabar con algunos guerreros de la Legión Gris, la oscura marea de la guerra era imparable.","Unidad",[],["Noxus"],"ÉPICA"],"05NX006":["Granadero Renacido","Para usarme, descarta 1.\nCuando me descartes, invoco una copia idéntica de mí.","","''Algo no anda bien en nuestro grupo. Aunque la mayoría de las almas que revivimos aborrecen su regreso a la vida, este sujeto parece entender a los suyos y se divierte con las oportunidades subsecuentes. Qué curioso''.\n —Notas del Dr. Esslanger","Unidad",[],["Noxus"],"COMÚN"],"05NX005":["Belicista Antiguo","Cuando me descartan, otorgo +2|+0 a tu aliado Más fuerte.","","A medida que crecía el poder de Lady Noradi, comenzó a pensar si sus poderes echarían raíces en los cadáveres que reposaban en las tumbas más antiguas de Noxus. Entendió que la luz de la vida no era más que un mero parpadeo en sus cascarones, pero que las sombras de la guerra aún danzaban en aquellas flamas marchitas.","Unidad",[],["Noxus"],"RARA"],"05NX001":["Sion","Cuando me descartan, otorgo Arrollar a tu aliado Más fuerte y me sumo a tu mazo.\nGano +1|+0 por cada carta que hayas descartado en esta partida (Máx.: +7|+0).","Si descartaste o invocaste 35+ de poder.","Sion vio destellos fugaces de recuerdos confusos: legiones que se erguían ante él; elogios, coronas, guerra; un rey moribundo; mucha sangre. Sin embargo, tan pronto recordó, volvió a olvidar.","Unidad",[],["Noxus"],"Campeón"],"05NX003":["Sal y Puntadas","Para usarme, descarta una carta.\nInvoco 1 Granadero Renacido y le doy +2|+0 en esta ronda.","","''Levántate de nuevo, hijo mío...''. —Dr. Esslanger, Médico Meditabundo","Hechizo",[],["Noxus"],"RARA"],"05NX015":["Duelista Caído","Cuando me invocan, otorgo No bloquea al enemigo Más débil.\nÚltimo Aliento: Creo 1 Duelista Resucitado en la mano.","","''Los primeros minotauros que reviví eran bestias dóciles e inútiles; ni el crepitar de la guerra ni la cercanía de la muerte agitaban sus sentidos''.\n —Notas del Dr. Esslanger","Unidad",[],["Noxus"],"RARA"],"05NX019":["¡Por la Gloria!","Reputación: Cuesto 3 menos. Invoco 2 Buscaglorias Trifarianas.","","Ningún ser que busca la gloria se detiene hasta obtenerla.","Hechizo",[],["Noxus"],"RARA"],"05NX013":["Jinete Caído","Cuando me descartan, creo 1 Jinete Resucitado en la mano.","","''No fue sino hasta que frotaron la armadura del jinete con hojas de tonoscuro que se salvaron de sentir la furia del basilisco. Las plantas eran oriundas de las zonas periféricas, igual que las bestias, y son tan penetrantes como venenosas''.\n —Notas del Dr. Esslanger","Unidad",[],["Noxus"],"COMÚN"],"05NX012":["Rugido del Asesino","Para usarme, descarta 1. Mato al enemigo Más débil.","","''Aliado... enemigo... No me importa''. —Sion","Hechizo",[],["Noxus"],"COMÚN"],"05NX014":["Armas de los Perdidos","Inflijo 3 de daño a una unidad e invoco 1 Rompeescudos Trifariano.","","''¡Rompeescudos!''. —Sion","Hechizo",[],["Noxus"],"COMÚN"],"05NX004":["Médico Sepulcral","Al jugar: Descarta 1 para robar una unidad.","","El Dr. Esslanger era un respetado médico jubilado que acumuló una increíble reputación gracias a sus años de trabajo arduo. Pero no fue sino hasta que conoció a una joven mujer de la nobleza cuya sangre había sido oscurecida por la traición, que verdaderamente comenzó a servir a Noxus.","Unidad",[],["Noxus"],"COMÚN"],"05NX016":["La Dama Sangrienta","Cuando se descarta un aliado sin Fugaz en la mano, creo una copia con Fugaz en la mano.","","Bajo el manto de la noche, Lady Faris Noradi condujo a su Legión Gris fuera de la capital noxiana. Tardaron tres duras y angustiantes semanas en llegar al pequeño puesto demaciano que sus exploradores habían identificado. Era momento de hacer una demostración.","Unidad",[],["Noxus"],"ÉPICA"],"05NX002":["Noble Rebelde","Recibo +2|+1 una vez que descartes 3+ cartas en esta partida.","","''¿Qué podría inspirar lealtad de manera más efectiva en un traidor que ver a un conspirador asesinado y revivido para luchar bajo el estandarte noxiano? Todos servirán a Noxus, de una forma u otra''. —La Dama Sangrienta","Unidad",[],["Noxus"],"COMÚN"],"05BW005":["Nami","Cuando juegas un hechizo, otorgo +1|+0 al otro aliado Más débil que no se encuentre Inmóvil.","Has jugado 5+ hechizos con una Nami aliada en juego.","''¿Te despediste, joven Invocadora de Mareas?''.\n''Sí, venerable abuela''.\n''¿Tienes miedo?''.\n''... Sí, venerable abuela''.\n''Bien. Tener miedo significa ser cuidadoso, pero debes confiar en ti misma, de la misma manera que nosotros confiamos en ti. Ahora, vete. Que las corrientes te guarden''.","Unidad",[],["Aguasturbias"],"Campeón"],"05BW006":["Marea menguante","Inflijo 2 de daño de forma aleatoria a un enemigo o al nexo enemigo y creo 1 Corriente en la mano.","","''Presta atención al temperamento de la marea...''. —Nami","Hechizo",["ELEMENTAL"],["Aguasturbias"],"COMÚN"],"05BW002":["Viajero Saltarenas","","","''Es decir, claro, algunos de ellos nos cazan (como lo hacen con todo). Pero ya sabes, la mayoría de los trotatierras que conozco solo buscan disfrutar de su tiempo en el gran azul, igual que nosotros. Al fin y al cabo, todos somos personas''.","Unidad",[],["Aguasturbias"],"COMÚN"],"05BW008":["Guardia Abisal","Cuando juegas un hechizo, recibo +2|+0 en esta ronda.","","''Muchos miembros de nuestra tribu ven a Loto como un sujeto inquietante; lo consideran un luchador incansable con una mirada perturbadora y distante. Pero yo sé lo que alberga su corazón: miedo de no poseer la fuerza suficiente para salvarnos... y un amor extraordinario''. —Tama, Cantante Marai","Unidad",[],["Aguasturbias"],"COMÚN"],"05BW011":["Almirante de la Flota Shelly","Cuando juegas 2 hechizos en cada ronda, otorgo +1|+1 a los demás aliados.","","''ESCUCHA, SOLDAGO. TENGO MÁG DE TREGIENTOS ASESINATOS CONFIRMAGOS Y SOG LA MEJOG AGMIRANTE EN TODAS LAS FUEGZAS DE LA MAGINA, ASÍ QUE SI TE GIGO QUE NAGES, TÚ NAGA, ¿SÍ? ¡BUENO, GRAGIAS!''.","Unidad",[],["Aguasturbias"],"ÉPICA"],"05BW003":["Maremoto","Inflijo 1 de daño a dos enemigos diferentes seleccionados de forma aleatoria y creo 1 Ola Aplastante en tu mazo.","","''¡Océanos, desbórdense!''. —Nami","Hechizo",["ELEMENTAL"],["Aguasturbias"],"RARA"],"05BW004":["Avatar de las Mareas","Si obtuvieras una gema de maná, en su lugar rellena tu maná de hechizos.\nCuando juegas un hechizo, creo otro aleatorio en tu mano que cueste 3 o menos y le otorgo Fugaz.","","Para los Marai, el Leo'lei es un presagio de grandes cambios. Se dice que cada despliegue de sus elegantes alas influye en el flujo de las mareas.","Unidad",[],["Aguasturbias"],"ÉPICA"],"05BW001":["Protectora Marai","Cuando me invocan, invoco 1 seguidor aleatorio de costo 1.","","Los Marai rara vez quieren aventurarse lejos de casa. Pero Ai'la nació con curiosidad en su alma y, a pesar de estar obligada a cumplir con su tribu, pasa cada momento despierta soñando con el día en que pueda ser realmente libre.","Unidad",[],["Aguasturbias"],"RARA"],"05BW010":["Venerable Abuela Marai","Cuando me invocan, creo 5 hechizos aleatorios de 6+ de costo en el mazo, y reduzco su costo a 3.","","La luz celestial que emana de una piedra lunar protege el hogar ancestral de los Marai. Cada cien años, cuando dicha luz comienza a menguar, se le asigna la tarea de encontrar otra piedra a una nueva Invocadora de Mareas... pues sin ella, la oscuridad engulliría a los Marai y caerían presa de los horrores que acechan en las profundidades.","Unidad",[],["Aguasturbias"],"COMÚN"],"05BW013":["Cantante Marai","Cuando me invocan, recibo Evasión si jugaste un hechizo en esta ronda.","","''El océano cree que la ola volverá;\nconfía en la marea, en la corriente y en la agitación de las aguas.\nAquí es donde las olas rompen contra la costa \ny donde el océano se deleita con el rugido atrevido del blasón''.\n —Verso extraído de la Serenata para la Invocadora de Mareas","Unidad",[],["Aguasturbias"],"RARA"],"05PZ015":["Motociclista Justiciera","Cada vez que tu oponente robe, planto 1 Trampa Aturdidora entre las 8 cartas de arriba del mazo enemigo.","","''Se observó a la oficial perseguir al sospechoso a gran velocidad hasta que cayó en una trampa que ella misma había preparado. Después del arresto, la oficial se multó a sí misma por exceso de velocidad y alegó (no sin un poco de dramatismo) que la justicia es una calle de doble sentido''. \n —Extracto del informe de un guardia","Unidad",[],["Piltóver y Zaun"],"ÉPICA"],"05PZ012":["Archivista de la Estación","Al jugar: Elige un hechizo de entre las primeras 5 cartas de tu mazo y creo una copia idéntica con Fugaz en la mano. Después, coloca esas primeras 5 cartas en tu mazo.","","Los detectives no podrían resolver ningún caso si no tuvieran pistas. El trabajo de los archivistas es reunir cada trozo de evidencia y crear nuevas posibilidades donde antes no había ninguna.","Unidad",[],["Piltóver y Zaun"],"RARA"],"05PZ026":["Línea de Ensamblaje","Invoco 2 Trabajadores de la Forja.","","''¡Cambio de turno, gente!''. —Capataz de la Forja","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"05PZ019":["Se Busca","Elige a un jugador y descarto su carta de menor costo para robar 3.","","''Todo tiene un costo''. —Corina Veraza","Hechizo",[],["Piltóver y Zaun"],"ÉPICA"],"05PZ031":["Albus Ferros","Cuando me invocan, robo Jayce. Al atacar: Inflijo 3 al nexo enemigo. Por cada hechizo de 6+ de costo que hayas jugado en esta partida, lo aumento en 1.","","''Una vez más, el magnánimo Albus Ferros es el centro de atención, al superar dramáticamente al clan Cadwalder por los derechos para patrocinar la investigación del Portal Hextech de Jayce. 'Un buen día para Ferros es un buen día para Piltóver', como dice el refrán, y de hecho, ayer fue un muy buen día para el clan Ferros''.\n—Fragmento de publicidad patrocinado en la Gaceta de Piltóver","Unidad",[],["Piltóver y Zaun"],"ÉPICA"],"05PZ027":["Descarga Eléctrica","Inflijo 3 de daño a un enemigo o al nexo enemigo, y 3 de daño a otro.","","''¡Estoy disparando!'' —Jayce","Hechizo",[],["Piltóver y Zaun"],"RARA"],"05PZ022":["Jayce","Al jugar: Recibo Ataque Rápido o Desafío.","Si jugaste dos hechizos de costo 6+. Cuando subo de nivel, creo 1 Portal de Aceleración en la mano.","''Y bien, Rosa, como bien sabes, esta tecnología poderformativa promete cambiar al mundo''.\n''Es un trabajo verdaderamente innovador, Jayce. La forma en que esos coinhibernadores se unen me deja sin aliento''.\n''A mí también. ¡Y todo fue idea de Axel! ¿Verdad, compa?''.\n''Ya me conoces, amigo, no me gusta presumir...''.","Unidad",[],["Piltóver y Zaun"],"Campeón"],"05PZ017":["Emanaciones del Sumidero","Inflijo 2 de daño a una unidad. Si agregaste 2+ cartas a tu mano en esta ronda, inflijo 3 de daño.","","''Déjalos ventilarse un poco. Los novatos no soportan el olor; pero déjame decirte algo... una vez que te acostumbras, ¡no hay nada mejor!''. —Vendedor de Hongos","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"05PZ013":["Pacificadora de Piltóver","Inflijo 2 de daño a una unidad y planto 2 Trampas Aturdidoras entre las 8 cartas de arriba del mazo enemigo.","","''Aquí está MI carta de presentación''. —Caitlyn","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"05PZ020":["Emboscada","Doy +2|+0 a un aliado en esta ronda. Si agregaste 2+ cartas a tu mano en esta ronda, le doy Evasión en esta ronda.","","''Rodearemos la ubicación y usaremos girahumos para ocultar nuestros movimientos...''. —Caitlyn","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"05PZ024":["Financiero de Ferros","Al jugar: Manifiesto un hechizo de tus regiones que cueste 6 o más.","","''Creo que la única ventaja de que el clan Ferros financiara mi trabajo es que pude hacer equipo con Reggie. No solo es una de las personas más competentes con las que he trabajado, ¡sino que es un tipazo!''.\n—Fragmento del diario de Jayce","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"05PZ010":["Inteligencia Avanzada","Planto 2 Trampas Aturdidoras entre las 8 cartas de arriba del mazo enemigo.\nRoba 1.","","''A mi señal''. —Caitlyn","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"05PZ014":["Corina, Mente Maestra","Al jugar: Planto 5 Trampas Aturdidoras entre las 5 cartas de arriba del mazo enemigo o activo los efectos de todas las trampas entre las 5 cartas de arriba del mazo enemigo.","","Corina sonreía mientras los alcaides de Piltóver derribaban su puerta, pisoteaban sus preciosas flores, y estas liberaban nubes de polen tóxico. Todo salía según lo planeado.","Unidad",[],["Piltóver y Zaun"],"ÉPICA"],"05PZ002":["Conocimiento de Primera Mano","TODOS los jugadores roban 2.","","''Este caso es muy popular. Un caballero estuvo revisándolo hace unas horas. ¡Disfrútalo!''. —Archivista de la estación","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"05PZ021":["La Forja del Mañana","Cuando me invocan, invoco 1 Trabajador de la Forja. Cuando juegas un hechizo de costo 6+, me destruyes y restablezco tu maná de hechizos.","","Si consideramos que Piltóver es una ciudad que avanza con la invención, las forjas son sus engranes.","Hito",[],["Piltóver y Zaun"],"RARA"],"05PZ025":["Capataz de la Forja","Al Golpear: Restablezco 1 de maná de hechizos.","","''Se requieren dos elementos para consolidar una idea en algo físico. El financiamiento es una mitad de la ecuación y la otra es una buena forja. Y esto no solo involucra las herramientas o la maquinaria de la forja. Si la persona que se encarga de ella no sabe dirigir las cosas... digamos que tu idea se quedará en el papel''. —Jayce","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"05PZ006":["Caitlyn","Al golpear: Planto 2 Trampas Aturdidoras entre las 8 cartas de arriba del mazo enemigo.","Si 5+ de tus trampas fueron activadas.","Caitlyn siempre fue una investigadora tenaz y orientada a los detalles, una cualidad que la ayudó a subir rápido en el escalafón jerárquico de los pacificadores de Piltóver. Sin embargo, cuando apareció un caso que involucraba a una tal C, uno que muchos otros pacificadores habían rechazado, parecía que Caitlyn por fin había encontrado un reto digno de ella... o eso creía.","Unidad",[],["Piltóver y Zaun"],"Campeón"],"05PZ004":["Escuadrón de Oficiales","Cuando me invocan, creo 1 Se Busca en la mano.","","Desde la descarga silenciosa en la calle hasta la preparación del ariete, no tardó mucho en dejar todo en orden. Solo era cuestión de esperar la señal de Caitlyn.","Unidad",[],["Piltóver y Zaun"],"RARA"],"05PZ009":["Oficial Encubierto","Golpe al Nexo: Planto 2 Trampas Aturdidoras entre las 8 cartas de arriba del mazo enemigo.","","Zayne Asako, como todos los niños zaunitas, tuvo que crecer rápido en aquellas calles oscuras y llenas de violencia. Tras perder a su hermano debido a otro crimen sin sentido, se convirtió en un pacificador de Piltóver, pues albergaba la esperanza de que la razón y la ley harían que su hogar fuera un lugar más seguro.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"05PZ016":["Golpe de Gracia","Coloco un seguidor enemigo en el mazo enemigo. Luego, tu oponente roba 1.","","Mientras que la gran ciudad de Piltóver es hogar de algunas de las mentes más brillantes de Runaterra, sus cárceles también albergan a algunas de las mejores mentes en Runaterra.","Hechizo",[],["Piltóver y Zaun"],"RARA"],"05PZ030":["Anomalía Hextech","Cuando me robas o me creas en la mano o cada Inicio de la ronda: Mientras estoy en la mano, me transformo en un hechizo aleatorio de +6 de costo.","","''... configurar la Hextech para que llegara a un estado estable fue la tribulación más difícil a la que me enfrenté. Había noches en que sentía que los cristales y el Hexite estaban conspirando activamente contra mí para hacerme fallar. Fue solo a través de un extenso periodo de pruebas y errores que logré que las partes de los componentes funcionaran en armonía...''.\n—Fragmento del diario de Jayce","Hechizo",[],["Piltóver y Zaun"],"RARA"],"05PZ028":["Aerocrucero Ferros","Obtengo +2|+0 cuando hayas jugado un hechizo de 6+ de costo en esta partida.","","''La gente de esta ciudad se desvive por la 'inteligencia'. Pero ¿de que sirve la mente más inteligente sin los medios para expresarse? No. Yo le enseñaré a Piltóver lo que es la grandeza. Yo me alzaré sobre ellos. Mi esplendor tapará el mismísimo sol y mi nombre continuará su legado''. —Albus Ferros","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"05PZ038":["Aluvión de Cohetes","Inflijo 4 de daño a un enemigo y 1 de daño al resto de los enemigos.","","''¡Se supone que deben volar, no irse A TODOS LADOS! ¡Por todos los cielos!\". —Heimerdinger","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"05PZ035":["Womp Hediondo","Último Aliento: Creo 1 copia mía en el mazo enemigo con 2 Hongos Venenosos.","","El hedor de un womp en lo más álgido de la temporada de hongos es algo único. Imagina una alcantarilla abierta y en su interior, una gran cantidad de pescados y huevos podridos. Y ni siquiera eso apestaría tanto.","Unidad",[],["Piltóver y Zaun"],"RARA"],"05PZ029":["Repartidor Hextech","Otorgo +1|+0 a los aliados con Tecnología en todas partes cuando hayas jugado un hechizo de 6+ de costo en esta partida.","","Inicialmente, el Repartidor Hextech se construyó para transportar materiales por todo Piltóver. Sin embargo, a medida que pasó el tiempo, los lugareños se fueron encariñando con él. Los trabajadores de la forja de Jayce hasta tenían un apodo para él: Latita. Un lord piltoviano le donó un sombrero y los niños ahora lo adornan con lo que sea que tengan a la mano.","Unidad",["TECNOLOGÍA"],["Piltóver y Zaun"],"RARA"],"05SI014":["Catálogo de Arrepentimientos","Inicio de la ronda: Creo una copia con Fugaz de un hechizo sin Fugaz que hayas jugado en la última ronda.","","La Islas Bendecidas olvidan. Las Islas de la Sombra recuerdan. Las Islas de la Sombra olvidan. Las Islas Bendecidas recuerdan.","Hito",[],["Islas de la Sombra"],"ÉPICA"],"05SI013":["Guardianes de la Niebla","En cada ronda, la primera vez que mates una unidad con un hechizo, invoco 1 Espectro de la Niebla con Endeble.","","La Niebla Negra atrapa a sus víctimas en círculos infinitos de tormento autoimpuesto. Por medio de los Atrapanieblas, Tek y Kama le dan a esas almas una oportunidad de romper aquel ciclo.\n","Unidad",[],["Islas de la Sombra"],"RARA"],"05SI009":["Senna","Cuando me invocan o Al atacar: Creo 1 Oscuridad en la mano si no la tienes. Tus hechizos de daño y asesinatos se aceleran con efecto Rápido.","Si te he visto matar 3+ unidades con hechizos o si he visto morir a un Lucian aliado.","''Ser un centinela implica luchar, morir o perder a tus seres queridos. Pero más allá de eso, implica vivir. Vivir para ti... y para tus seres queridos''.","Unidad",[],["Islas de la Sombra"],"Campeón"],"05SI016":["Cañón de Sombras","Mato una unidad y les doy -2|-0 a todos los enemigos en esta ronda.","","''Las sombras no existen sin la luz. La muerte no existe sin la vida''. —Senna","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"05SI004":["Vigilante de las Islas","En cada ronda, la primera vez que mates una unidad con un hechizo, inflijo 2 de daño al nexo enemigo.","","''Cachorros son cachorros''. —Garabato sobre el alma.","Unidad",[],["Islas de la Sombra"],"RARA"],"05SI012":["Centinela Solari","Cuando me invocan, creo 1 Oscuridad en la mano si no la tienes.","","''Ya no puedo sentir el sol. Aun así, llevo su recuerdo... y eso es suficiente''.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"05SI008":["Centinela Ixtali","Cuando me invocan, creo 1 Oscuridad en la mano si no la tienes. Cuando uses tu siguiente Oscuridad en esta ronda, la copio y hago que ataque al nexo enemigo.","","''Senna, me preguntaste que cuál es mi motivación para luchar en esta batalla. La niebla no me quitó nada ni amenaza mi hogar, pero quiero descubrir cuál es la razón de su existencia. ¿Necesito sentimientos para unirme a tu causa?''.","Unidad",[],["Islas de la Sombra"],"RARA"],"05SI003":["Oscuridad Lacerante","Dreno 5 de una unidad.","","''La vida atrae a la muerte''. —Senna","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"05SI010":["Dess y Ada","Cuando me invocan, creo 1 Oscuridad en la mano si no la tienes. Tu siguiente Oscuridad en esta ronda cuesta 0 y obtiene ''Inflijo daño a todos los objetivos enemigos''.","","''¿Otra pesadilla?''.\n''No fue tan mala, tú no estabas en ella''.\n''Torpe. ¿Y cuál era la parte mala?''.\n''Que no estabas en ella''.","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"05SI011":["Centinela en Ascenso","La primera vez que mates una unidad con un hechizo, recibo +2|+1.","","¿Qué es lo que ve la niebla cuando observa a Maeve? Exuberancia, confianza... un optimismo irrefrenable. Su anhelo por apagar esa flama provocadora debe ser enorme, pues ¿a qué le teme más la muerte... si no a la vida?","Unidad",[],["Islas de la Sombra"],"COMÚN"],"05SI015":["Centinela Buhru","La primera vez que mates una unidad con un hechizo, recibo +2|+1.","","La filosofía de los buhru y de los centinelas tienen un punto en común: todos los seres han de morir, pero a algunos se les debe dar la muerte.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"05MT004":["Camphor, la Duda","Cuando me invocan, si fijaste aliados como objetivo en 4 rondas distintas, recibo Escudo Antihechizos, Arrollar y Desafío.","","Durante siglos, la demonio Camphor acechó las tierras de Targón al drenar la misma fuerza que definía a sus víctimas. De los fuertes tomaba la fortaleza; de los sabios, su conocimiento. Sin embargo, estos bienes no le interesaban. Ella se regodeaba en el sufrimiento, la duda y la miseria que ocasionaba. Camphor era un monstruo en todo sentido de la palabra.","Unidad",[],["Targón"],"ÉPICA"],"05MT006":["Albígneo Herido","","","''Los targonianos no necesitan más pruebas de la crueldad de los dioses. Mira lo que nos hicieron. Mira lo que le hicieron a nuestros compañeros más queridos''. — Pantheon","Unidad",["DRAGÓN"],["Targón"],"RARA"],"05MT008":["Salto con Escudo","Otorgo +1|+1 a un aliado y Aturdir a un enemigo.","","Pantheon estaba bien versado en las artes de la guerra. Gracias a incontables batallas sabía que sus enemigos siempre seguirían de cerca su lanza, pero no su escudo.","Hechizo",[],["Targón"],"RARA"],"05MT014":["Maravilla Celestial","Lanzo Aturdir a dos enemigos.","","''El cielo nocturno de Targón es un espectáculo de belleza inimaginable. Pero también es muy fácil enloquecer mirando tanta vastedad, sin saber cuán lejos están las estrellas en el cenit ni qué clase de seres pueden estar observándote desde los rincones del universo...''. —Escalador targoniano","Hechizo",[],["Targón"],"COMÚN"],"05MT003":["Pantheon","","Si fijaste aliados como objetivo en 5+ rondas distintas.","Aquí se yergue Atreus, a quien le fue arrebatada su libertad por los mismos Aspectos a quienes veneraba. Aquí se yerguen las ascuas de la guerra, quien concedió a Atreus dones que pocos mortales comprenden. Aquí se yergue un hombre listo para luchar y morir por aquellos a quienes ama.","Unidad",[],["Targón"],"Campeón"],"05MT013":["Iula","Al jugar: Otorgo Escudo Antihechizos o Arrollar a un aliado. Si no tienes, lo recibo yo.","","Iula aún recuerda el ardiente pesar que la atormentaba después de enterarse de la muerte de su esposo. Su respuesta fue rápida cuando Pantheon llegó con ella para pedirle que lo ayudara a destruir a una criatura que devoraba ese mismo dolor.","Unidad",[],["Targón"],"COMÚN"],"05MT009":["Vínculos de Batalla","Otorgo +2|+2 a 2 aliados.","","Luchar contra los dioses parecía una causa perdida, pero los pocos que se atrevieron aprendieron algunas lecciones a través de las cicatrices y de los gritos. La manera de pensar de los dioses era individualista, egoísta, y habían perdido el don de la camaradería. Esta sería su arma contra ellos; esta sería su armadura.","Hechizo",[],["Targón"],"COMÚN"],"05MT010":["Mística Cegada","Al jugar: Otorgo +1|+1 a un aliado y Silenciar a un seguidor enemigo.","","Antaño, Eshiyme era una oráculo muy venerada quien utilizaba su Visión para guiar a aquellos que lo necesitaban. Pero Camphor robó su don y pretendía darse un festín con su angustia inevitable. Qué equivocada estuvo Camphor al subestimar a la valiente Eshiyme.","Unidad",[],["Targón"],"COMÚN"],"05MT002":["Juntos Resistimos","Doy +1|+2 a 2 aliados en esta ronda.","","''Debemos buscar nuestra fuerza en los lazos familiares''. — Pantheon","Hechizo",[],["Targón"],"RARA"],"05MT012":["Coloso Liberado","Cuando me invocan o al Atacar: Creo 1 Gema en la mano.","","Los colosos son los antiguos y venerados protectores de los lugares más sagrados de Targón. Herirlos es como si se hiriera a la mismísima montaña. Torturarlos implica un crimen que ningún targoniano puede perdonar.","Unidad",[],["Targón"],"COMÚN"],"05MT011":["Contra Todo Pronóstico","Si tu oponente tiene más unidades que tú, otorgo +1|+1 a un aliado por cada unidad extra que tenga.","","El pequeño grupo de valientes sabía que se estaba enfrentando en lucha con seres de poder inimaginable. Sabían que era muy posible que murieran y sin embargo, lo hicieron.","Hechizo",[],["Targón"],"ÉPICA"],"05MT005":["Buscasagas","","","Tor sintió que su vida se desvanecía con cada latido de su corazón, pero en esa oscuridad espesa y amenazante, donde se esperaba que aceptara el terror, encontró un propósito. No solo enfrentaría la muerte de forma voluntaria, sino que traería consigo al mismísimo demonio que había osado a acortar su vida. Así sería recordado. Esta sería la saga de Tor.","Unidad",[],["Targón"],"COMÚN"],"05DE003":["Gorlith, el Inescalable","Al jugar: Intercambio mi vida y la vida de tu nexo.\nLos enemigos con menos vida que yo no me pueden bloquear.","","''Un tributo honorable para aquellos que partieron, pero que son recordados: cuando la gente de Demacia ve los rayos del sol brillando sobre su superficie, sabrán que la esperanza y el espíritu indomable que inspiró su construcción vivirá a través de él''. \n—Placa en el taller de Durand","Unidad",[],["Demacia"],"ÉPICA"],"05DE009":["Galio","Cuando me invocan, otorgo +0|+3 a los otros aliados.","Si al Fin de la ronda tus aliados tienen 25+ de vida total.","Tras su creación, Galio pasó muchos años sumido un profundo sueño donde no sentía ni sabía nada del mundo. No fue sino hasta que la magia lo trajo de nuevo a la vida y experimentó la emoción del combate que conoció la dicha de caminar entre los vivos. Ahora, cuando duerme, ¡echa de menos todas esas maravillas!","Unidad",[],["Demacia"],"Campeón"],"05DE020":["Escudo de Durand","Otorgo +0|+3 a un aliado. En el siguiente Inicio de ronda, le otorgo +0|+2.","","La sola visión de Galio es suficiente para inspirar a los corazones nobles de Demacia.","Hechizo",[],["Demacia"],"RARA"],"05DE021":["Poder de la Vanguardia","Para usarme, gasta todo tu maná. Invoco 1 Vanguardia Valerosa e incremento sus estadísticas en esa cantidad. Si gastaste 9+ de maná, otorgo +2|+2 a los demás aliados Élite.","","En momentos donde parece que toda esperanza se desvaneció, los soldados de Demacia confían en la Vanguardia.","Hechizo",[],["Demacia"],"ÉPICA"],"05DE017":["Vientos de Guerra","Curo a un aliado por completo. Luego, dicho aliado y un enemigo se Golpean entre sí.","","''¡Alas a la obra!''. —Galio","Hechizo",[],["Demacia"],"RARA"],"05DE010":["Escultora de Durand","Cuando invocas a otro aliado le otorgo +0|+1.","","''Puede que no sea evidente para quienes carecen de formación, pero el trabajo de un gran artista se observa en cada golpe de su cincel''.","Unidad",[],["Demacia"],"COMÚN"],"05DE013":["Ciervo de Petricita","Al apoyar: Recibo todo el daño dirigido al aliado que apoyo en esta ronda.","","El guardián de petricita le hizo caso al guardabosques montado en un ciervo y empequeñeció a la criatura misma que había inspirado su elegante diseño.","Unidad",[],["Demacia"],"ÉPICA"],"05DE015":["Dragón de la Montaña","Furia me otorga +0|+2 en vez de +1|+1.","","A pesar de su apariencia, los dragones de la montaña no se enfadan con facilidad. Su tolerancia con respecto a las otras bestias que habitan la montaña los convierten en protectores naturales de las criaturas más vulnerables.","Unidad",["DRAGÓN"],["Demacia"],"ÉPICA"],"05DE019":["Arquitecto de Durand","Al apoyar: Doy +0|+2 y Formidable al aliado que apoyo en esta ronda.","","''El guardabosques Corazón del Olmo trajo noticias lúgubres'', dijo el arquitecto con calma mientras enrollaba el pergamino una vez más para ocultar sus temblorosas manos. Se giró hacia los escultores que estaban esperando y asintió con la cabeza tiesa. ''Parece que llegó el momento de que los protectores ocultos de Demacia salgan de su escondite''.","Unidad",[],["Demacia"],"RARA"],"05DE014":["Protegida de Durand","Al jugar: Otorgo +0|+1 y Dureza a un aliado.","","Shireen levantó la vista de su trabajo al oír el golpeteo de unas pezuñas. El paso del guardabosques la dejó intranquila, pero sentía curiosidad. Le pidió a su ave de petricita que volara y lo siguiera.","Unidad",[],["Demacia"],"COMÚN"],"05DE012":["Aliancha de Petricita","Cuando invocas a otro aliado, recibo Desafío.","","Conforme el Aliancha volaba sobre sus cabezas, los maltrechos soldados de Demacia lanzaron una ovación, inspirados por su forma imperecedera.","Unidad",[],["Demacia"],"RARA"],"05DE018":["Sabueso de Petricita","","","''Siempre es una dicha verlos cobrar vida. Uno olvida lo distintos que son y cómo sus personalidades son un reflejo del artista que los creó''. —Escultora de Durand","Unidad",[],["Demacia"],"COMÚN"],"06NX024":["Lord Muchacrín","Al jugar: Inflijo 2 de daño a un enemigo.\nTus Hechizos Rápidos, Hechizos Lentos, y Habilidades tienen \"Cuando inflijo daño a un enemigo Aturdido o dañado, lo elimino.\"","","''Acto 2: Un lord artero, con pocas cosas a su nombre aparte de un guantelete Kashuri robado, encanta al público jonio. Sin embargo, su máscara es burda y se ve su rostro detrás. Ruega por su vida mientras clama inocencia. La mano de hierro con la que buscaba reinar yace vacía''.","Unidad",[],["Noxus"],"RARA"],"06NX033":["Ejecución Estratégica","Lanzo Aturdir a 2 enemigos o gasto 6 de Maná para invocar a 1 General Legionario.","","La asignación es una de las primeras y más importantes decisiones que se deben tomar antes de cada batalla. Un buen comandante sabe bien que la clave de la victoria...","Hechizo",[],["Noxus"],"RARA"],"06NX012":["Annie","Al atacar: Inflijo 2 de daño a mi enemigo defensor. Si muere o desaparece, inflijo 2 de daño al nexo enemigo en su lugar.","Si te he visto jugar 6 hechizos Rápidos, Lentos o Habilidades. Cuando subo de nivel, creo 1 Tibbers en la mano.","Hace más de una década, Amoline Kiosar escapó del Conservatorio Floroscura con un bien invaluable e incandescente bajo su control. Los exploradores de Floroscura la buscaron en todos los rincones del imperio, pero ninguno de los rumores los llevó a Amoline. Y fue así que, años más tarde, cuando llegaron noticias acerca de una niña perdida que ardía con ira al norte de las Montañas de Hierro, Fynn Retrick reunió sus cosas con desgano y se marchó para investigar. No esperaba encontrar mucho. Qué equivocado estaba...","Unidad",[],["Noxus"],"Campeón"],"06NX029":["La Botica Gris","Cuando muere un aliado con 5+ de Poder, creo un seguidor aleatorio con 5+ de Poder en la mano.","","''Hoy me sorprendí pensando en mi antigua clínica en Colina Penrose y en todos los años que pasé ahí intentando desvelar los secretos de la fisiología. ¡Fueron años! Hoy en día llevo un par de meses al servicio de lady Noradi, pero ahora sé que no aprendí nada. Qué ingenuo fui. Qué afortunado también''.\n—Notas del Dr. Esslanger","Hito",[],["Noxus"],"ÉPICA"],"06NX032":["Dragarto Obediente","Cuando un aliado ataque, yo también ataco.","","''Los dragartos son un encanto, ¿no te parece? Siempre dispuestos a complacer. Siempre manipulables. Ojalá mis enemigos tuvieran las mismas cualidades''. —Espina de la Rosa","Unidad",["PERRO"],["Noxus"],"COMÚN"],"06NX030":["Desertor de la Legión","Obtengo todas las mejoras de todos los aliados en todas partes.","","''Acto 1: Un exsoldado después de abandonar su puesto tras el robo de un antiguo artefacto kashuri, se esconde en un bar de Qayanvi. Está lleno de arrogancia y demasiada bebida. ¡Lo que él no sabía es que su tesoro robado le susurra todo lo que ve a su verdadero dueño! Su vida se vertía cual vino cuantioso, cual carmesí noxiano sobre oro jonio''.","Unidad",[],["Noxus"],"RARA"],"06NX013":["Lanzahechizos","Al jugar: Lanzo Aturdir a un enemigo. Si ya está Aturdido, le inflijo 2 de daño.","","''Estudiante: Sydell Kythera\nMaestro: J. Willough\nReporte: Una araña me mordió en el antebrazo izquierdo. Sydell dice que todo fue un malentendido, pero sus muecas de felicidad contradicen su inocencia. Se le ordena cumplir con dos semanas de tareas adicionales (en el comedor)''.\n —Tarjeta disciplinaria de Floroscura","Unidad",["ARAÑA"],["Noxus"],"COMÚN"],"06NX040":["Fosas de Entrenamiento Trifarianas","En cada ronda, cuando un aliado con 5+ de Poder ataca por primera vez, lanzo Preparar.","","\"¡Pelearán a mi señal! Si matan a su compañero de combate, ¡busquen otro! Si caen, ¡mueran sabiendo que su muerte hizo más fuerte a Noxus! Soldados trifarianos... ¡comiencen!\". —Asesora Trifariana","Hito",[],["Noxus"],"ÉPICA"],"06NX028":["Conservatorio Floroscura","Cuenta regresiva 11: Creo 1 Tybaulk en la mano.\nAvanzo 1 ronda por cada hechizo Rápido, hechizo Lento o Habilidad que hayas jugado en esta partida.","","\"'... a estas alturas, sin duda has escuchado los rumores del fallo abismal de la Academia Rosaguarda. Espero que hayas aprendido algo de los errores de nuestra escuela hermana. Espero que lideres tu institución de forma que beneficie al imperio''.\n —Una carta quemada, encontrada entre los escombros del conservatorio\"","Hito",[],["Noxus"],"RARA"],"06NX014":["Desintegrar","Elige una unidad. La próxima vez que reciba 1 o más de daño en esta ronda, la elimino.","","La directora Telsi habló extensamente acerca de los dogmas noxianos, dejando así a los niños ante ella cada vez más aburridos e inquietos. Sin embargo, mientras la mayoría de los estudiantes contenían sus impulsos, Annie reaccionaba. Primero con humo y luego con fuego.","Hechizo",["ELEMENTAL"],["Noxus"],"COMÚN"],"06NX031":["Yeti Cautivo","Reputación: Cuesto 4 menos.","","La multitud quedó boquiabierta cuando llevaron a los dos yetis encadenados a la legendaria fosa de combate de Bordent. Nadie creyó que las bestias fueran lo suficientemente fuertes como para romper sus cadenas, porque ninguno de ellos se había enfrentado antes a la fuerza de un yeti.","Unidad",["YETI"],["Noxus"],"COMÚN"],"06NX009":["Lomogris Cautivo","Al atacar: Inflijo 3 de daño a mi defensor. Si muere o desaparece, inflijo 3 de daño al nexo enemigo en su lugar.","","''Acto 3: Una cuidadora cruel y su mascota. El lomogris es inocente, incluso en sus propósitos espeluznantes, ya que el artefacto que lleva lo obliga al servilismo. La cuidadora se niega a gritar mientras la usan de alimento para su propia mascota. Ojalá todos los noxianos fueran tan nobles al morir''.","Unidad",[],["Noxus"],"COMÚN"],"06NX015":["Estudiante Manálmico","En cada ronda, la primera vez que juegues un hechizo Rápido, Lento o una Habilidad, yo juego Ascuas Mágicas.","","''La primera vez que vi a Daani debió ser hace un par de años. Un chico muy amable. Venía de una familia amable. Luego, en mi último viaje, hice una parada en su pueblo y encontré al pobre Daani sentado solo en la plaza. Me dijo que estaba esperando a que su familia regresara a casa. Pobre chico, debió estar ahí sentado durante meses. No tuve el corazón de decirle lo que había visto más atrás en el camino...''. —Fynn Retrick","Unidad",[],["Noxus"],"COMÚN"],"06NX037":["Petroráculos de Noxus","Creo 1 Determinación Afilada, Muerte Giratoria o Armas de los Perdidos con Fugaz en la mano.","","''Clara, cariño, tienes que limpiar bien la sangre de las fichas''. —Ophelia Noradi, Aristócrata Carmesí","Hechizo",[],["Noxus"],"RARA"],"06NX008":["La Prefecta","Recibo +1|+0 cuando juegues un hechizo Rápido, Lento o una Habilidad.","","''Varios de los chicos están en una edad en la que sus inclinaciones naturales los hacen rebelarse contra una autoridad formal. Por fortuna, la mayor goza de la admiración del resto, y también es susceptible a la manipulación de nuestra causa. Si los estudiantes deciden ignorar nuestras lecciones, les enseñaremos a través de ella''. —Directora Telsi","Unidad",[],["Noxus"],"ÉPICA"],"06MT044":["Estelacornio Solari","Amanecer: Doy +0|+2 a otros aliados en esta ronda.","","Los estelacornios nacen de las estrellas, y algunos brillan más que otros.","Unidad",[],["Targón"],"COMÚN"],"06MT036":["Consulta los Cielos","Curo por completo a todos los aliados, y luego hago que su poder sea igual a su vida.","","''Antes que nada debemos tener compasión con nosotros mismos. Lo demás vendrá después''. —Soraka","Hechizo",[],["Targón"],"ÉPICA"],"06MT039":["Dragonera","Cuenta regresiva 3: Invoco 1 Inviolus Vox.","","''Se dice que los dragones celestiales nacieron de las mismas nebulosas, que emergieron completamente formados de polvo cósmico brumoso. ¿Pero cómo podríamos saberlo nosotros los mortales? Desde tan lejos, lo único que vemos es su luz''. —Heraldo de Dragones","Hito",[],["Targón"],"ÉPICA"],"06MT045":["Trifecta Celestial","Convoco una carta Celestial de costo bajo, mediano y alto.","","''Las estrellas vaticinan un gran potencial. Algo se acerca. ¿Qué forma tomará? ¡Yo no lo puedo saber! ¿Tú que piensas, Kulun?''. —Soñadora Lunar","Hechizo",[],["Targón"],"RARA"],"06MT043":["Petroráculos de Targón","Creo 1 Contempla el Infinito, Silencio o Bendición de Targón con Fugaz en la mano.","","''Es de lo más extraño, Shorin... Aunque la piedra esté volteada, sé perfectamente cuál constelación está pintada en ella''. —Tyari, el Viajero","Hechizo",[],["Targón"],"RARA"],"06MT029":["Esmus, Aliento del Mundo","Cuando me invocan, planto 1 Campanilla en la primera carta de tu mazo.\nAl apoyar: Otorgo +1|+1 al aliado al que apoyo.","","''... pero yo escuché que Esmus fue creada por el mismísimo Guardián y ¡que su nacimiento trajo el canto al mundo!''.\n''¡Puras mentiras! Se sabe que Esmus porta el rostro de una antigua cantante que tenía el corazón de un ángel pero la voz de los muertos... ¡hasta que el mismo Bardo le otorgó una bella voz!''.\n''¡Puras mentiras! Esmus es...''.\n—Fragmento de El nacimiento de Esmus, un juego popular de los bardos","Unidad",[],["Targón"],"COMÚN"],"06MT038":["La Luz Sinuosa","Anochecer: Doy +2|+1 y Arrollar a los demás aliados en esta ronda.","","'Madre Luna, danos tu fuerza, que con tu luz podamos atravesar hasta la más profunda oscuridad''. —Plegaria Lunari","Unidad",[],["Targón"],"COMÚN"],"06MT047":["Vórtice Místico","Cuando me invocan o cuando activo Cuenta regresiva, planto 3 Campanillas en tu mazo. Cuenta regresiva 2: Roba 1.","","''Entonces las vi... miles de ellas, todas cantando y bailando de aquí para allá. Lo siguiente que vi fue un destello de luz y todas se habían ido con todo y el templo. No quedó ni una piedra. ¿Y qué había en mis manos? El viejo Gaff tenía una campanilla en las manos''. —Historia del viejo Gaff, parte 3","Hito",[],["Targón"],"RARA"],"06MT041":["Jauría de Sabuesos Estelares","Mis mejoras de Destino se otorgan a las Jaurías de Sabuesos Estelares aliadas en todas partes.","","Fue imposible para los escaladores atraer o persuadir a los sabuesos estelares en su viaje. Se mostraban distantes, aparentemente habituados a la magia de la montaña.","Unidad",["PERRO"],["Targón"],"COMÚN"],"06MT049":["Favor de Mikhael","Otorgo +1|+2 a un aliado y elimino todas sus palabras clave negativas.","","Aquellos que escuchan el tañido de la campana se sorprenden por la pureza de su tono.","Hechizo",[],["Targón"],"RARA"],"06RU025":["Evelynn","Origen: Abrazo de la Agonía.\nCuando me invocan, invoco 1 Despojo aleatorio.","Cuando te veo o un aliado mata a 1 Despojo aliado, recibo sus palabras clave positivas en esta ronda y subo de nivel.","Las pupilas de la sacerdotisa se dilataron por completo y su mano tembló con nerviosa emoción. Estaba preparada. Este era el momento exacto que Evelynn más ansiaba. Sonrió y lentamente deshizo su ilusión. Entonces, como siempre, comenzaron los gritos.","Unidad",[],["Runaterra"],"Campeón"],"06RU001":["Bardo","Origen: El Guardián Trotamundos.\nAl atacar: Planto 3 Campanillas en tu mazo.","Si aumentaste las estadísticas totales de aliados en juego o en la mano 20+ veces.","''Así es, ¡el viejo Gaff ha visto cosas bastante extrañas! La primera vez fue el mismísimo Guardián, o eso creo. Pasó como una estrella fugaz por el firmamento. Se sintió como si el mundo se detuviera por un minuto y solo estuviéramos ahí él y yo...''. —Historia del viejo Gaff, parte 1","Unidad",[],["Runaterra"],"Campeón"],"06RU002":["Jhin","Origen: El Virtuoso.\nAl atacar: Inflijo 2 de daño a todos los enemigos Aturdidos.","Si jugaste 12+ hechizos Rápidos, Lentos o Habilidades.","''Apertura: La escena comienza en la ciudad de Qayanvi, donde un viejo maestro convoca a su joven pupilo. Su tarea es acabar con un grupo de villanos nefastos y recuperar los artefactos sagrados robados. El actor es entusiasta, pero no ha tomado su lugar. Por ahora simplemente se prepara y está en espera del momento adecuado''.","Unidad",[],["Runaterra"],"Campeón"],"06FR029":["Helados de Miedo","Lanzo Helar a un enemigo e invoco 1 Jauría Dientescarcha.","","Con el frío también llegan los dientescarcha, y no tienen que ganarle a sus presas en velocidad... solo deben ser más pacientes.","Hechizo",["ELEMENTAL"],["El Fréljord"],"ÉPICA"],"06FR033":["Jabalí de Caza","Último Aliento: Obtén una gema de maná vacía.","","En el Fréljord, el ciclo de vida y muerte tiene un aspecto distinto. El ambiente hostil se asegura de que todo se utilice.","Unidad",[],["El Fréljord"],"COMÚN"],"06FR038":["Alas del Criofénix","Inflijo 3 de daño a TODAS las unidades.\nIluminación: En su lugar, inflijo 3 de daño a todos los enemigos y curo 3 a tu nexo.","","Bajo la sombra de las alas del gran Criofénix, sus seguidores se alegran y sus enemigos se acobardan.","Hechizo",["ELEMENTAL"],["El Fréljord"],"RARA"],"06FR030":["Heraldo de los Siervos","Al jugar: Invoco 1 Siervo Congelado o hago Avanzar 1 ronda a todos tus Siervos Congelados.","","El extraño sonido silbante que se escuchó de la criatura apenas fue perceptible, pero mientras rebotaba entre los muros del barranco, los exploradores sintieron cómo hacía vibrar sus huesos. Ante sus propios ojos rápidamente se formaron grietas de tamaño desproporcionado en la superficie del hielo.","Unidad",["AVE"],["El Fréljord"],"COMÚN"],"06FR039":["Fiereza de Garraferoz","Transformo un seguidor aliado en 1 Garraferoz Alfa.","","''¡Gran espíritu Garraferoz, concédenos tu poder!''. —Udyr","Hechizo",[],["El Fréljord"],"RARA"],"06FR028":["Revna, la Guardasaberes","Cuando me invocan, otorgo mis estadísticas a las unidades en tu mazo. Luego, roba una unidad con 5+ de Poder.","","Los Guardasaberes avarosanos generalmente son ancianos experimentados de la tribu, protectores de la gente y cuentacuentos habilidosos. Ellos mantienen la tradición de cazar y luchar por la vida a través de sus historias y canciones. ","Unidad",[],["El Fréljord"],"ÉPICA"],"06FR037":["Hielo Quebradizo","Otorgo a un enemigo ''Recibo Helar en el siguiente Inicio de la ronda''.","","Por muy grueso que parezca, siempre hay que tantear el hielo antes de pisarlo.","Hechizo",["ELEMENTAL"],["El Fréljord"],"COMÚN"],"06BC045":["¡Polvoriento Estornudoso!","Doy +1|+1 a los aliados en esta ronda. Si son creados, les doy +2|+2.","","''HOLA. YO HONGO YO HABLANDO YO NO SABER POR QUÉ O CÓMO O QUÉ SUCEDIENDO POR FAVOR DEJAR YO SER HONGO. POR FAVOR, GRACIAS. ADIÓS''. —Hongo","Hechizo",[],["Ciudad de Bandle"],"ÉPICA"],"06BC036":["Paparo, el Grande","Al jugar: Manifiesto un yordle.\nAl atacar:: Otorgo +1|+0 a los yordles aliados.","","''¡TODO EL MUNDO adora a Paparo! ¡Todos los veranos nos trae cositas de todo el mundo y siempre son sabrosas, hermosas o confusas! ¡A veces son las tres!''. —Ava Sionada","Unidad",["YORDLE"],["Ciudad de Bandle"],"ÉPICA"],"06BC040":["Petroráculos de Bandle","Creo 1 Arpón Eléctrico, Estribillo Heroico o Artilugio Yordle con Fugaz en la mano.","","Los Yordles siempre están listos para jugar... ¡pero que no te sorprenda si las reglas cambian a mitad del juego!","Hechizo",[],["Ciudad de Bandle"],"RARA"],"06BC039":["Bombardeo","Inflijo 2 de daño a una unidad e invoco 1 Bomba Destartalada.","","''Eso no es nada bueno'', dijo Giselle en voz baja, mientras se ocultaba.","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"06BC044":["Amarre Cósmico","Inflijo 2 de daño a un enemigo y Aturdo a otro. Planto 6 Campanillas en tu mazo.","","''Mamá, ¿a dónde va el Guardián?''.\n''Va a todos lados, cariño. Allá hasta donde puedes ver''.\n''¿Y por qué?''.\n''Ah, cariño, no te preocupes por eso. Ni nuestros ancianos más sabios entienden los caminos del Guardián...''.\n—Una madre y su hijo","Hechizo",[],["Ciudad de Bandle"],"RARA"],"06BC026":["Byrd, el Campanero","Cuando me invocan, planto 1 Campanilla en la primera carta de tu mazo.","","''... el segundo fue el bueno. ¡Estaba barriendo el piso cuando de repente vi mi cenita tirada por todos lados y mis sartenes y ollas bamboleándose en dos patas mientras salían corriendo por la puerta! Corrí tras ellos lo más rápido que me permitieron mis viejas rodillas y los encontré en el templo, hurgando entre los estantes como si buscaran algo''. —Historia del viejo Gaff, parte 2","Unidad",[],["Ciudad de Bandle"],"COMÚN"],"06BC030":["Hongo de Proximidad","Inflijo 1 de daño a una unidad. Si una de tus trampas o bendiciones se activaron esta ronda, inflijo 3 de daño en su lugar.","","''Si está brillando, ¡termina explotando!''. —Regla número 463 de los exploradores de Bandle","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"06BC031":["Maduli, el Celador","Cuando me invocan, planto 1 Campanilla en la primera carta de tu mazo y luego duplico las bendiciones en tu mazo.","","''Sí que me dio una buena pelea. Le salían brazos por todos lados. Dientes grandes cuales pedruscos. Ah, y cuando la criatura pasó ese mazo por sus dientes, hizo un sonido tan escalofriante que creí que moriría. Corrí por mi vida, claro que sí. Pero no antes de verlos... ¡eran hoyos en el cielo! ¡Cientos de ellos!''.\n—Historia del viejo Gaff, parte 4","Unidad",[],["Ciudad de Bandle"],"RARA"],"06BC035":["El Árbol de Papel","Cuando ataca un aliado con una unidad Unida, otorgo +1|+0 a esa unidad.","","Las hojas del árbol de papel centellean con la misma magia feérica que creó el árbol mismo. Y, al igual que los pájaros que inspiraron su forma, son incapaces de resistirse al encanto de las cosas brillantes.","Hito",[],["Ciudad de Bandle"],"RARA"],"06IO005":["Teatro Macabro","Lanzo Retirada a una unidad con 3 o menos de Vida.","","''El arte necesita su tiempo''. —Jhin","Hechizo",[],["Jonia"],"COMÚN"],"06IO038":["Apoyo Moral","Cuesto 2 menos si has apoyado a un aliado esta partida. Doy Barrera a un aliado en esta ronda.","","''Confía en el equilibrio. Camina por la brecha''. —Shen","Hechizo",[],["Jonia"],"COMÚN"],"06IO012":["Llamado Kinkou","Invoco 1 Guardiana de Máscaras ahora o en el siguiente Inicio de la ronda. Roba 1.","","''Con máscaras viejas, los ojos jóvenes ven mejor''.\n—Guardiana de Máscaras","Hechizo",[],["Jonia"],"COMÚN"],"06IO009":["Emboscada de Dragón","Inicia un ataque gratis con 2 Cachorros de Dragón.","","''El deseo hecho realidad''.\n—La Domadora de Dragones","Hechizo",[],["Jonia"],"COMÚN"],"06IO033":["Tormenta de Cuchillas","Durante el resto de la partida, cuando lances Danza de Cuchillas, invoco otra Cuchilla atacante.\nDanza de Cuchillas 1.","","''¡Tú lleva el baile y yo te sigo!''. —Bailarina del Listón","Hechizo",[],["Jonia"],"ÉPICA"],"06IO004":["La Creadora","Al jugar: Lanzo Retirada a una unidad con menos Poder que yo.","","''La Creadora es extraordinaria en su arte. ¡Es una artesana de leyenda! ¡Sus creaciones no tienen igual! ¡Su ejecución es impecable! Es un gran honor estar ante su presencia y más aún portar un instrumento de su creación''. —Testigo Kashuri","Unidad",[],["Jonia"],"RARA"],"06IO010":["Colina Vientorraudo","Cuando me invocan, roba Yasuo, y Aturdo al enemigo Más fuerte.\nCuando obtienes la ficha de ataque, Aturdo al enemigo Más fuerte.","","Para la mayoría, la paz es un hogar feliz y la cálida tranquilidad que se encuentra en el abrazo de un ser querido. Para Yasuo, es ese raro momento en el que los vientos se calman y ofrecen una promesa en lugar de un recuerdo. ","Hito",[],["Jonia"],"ÉPICA"],"06IO036":["Petroráculos de Jonia","Creo 1 Teatro Macabro, Ritual de Renovación o Unidos con Fugaz en la mano.","","''Aprender a leer a tu oponente es una habilidad esencial, incluso fuera de batalla. Pero lo más importante es que los juegos son para divertirse. ¡Ahora ve y tráeme mi lavapiés!''. —Mentor Inspirador","Hechizo",[],["Jonia"],"RARA"],"06IO003":["La Tramoyista","Al jugar: Lanzo Aturdir a un enemigo.","","''Acto 4: Una joven sacerdotisa entra a nuestro relato. Su historia es trágica y se ha pasado entre las bocas pálidas de aquellos a quienes traicionó. Desesperada por redimir su transgresión, porta en sus brazos un gran peso, un regalo dorado para los noxianos a los que recibió en su tierra. Solo nos queda preguntar: ¿qué le rompió el corazón? ¿La bala o la aflicción?''.","Unidad",[],["Jonia"],"COMÚN"],"06IO035":["Estudiante Kinkou","Cuando otro aliado obtiene Barrera, recibo Barrera esta ronda si no la tengo.","","''Acepta el equilibrio en todo aspecto. En la mente, el cuerpo y el espíritu. Resiste los impulsos impetuosos de la juventud. Eleva tu perspectiva''. —Shen","Unidad",[],["Jonia"],"RARA"],"06PZ032":["Fonógrafo Descontrolado","Elige una de dos cartas de hechizo de 2 de costo para crearlas en la mano y reduzco su costo a 0 en esta ronda. Repito este efecto dos veces más.","","La primera ruleta de cantos de Zaun era sorprendentemente confiable. Lo único malo era que nadie pudo descifrar cómo controlar el volumen.","Hechizo",[],["Piltóver y Zaun"],"ÉPICA"],"06PZ042":["Imperfeccionista Malvada","Al jugar: Elige una carta en la mano. Creo 4 copias idénticas en tu mazo y reduzco su costo en 1.","","''Pues lo único que voy a decir de hoy es que las cosas podrían haber salido mejor. Eso es todo. Futura yo... sabes bien lo que hicimos''.\n —Diario de Kay","Unidad",[],["Piltóver y Zaun"],"ÉPICA"],"06PZ025":["Soledad","Cuando me invocan, invoco 1 Despojo aleatorio.\nCuando invocas un aliado de costo 1, le otorgo una palabra clave al azar.","","''De camino a casa desde el Entresuelo, volví a ver a esa pobre vagabunda llorando en un pequeño callejón. El hecho de que tantos la ignoren con tanta intención me rompe el corazón tanto como su propia y palpable consternación. Así que, mañana, si nos volvemos a cruzar, haré lo posible por ayudarla en lo que pueda''.\n —Notas del diario de Lady Sempescu","Unidad",[],["Piltóver y Zaun"],"RARA"],"06PZ043":["Petroráculos de Piltóver","Creo 1 Réplica, Transmodulador Hextech o ¡Día del Progreso! con Fugaz en la mano.","","''No encontrará un conjunto de piezas de mejor calidad en ningún lugar del mundo, buen señor. Mi hija puso el corazón en cada uno de los detalles''. —Corin Reveck ","Hechizo",[],["Piltóver y Zaun"],"RARA"],"06PZ027":["Invitación Discreta","Creo 1 Personaje Sospechoso o 1 Guitarrista Quimopunk con Fugaz en la mano y reduzco su costo en 1.","","La mejor vida nocturna en Zaun es solo para aquellos que tienen invitación. Si no eres parte de la banda, tienes que ser alguien muy importante para ganarte un lugar. O puedes encontrar un boleto en el piso.","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"06PZ038":["Camufleador Chatarrero","Le otorgo a un aliado Evasión y ''Golpe al Nexo: Roba 1 carta''.","","''¡NO VAN A CREER lo que encontré hoy!''. —Chatarrero del Sumidero","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"06PZ039":["Chatarra Rescatada","Para jugar, descarta hasta 2 cartas. Creo 2 seguidores de tus regiones que cuestan 1 más y reduzco su costo en 1.","","En las profundidades de Zaun, los lugareños se ven obligados a convertir los restos y la chatarra que rescatan a material utilizable. Tras décadas de práctica, se han vuelto bastante buenos.","Hechizo",[],["Piltóver y Zaun"],"RARA"],"06BW006":["Illaoi","Al atacar: Hago Surgir 1, luego agrego el Poder de tu Tentáculo Más fuerte al mío en esta ronda.","Si me he visto a mí o a Tentáculos aliados infligir 15+ de daño.","El ''Ojo de Nagakabouros'' es solo un nombre, pero Illaoi lo toma como un desafío para vivir como si su diosa, quien se aburre con facilidad, fuera su compañía.","Unidad",[],["Aguasturbias"],"Campeón"],"06BW036":["Rata de Muelle","Tengo +1|+0 por cada ronda distinta en la que hayas dañado al nexo enemigo.","","''No hay lugar más sangriento en Aguasturbias que los muelles. Solo mira a esas ratas. Todas se criaron en la sangre. Es todo lo que anhelan. Sucias sabandijas ''. —Carnicero Cercenador","Unidad",[],["Aguasturbias"],"ÉPICA"],"06BW038":["Megacolmillo","Una vez que tengas Profundidad, curo 3 a tus aliados y a tu nexo.","","''¿Qué es lo que quiere?''.\n''Quiere... ¡va tras las naranjas!''.\n''Por la Mujer Barbuda, ¡DENLE TODAS LAS CAJAS!''. —Marineros desafortunados","Unidad",["MONSTRUO MARINO"],["Aguasturbias"],"COMÚN"],"06BW030":["Ojo de Nagakabouros","Hago Surgir 2.\nRoba 2.","","Nagakabouros es una deidad de la providencia, siempre y cuando logres sobrevivir el acto de adoración.","Hechizo",[],["Aguasturbias"],"COMÚN"],"06BW011":["Nagakabouros","Cuando me invocan o al Inicio de la ronda: Hago Surgir 2. Luego, si tu Tentáculo Más fuerte tiene 12+ de Poder, creo 1 Furia de Nagakabouros en tu mano.","","''La Serpiente Madre. La Gran Kraken. La Mujer Barbuda. A Nagakabouros no le importan muchos sus alias y le importan menos los muertos inquietos''. —Illaoi","Unidad",[],["Aguasturbias"],"ÉPICA"],"06BW021":["Sermón de la Turbulencia","Inflijo 3 de daño a una unidad enemiga.\nHago Surgir 3.\nInflijo 1 de daño al nexo enemigo.","","''De niños aprendemos a navegar por aguas peligrosas. Resistirse es morir. Es normal que la primera prueba que debe superar una sacerdotisa sea olvidar esta lección; luchar contra la corriente con todas sus fuerzas. Porque una Portadora de la Verdad no es aquella que nada... es la corriente misma''. —Illaoi","Hechizo",[],["Aguasturbias"],"ÉPICA"],"06BW045":["Sangre en el Agua","Inflijo 1 de daño a lo que sea. Luego, lanzo Preparar.","","No hay mucho que pueda mantener lejos a los tiburones que merodean en la Bahía del Destripador. Una vez que prueban la sangre es todo lo que anhelan.","Hechizo",[],["Aguasturbias"],"COMÚN"],"06BW028":["Tentáculo Aplastante","Hago Surgir 2, luego tu Tentáculo Más fuerte y un enemigo se Golpean entre sí.","","''La vida es una prueba. Y aunque no nos guste demasiado, el dolor es el maestro más constante''. —Illaoi","Hechizo",[],["Aguasturbias"],"RARA"],"06BW035":["La Voz del Océano","Al atacar: Hago Surgir 1 y le doy Arrollar a tu Tentáculo Más fuerte en esta ronda.","","No hace falta demasiado para invocar a Nagakabouros. Ella responderá el llamado de aquellos cuya alma esté a la par del océano en cada ola, cada vez que rompen. Es una batalla que pocos pueden soportar.","Unidad",[],["Aguasturbias"],"RARA"],"06BW015":["Plegaria Escuchada","Hago Surgir 2, o gasta 5 de Maná para hacer Surgir 4 en su lugar.","","Las oraciones a Nagakabouros no se consideran súplicas, ni se tratan de pedir y recibir. Su bendición no es contraria a la vida: encontrarás la pesadumbre, la lucha, el esfuerzo y ocasionalmente, una recompensa.","Hechizo",[],["Aguasturbias"],"COMÚN"],"06BW007":["Ídolo Vigilante","Inicio de la ronda: Me inflijo 2 de daño y hago Surgir 1.","","Cuando los horrores se desbordan de las Islas de la Sombra, el ídolo brilla cual faro en el horizonte.","Unidad",[],["Aguasturbias"],"COMÚN"],"06BW037":["Ganancias del Rescate","Manifiesto un seguidor que puedas costear.","","''Muy bien, Baz. ¿Seguro que quieres volver a intentarlo?''.\n''La tercera es la vencida, Gav. Además, creo que ya hemos peleado contra todo lo que hay en esta apestosa ciudad''.\n''Peleamos y perdimos, Baz''. —Baz y Gav, aspirantes a cazarrecompensas","Hechizo",[],["Aguasturbias"],"ÉPICA"],"06BW041":["Timo","Elige 1 de 2 cartas que no sean campeones de la mano enemiga y creo una copia en tu mano. Pillaje: Cuesto 1 menos.","","''¿CINCO ases? ¡Parece que gané otra vez!''. —Tahúr del Billar","Hechizo",[],["Aguasturbias"],"RARA"],"06BW016":["Vigía Buhru","Cuando me invocan, hago Surgir 3.","","La sencillez es lo mejor de la vida. Un rocío de agua salada en el rostro, el canto de las aves en los oídos... y un enemigo sin complicaciones en el horizonte.","Unidad",[],["Aguasturbias"],"COMÚN"],"06BW009":["Líder Buhru","Al jugar: Un aliado de costo 1 inicia un ataque gratis.","","''¡No olvides la sabiduría del mar! ¡Si no te mueves, te moverán! Si te pierdes, solo sigue mi voz, porque seguramente tu enemigo sí sabe a dónde va''. ","Unidad",[],["Aguasturbias"],"RARA"],"06BW043":["Petroráculos de Aguasturbias","Creo 1 ¡Más Pólvora!, Juguetón Bromista o Carnada para Tiburones con Fugaz en la mano.","","''Ni te esfuerces por descubrir los engaños de alguien en una partida de las piedras esas. Aguasturbias rebosa de excelentes mentirosos. Si en verdad quieres ganar, mira las manos''. —Twisted Fate","Hechizo",[],["Aguasturbias"],"RARA"],"06BW018":["Steem","Cuando me invocan, invoco 1 Despojo aleatorio.\nCuando invocas un aliado de 1 de costo, le otorgo Vulnerable al enemigo Más fuerte.","","El primer encuentro de Evelynn con Steem fue violento y emocionante. Evelynn recordó cómo Steem sonrió con un placer desenfrenado mientras ella lo despellejaba y cómo devolvía el sufrimiento con el mismo entusiasmo cuando llegaba su turno. Después de dominar finalmente a Steem, Evelynn decidió no destruir al demonio menor, sino unirlo a ella para siempre. Pensó que tal vez podrían compartir con el mundo su mutuo amor por la masacre.","Unidad",[],["Aguasturbias"],"COMÚN"],"06SH014":["Abominación del Vacío","Cuando me invocan, recibo todas las palabras clave positivas que los aliados haya tenido en esta partida.\nCuando un aliado tiene una nueva palabra clave positiva, la recibo.","","''Ya habíamos oído relatos de las brechas del Vacío y de la devastación que traían consigo. Pero verlo en carne propia... No sé si alguna vez mis ojos se librarán de esa visión o si mi corazón pueda olvidar ese horror''. —Sobreviviente de Belveth","Unidad",[],["Shurima"],"ÉPICA"],"06SH016":["Heraldo de la Colmena","Al jugar: Intercambio las palabras clave positivas entre una unidad y yo.","","''Me habló como... como si me conociera. Como si quisiera que me encontrara... con algo...''. —Kai'Sa","Unidad",[],["Shurima"],"RARA"],"06SH009":["Kai'Sa","Cuando me invocan o al Inicio de la ronda: Si tienes la ficha de ataque, creo 1 Segunda Piel en la mano.","Si Evolucionaste.","Solo unos días antes, Kai'Sa había notado que su segunda piel se erizaba con una emoción nueva, que la empujaba con un vigor cada vez mayor hacia la costa de Shurima. Algo estaba mal, y a medida que Kai'Sa se acercaba a Belveth, rápidamente se dio cuenta de la magnitud del horror que se desataba ante ella.","Unidad",[],["Shurima"],"Campeón"],"06SH048":["Rito de Iniciación","Manifiesto un Hito aliado que haya sido destruido esta partida y lo invoco.","","''Un momento preservado en el tiempo''. —Zilean","Hechizo",[],["Shurima"],"COMÚN"],"06SH037":["Garramarchita Baccai","Al jugar: Otorgo Vulnerable a un enemigo.\nCuando Desafías a un enemigo, le doy -2|-0 en esta ronda.","","Su cordura se desvanecía poco a poco, cual dunas al viento, y en su lugar, una semilla de enojo floreció y se convirtió en una flor de ira que no se saciaría ni con toda el agua encontrada en el desierto.","Unidad",[],["Shurima"],"COMÚN"],"06SH008":["Anciana Belvethí","","","Shalatai se estremeció ante el horror que tenía enfrente. Allí yacía Ferai, la amable hija del carnicero, aplastada hasta la muerte. A su lado estaba Gorrub, el hijo del pescador, con las manos sin vida extendidas hacia su amada. Cuántos recuerdos perdidos. Cuántas vidas perdidas. Con una mueca, Shalatai se giró hacia el mal, dispuesta a dar su vida para salvar al resto de su pueblo.","Unidad",[],["Shurima"],"COMÚN"],"06SH042":["Petroráculos de Shurima","Creo 1 Depredador Implacable, El Peso del Juicio o Fuego Espiritual con Fugaz en la mano.","","''La esencia de las partidas de Tellstones no es quién gana, ¡sino lo genial que luces mientras juegas!''. —Akshan","Hechizo",[],["Shurima"],"RARA"],"06SH050":["Arenas del Tiempo","Doy -2|-0 a los enemigos en esta ronda. Creo 1 Siglo al Instante con Fugaz en la mano.","","Las arenas del tiempo fluyen sin pensamiento ni consideración. Su esquema es de cruel indiferencia, pero no todos son esclavos de sus insensibles maquinaciones...","Hechizo",[],["Shurima"],"RARA"],"06SH049":["Llamado a la Gloria","Cuesto 2 menos por cada aliado Ascendido diferente que hayas invocado en esta partida.\nManifiesto una carta del Mazo del Emperador de costo 9 o menos.","","''Contemplen nuestra obra... ¡miren lo que hemos construido!''. —Azir","Hechizo",[],["Shurima"],"RARA"],"06SH036":["Cámara de Renovación","Cuando invocas a un campeón, me destruyo para que reciba +2|+1 y Escudo Antihechizos.","","Nasus emergió del sarcófago con la mente esclarecida y sus heridas completamente curadas. Garabateó un par de notas y miró los sarcófagos que colgaban alto en el techo mientras pensaba en el estado mental de las aberraciones bestiales en sus interiores. Solo el tiempo dirá si esta magia podrá traer a los baccai de regreso de la locura, una magia que los demás Ascendidos alguna vez manifestaron. Pero ahora ellos ya no estaban y Renekton y su locura sí. Nasus garabateó un par de palabras más con la esperanza de haber encontrado una forma de salvar a su hermano.","Hito",[],["Shurima"],"ÉPICA"],"06SH011":["Supercarga","Otorgo Arrollar y Escudo Antihechizos a un aliado.","","''Yo te enseñaré a pelear''. —Kai'Sa","Hechizo",[],["Shurima"],"COMÚN"],"06SH017":["Buscadora del Vacío","Inflijo 1 de daño a un seguidor. Si Evolucionaste, inflijo 3 de daño a una unidad.","","''Duele, ¿verdad?''. —Kai'Sa","Hechizo",[],["Shurima"],"RARA"],"06SH007":["Ente del Vacío","Mientras estoy en la mano, tengo una palabra clave aleatoria que cambia en cada ronda. Cuando me invocan, recibo esta palabra clave.","","Dharna recordaba haber abierto las ventanas aquella mañana y olido las hogazas recién horneadas. En el camino, los pescadores habían comenzado a transportar la pesca del día a los mercados de mediodía. Recordó haber sonreído al pensar que sería un buen día.","Unidad",[],["Shurima"],"COMÚN"],"06SH010":["Cañón del Vacío","","","La erupción del Vacío en la ciudad de Belveth fue tan repentina como aterradora. La mayoría de los civiles estaban aterrorizados por el caos que repentinamente envolvió la ciudad y huyeron para ponerse a salvo tan rápido como pudieron. La mayoría, salvo Koyemi.","Unidad",[],["Shurima"],"COMÚN"],"06SH034":["Dominación","Cuando me invocan, invoco 1 Despojo aleatorio.\nCuando invocas un aliado de costo 1, le otorgo +1|+0.","","A veces, lo único que quieren los poderosos es sentirse indefensos.","Unidad",[],["Shurima"],"ÉPICA"],"06DE045":["Luz Inspiradora","Otorgo Ánimo a los aliados.","","''¡Basta de esconderse! ¡Da un paso a la luz e irradia conmigo!''. —Lux","Hechizo",[],["Demacia"],"COMÚN"],"06DE038":["Lord Eldred, Líder Cazamagos","Otros aliados y tu nexo tienen Dureza.\nCuando un aliado sobrevive al daño, le otorgo +1|+1.","","''No pude evitar escuchar tus fervientes susurros, querida esposa. Te aconsejo que seas más prudente al hablar de asuntos familiares en un lugar tan público. Nunca sabes quién podría estar escuchando''.","Unidad",[],["Demacia"],"ÉPICA"],"06DE037":["Decreto Real","Doy +2|+2 y Desafío a un aliado en esta ronda o invoco 1 Lord Distinguido.","","''De inmediato, rey Jarvan. Se hará cueste lo que cueste''. —Barrett Buvelle, Lord Distinguido","Hechizo",[],["Demacia"],"RARA"],"06DE035":["Pilar de Petricita","TODOS los hechizos cuestan 2 más.\nCuenta regresiva 2.","","Los cazamagos erigen obeliscos de petricita enormes en todas sus bases para asegurar que hasta los magos más poderosos se queden sin sus poderes.","Hito",[],["Demacia"],"COMÚN"],"06DE042":["Petroráculos de Demacia","Creo 1 Barrera Prismática, Arresto o ¡Por Demacia! con Fugaz en la mano.","","''¿Por qué le llaman 'Gambito de Rey'? ¡Las reinas también se arriesgan!''. —Cithria de Pradonubes","Hechizo",[],["Demacia"],"RARA"],"06DE036":["Papá Dragón Protector","Al atacar: Roba una unidad. Si es un Dragón, lo invoco atacando.","","''Por suerte, mi investigación parece señalar que los padres de la progenie pasan la mayor parte de su tiempo cazando a una buena distancia de sus crías. No hace falta decir que si los machos regresaran, ¡todos aquí seríamos comida de dragón! ¡Ja, ja!''. —Anden Mayne, Ovólogo","Unidad",["DRAGÓN"],["Demacia"],"ÉPICA"],"06DE030":["Seducción","Invoco 1 Despojo aleatorio y le otorgo +1|+0.","Missing Translation","''Más cerca, cariño...''. —Evelynn","Hechizo",[],["Demacia"],"COMÚN"],"06SI012":["Gwen","Al atacar: Cuando otro aliado obtiene poder de Consagrar, yo también lo obtengo. Dreno 2 del nexo enemigo.","Si infligí 10+ de daño.","Gwen se abrió paso a cortes a través de la Niebla Negra y pensó que era extraño lo mucho que esta cubría el lugar. Una vez que lo hizo, la mansión encantada se alzó como un faro de entre los árboles sombríos. No es de extrañar que Gwen se sintiera atraída hacia ella. Qué extraña era... pero ¡también era magnífica!","Unidad",[],["Islas de la Sombra"],"Campeón"],"06SI020":["Púas de Odio","Mato a un aliado para infligir 3 de daño a una unidad y, si Evelynn empezó en tu mazo, invoco un Despojo aleatorio.","","''Haz todo el ruido que quieras''. —Evelynn","Hechizo",[],["Islas de la Sombra"],"RARA"],"06SI013":["Bailarinas Eternas","Al atacar: Revivo una copia con Endeble del aliado atacante muerto Más fuerte que no sea Bailarinas Eternas con mi Poder o menos.","","Siempre es más fácil unirse a alguien en la pista de baile que ser la primera persona en bailar. Sin embargo, los gemelos siempre están encantados de demostrar a los demás cómo se hace.","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"06SI037":["Petroráculos de las Islas de la Sombra","Creo 1 Marca de las Islas, Viaje Espiritual o Desmoronar con Fugaz en la mano.","","''Decoraciones... bien pulidas. Fichas... aprender las reglas. Juego curioso. Me deja sin aliento... Una artesanía sin igual... Es inolvidable''. —Diario recuperado","Hechizo",[],["Islas de la Sombra"],"RARA"],"06SI040":["Regreso Desgarrador","Revivo al seguidor aliado más fuerte y le otorgo Endeble y Temible. Doy -1|-0 a los Enemigos en esta ronda.","","Los espíritus se pueden expulsar durante un tiempo... pero siempre regresan.","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"06SI027":["Aguja Enhebrada","Mato a un aliado para infligir daño equivalente a su Poder a un enemigo.","","''¡Agujas listas!''. —Gwen","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"06SI018":["Vora","Cuando me invocan, invoco 1 Despojo aleatorio.","","A diferencia de otros demonios que atraen a sus víctimas con falsas promesas, Vora tiene un deseo demasiado fuerte, abrumador. Más que una depredadora que acecha su comida, es una bestia salvaje que necesita alimentarse.","Unidad",[],["Islas de la Sombra"],"RARA"],"06SI015":["Que Suene la Banda","Invoco 2 Bandas Espectrales.","","''¡Mantengan la energía! ¡Paso doble!''. —Director de las Nieblas","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"06SI030":["Invitación Formal","Creo copias en la mano de 2 seguidores aliados que hayan muerto esta partida.","","''Henos aquí, cariño. Escuché que esta noche será un evento espléndido, ¡y sospecho que veremos muchas caras conocidas!''. —Invitado Fantasmal","Hechizo",[],["Islas de la Sombra"],"RARA"],"06SI026":["Director de las Nieblas","Último Aliento: Creo 1 Banda Espectral en la mano.","","''¡Sigan tocando, amigos míos! ¡Tendremos el concierto más animado de la historia!''.","Unidad",[],["Islas de la Sombra"],"RARA"],"06SI033":["Tumba Embrujada","Cuenta regresiva 2: Revivo al aliado Más fuerte.","","El sonido del choque de espada y escudo fue una sentencia de muerte. Llamó a espíritus cuyos vínculos con el mundo no habían sido cercenados y cuya voluntad ni la muerte logró sofocar.","Hito",[],["Islas de la Sombra"],"ÉPICA"],"06SI016":["Anfitrión Enérgico","","","''Los INVITAMOS CORDIALMENTE a la fiesta de sus vidas en LA CELEBRACIÓN DE MEDIANOCHE. Festejamos en la MANSIÓN PORCELANA con bebidas, baile y diversión. (Las celebraciones terminarán puntualmente a la decimotercera hora)''. \n—Una invitación escrita en elegante cursiva","Unidad",[],["Islas de la Sombra"],"RARA"],"06SI028":["Mayordomo Espectral","","","¿Qué sería de una fiesta elegante sin bocadillos elegantes?","Unidad",[],["Islas de la Sombra"],"COMÚN"],"06SI043":["Sotobosque","Desecha 3.\nDreno 2 de una unidad.","","El crecimiento más viejo encuentra un propósito, incluso en las Islas de la Sombra.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"06SI022":["Amante Fantasmal","","","Ya fuera un fantasma, un recuerdo o un sueño, algo en él me resultaba conocido...","Unidad",[],["Islas de la Sombra"],"COMÚN"],"06SI019":["Sultur","Cuando me invocan, invoco 1 Despojo aleatorio.","","''Tengan cuidado con aquellos que sonríen en estas islas embrujadas. Tal vez sean tan recién llegados que no entienden la brutalidad de este lugar. Tal vez estén locos. Tal vez sean algo totalmente distinto. No obstante, tengan cuidado''.\n—Notas de Jens Tommen","Unidad",[],["Islas de la Sombra"],"COMÚN"],"06NX022":["Cargo de la Legión","Roba un aliado con 5+ de Poder o aumento a un aliado a 5 de Poder en esta ronda.","","''Muy pocos han tenido la oportunidad de servir en la Legión Trifariana. No desaproveches esta oportunidad''. —Asesora Trifariana","Hechizo",[],["Noxus"],"ÉPICA"],"06NX019":["Desertor Noxiano","Al atacar: Aumento mi poder al nivel del aliado Equipado Más fuerte en esta ronda.","","''He vuelto a soñar y escucho aquella voz en la oscuridad. Viví una maldita década siendo un perro obediente del imperio, yendo a donde me ordenaban ir y matando a quienes me ordenaban matar. ¿Y para qué? ¿Por la gloria de Noxus? La gloria es una bonita mentira en la que antes creía, pero ya no. Kayn me mostró una senda diferente… una que conduce a la venganza''.\n —Royce, el diario del Carnicero","Unidad",["CULTISTA"],["Noxus"],"COMÚN"],"06NX023":["Maestra Pescadora Jonia","Cuando me invocan, Improviso.","","La vida de Trisk acabó de cabeza cuando, durante lo que sería su último torneo de pesca, se las ingenió para pescar un crepitante Jax. Se rehúsa a discutir el incidente, pero el tamaño del monstruo marino del que lo rescató Trisk aumenta cada vez que vuelve a hablar del tema.","Unidad",["MAESTRO DE ARMAS"],["Noxus","Jonia"],"COMÚN"],"06NX044":["Tirahilos Acechante","Al atacar: Incremento el poder de otros aliados atacantes para que igualen el mío en esta ronda.","","''Una buena madre les enseña a cazar a sus hijos, pero una madre excepcional va de cacería por ellos'' –Elise.","Unidad",["ARAÑA"],["Noxus"],"COMÚN"],"06NX041":["Paloma Carmesí","Al apoyar: Inflijo 1 de daño al aliado que apoyo para recibir +1|+1 en esta ronda.","","''Es muy divertido darle de comer a las aves. Feoward y yo apostamos a que sorberían sangre como un basilisco de Bordent. ¡Y vaya sorpresa! ¡Resultó que las palomas sí eran noxianas!''. —Edvin Cortain, Curador Carmesí","Unidad",["AVE"],["Noxus"],"ÉPICA"],"06NX020":["Balista de los Darkin","Puedes gastar 8 de maná para jugarme como Naganeka de Zuretta.","","Los Noxianos sabían que las estepas al este de Valoran eran eriales donde no se podía cultivar ni fundar asentamientos. Sin embargo, con el correr de los siglos, se fundó un imperio nuevo con ansias de expandirse. Las tierras baldías se volvieron fértiles gracias a las nuevas técnicas de agricultura y las armas que la gente creyó que estaban bien enterradas se desenterraron una vez más.","Equipo",["DARKIN"],["Noxus"],"ÉPICA"],"06NX039":["Banquete del Juerguista","Inflijo 2 de daño a un aliado para dar +2|+0 a los aliados en esta ronda.","","''No es un banquete hasta que alguien comience a gritar. Así que grita, muchacho''. —Vladimir","Hechizo",[],["Noxus"],"COMÚN"],"06NX026":["Martillotes","","","Si bien Vessid no es el duelista más rápido en Bordent, es poco lo que sus oponentes pueden hacer para defenderse cuando los golpea con sus martillotes.","Equipo",[],["Noxus"],"COMÚN"],"06NX034":["Portador Furioso","Un aliado Equipado Golpea a un enemigo.","","''Una vez más somos hermanos de sangre''. —Desertor Noxiano","Hechizo",["CULTISTA"],["Noxus"],"RARA"],"06NX036":["Runescudero","Cuando me invocan, lanzo Reforjar.","","Durante meses trabajó arduamente en el frío y la lluvia, su tarea era ingrata y no se divisaba un fin. Y, sin embargo, el fin llegó. Por fin haría algo con su vida.","Unidad",[],["Noxus"],"COMÚN"],"06NX027":["Enfrentamiento Brutal","Destruyo el equipo de un enemigo. Un aliado y ese enemigo se Golpean.","","''Uno, dos, míralo gritar,\nEl soldado en llamas está,\nTres, cuatro, míralo arder,\n¡Tibbers quiere a hombres moler!''. —Annie","Hechizo",[],["Noxus"],"RARA"],"06MT035":["Xolaani, la Tejesangre","Recibo +2|+2 por cada aliado que haya muerto con su poder aumentado.\nPotenciación a 16: Me transformo en Xolaani, la Ruina del Aspecto.","","Xolaani se limitó a observar mientras Anaakca caía de rodillas, sometido por el enemigo que tan desesperadamente buscaba destruir. Lentamente, sus latidos resonaron al unísono con los demás. Otro corazón para controlar; otro cuerpo para dominar.","Unidad",["DARKIN"],["Targón"],"ÉPICA"],"06MT007":["Guiverno Seráfico","Potenciación a 5: Arrollar.","","''Ah, ya veo... las formas que quedaron en la montaña eran simples marcas... conductos de los seres del reino más allá de las estrellas...''. —Guardasaberes Skai'en","Unidad",["DRAGÓN"],["Targón"],"RARA"],"06MT037":["Sellado en Acero","Aniquilo a un aliado y creo 1 Forma Corrompida con sus estadísticas.","","Los dioses guerreros caídos que estaban encerrados en esas armas no pudieron ser vencidos con facilidad, por lo que se les tuvo que aprisionar.","Hechizo",[],["Targón"],"RARA"],"06MT031":["Mihira, Aspecto de la Justicia","Fin de la ronda: Otorgo +1|+1 a los aliados en juego y en la mano.\nPotenciación a 5: Evasión, Robo de Vida y Arrollar.","","''Hay quienes veneran los Aspectos como si fueran dioses. Otros los ven como mensajeros del reino del más allá. Pero también hay quienes les temen... y quizá con justa razón''. —Guardasaberes Skai'en","Unidad",[],["Targón"],"ÉPICA"],"06MT010":["Juicio Divino","Doy ''No me pueden dañar ni matar'' a un aliado en esta ronda.\nDoy +1|+0 a todos los aliados en esta ronda.","","''¡La llama de la justicia me protege!''. —Kayle","Hechizo",[],["Targón"],"RARA"],"06MT016":["Mensajero Alado","Potenciación a 3: Evasión.","","''Sí... te reconozco. El mensaje que traes... solo puede ser un llamado''. —Ryze","Unidad",[],["Targón"],"COMÚN"],"06MT015":["Llamas Purificadoras","Otorgo +2|+2 a 2 aliados en la mano.","","''¡El mal arderá!''. —Kayle","Hechizo",[],["Targón"],"COMÚN"],"06MT042":["Protector Crepuscular","Amanecer: Doy +1|+1 a los aliados con Amanecer en esta ronda.\nAnochecer: Otorgo +1|+0 a los aliados con Anochecer.","","Durante el crepúsculo y justo antes del amanecer, se puede escuchar a la lechuza. Su llamado es un recordatorio de los espacios liminales entre el alba y el ocaso.","Unidad",["AVE"],["Targón"],"RARA"],"06MT008":["Kayle","Tengo +1|+0 por cada vez que un aliado haya atacado con poder aumentado.\nCuando me invocan, otorgo +1|+0 a los aliados.\nPotenciación a 6: Ataque Rápido.","Si al Inicio de la ronda: Tengo 11+ de Poder.","''Los demacianos la conocen como la Protectora Alada. Sin embargo, quienes vivimos bajo la bóveda de las estrellas en Targón la conocemos como la hija de la Justicia, aquella que carga con un propósito divino y porta una espada de fuego estelar''. —Guardasaberes Skai'en","Unidad",[],["Targón"],"Campeón"],"06MT004":["Pastor Errante","Al jugar: Elige un aliado y este Improvisará. Si no lo haces, yo Improvisaré.","","Jax ayudó a Chaska a rescatar a su rebaño de las hadas furibundas. Luego, Chaska hizo lo propio con Jax. Estos dos viajan juntos, siempre y cuando uno de ellos no se pierda.","Unidad",["MAESTRO DE ARMAS"],["Targón","Ciudad de Bandle"],"COMÚN"],"06MT017":["Clérigo Divino","Potenciación a 3: Robo de Vida.","","''Se dice que cuando Mihira abandonó este lugar, dejó una parte de sí misma... una flama sagrada que arde con gran fulgor. Durante años, mi familia ha cuidado de aquella flama y la ha mantenido encendida, con la esperanza de que algún día regrese''.","Unidad",[],["Targón"],"RARA"],"06MT040":["La Protección de la Inmensidad","Cuando hayas Equipado a un aliado en esta partida, cuesto 2 menos.\nDoy Escudo Antihechizos a un aliado en esta ronda.","","Levanta la vista al cielo nocturno y fija tu mirada en una pequeña parte del firmamento. Ahora imagina a todos aquellos que han vivido ahí, imagina todo el conocimiento que obtuvieron y las experiencias que vivieron a lo largo de incontables milenios. Imagina toda esa información concentrada en un fragmento que quepa en la palma de tu mano. Piensa en la cantidad de información que sostendrías. En todo el poder.","Hechizo",["CULTISTA"],["Targón"],"RARA"],"06MT034":["Impacto Celestial","Aniquilo una unidad o Hito. Curo 3 a tu nexo.","","''¿Quién vendrá en nuestro momento más aciago?''. —Anciano de Shurima","Hechizo",[],["Targón"],"RARA"],"06MT033":["Bandas Dracónicas","Mi portador es un Dragón.","","Muchas personas invocan el poder de los dragones, aunque este se manifiesta de formas distintas por toda Runaterra. Quienes invocan el poder de un dragón celestial puede que descubran la fuerza interna que poseen, la cual arde con el fulgor y el calor de una estrella.","Equipo",[],["Targón"],"COMÚN"],"06MT053":["Joyera Generosa","Cuando juegas un hechizo, otorgo +1|+1 a un aliado aleatorio en la mano.","","Con ojos amables, pero de expresión escondida detrás de un velo, ofrece cuentas de cristal para orar a quienes se preparan para comenzar sus peregrinaciones. No les pide nada a cambio, pues el precio será saldado en la montaña.","Unidad",[],["Targón"],"ÉPICA"],"06MT006":["Magnetita de los Darkin","Al apoyar: Otorgo +1|+1 al aliado al que apoyo.\nPuedes gastar 8 de maná para jugarme como Horazi.","","Puede que quienes aprisionaron a los Darkin pensaron que encapsular a la legendaria guerrera Horazi en un orbe de metal estelar apagaría su irascible voluntad. Pero mientras su general se agitaba, también lo hacía Horazi, quien entendió que incluso los antiguos protectores de Targón podían ser tentados con promesas de susurros lejanos.","Equipo",["DARKIN"],["Targón"],"ÉPICA"],"06MT018":["Guardaleyes","Al jugar: Lanzo Aturdir a los enemigos con menos poder que yo.","","''Temo que el día al fin ha llegado... La justicia vuelve con alas doradas. ¡Y junto a ella, un ejército resplandeciente!''. —Guardasaberes Skai'en","Unidad",[],["Targón"],"COMÚN"],"06MT052":["Bendición Celestial","Otorgo Ánimo a un aliado en juego y a un aliado en la mano.","","''Por la gracia divina''. —Kayle","Hechizo",[],["Targón"],"COMÚN"],"06MT032":["Cultista Lunari","Cuando me invocan o cuando hayas Equipado un aliado en esta partida, creo 1 Gema en la mano.","","Ella buscaba poner un alto al conflicto entre el Sol y la Luna, entre el día y la noche. El arco ofrecía poder, aunque a un terrible costo... Y, sin embargo, le juró lealtad con la esperanza de detener la guerra de una vez por todas. ","Unidad",["CULTISTA"],["Targón"],"COMÚN"],"06RU008":["Jax","Origen: Gran Maestro de Armas.\nEquipamiento automático: La Luz de Icathia.","Si los aliados equipados atacaron con 16+ de poder total.","Hace siglos, el Vacío le arrebató su hogar a Jax. Ahora viaja por el mundo en busca de guerreros que posean la fuerza de voluntad (y las agallas) para un día enfrentarse a ese enemigo tan terrible.","Unidad",["MAESTRO DE ARMAS"],["Runaterra"],"Campeón"],"06RU006":["Ryze","Origen: El Mago Rúnico.\nCuando me invocan o al Inicio de la ronda: Creo 2 Hojeadas al Pasado en tu mazo.","Si veo 3+ Runas del Mundo únicas.","Ryze llegó a la cumbre en compañía del sirviente silencioso de Kayle. Miró hacia abajo, a una tierra arrasada por la guerra, y logro divisar las monstruosidades Darkin que ahí luchaban. Durante siglos, había observado cómo la humanidad iba de una catástrofe a otra. Y pensó: ''¿Qué pasaría si mis esfuerzos fueran inútiles y Runaterra estuviera ya destinada a su destrucción?''.","Unidad",[],["Runaterra"],"Campeón"],"06RU005":["Kayn","Origen: El Segador Sombrío.\nEquipamiento automático: La Guadaña Darkin.\nCuando mato a un enemigo, me curo 2.","Si he Golpeado dos veces. Cuando subo de nivel, lanzo Retirada sobre mí.","Con la caída de otro cadáver, Kayn soltó una carcajada de alegría ante la certeza de que pronto liberaría la segunda arma Darkin que yacía debajo. En su interior, la expectativa de Rhaast crecía con la certeza de que la caída de Kayn esta cuestión de tiempo.","Unidad",["DARKIN"],["Runaterra"],"Campeón"],"06RU026":["Aatrox","Origen: El Destructor de Mundos.\nEquipamiento automático: La Espada Darkin.\nCuando me invocan o al Golpear: Curo 2 a tu nexo y creo 1 Destructor de Mundos en la mano si no tienes 1.","Si jugaste Destructor de Mundos.","Incluso a continentes de distancia, Aatrox sintió su despertar. Sentía que el odio aún ardía. Ya había destruido sus estatuas, ahora podría librar una última guerra contra la Cobarde de Icathia y acabar con su patética existencia.","Unidad",["DARKIN"],["Runaterra"],"Campeón"],"06RU009":["Varus","Origen: La Flecha del Castigo.\nEquipo automáticamente El Arco Darkin.","Si fijaste 7+ aliados como objetivo.","¿Y si, con el paso del tiempo, el hombre que se convirtió en el Darkin se acuerda de quién es gracias a las voces mortales en su interior? ¿Qué pasaría si, en lugar de ignorar por completo esas voces, llegara a creer lo que dicen?","Unidad",["DARKIN"],["Runaterra"],"Campeón"],"06FR004":["Aprendiz del Forjaarmas","La primera vez que equipas a un aliado, lo Forjo.","","Ornn creó la Forja viviente hace muchísimos años, pero decidió buscarla hace muy poco tiempo. Jamás se le pasó por la mente que podría buscar un nuevo propietario y que se iría por su cuenta.","Unidad",[],["El Fréljord"],"COMÚN"],"06FR011":["Ornn","Al jugar: Me equipo con una copia exacta del equipo de un aliado o el equipo más fuerte de la mano.\nAl atacar: Me Forjo dos veces.","Si un aliado Golpeó e infligió 8+ de daño de un Golpe.","Si alguien le hubiera preguntado a Ornn por qué tenía tan poca paciencia, hubiera dicho simplemente que sí la tiene y que, de hecho, esa era la razón por la que su trabajo es incomparable. Era con las PERSONAS con quienes no tenía paciencia. Pero nadie le preguntó, así que nunca respondió.","Unidad",[],["El Fréljord"],"Campeón"],"06FR035":["Vine a Ayudar","Doy +0|+3 a un aliado en esta ronda. Si recibe daño, le doy +2|+3.","","''No te preocupes, porito. ¡Estoy contigo!''. —Braum","Hechizo",[],["El Fréljord"],"COMÚN"],"06FR034":["El Frío Despiadado","Lanzo Helar al enemigo más fuerte. Me copio si Equipaste a un aliado en esta partida.","","Anaakca avanzaba a tal velocidad que el mismo Fréljord parecía seguirla en su carrera. Aquellos que sobrevivieron a su masacre pronto sintieron un frío que les heló la piel y que, finalmente, les detuvo el corazón.","Hechizo",["CULTISTA"],["El Fréljord"],"COMÚN"],"06FR018":["La Lanza Darkin","Al atacar: Otorgo +1|+1 a los 2 aliados de arriba de tu mazo.\nPuedes gastar 8 de maná para jugarme como Anaakca.","","''Matriarca, el invierno se ha intensificado. Los avarosanos huyeron más allá de sus puestos de avanzada. Al norte está el mar... Nuestro único camino es hacia el este''.\n\"No lo escuches, matriarca. Ese camino lleva a los Hielos Perpetuos. Y más allá, se alzan las tierras susurrantes. Si me lo preguntan, es mejor morir que lidiar con esa tierra maldita''.\n''Es una fortuna que ustedes no decidan el futuro de mi pueblo''.\n''Es verdad, matriarca. Sin embargo, podría haber un tercer camino. Permítame ir al este. Es mejor que una persona se pierda en la oscuridad y no todo nuestro pueblo''.\n —Matriarca Sejuani, deliberando con sus generales","Equipo",["DARKIN"],["El Fréljord"],"ÉPICA"],"06FR012":["Artesana Favorecida","Cuando me invocan, creo 1 Tiempo y Dedicación en la mano.","","''Mi madre me contó la historia de Ornn, tal como su madre se la contó a ella y así sucesivamente. Ahora, yo te la contaré a ti. Escucha bien y no me interrumpas. Hace tiempo, a través de un enorme, cálido y agitado mar…''.","Unidad",[],["El Fréljord"],"COMÚN"],"06FR005":["Forja de Ornn","Cuando me invocan o al Inicio de la ronda: Creo 1 Tiempo y Dedicación con Fugaz en la mano.","","Estar solo en la forja del Hogar, acompañado solo con el sonido del suave paso del río derretido debajo y el golpe del martillo contra el yunque… eso le gustaba bastante.","Hito",[],["El Fréljord"],"RARA"],"06FR040":["Guardián de las Tribus","Cuando me invocan, otorgo +1|+1 a los aliados por cada subtipo distinto que hayas invocado en esta partida.","","''... y había una criatura ENORME que cuidaba a todas las criaturitas...''. —Ingvar la Joven","Unidad",[],["El Fréljord"],"ÉPICA"],"06FR020":["Fractura","Inflijo 1 de daño a TODO o destruyo el equipo de una unidad.","","El frío no perdona a nada ni a nadie.","Hechizo",["ELEMENTAL"],["El Fréljord"],"RARA"],"06FR027":["Gastrodóptera Lanuda","Potenciación a 8: Regeneración.","","Aunque los troles no son muy conocidos por su intelecto, pueden ser sorpresivamente ingeniosos.","Unidad",[],["El Fréljord"],"RARA"],"06FR032":["Don del Sangre Hogareña","Curo 4 a tu nexo y otorgo +1|+1 a todos los aliados y equipo en tu mazo. Roba 1 de ellos.","","''Ven, caliéntate junto al fuego''. —Reforjador Sangre Hogareña","Hechizo",[],["El Fréljord"],"ÉPICA"],"06FR022":["Rugido Ardiente","Forjo a un aliado e inflijo 1 de daño a TODAS las unidades. Luego lo hago de nuevo.","","''¡Se debe forjar una voluntad de hierro!''. —Ornn","Hechizo",["ELEMENTAL"],["El Fréljord"],"RARA"],"06FR021":["Poro Puchero","Potenciación a 3: Arrollar, Regeneración y Dureza.","","''¡Vamos, tienes que tomar tu medicina! ¡No te sentirás mejor hasta que lo hagas!''. —Ingvar la Joven","Unidad",["PORO"],["El Fréljord"],"COMÚN"],"06FR023":["Coloso Forjado","La primera vez que me Equipes, creo una copia mía de 4 de costo en la mano. Le otorgo las estadísticas del Equipo.","","Aunque no lo admitía, Ornn estaba muy complacido con los colosos: estas criaturas cumplían muy bien el rol que les había asignado y, lo mejor de todo, no hablaban.","Unidad",[],["El Fréljord"],"ÉPICA"],"06FR008":["Reforjador Sangre Hogareña","Al jugar: Forjo un aliado dos veces y lo curo 3 a él y a tu nexo.","","Todos los Sangre Hogareña habían partido cuando Ornn decidió abandonar el mundo. Sin embargo, su nombre aún seguía en el recuerdo a pesar de haber pasado tantas generaciones. Sin embargo, las historias de Ornn volvieron a emerger hace poco tiempo y se dice que mucha gente volvió a la senda de los Sangre Hogareña.","Unidad",[],["El Fréljord"],"COMÚN"],"06FR009":["Forjaarmas Hábil","Al jugar: Forjo un aliado.","","Cuando Fiske pensó en tener un aprendiz, se imaginó a una persona dedicada, competente, fuerte y seria en lo que respecta a su arte. Pero Kindra no tenía ninguno de estos atributos; por el contrario, era propensa a soñar despierta, a jugar en lugar de trabajar y a meterse en problemas con su tonta tortuga. No obstante, sí que estaba aprendiendo… y eso es lo que importa.","Unidad",[],["El Fréljord"],"COMÚN"],"06FR024":["Mazohueso","","","''¡Cronch!''. —Tarkaz, el Sinclán","Equipo",[],["El Fréljord"],"COMÚN"],"06FR017":["Cultista de Vallefrío","Tus aliados Equipados tienen Arrollar.","","La Garra Invernal tenía razón. Los avarosanos SÍ habían sido demasiado blandos. Era hora de un nuevo líder, alguien que no buscara unir al Fréljord con la paz, sino gobernar las tierras. ","Unidad",["CULTISTA"],["El Fréljord"],"RARA"],"06FR041":["Toque del Invierno","Obtén una gema de maná vacía. Iluminación: Cuesto 1. Roba 1.","","Extrañas runas palpitan desde las caras de la gema que llevas en la mano. Con un espeluznante destello, su luz se eleva desde la superficie y se enreda en tu brazo como una espiral escalofriante. Pero en lugar de congelarte, su frío te vigoriza, como si te impregnara con su propia esencia. ","Hechizo",["ELEMENTAL"],["El Fréljord"],"ÉPICA"],"06FR036":["Misticismo Salvaje","Obtén una gema de maná vacía.\nInvoco 1 Místico Feral.","","''Los espíritus, las estrellas... nos reunieron una vez más''. —Clarividente Hyara","Hechizo",[],["El Fréljord"],"ÉPICA"],"06BC015":["Norra","Golpe al Nexo: Planto 1 Portal Misterioso entre las 4 cartas de arriba de tu mazo.","Si invocaste 6+ aliados creados.","Norra trabajó con presteza con recuerdos de su hogar en mente. Trabajar con portales implica muchísimo riesgo… y aún no se había tomado su primera taza de té. Pero a Norra le encantaban los acertijos, en especial aquellos que podían dejarla varada en otras dimensiones entre el tiempo y el espacio. Trabajó con mayor rapidez mientras pensaba en su querida gata, la cual seguro estaba preocupada y la esperaba para cenar.","Unidad",["YORDLE"],["Ciudad de Bandle"],"Campeón"],"06BC043":["Porocuentos","Creo 3 poros aleatorios de 1 de costo en la mano.","","''... TONCES EL PORO DIJO '¡OYE, TÚ! ¡YO TAMBIÉN QUIERO POROGALLETAS!'. LUEGO, LOS POROS SE JUNTARON EN LA GRAN REUNIÓN DE POROS PARA HABLAR DE TODOS LOS PROBLEMAS QUE TIENEN LOS POROS, COMO DÓNDE ESTÁN LAS POROGALLETAS, POR QUÉ NO HAY MÁS POROS Y...''. —Ingvar la Joven","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"06BC051":["Lanzabananas","Al jugar: Inflijo daño equivalente a mi Poder a una unidad.","","''¡OIGAN! ¿ALGUIEN NECESITA POTASIO?'' –Bananín, momentos antes de ''El Incidente''. ","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"06BC047":["Magia Compartida","Le doy a un aliado con una unidad Unida las estadísticas y palabras clave de su unidad Unida esta ronda y la traslado a otro aliado.","","Se podría pensar que el campo de batalla no es lugar para un pastor, pero el conjunto de habilidades que poseen tiene una utilidad asombrosa. Solo hay que ver a los combatientes como ovejas que necesitan un pastor.","Hechizo",["MAESTRO DE ARMAS"],["Targón","Ciudad de Bandle"],"RARA"],"06BC019":["La Amante del Té","Cuando me invocan, planto 1 Portal Misterioso entre las 4 cartas de arriba de tu mazo.","","Ashane era famosa por el té que preparaba antes de extraviarse en el Umbral Entremundos. Mientras experimentaba con sabores nuevos, la desafortunada mezcla de dos hojas la hizo caer en un profundo sueño. Tuvo sueños inquietos con criaturas raras y estructuras imposibles, cuya silueta se marcaba en un horizonte infinito. Sin embargo, al despertar, descubrió que aquellos sueños eran bastante reales.","Unidad",["FEÉRICO"],["Ciudad de Bandle"],"COMÚN"],"06BC029":["El Báculo Darkin","Al Golpear: Restablezco 1 de maná de hechizos.\nPuedes gastar 8 de maná para jugarme como Baalkux.","","Pensaron que el Bandlebosque era el lugar perfecto para ocultar un arma Darkin: la naturaleza de dicho bosque lo hace prácticamente imposible de recorrer y los yordles sabrían cómo evadir una maldad tan abyecta. Sin embargo, los targonianos fallaron en entender la eficacia de una magia tan extraña... y los efectos que tendría en la flora del lugar.","Equipo",["DARKIN"],["Ciudad de Bandle"],"ÉPICA"],"06BC038":["El Surgimiento Súbito","Cuando hayas Equipado a un aliado en esta partida, cuesto 2 menos.\nAumento a un aliado a 4|4 en esta ronda.","","''Hay muchísimo poder en nuestro interior''. —Varus","Hechizo",["CULTISTA"],["Ciudad de Bandle"],"RARA"],"06BC017":["Portalpalooza","Planto 2 Portales Misteriosos entre las 4 cartas de arriba de tu mazo.\nRoba 1.","","''¡Debería usar Los caminos bajos más a menudo! Qué tontita soy, siempre olvido tener cuidado con mi cabeza…''.\n —Norra","Hechizo",[],["Ciudad de Bandle"],"RARA"],"06BC020":["Artista del Origami","Recibo +1|+0 por cada una de tus trampas o bendiciones que se hayan activado en esta ronda.","","La magia del modelismo con papel a veces puede ser impredecible. Este arte se centra tanto en la intención que se proyecta en la creación de un objeto como en el deseo de este de tener forma.","Equipo",[],["Ciudad de Bandle"],"RARA"],"06BC028":["Cultista Floreciente","Cuando hayas Equipado un aliado en esta partida, recibo Evasión.","","Personas, plantas o animales... La influencia corruptora de los Darkin no perdona a nada ni a nadie.","Unidad",["CULTISTA"],["Ciudad de Bandle"],"COMÚN"],"06BC021":["Constructo de Chatarra","Último Aliento: Planto 1 Portal Misterioso entre las 4 cartas de arriba de tu mazo.","","Aunque apenas había nacido el día anterior, Marv (como Norra lo llamó de forma afectuosa) estaba muy orgulloso de ser su asistente. Sin embargo, insistía tajantemente en que se refirieran a él como ''chatarra'' y no como ''basura'', pues la segunda tiene una connotación negativa.","Unidad",["FEÉRICO"],["Ciudad de Bandle"],"COMÚN"],"06BC042":["Cambiaformas Curiosos","Cuando un seguidor aliado se transforma en otro seguidor, me transformo en una copia exacta suya.","","Forma que el camaleón ve, forma que el camaleón toma.","Unidad",[],["Ciudad de Bandle"],"RARA"],"06BC023":["Señales Desconcertantes","Devuelve un hechizo Rápido o Lento a la mano o destruyo el Equipo de una unidad. Roba 1.","","''¡Ay de mí! ¿Era por acá, por allá o… por acullá? ¡Siempre lo olvido!''. —Norra","Hechizo",[],["Ciudad de Bandle"],"RARA"],"06BC041":["Partepalooza de Skrappy","Cuando me descartes, invócame. Cuando invocas un Yordle Mecha, le otorgo una palabra clave al azar.","","No importa si es grande o pequeño, animado o inanimado, si hay un coso que deseas encontrar, ¡búscalo en la tienda de Skrappy! Pero no le preguntes a Skrappy dónde encontrarlo porque cree que catalogar no sirve de nada.","Hito",[],["Ciudad de Bandle"],"RARA"],"06BC011":["Viaje Mágico","Planto 1 Portal Misterioso entre las primeras 4 cartas de tu mazo y 1 Campanilla en la primera carta de tu mazo.","","Mientras deambula a sus anchas por los diferentes reinos, Bardo escucha y es consciente del gran conflicto que se avecina… uno que podría silenciar la canción de la creación.","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"06BC032":["Colección Ecléctica","Por cada aliado, planto 1 Portal Misterioso y 3 Campanillas entre las 10 cartas de arriba de tu mazo, y 1 Trampa Aturdidora y 3 Hongos Venenosos en el mazo del enemigo.","","''¡Portales, portales en todas partes!''.\n —Norra","Hechizo",[],["Ciudad de Bandle"],"ÉPICA"],"06BC024":["Protector del Entremundo","En cada ronda, la primera vez que una de tus trampas o bendiciones se activa, le doy +1|+1 e Impacto a los aliados en esta ronda.","","Gaspar fue el primer yordle que llegó al Umbral Entremundos. Por muchos años deambuló solo entre los tortuosos caminos y portales que parecen no llevar a ningún lado. Tras decidir que nadie más debía pasar por el mismo calvario, ahora ayuda a otros viajeros perdidos a encontrar el camino a casa.","Unidad",["FEÉRICO"],["Ciudad de Bandle"],"RARA"],"06BC033":["Mecapulverizador","Para usarme, descarta 1.","","''¡Miren! Conseguí el guante de boxeo en los restos de un barco transbordador hundido. ¡También recuperé resortes y metal de las profundidades de Zaun y las forjas de Demacia! ¡Esta es una auténtica creación del mundo!''. —Paparo el Grande","Equipo",[],["Ciudad de Bandle"],"COMÚN"],"06BC016":["Biblioteca Viviente","Cuando me invocan, si una de tus trampas o bendiciones se activaron en esta ronda, roba 1.","","Él considera que es su deber poseer una inmensa cantidad de conocimientos, así que reúne tomos de diferentes viajeros que han cruzado el Umbral Entremundos. Por desgracia, todo este conocimiento parece habérsele subido a la cabeza.","Unidad",["FEÉRICO"],["Ciudad de Bandle"],"COMÚN"],"06IO044":["Cantante Serena de los Cielos","Cuando me invocan, reduzco a la mitad y redondeo el costo de los hechizos en tu mazo.","","''Algunos buscan la paz a través de la meditación. Otros buscan conocimiento para la autorreflexión. Pero solo aquellos que encuentran su centro en la expresión y la creación son quienes pueden traer paz a los demás''. –Karma.","Unidad",[],["Jonia"],"ÉPICA"],"06IO013":["Estilo Wuju","Doy +2|+0 a un aliado en esta ronda.\nCreo 1 Meditar en la mano.","","''Un corte de muchos''.\n —Maestro Yi","Hechizo",[],["Jonia"],"RARA"],"06IO023":["El Abanico Darkin","Al atacar: Invoco 1 Cachorro de Dragón atacante.\nPuedes gastar 9 de maná para jugarme como Praa, el Cruzafisuras.","","''En el puente entre los mundos hace mucho que percibo una sombra que palpita con una furia silenciosa. Aunque sé que no debo adentrarme en la oscuridad que le sigue, el latido se ha hecho más fuerte y rápido en los últimos tiempos... y me temo que las criaturas del reino espiritual pronto comenzarán a buscarla''. —Shen","Equipo",["DARKIN"],["Jonia"],"ÉPICA"],"06IO029":["El Espíritu de Wuju","Flujo: Cuesto 2 menos.\nCuando me invocan, roba un hechizo.","","''El maestro Doran creía que cada uno de los ojos del Espíritu de Wuju ofrecía una perspectiva única del ser de una persona. Pero, por más que yo lo intento, lo único que ven los lentes de mi yelmo son distintos tonos de verde. ¿De qué me estoy perdiendo?''. —Lui, discípula de Doran","Unidad",[],["Jonia"],"COMÚN"],"06IO037":["La Flama Negra","Al jugar: Capturo a un aliado. Cuando atacas por primera vez en cada ronda, invoco una copia atacante suya con Endeble.","","''¿Qué es la vida, sino la sombra de la existencia? Abraza la oscuridad y vivirás para siempre''. —Zed","Hito",[],["Jonia"],"ÉPICA"],"06IO031":["Espada del Alma","Flujo: Cuesto 2 menos.","","''¡Espada y cuerpo!''. —Maestro Yi","Equipo",[],["Jonia"],"COMÚN"],"06IO014":["Discípulo Vastaya","Golpe al Nexo: Lanzo Retirada sobre mí y me transformo en Viento Shimon.","","Ting sonrió mientras los atacantes inundaban el templo. ¡Por fin tenía una oportunidad de probar su valía! Primero fue Wukong y luego Yi… ambos habían despreciado sus talentos. ¡Que otros busquen a sus ''maestros''! Él estaba listo. Él era el Viento de Shimon. ","Unidad",[],["Jonia"],"ÉPICA"],"06IO008":["Maestro Yi","Inicio de la ronda: Reduzco en 1 el costo de un hechizo en tu mano y Flujo: Otorgo +2|+0 a todos los aliados Maestros Yi en todas partes.","Si los Maestro Yi aliados infligieron 12+ de daño.","El Maestro Yi no podía dejar de pensar en el arma Darkin. Desde que la descubrieron, un terrible sentimiento de miedo lo había atormentado. Algunos de sus estudiantes tenían muchísimo interés (demasiado, de hecho), por lo que guardó las cuchillas curvas en lo profundo del templo y bien custodiadas. Con algo de esfuerzo, alejó esos pensamientos de su mente y continuó con su meditación. Transmitir las enseñanzas de Wuju era lo único que importaba y Jun tenía un futuro prometedor.","Unidad",[],["Jonia"],"Campeón"],"06IO040":["Técnica del Viento Gemelo","Elige un seguidor. Invoco una copia suya exacta con Endeble. Si es un enemigo, le lanzo Aturdir.","","Para los habitantes de Jonia, el viento es el más caprichoso de los elementos. Caprichoso, pero no indomable. ","Hechizo",[],["Jonia"],"RARA"],"06IO011":["Jun, la Prodigio","La primera vez que me Equipes, recibo Barrera y Robo de Vida en esta ronda.","","A su señal, Jun desató una ráfaga de golpes tan precisos como los de Yi. A pesar de que él esquivó los golpes con gran habilidad, se inclinó ante ella con una sonrisa en su rostro.","Unidad",[],["Jonia"],"RARA"],"06IO015":["La Testigo","Flujo: Cuesto 2 menos.\nAl jugar: Lanzo Aturdir a un enemigo.","","¿Cuál es el papel de esta criatura en este extraño y cruel espectáculo? Ah, más que parte del público, es una observadora, un lente por el cual pasan todas las cosas y se comparan con la verdad y la belleza. ¡La Testigo!","Unidad",[],["Jonia"],"COMÚN"],"06IO030":["Valle de la Niebla","Cuando me invocan, roba un equipo.\nLa primera vez en cada ronda que un aliado sin equipar sea Equipado, restablezco 2 de maná de hechizos.","","''El piso de Caída de Niebla es sagrado. Las espadas que adornan el paisaje han estado aquí durante siglos. Es mi creencia que si se deja una espada aquí con un poema en su empuñadura, los espíritus de sus antiguos portadores las imbuirán con sus bendiciones''.\n —Discípulo de Doran, pergamino escrito a mano","Hito",[],["Jonia"],"RARA"],"06IO034":["Elección Trascendental","Si Equipaste a un aliado en esta partida, cuesto 1 menos.\nDoy +2|+0 o +0|+2 a un aliado en esta ronda.","","Lágrimas de ira cayeron por el rostro de Jun mientras reconocía los cadáveres que inundaban el piso. Le había fallado a ellos y a su maestro. Ahora solo quedaba una opción…","Hechizo",["CULTISTA"],["Jonia"],"RARA"],"06IO028":["Señuelo Tentador","Doy Desafío a un aliado en esta ronda. Si ya está Equipado, roba 1.","","La carnada correcta abre el apetito de cualquier criatura.","Hechizo",["MAESTRO DE ARMAS"],["Jonia","Noxus"],"RARA"],"06IO025":["Fanático de la Daga Sombría","Cuando hayas Equipado un aliado en esta partida, creo 1 Demonio Sombrío en la mano.","","Fue en la oscuridad donde la vio: era un arma que podía cortar las sombras. En ese momento, escuchó una voz que lo llamaba. Aquella voz, distante pero poderosa, lo llevó hasta Kayn; la verdad de sus palabras fueron su guía.","Unidad",["CULTISTA"],["Jonia"],"COMÚN"],"06IO039":["Colalarga de Navori","Al jugar: Invoco 1 Bandolero de Navori o doy +1|+1 a otros aliados en esta ronda.","","Una noche de invierno, el colalarga hizo amistad con su camarada Bandolero, pues ambos compartían los remanentes de un campamento abandonado. Al terminar la semana, descubrieron que ambos tenían inclinación por las travesuras y un fuerte interés en el brillo dorado del dinero.","Unidad",[],["Jonia"],"COMÚN"],"06IO032":["Alma Indigna","Flujo: Cuesto 2 menos.\nLanzo Retirada a una unidad o un hito. Si tiene algo unido, destruyo eso primero.","","''No eres digno del poder que posees''. —Rhaast","Hechizo",[],["Jonia"],"RARA"],"06IO001":["Aprendiz de Doran","Cuando me invocan, creo 1 Preparación en la mano.","","''Obtuve todo el conocimiento que pude para continuar con este arte sagrado. En cuanto a Doran, su maestro y el maestro antes de él… espero que sus espíritus guíen mi martillo''.\n —Discípulo de Doran, pergamino escrito a mano","Unidad",[],["Jonia"],"COMÚN"],"06IO016":["Invocadragones","Inicio de la ronda: Flujo: Invoco El Empíreo y le otorgo Endeble.","","''La forma del agua refleja tus deseos. Dime, errante... ¿qué es lo que ves?''.","Unidad",[],["Jonia"],"ÉPICA"],"06PZ034":["Hexbliterador","Inflijo 6 de daño a una unidad. Si va a morir, en vez de eso, la Aniquilo.","","Para algunas criaturas la muerte no es suficiente.","Hechizo",[],["Piltóver y Zaun"],"RARA"],"06PZ006":["Canción Final","Creo un hechizo nuevo aleatorio de 2 de costo en la mano, reduzco su costo en 2 y le otorgo Fugaz.","","No hay nada más satisfactorio que una buena reverberación.","Hechizo",[],["Piltóver y Zaun"],"RARA"],"06PZ021":["Seraphine","Cuando me invocan, creo un hechizo nuevo aleatorio de 2 de costo en la mano.","Si jugaste 9+ hechizos nuevos.","Seraphine nunca hablaba con su padre acerca de sus viajes ''secretos'' al Distrito Suburbano o de las pequeñas actualizaciones que le hacía a su escenario. Ella estaba segura de que le prohibiría participar en el duelo de música grunge de Zaun, pero una noche él deslizó el volante del evento bajo su puerta. Seraphine no pudo más que sonreír y ponerse manos a la obra.","Unidad",[],["Piltóver y Zaun"],"Campeón"],"06PZ040":["Taberna del Callejón","Cuando me invocan, invoco 1 Tabernero del Callejón.\nTus cartas nuevas cuestan 1 menos.","","Cuando terminó de secar el último vaso, el posadero echó un vistazo al lugar. Muchos extraños se han vuelto amigos entre las paredes del bar y las pintas y marcas de tantísimas noches de desenfreno se pueden ver en cada rincón. El posadero sonrió para sus adentros. No era un lugar perfecto, pero era suyo.","Hito",[],["Piltóver y Zaun"],"ÉPICA"],"06PZ008":["El Arpa Darkin","Puedes gastar 8 de maná para jugarme como Styraatu.","","Mientras los targonianos pensaban dónde esparcirían las armas Darkin, uno de ellos propuso las tierras que más tarde se convertirían en Zaun. Pensaron que lo profundo de los muros y los pasajes cavernosos sería un excelente lugar para enterrarlas. Un lugar lejos del alcance de los humanos. Pero no de los chireanos.","Equipo",["DARKIN"],["Piltóver y Zaun"],"ÉPICA"],"06PZ018":["Nota Alta","Inflijo 2 de daño a una unidad. Si has jugado 6+ hechizos nuevos distintos en esta partida, inflijo 1 a otra unidad.","","Fácil y sencillo.","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"06PZ014":["Presidenta del Club de Fans","Al jugar: Manifiesto un hechizo de 5 de costo y fijo su costo en 2.","","''No importa lo fuerte que suene tu voz, ¡es tu corazón el que hablará por ti!''. —Presidenta del Club de Fans","Unidad",[],["Piltóver y Zaun"],"RARA"],"06PZ030":["Bocetos Inspiradores","Al atacar: Creo un hechizo nuevo de 2 de costo en la mano y le otorgo Fugaz.","","''Válgame, suena a que está lloviendo''.\n''¿Eh? Pero si hace mucho sol allá afuera, papá''.\n''¡Rápido! ¡Hay que resguardar los bocetos! ¡Es una LLUVIA DE IDEAS!''.\n''Ay, papááá''.\n —Seraphine y su padre","Equipo",[],["Piltóver y Zaun"],"RARA"],"06PZ046":["Fórmula","Roba 2. Recargo tu maná de hechizos.","","''La magia no es más que una verdad científica aún por descubrirse''. –Jayce.","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"06PZ007":["Cultista Ambicioso","Cuando hayas Equipado un aliado en esta partida, creo un hechizo nuevo de 2 de costo en la mano y fijo su costo en 0 en esta ronda.","","''Nunca tuve un problema con sacrificarme en pro de la ciencia. No me importó el riesgo a mi persona, y el poder ilimitado que obtuve a través del intercambio fue más que una recompensa para mí''.","Unidad",["CULTISTA"],["Piltóver y Zaun"],"COMÚN"],"06PZ041":["Gatito Astuto","Cuando me invocan, si fui creado, roba 1 y yo recibo +2|+1.","","Cuando no están durmiendo durante el día o vomitando durante la noche, los gatos siempre tienen alguna travesura entre garras.","Unidad",["GATO"],["Piltóver y Zaun"],"COMÚN"],"06PZ036":["La Rockera Zaunita","Al jugar: Inflijo 1 de daño a todos los enemigos. Si jugaste 6+ hechizos nuevos en esta partida, en vez de eso, inflijo 3 de daño.","","''¡Zaun! ¡Espero que estén listos para gritar con todo, porque estamos a punto de hacer volar este lugar!''. —La Rockera Zaunita","Unidad",[],["Piltóver y Zaun"],"RARA"],"06PZ010":["Acusticiero","Al golpear: Creo un hechizo nuevo aleatorio de 2 de costo en la mano.","","Una vez soñó que abandonaba Zaun y viajaba por el mundo con una canción en el corazón. Ahora, el mundo dormía en su habitación, esperando las canciones que podría traer el mañana.","Unidad",[],["Piltóver y Zaun"],"ÉPICA"],"06PZ022":["Solo de Batería","Roba 2.\nFlujo: Reduzco el costo de esas cartas en 1.","","El ritmo es la esencia de la música, pero de vez en cuando es necesario dejarse llevar.","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"06PZ029":["La Sensación","Doy +2|+0 y Ataque Rápido a un aliado en esta ronda.\nFlujo: Creo un hechizo nuevo de 2 de costo en la mano.","","''¡No los escucho, gente de Zaun!''. —Seraphine","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"06PZ020":["Bellota, el Hextécnico","Golpe al Nexo: Reduzco en 1 el costo del hechizo más caro en tu mano.","","No encontrarás su nombre en ninguno de los planos ni en los créditos de ninguna de las canciones, pero aquellos que saben están de acuerdo: Bellota era el centro de toda la operación.","Unidad",[],["Piltóver y Zaun"],"ÉPICA"],"06PZ009":["Riff Cáustico","Flujo: Cuesto 2 menos.\nInflijo 1 de daño a todos los enemigos.","","Se requiere de un sonido especial para sobresaltar entre el traqueteo y estruendo de Zaun, pero la Rockera siempre da lo que promete.","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"06PZ037":["El Desacorde Violento","Inflijo 1 de daño a una unidad. Si Equipaste un aliado en esta partida, me copio con el mismo objetivo.","","Si la discordia es la cacofonía de la destrucción, que así sea.","Hechizo",["CULTISTA"],["Piltóver y Zaun"],"RARA"],"06PZ019":["Cadenero Zaunita","Inicio de la ronda: Flujo: Restablezco 2 de maná de hechizos.","","Si las cosas se hicieran como él quiere, NADIE entraría.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"06PZ033":["Gatalizador v1.0","Tus hechizos y Habilidades infligen 1 de daño adicional.","","''Ubicación: sector 3, vía inferior 19B\nElemento: arma de fuego ilegal\nNotas: Durante la operación se confiscó: Luminia. El arma es altamente peligrosa. Manéjese con extremo cuidado''.\n —Reporte de campo del Alcaide de Piltóver","Equipo",[],["Piltóver y Zaun"],"COMÚN"],"06BW029":["Náufrago Piltoviano","Cuando me invocan, Improviso.","","Pesh conoció a Jax durante una riña portuaria. Si bien huyeron justo a tiempo, su escape fue más por conveniencia que por camaradería. Desde entonces, y tras ver que las cosas alrededor de Jax se rompen, Pesh lo transporta. Y es que si hay algo que Pesh adora más que la chatarra, es algo roto que necesite ser reparado.","Unidad",["MAESTRO DE ARMAS"],["Aguasturbias","Piltóver y Zaun"],"COMÚN"],"06BW034":["Metal Pesado","Destruyo el equipo de una unidad y le inflijo 2 de daño.","","''¡¿A QUIÉN SE LE OCURRE LANZAR UN ANCLA EN UNA PELEA EN EL BAR?! ¡¿ACASO ENLOQUECIERON?!''. —Cantinero de Aguasturbias","Hechizo",[],["Aguasturbias"],"RARA"],"06BW027":["Partes de un Todo","Para usarme, descarta 1. Roba 2 y si descartaste un equipo, invoco 1 Espejismo de Icathia.","","La tripulación de Jax es prueba de que el todo puede ser más que la suma de sus partes. Sin embargo, Pesh tiene una perspectiva diferente: a veces, cada parte es genial por mérito propio.","Hechizo",["MAESTRO DE ARMAS"],["Aguasturbias","Piltóver y Zaun"],"RARA"],"06BW039":["La Ola Interminable","Cuando hayas Equipado a un aliado en esta partida, cuesto 2 menos.\nRoba 2 cartas y les otorgo Fugaz.","","A pesar de que los viejos huesos de Ibaaros se movían con lentitud, las aguas que brotaban frente a él fluían a una velocidad casi incomprensible.","Hechizo",["CULTISTA"],["Aguasturbias"],"RARA"],"06BW026":["Cultista Buhru","Cuando aliados Equipados ataquen, inflijo 1 de daño al nexo enemigo.","","No importaba de dónde venía el poder... su diosa no repararía en ello. Lo que sí importaba era la gloria que recibiría gracias a los monstruos que eliminara.","Unidad",["CULTISTA"],["Aguasturbias"],"COMÚN"],"06BW014":["El Arpón Darkin","Al atacar: Roba 1 carta en el siguiente Inicio de la ronda y le otorgo Fugaz.\nPuedes gastar 9 de maná para jugarme como Ibaaros.","","''Al estrecho de Daray no entran, por ahí no pasan,\nAhí donde las aguas susurran y los vientos delatan,\nAhí donde las bestias marinas y las aves atacan,\nPues bajo el estrecho, el miedo y la oscuridad aguardan''.\n —Rima de Aguasturbias","Equipo",["DARKIN"],["Aguasturbias"],"ÉPICA"],"06BW004":["Prueba del Espíritu","Doy Vulnerable a un enemigo en esta ronda. Si muere en esta ronda, inflijo 1 de daño al nexo enemigo.","","''¿Te levantarás o te acobardarás?'' —Illaoi","Hechizo",[],["Aguasturbias"],"RARA"],"06BW044":["Astuto Pez Tritón","Golpe al Nexo: Roba 1 carta y le otorgo Fugaz.","","''Son unas criaturitas desagradables y embusteras, pero al menos es fácil darse cuenta cuando se roban algo''.","Unidad",["REPTIL"],["Aguasturbias"],"COMÚN"],"06BW047":["Marai Traviesa","Cuando juegas un hechizo, invoco 1 Barril de Pólvora.","","''Bibi es un poco... desquiciada, sí. ¡Pero eso es lo que amamos de ella!'' –Ai'la, Protectora Marai.","Unidad",[],["Aguasturbias"],"RARA"],"06BW023":["Alfanje Dentado","Pillaje: Cuesto 2 menos.","","''Como dice el dicho: 'Nada arregla una trifulca en Aguasturbias más rápido que un alfanje''.\n''Yo diría que una pistola lo haría más rápido''.\n''Cállate, Baz''.\n —Baz y Gav, aspirantes a cazarrecompensas","Equipo",[],["Aguasturbias"],"COMÚN"],"06BW042":["Buque Cargado","Inflijo 2 de daño a una unidad. Roba 1 carta en el siguiente Inicio de la ronda por cada daño infligido y le otorgo Fugaz.","","''No te preocupes, Rex se hará cargo de la explosión… y yo me haré cargo del tesoro. Y también me haré cargo de la parte de Rex porque, de lo contrario, tratará de meterla en el cañón… y eso nunca acaba bien''. —Suboficial","Hechizo",[],["Aguasturbias"],"ÉPICA"],"06BW040":["Ojo Divino","Al atacar: Hago Surgir 2.","","''¡Mantente fuerte bajo su mirada!''. —Illaoi","Equipo",[],["Aguasturbias"],"RARA"],"06SH032":["Armería Sepultada","Cuenta regresiva 2: Creo 1 Tesoro de las Arenas en la mano.","","''¿Por qué tienes que tocar todo?''.\n''¿Crees que tenga alguna trampa? ¿Que una roca gigante saldrá rodando de…?''.\n''¡CORREEE!''.\n —Argus y Silvio, asaltatumbas","Hito",[],["Shurima"],"COMÚN"],"06SH035":["El Altar de Sangre","Cuando Matas a una unidad, reduzco en 1 el costo de la siguiente unidad Darkin que juegues.","","Una vez más, el altar rebozaba vida y hacía temblar las arenas a su alrededor con un ritmo suave y constante. Cada uno de los discípulos de Xolaani sentían el mismo ritmo en lo profundo del corazón. Cada músculo, cada pensamiento, cada momento... todo estaba bajo su control.","Hito",[],["Shurima"],"RARA"],"06SH046":["Relicario del Acólito","Cuando me invocan, creo 1 Acólito Ruinoso en la mano. Cuando me destruyes, creo 1 Relicario del Acólito en las primeras 5 cartas de tu mazo.","","''¡Nuestras manos le dan forma al desierto!''. —Acólito Ruinoso","Hito",[],["Shurima"],"RARA"],"06SH033":["Maldición de la Tumba","Predecir. Doy a una unidad ''Recibo el doble de daño y, si voy a morir, me Aniquilo'' en esta ronda.","","''Solo los necios buscan un poder fuera de su control''. —Xerath","Hechizo",[],["Shurima"],"RARA"],"06SH028":["Puerta del Vacío","Cuando invocas a un aliado o un aliado muere, les otorgo cada una de sus palabras clave positivas a 3 aliados en tu mazo.","","El Heraldo de la Colmena levantó ambas manos en dirección a la estructura colosal de arriba. ''UN TRONO'', gritó. ''PARA UNA EMPERATRIZ''. La Puerta del Vacío palpitó con vida. Pronto.","Hito",[],["Shurima"],"ÉPICA"],"06SH005":["Baccai Abandonado","Al jugar: Lanzo Predecir. Si eliges un Darkin o un equipo, recibo +1|+1.","","En su mano sostenía un cinturón trenzado. Era un regalo que su amigo Rhaast le había dado antes de la ceremonia de Ascensión. Sin embargo, aún cuando reverenciaba el poder Darkin, albergaba un resentimiento oculto en su corazón de bestia.","Unidad",["CULTISTA"],["Shurima"],"COMÚN"],"06SH056":["Castigar","Mato a TODOS los seguidores.","","A veces la luz te atrae a ti y a veces tú atraes la luz.","Hechizo",[],["Shurima"],"RARA"],"06SH040":["Resurrección Temeraria","Cuando hayas Equipado a un aliado en esta partida, cuesto 2 menos y revivo al campeón aliado muerto Más fuerte.","","''Nunca morirás, porque yo nunca te lo permitiré''.\n —Xolaani","Hechizo",["CULTISTA"],["Shurima"],"ÉPICA"],"06SH021":["Horror Camuflado","Al jugar: Golpeo a un enemigo.","","A medida que el ataque continuaba, de la puerta que se abría brotaban criaturas cada vez más feroces. La ciudad de Belveth se había perdido. Sin embargo, cual cruel broma del destino, su nombre perduraría.","Unidad",[],["Shurima"],"RARA"],"06SH051":["Pastora Rocosa","Cuando invocas a otro aliado, Avanzo 1 ronda a tu Hito con la Cuenta regresiva más alta.\nCuando me invocan, invoco 1 Rocoso en Hibernación.","","''Los rocallosos tratan a Sadira como si fuera una de los suyos. Si se lo permitiera, se iría con ellos en un abrir y cerrar de ojos. ¡Pequeña diablilla!''. —Kadira, Naturalista del Desierto","Unidad",[],["Shurima"],"RARA"],"06SH055":["Sacerdotisa de la Luz del Desierto","Inicio de la ronda: Me inflijo 4 de daño. Roba un campeón y le otorgo +2|+2. Si tu mazo comenzó con 6+ campeones diferentes, lo invoco.","","Los fieles se levantan mientras el mal los invade y ofrecen lo que queda de sus fuerzas para canalizar la luz de la justicia. Un llamado desesperado de liberación que saben será respondido antes de que la oscuridad los consuma.","Unidad",[],["Shurima"],"ÉPICA"],"06SH004":["Sangrías de los Darkin","Último Aliento: Si mi portador no es 1 Sirviente Darkin, invoco 1 Sirviente Darkin.\nPuedes gastar 6 de maná y matar a un aliado para jugarme como Xolaani.","","Conforme la pelea arreciaba, Jun, desesperada y gravemente herida, se dirigió a la voz que susurraba en sus pensamientos. ''Nunca morirás'', dijo con la suavidad de una lluvia de verano. ''Porque yo no te lo permitiré''.","Equipo",["DARKIN"],["Shurima"],"ÉPICA"],"06SH038":["Cuchilla Oscilante","Al golpear: Creo 1 Hallazgo Fortuito en la mano.","","''Persigue lo que quieras y no tengas piedad''. —Saquearruinas\n","Equipo",[],["Shurima"],"COMÚN"],"06DE048":["Bloqueo de Ursotejón","","","''Si son amigos, entonces sean bienvenidos aquí; pero ay de quienes se entrometan en este reino con maldad en el corazón, ¡pues probarán la venganza de su poderoso protector!''.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"06DE024":["¡Atrapa!","Doy +1|+1 a un aliado en esta ronda o lo equipo con un equipo en la mano que cueste 2 o menos.","","Este movimiento es más doloroso si la otra parte aún no ha comido.","Hechizo",["MAESTRO DE ARMAS"],["Demacia","El Fréljord"],"RARA"],"06DE025":["Recluta de Buen Corazón","Cuando me invocan, doy Barrera a los aliados Equipados en esta ronda.","","''El chico es un peligro. Me negué fehacientemente a traerlo con nosotros de cacería porque aún se refiere a esa horrible criatura como 'hermana'. Es una inocencia tan ciega que francamente me da asco. Aunque supongo que también me produce lástima. Por lo menos esto será una lección importante para él''. —Extracto del diario de Sirius Rowill, el Paladín Ferviente","Unidad",[],["Demacia"],"RARA"],"06DE033":["Silenciar y Suprimir","Destruyo el equipo de una unidad y, si es un seguidor, lo Silencio.","","''Tú te lo buscaste''. —Lord Eldred, Líder Cazamagos","Hechizo",[],["Demacia"],"RARA"],"06DE039":["Rugido de Icathia","Invoco 2 Espejismos de Icathia Equipados con hasta 2 Equipos en la mano que cuesten 2 o menos.","","Jax ha tenido incontables sueños donde lucha junto a su gente perdida. Unas batallas las ganan y otras, las pierden... pero siempre están juntos.","Hechizo",["MAESTRO DE ARMAS"],["Demacia"],"RARA"],"06DE011":["La Égida Darkin","Puedes gastar 5 de maná para jugarme como Joraal.","","''Hijo mío, escucha mis palabras. Ese escudo debe permanecer intacto. Hace muchos años, mi casa lo recibió como regalo con la condición de que lo mantuviéramos bajo resguardo. Es mi responsabilidad y, cuando yo muera, será la tuya. ¿Me estás escuchando? No vuelvas a intentar alcanzarlo. No debes tocarlo jamás''.\n''Pero, mami, la voz que emana de su interior... me implora llorando. Suena tan triste''.\n''Con mayor razón, hijo mío''.\n —Lady Fortis y su hijo","Equipo",["DARKIN"],["Demacia"],"ÉPICA"],"06DE021":["Vayne","Cuando me invocan o al Inicio de la ronda: Creo 1 Voltereta en la mano o, si ya tienes una, reduzco en 1 su costo.","Si te he visto atacar 4 veces.","''Antaño, nuestro objetivo era humano, lo que significa que es más inteligente que las bestias comunes. Un paso en falso podría significar la muerte para todos nosotros. No se alejen, avisen de cualquier cosa sospechosa. Pero lo más importante es que recuerden...''.","Unidad",[],["Demacia"],"Campeón"],"06DE043":["Canicornia Confiable","Recibo +2|+2 la primera vez que invoques una carta Élite.","","''No es tan rápida como un aliplata, pero te sorprendería ver lo rápido que la llevan sus patitas''. —Cithria, Dama de las Nubes","Unidad",["PERRO"],["Demacia"],"COMÚN"],"06DE018":["Condena","Cuesto 5 menos si atacaste 2+ veces en esta ronda.\nUn aliado golpea a un enemigo.","","''Proyectiles purificadores''. —Vayne","Hechizo",[],["Demacia"],"COMÚN"],"06DE041":["Fuerza de Campeones","Doy Preparar y +4|+4 a los aliados en esta ronda.","","''¡A la batalla con el corazón radiante!''. —Lux","Hechizo",[],["Demacia"],"ÉPICA"],"06DE026":["Mitos de Icathia","Creo 1 Espejismo de Icathia en la mano que cuesta 0 en esta ronda, o creo 1 Espátula Dorada en la mano.","","Las leyendas cuentan que el portador original de la Espátula Dorada era una criatura marina que poseía una habilidad culinaria sobresaliente, una criatura que buscaba convertirse en una guerrera igual de fuerte y temeraria que Jax.\n\nOtras leyendas más veraces cuentan que esa leyenda en particular la inventó un cierto chef quien habría añadido DEMASIADO licor a una de sus recetas.","Hechizo",[],["Demacia"],"RARA"],"06DE044":["Cargador de Petricita","No recibo daño de hechizos ni Habilidades de enemigos.","","''Nada es más fuerte que la petricita''. —Arquitecto de Durand","Unidad",[],["Demacia"],"RARA"],"06DE017":["Guerra de Pescados","Un aliado y un enemigo se Golpean entre sí, o un aliado Equipado Golpea a un enemigo y luego se desequipa.","","''¡Pescado, te presento a cara!''. —Maestra Pescadora Jonia","Hechizo",["MAESTRO DE ARMAS"],["Demacia"],"COMÚN"],"06DE040":["Prospecto Tentador","Elige un seguidor o equipo de las primeras 4 cartas de tu mazo. Róbalo y coloca el resto en tu mazo.","","Susurros suaves y tentadores plantan deseo en lo profundo del corazón. Como una espina clavada, este sentimiento se infecta y da paso a la ambición, a la injusticia y a la muerte. Y así, el ciclo continúa.","Hechizo",["CULTISTA"],["Demacia"],"COMÚN"],"06DE028":["Arpía Sangre Maldita","Al jugar: Me Equipo con un equipo de la mano que cueste 2 o menos.\nLa primera vez que vaya a morir al estar Equipada, me curo por completo y destruyo el equipo.","","''Kian, si estás leyendo esto... espero ya estar muerta. Me es imposible controlar lo que me pasa. La sangre bajo mis uñas ya no se quita y tengo muchísima comezón. Me rasco una y otra vez, pero nada funciona. Me duele. Solo quiero que el dolor se detenga. Si de alguna forma sigo viva, prométeme que dejarás de buscarme.\n\nPodría suplicar perdón, pero no lo merezco. Pórtate bien con mamá, ¿sí?''.\n —Carta arrugada encontrada dentro de un morral roto","Unidad",[],["Demacia"],"ÉPICA"],"06DE027":["Paladín Ferviente","Al atacar: Doy +1|+1 a los aliados Equipados en esta ronda.","","''Eres Janan, ¿verdad? ¿Qué puedes decirme acerca de Sirius?''\n''Ah, ¿del Paladín Rowill? Hace unos años le revocaron su título. Al parecer, ignoró de forma consciente todas las órdenes que se le daban. Parece ser que hace lo que se le da la gana y no acepta un 'no' como respuesta''.\n''Ah''.\n''Y... ¿por qué le permitiste que se uniera a la cacería?''.\n''Yo no se lo permití''.\n''Entonces, ¿quién...? Ah, entiendo. Genial''.\n —Vayne y Janan, Cazadora Viuda","Unidad",[],["Demacia"],"RARA"],"06DE019":["Viuda Cazadora","Al jugar: Me Equipo con un equipo de la mano que cueste 2 o menos.","","''A pesar de que la mujer tiene aspecto de ser una luchadora bastante competente, su pesar es demasiado reciente y pone en riesgo su estabilidad. La desolación es una motivación muy convincente, yo lo sé muy bien, pero ¿tan desenfrenada? Tal vez lo que quiere es morir...''. —Extracto del diario de Sirius Rowill, el Paladín Ferviente","Unidad",[],["Demacia"],"COMÚN"],"06DE032":["Acero Demaciano","","","Son la espada y escudo de elección estándar para los hermanos en armas con casco de Demacia.","Equipo",[],["Demacia"],"COMÚN"],"06DE029":["Elkin Resoluto","La primera vez que un aliado sea equipado, recibo Dureza.","","''¡Atrás, criatura maldita! Si dañas una sola hebra del manto inmaculado de Pureza, ¡yo mismo me encargaré de que sufras UNA ETERNIDAD DE AGONÍA!''. —Sirius Rowill, el Paladín Ferviente","Unidad",[],["Demacia"],"COMÚN"],"06DE010":["Paladina Desertora","Cuando hayas Equipado un aliado en esta partida, recibo Explorar.","","La supresión de sus habilidades mágicas durante años hizo que brotara en ella un sentimiento de autodesprecio que luego volcó sobre sus víctimas. Tras desertar de los paladines guardianes, su furia quedó a la deriva hasta que una voz la llamó desde la oscuridad y le habló sobre un nuevo orden en el que podría dar rienda suelta a su crueldad.","Unidad",["CULTISTA"],["Demacia"],"RARA"],"06DE006":["Chef de Combate","Cuando me invocan, Improviso, después Fórjame.","","Tras su servicio en el ejército demaciano, Breshi pensó en jubilarse y cocinar en la taberna de alguna aldea tranquila. Sin embargo, Jax arruinó sus planes tras comenzar una riña en la taberna y externar una opinión negativa sobre los huevos hervidos del lugar. Desde entonces, Breshi solo se dedica a una cosa: enseñarle buen gusto a Jax.","Unidad",["MAESTRO DE ARMAS"],["Demacia","El Fréljord"],"COMÚN"],"06DE034":["Caniloba Fiel","Si un aliado murió en esta ronda, cuesto 2 menos.\nAl jugar: Me Equipo con un equipo que cueste 2 o menos desde la mano y me Forjo.","","''Tengo a Maggie desde que era una cachorra. Ya es un poco anciana, pero sigue siendo tan letal como una cuchilla recién afilada. Daría mi vida por ella y yo sé que ella daría la suya por mí''. —Janan, Viuda Cazadora","Unidad",["PERRO"],["Demacia"],"COMÚN"],"06SI045":["Corte Álmico","Mato a un aliado para invocar 2 copias Endebles de sí mismo.","","De todas formas no lo estaban usando.","Hechizo",[],["Islas de la Sombra"],"RARA"],"06SI007":["Alabarda de los Darkin","Para jugarme, mata a un aliado.\nPuedes gastar 10 de maná para jugarme como Taarosh.","","Recargado contra los confines de su celda, Taarosh oyó el llamado de su general. Su plan era responder de una u otra forma.","Equipo",["DARKIN"],["Islas de la Sombra"],"ÉPICA"],"06SI034":["Espectro de los Ecos","Fin de la ronda: Por cada aliado que haya muerto en esta ronda, otorgo +1|+1 a todas las copias de aliados en todas partes.","","''No sé bien qué tipo de magia maligna utilizan y NO QUIERO SABERLO. Lo único que necesito saber es que, si se levantan, todos morirán. Una vez más''. —Vigilante de las Islas","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"06SI029":["Lanza Maléfica","Si un aliado murió en esta ronda, cuesto 2 menos.","","''No hay justicia, solo venganza''. —Kalista","Equipo",[],["Islas de la Sombra"],"COMÚN"],"06SI032":["Quietus","Mato a una unidad con un total de 4 o menos de poder y vida, o destruyo el equipo de una unidad.","","Como sea que la muerte se manifieste en las Islas de la Sombra, que sea bendita y rápida.","Hechizo",[],["Islas de la Sombra"],"RARA"],"06SI031":["Armas de los Caídos","Doy a un aliado ''Último Aliento: Invoco 1 Espejismo de Icathia con mi equipo'' en esta ronda.","","A veces, lo mejor que puedes hacer por un aliado caído es tomar sus armas y seguir peleando.","Hechizo",["MAESTRO DE ARMAS"],["Islas de la Sombra","Shurima"],"RARA"],"06SI014":["Vestíbulo Opulento","Cuando me invocan, invoco 1 Banda Espectral.\nInicio de la ronda: Si tienes la ficha de ataque, invoco 1 Banda Espectral.","","''Los jugadores están listos; el escenario, preparado. El público espera. Maestro, ¡adelante, por favor!''. —Anfitrión Enérgico","Hito",[],["Islas de la Sombra"],"ÉPICA"],"06SI038":["Prodigio Redimido","Al atacar: Invoco 1 Banda Espectral atacante.","","Aspirar a la perfección era una meta extenuante y llena de limitaciones. La perfección no admitía una vida propia ni momentos de relajo. Sin embargo, la imperfección perfecta... eso sí era algo a lo que valía la pena aspirar.","Unidad",[],["Islas de la Sombra"],"RARA"],"06SI003":["Fireth, Segadora de las Arenas","Cuando me invocan, Improviso.","","Jax le preguntó su nombre a Fireth como dos docenas de veces durante las primeras semanas de su viaje. Pero todo lo que ella decía era: ''¡Yo soy la Segadora!''. Entonces, a Breshi se le ocurrió algo: iba a preparar una tarta, pero iba a necesitar el nombre del miembro más fuerte del grupo para celebrar como se debe.","Unidad",["MAESTRO DE ARMAS"],["Islas de la Sombra","Shurima"],"ÉPICA"],"06SI006":["Guardiana de la Caja","Cuando hayas equipado un aliado en esta partida, recibo Robo de Vida.","","''La Caja no revela sus secretos de forma gratuita, Shieda Kayn, sino que demanda un lúgubre precio. Si tienes el valor de mirar la sombra de sombras, atestiguarás las maravillosas pero terribles cosas que yacen en su interior''. —Ysdra, Guardiana de la Caja","Unidad",["CULTISTA"],["Islas de la Sombra"],"COMÚN"],"06SI039":["La Forma del Miedo","Mato a un aliado para invocar 1 Niebla Invasiva.","","Solo un tonto miraría a la Niebla Negra con la esperanza de encontrar una forma conocida.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"06SI042":["Caballero Inmortal","Cuando vaya a obtener Endeble, recibo +1|+1 en su lugar.","","Los soldados que habían sido entrenados para resistir el castigo en vida eran más diligentes y competentes en la muerte, impertérritos ante el frío, el dolor o el miedo.","Unidad",[],["Islas de la Sombra"],"RARA"],"06SI036":["Devastación Absoluta","Mato a TODAS las unidades excepto a los aliados Darkin y Equipados.","","Mientras tomaba las armas, su humanidad la abandonó y, en su lugar, una esencia de odio colmó el cascarón vacío que había sido la estudiante Jun. Esta esencia bañó cada ángulo de su cuerpo y sus alrededores, lo cual agitó al aletargado Darkin.","Hechizo",["CULTISTA"],["Islas de la Sombra"],"RARA"],"06SI046":["Vigía Incesante","Último Aliento: Roba 1.",""," ''... y así permaneceré alerta, hasta la eternidad, porque mi deber está más allá de la vida y más allá de la muerte''.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"06SI041":["Guardián del Plenilunio","Cuando invocas a un aliado con Endeble, le otorgo +1|+0.\nAnochecer: Invoco 1 Retoño.","","Lejos de las costas de las Islas de la Sombra, se encuentran, torcidos e inmóviles, cadáveres de árboles que parecen muertos hace mucho tiempo. Solo los ávidos observadores notarán que una vida nueva crece en la tierra bañada de luz de luna.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"07PZ009":["Relojito Aumentado","Al jugar: Lanzo Predecir. Luego, roba 1 carta y reduzco su costo en 1.","","''Todo lo que este pequeñuelo necesitaba era un poco de afinamiento. Aparejos nuevos por aquí, un nuevo brazo por allá, y listo… ya tiene un nuevo propósito en la vida. El tiempo es un regalo que todo el mundo debería tener de más, creo yo''. –Ekko","Unidad",[],["Piltóver y Zaun"],"ÉPICA"],"07PZ017":["Vendedor de Bombas Aturdidoras","Cuando juegas un hechizo, planto 1 Trampa Aturdidora entre las 8 cartas de arriba del mazo enemigo.","","''¿Sabes qué otra cosa hace a estas preciosidades mejores que los hongos? ¡Que tu eliges cuándo explotan! Eso SÍ que les da valor, ¿a que no?''.","Unidad",[],["Piltóver y Zaun"],"RARA"],"07PZ005":["Tiro por la Culata","Inflijo 1 de daño a un enemigo y al nexo enemigo. Descarto hasta 2 para aumentar el daño en 1 por cada carta descartada.",""," ''Bueno, bueno. Puede que esto solo funcione una vez, pero créeme... ¡será un BUM!''. —Jinx","Hechizo",[],["Piltóver y Zaun"],"RARA"],"07NX009":["Tiro con Estilo","Inflijo 1 de daño al nexo enemigo. La próxima vez que un aliado Golpee al nexo en esta ronda, creo 1 Tiro con Estilo en la mano.","","''Nadie podría seguirme el ritmo, ni aunque solo usara palos y piedras como armas. ¿Y con mi conjunto? Mejor ni lo intenten''. –Samira","Hechizo",[],["Noxus"],"ÉPICA"],"07NX008":["Filo Elegante","Pillaje: Recibo +2|+0.","","''Mi precio es alto y no trabajo para cualquiera. Si tienes la suerte de contratarme, no solo tendrás a alguien con gracia y entereza, sino a alguien cuya espada jamás falla en su objetivo. Pero lo más importante es que tendrás a alguien con estilo, pues ¿a quién no le gustan los asesinatos con broche de oro?''.","Unidad",[],["Noxus"],"COMÚN"],"07NX014":["Pirueta","Pillaje: Cuesto 2 menos.\nInflijo 1 de daño a lo que sea y lanzo Aturdir a un enemigo.","","''¿Qué? Solo estaba calentando. No me digas que ya te moriste''. - Filo Elegante","Hechizo",[],["Noxus"],"RARA"],"07NX007":["Samira","Pillaje o Golpear: Creo un Instinto en la mano si no tienes uno.","Si te he visto jugar 6 cartas. Se restablece cuando inicias una ronda con la ficha de ataque.","''Siempre estoy tras algún objetivo que pidió más de lo que podía pagar. Huir de esas deudas hace que te ganes al peor tipo de enemigo: el que me llama''.","Unidad",[],["Noxus"],"Campeón"],"07NX006":["Dandy Galante","Pillaje: Duplico mi poder.",""," ''Mira, por lo general me gusta poner algunas reglas, como... 'mantén tus pezuñas lejos de mi cabello y mi cara'. Pero ¿a quién quiero engañar? Ni siquiera me pondrás un dedo encima''.","Unidad",[],["Noxus"],"COMÚN"],"07NX015":["Dame, la Saqueadora","Pillaje: Otorgo +1|+0 a los aliados","","''Ah, a Dame le gusta el melodrama. Algunas rechazarían tal nivel de vanidad, pero cuando está en su apogeo, todos recibimos nuestra paga''. –Filo Elegante","Unidad",[],["Noxus"],"COMÚN"],"07NX003":["A Toda Potencia","Doy +2|+0 a un aliado en esta ronda.\nPillaje: Le doy +2|+1.",""," ''Indari movió algunos hilos para que pudiéramos entrar sin hacer alboroto. Aunque, ojalá podamos mover un poco el avispero al salir''. –Samira","Hechizo",[],["Noxus"],"COMÚN"],"07NX004":["Artífice Diestra","Cuando me invocan, activo todos los efectos de Pillaje de los aliados.","","''Montar un negocio puede ser complicado en algunos lugares, pero bastó una mirada a mi mercancía y a la de Lani para que el dinero comenzara a llover. No vi a mi objetivo entre los que se acercaban a mirar, pero hay otros muy violentos esta noche. Después de todo, descubrir quién quiere matar a quién es una manera decente de adaptarte al terreno''. –Miel","Unidad",[],["Noxus"],"RARA"],"07NX001":["Demoledora Audaz","Al jugar: Inflijo 1 de daño al nexo enemigo o activo el efecto Pillaje de un aliado.","","''La información es un elemento vital si te dedicas al negocio de las armas. Conceptualizar, probar, reestructurar, modificar: cada uno de esos procesos requiere información. Y no hay nada mejor que una prueba de campo para recabar una muestra aceptable… ¡y para hacer un par de cráteres!''. –Lani","Unidad",[],["Noxus"],"RARA"],"07NX005":["Capitana Indari","Cuando me invocan, Improviso.\nPillaje: Forjo a otros aliados.","","''He trabajado con muchos operativos en el pasado. Algunos eran fáciles, otros eran todo un reto... y luego está Samira. Acepté el hecho de que no podía dominarla; en vez de eso, soy yo quien dirige el caos, aspiro a él y, en ocasiones, me uno también''.","Unidad",["MAESTRO DE ARMAS"],["Noxus"],"RARA"],"07BW018":["Babs la Senil","Cuando recargas tu maná, recibo +1|+0 por cada maná recargado.","","''¡Mira aquí, pequeño Jack! Esto te interesa, ¿a que sí?''.","Unidad",[],["Aguasturbias"],"COMÚN"],"07BW021":[" Bucanera Insolente","Pillaje: Invoco un seguidor aleatorio de 1 de costo y le otorgo Imprudente.","","''Si fuera tú, la evitaría. Tiene el mal hábito de envolver a los demás en sus propios problemas''. —Samira","Unidad",[],["Aguasturbias"],"COMÚN"],"07BW002":["Jack","Al golpear: Creo 1 Moneda en la mano.\nCuando recargas tu maná, me curo 1 por cada maná recargado.","Si gastaste 12+ de maná en una ronda.","''Debes ser o muy valiente o muy ignorante para querer enfrentarte a mí. En cualquier caso, el resultado será el mismo. Te daré un consejo: preocúpate por salir con vida''.","Unidad",[],["Aguasturbias"],"Campeón"],"07BW040":["Nukkle","Cuando me invocan, creo 1 Mako Fugaz en la mano.","","''Un cortecito por acá, una rebanadita por allá... siempre para divertirse. Un poco de sangre en el agua no lastima a nadie. Bueno, al menos no a mí''. –Nukkle","Unidad",[],["Aguasturbias"],"RARA"],"07BW001":["Promotor Pérfido","Cuando recargas tu maná, creo 1 seguidor aleatorio con Fugaz en la mano que puedas costear exactamente.","","''Si estás buscando al carmesí, entonces necesitas a Jack. ¿Quieres saber dónde, cuándo, quién y cuánto? Entonces, avísame''.","Unidad",[],["Aguasturbias"],"RARA"],"07BW003":["Carterista","Último Aliento: Creo 1 Moneda en la mano.","","''¡Oye, vuelve aquí, bola de mocos! ¡Ese dinero era de mis papas!''. –Ángel","Unidad",[],["Aguasturbias"],"COMÚN"],"07BW014":["Pablo Cinco Puños","Cuando me invocan, creo 1 Combate de Boxeo Fugaz en la mano.","","''¡Así se hace, Jackie! Sigue con ese encanto de Aguasturbias y yo seguiré entrenándote. Ah, esto me recuerda a mis días de gloria. En ese entonces, me decían 'Pablo el Guapetón'… ¿Cómo que no me decían así? ¡Claro que sí! Me parece que ese golpe te afectó la memoria''. –Pablo Cinco Puños","Unidad",[],["Aguasturbias"],"COMÚN"],"07BW013":["Ángel","Pillaje: Creo 3 Monedas en la mano.","","''¿Eso es lo mejor que tienes? Qué adorable. Ahora es mi turno''.","Unidad",[],["Aguasturbias"],"COMÚN"],"07BW006":["Negocios Riesgosos","Inflijo 3 de daño a una unidad. Si muere, creo 2 Monedas en la mano.","","''Quien no arriesga, no gana… y estas quijadas están hechas para encarar riesgos''. —Jack","Hechizo",[],["Aguasturbias"],"ÉPICA"],"07BW026":["Cadena con Púas","Pillaje: Cuesto 2 menos.\nRoba 2 cartas en el siguiente Inicio de la ronda y les otorgo Fugaz.","","Para cuando escuches el ruido de cadenas… ya será muy tarde para huir.","Hechizo",[],["Aguasturbias"],"RARA"],"07BW027":["Padre Furia","Pillaje: Restablezco 1 de maná de hechizos y creo un hechizo aleatorio de 1 de costo de una de tus regiones en la mano.","","Los orígenes del Padre Furia son tan densos como un nubarrón. Ni siquiera los que indagan sobre ellos obtienen una respuesta clara... Al menos, no una que puedan oír por encima del estruendo de su destrucción.","Unidad",[],["Aguasturbias"],"RARA"],"07BW008":["Combate de Boxeo","Un aliado y un enemigo se Golpean entre sí. Dicho Golpe no puede reducir su vida a menos de 1.","","Algunas veces comercias con monedas y aceite para lámparas; otras veces, con dientes y nudillos. Así son las cosas, pero ¿un intercambio justo? ¡Eso se tiene que aprovechar!","Hechizo",[],["Aguasturbias"],"COMÚN"],"07BW041":["Puños Percebescos","Al golpear: Creo 1 Moneda en la mano.","","''Mmm... sé que no es el equipamiento más convencional del mundo, no te lo voy a negar. Pero te recomiendo que lo pruebes, te va a gustar''. –Toro","Equipo",[],["Aguasturbias"],"RARA"],"07BW004":["La Corte del Rey","Cuando me invocan, roba 1 Jack.\nCuando invocas a un aliado, creo 1 Combate de Boxeo con Fugaz en la mano.\nCuando un aliado sobrevive al daño, le otorgo Imprudente.","","Jack y su gente se valen de su embarcación personal para recorrer las aguas de Runaterra, desde Aguasturbias hasta Jonia. Nadie sabe cómo pueden viajar bajo el agua sin hundirse, pero dicen que es bajo la superficie donde yace el verdadero peligro…","Unidad",[],["Aguasturbias"],"ÉPICA"],"07BW025":["Inferna","Cuando actives Pillaje, roba 1 carta y le otorgo Fugaz.","","''Dedicarse a la piromanía en el mar tiene sus ventajas: el agua no permite que las llamas se salgan de control… y tampoco te pide que compartas el botín''.","Unidad",[],["Aguasturbias"],"RARA"],"07IO020":["¡Estás Fuera!","Lanzo Retirada a un aliado y creo 1 Moneda en la mano, o gasto 5 de maná para lanzar Retirada a un enemigo y creo 1 Moneda en la mano.","","''Solo intervendré bajo dos condiciones. Uno, si tu oponente lo está pasando demasiado bien dándote una paliza. O dos, ¡si tú la estás pasando demasiado bien y también me dan ganas de divertirme!''. –Profesional de la Arena","Hechizo",[],["Jonia"],"RARA"],"07IO014":["Maestro Bingwen, el Reclutador","Al jugar: La próxima vez que uses una unidad en esta ronda, invoco una copia exacta suya con Endeble.","","Bingwen el Pájaro es un exluchador que se ganó dicho apodo gracias a su agilidad y a su postura de grulla. Tras su retiro, se convirtió en entrenador y usó su carácter rígido y su aguda intuición para separar al verdadero talento de la mediocridad.","Unidad",[],["Jonia"],"ÉPICA"],"07IO023":["El Veterano","Al jugar: Lanzo Retirada al enemigo Más fuerte. En cambio, si gastaste 16+ de maná en esta ronda, lanzo Retirada a todos los enemigos.","","''La máscara se queda donde está, niña. Y a menos de que quieras terminar pareciéndote a esta cosa, no vuelvas a pedirlo''.","Unidad",[],["Jonia"],"RARA"],"07IO011":["Sett","Recibo Barrera la primera vez que mi vida vaya a reducirse a menos de 1 al atacar.","Si gastaste 40+ de maná.","Mientras se deleita con el rugir de la multitud agolpada en su exclusiva arena clandestina, Sett se permite un raro momento de introspección. Recuerda las razones por las que luchó y reflexiona sobre las experiencias que aún podrían llegar a su vida. Sin embargo, hay algo que sabe con certeza: ser el Jefe es maravilloso.","Unidad",[],["Jonia"],"Campeón"],"07IO046":["Alabrillo Real","Otros aliados ave tienen +1|+0 y Ataque Rápido.","","''En estas junglas, descubrí que los especímenes más bellos son a la vez los depredadores más letales''. —Anura","Unidad",["AVE"],["Jonia"],"RARA"],"07IO009":["Contadora Proactiva","Golpe al Nexo: Creo 1 Moneda en tu mano.","","En medio de pescadores ambiciosos y conspiradores egoístas, Lise cuenta con la cualidad que Sett aprecia por sobre todas las demás: confiabilidad. Nunca está distraída, siempre explica las cosas con propiedad y nunca deja a Sett con dudas. Esa actitud le permitió ganarse el apoyo del Jefe y sirvió como una advertencia para cualquiera que vaya buscando problemas: si apuestas contra la Casa, perderás.","Unidad",[],["Jonia"],"RARA"],"07IO019":["Cantinera Agradable","Al jugar: Curo 3 a un aliado o a tu nexo y creo 1 Moneda en la mano.","","''La primera ronda es para presentarse. La segunda para amenizar el ambiente. En la tercera, comienzan a surgir los problemas. Ya es en la cuarta cuando la gente comienza a irse de boca... ¡no creerías las cosas de las que me entero!''.","Unidad",[],["Jonia"],"COMÚN"],"07IO017":["Hagan sus Apuestas","Roba 2 y creo 2 Monedas en la mano.",""," ''Ellos nos dan dinero y nosotros les damos una oportunidad. ¡Ja!... y algunos todavía se preguntan por qué la Casa siempre gana''.","Hechizo",[],["Jonia"],"COMÚN"],"07IO047":["Cobra Encantadora","En cada ronda, la primera vez que juegues otro seguidor, invoco una copia exacta suya. Si tu tablero está lleno, yo recibo sus estadísticas y palabras clave.","","''¿Crees que estas flores tienen algún valor? Dirás que perdí la razón, pero ¿no parece como si estuvieran... bailando?''. —Saqueador Piltoviano","Unidad",["REPTIL"],["Jonia"],"ÉPICA"],"07IO013":["Profesional de la Arena","Cuando me invocan, creo 1 Moneda en la mano.","","''Algunas personas lo hacen por el dinero; otras, por la sangre; y algunas más, solo para oír los vítores del público. ¿Por qué lo hago yo? No podría elegir solo una razón, las necesito todas… y aquí lo tengo todo y más''.","Unidad",[],["Jonia"],"COMÚN"],"07IO012":["Supervisor de Seguridad","Cuando me invocan, creo 1 Supervisor de Seguridad con Fugaz en la mano y le otorgo +1|+1 a otros Supervisor de Seguridad. Potenciación a 5: Ataque Rápido.","","''Si quieren creer que eres tonto, no los contradigas. Deja que las manzanas podridas crean que están a salvo para dar rienda suelta a sus jueguitos. No hay nada mejor en la vida que verlas a los ojos cuando se dan cuenta de que te subestimaron''. –Sett","Unidad",[],["Jonia"],"RARA"],"07IO007":["Ahora Bésense","Lanzo Aturdir a 2 enemigos y creo 1 Moneda en la mano.","","''¿Qué? Él dijo que soportaría el golpe... ¡nunca especificó de quién!''. –Sett","Hechizo",[],["Jonia"],"COMÚN"],"07SH023":["General de las Arenas Desmoronadas","Recibo +1|+0 por cada aliado con Endeble que hayas invocado en esta partida.","","''Aunque no seas más que granos de arena para este enemigo, yo te veo. Siento tu presencia en las dunas. ¡Concédeme tu fuerza y codo a codo acabaremos con nuestros enemigos!''.","Unidad",[],["Shurima"],"RARA"],"07SH018":["Guardasecretos","Cuando me invocan, creo en el fondo de tu mazo dos campeones aleatorios de nivel 2 que no estén en tu mano, mazo o juego.","","No sabía del todo lo que había visto, la forma que la calamidad podía adoptar ni cuándo podría aparecer, pero conoce este mundo y a sus habitantes. No están listos y puede que nunca lo estén.","Unidad",[],["Shurima"],"ÉPICA"],"07SH008":["Ataque en manada","Inicia un ataque gratis con una copia exacta con Endeble de cada aliado gato.","","Una cazadora solitaria ya es suficientemente temible... pero una manada entera es realmente feroz.","Hechizo",[],["Shurima"],"COMÚN"],"07FR008":["Cría Mantogélido","Gasta 6 de Maná para jugarme como Matriarca Mantogélido.","","Hay muchos peligros en el Fréljord, especialmente para quienes desconocen sus gélidas verdades.","Unidad",["PERRO"],["El Fréljord"],"COMÚN"],"07FR009":["Herrera Ingeniosa","Cuando me invocan, Improviso.\nLa primera vez que Forjes o Equipes a un aliado en cada ronda, curo 1 a tu nexo.","","''Quizá la pequeña bola peluda no me ayuda a trabajar más rápido, pero sí que me hace sonreír. Eso ya es ayuda suficiente''. —Herrero Innovador","Unidad",["MAESTRO DE ARMAS"],["El Fréljord"],"RARA"],"07FR005":["Baluarte de Siervos","No recibo daño de hechizos ni Habilidades de aliados.","","''Una vez que se desata la avalancha, nada puede detenerla''. –Lissandra","Unidad",[],["El Fréljord"],"RARA"],"07SI002":["Cosecha de Almas","Mato a un seguidor con 3 o menos de Poder, o gasto 3 de Maná para matar a un campeón con 3 o menos de Poder.","","No es más que un suspiro en el viento que se puede sentir pero apenas oír; que intercambia una vida por otra.","Hechizo",[],["Islas de la Sombra"],"RARA"],"07SI001":["Erradicación","Mato a TODAS las unidades con 3 o menos de Poder.","","Quienquiera que me vea, conocerá el toque de la aniquilación… y jamás se liberarán de él.","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"07SI007":["Mascota Sepulcral","La primera vez que muera otro aliado en cada ronda, roba 1.","","''¡Le enseñé un nuevo truco! ¿Quieres verlo?''. —Espectro Bromista","Unidad",["PERRO"],["Islas de la Sombra"],"COMÚN"],"07MT003":["Cría del Cosmos","Inicio de la ronda: Nos curo 1 a mí y a tu nexo.","","Recorren el firmamento como lágrimas de una aurora. Sus miradas radiantes reconfortan el corazón, alivian las heridas y reparan lo que está roto.","Unidad",[],["Targón"],"RARA"],"07MT001":["Estrella Fugaz","Inflijo 4 de daño a un enemigo que haya atacado en esta ronda o que esté Aturdido.","","Las estrellas vigilan nuestros actos, ya sean buenos o malos. La gente bondadosa es recompensada, mientras que las personas malvadas son juzgadas.","Hechizo",[],["Targón"],"COMÚN"],"07MT007":["Erudito Inmolado","Último Aliento: Creo en la mano copias de los primeros 3 hechizos que hayas usado sobre mí.","","''Camphor se ha llevado muchas cosas de muchas personas. Cuando sea tu hora de morir, asegúrate de que sea en tus propios términos. No le des la satisfacción''. —Pantheon","Unidad",[],["Targón"],"ÉPICA"],"07BC005":["Blandefilos Tallada","","","''Vaya, eso es nuevo''. –Blandefilos Feérica","Unidad",["FEÉRICO"],["Ciudad de Bandle"],"COMÚN"],"07BC009":["Pastelazo","Inflijo 1 de daño a una unidad. Creo 1 Pastel Peligroso en la mano.","","Prepárate.","Hechizo",[],["Ciudad de Bandle"],"RARA"],"07BC015":["Condensar","Elige un seguidor y creo una copia de 1 de costo suya en la mano y fijo sus estadísticas en +1|+1.","","''Mmm... supongo que ser más pequeña no siempre te hace más linda''. —Lulu","Hechizo",[],["Ciudad de Bandle"],"RARA"],"07DE002":["Orden de Cateo","Un aliado con 4+ de Poder Captura a una unidad o un aliado Captura un Hito.","","''No te muevas ni hagas ruido. Resistirte sería un desacierto''. —Inspectora Cazamagos","Hechizo",[],["Demacia"],"RARA"],"07DE005":["¡Formación!","Doy +2|+2 a un aliado en esta ronda.","","''¡Resistan! ¡Fueron heridos, pero no derrotados!''. –Vanguardia Valerosa","Hechizo",[],["Demacia"],"COMÚN"],"07DE008":["Altar de la Unidad","Cuando me invocan, roba una unidad.\nCuando invocas a un aliado, hago que sus estadísticas sean iguales a su costo.","","La primera vez que vio el Altar, Cithria se quedó sin palabras. Por un rato, no pudo más que sentir asombro por la majestad de aquellos héroes honorables. ¿Alguna vez sería lo suficientemente audaz como para estar a su lado?","Hito",[],["Demacia"],"RARA"],"07PZ019":["Orugamóvil Quimtech","Tengo +1|+0 por cada aliado de 1 de costo que hayas invocado en esta partida.","","''Tengo que dibujarle MUCHA' pata' al caballo, don Lagarto, poque tenemo' que llegar al ca'tillo RÁPIDO. Oh, oh... Quedó un poco... estraño. Y un poco velde''. —Ingvar la Joven","Unidad",[],["Piltóver y Zaun"],"RARA"],"07PZ021":["Anura y Froop","Los aliados que tengan un subtipo diferente al de otros aliados en juego cuestan 1 menos.","","''¡No te lastimaré, amigo! Vine a esta jungla por la ciencia, no a destruirla''.","Unidad",["REPTIL"],["Piltóver y Zaun"],"ÉPICA"],"07PZ022":["Corriente Divina","Inflijo 1 de daño a un enemigo o al nexo enemigo y 1 de daño a otro.","","A la mayoría de piltovianos les da lo mismo el flujo del viento. Para muchos zaunitas, hasta la más suave brisa lleva el aroma de la salvación.","Hechizo",["ELEMENTAL"],["Piltóver y Zaun"],"COMÚN"],"07PZ013":["Monumento del Sumidero","Si tu nexo recibe daño que no sea de Hongo Venenoso, en su lugar, tu oponente planta 5 Hongos Venenosos en tu mazo por cada punto de daño.","","En las profundidades de las calles de Zaun, eres lo que comes.","Hito",[],["Piltóver y Zaun"],"ÉPICA"],"07PZ015":["Trampa de Chatarra Épica","Para usarme, gasta todo tu maná. Invoco 1 Trampa de Chatarra Fugitiva e incremento sus estadísticas en esa cantidad.","","''La principal responsabilidad de un científico es controlar variables. Las consecuencias de accidentes en un campo como el nuestro... ¡Siento escalofríos de solo pensarlo!''. —Profesor Heimerdinger","Hechizo",[],["Piltóver y Zaun"],"COMÚN"],"07NX028":["Capitán Kalrix","Golpe al Nexo: Inflijo daño al nexo enemigo igual a la mitad de su vida, redondeado.","","Noxus es un imperio construido para expandirse por encima de todo. Madera, piedra o acero: Nada puede detener el avance de un ariete noxiano.","Unidad",[],["Noxus"],"ÉPICA"],"07NX034":["Salón de Banquetes Carmesí","Los aliados cuestan 1 menos. Cuando juegues un aliado, le inflijo 2 de daño.","","''¡Vengan, amigos míos, tomen asiento! La compañía es buena y la bebida, abundante. No puedo esperar para mostrarles lo que cenaremos''. —Vladimir","Hito",[],["Noxus"],"ÉPICA"],"07NX032":["Tomo Corvunato","Cuando mi portador juega una Habilidad, la copio.","","El Conservatorio Floroscura era famoso por su colección de textos, muchos de los cuales terminaron convirtiéndose en combustible para el rugiente fuego provocado por un pupilo notoriamente difícil...","Equipo",[],["Noxus"],"RARA"],"07NX033":["Tricola Piel de Hueso","Cuando me invocan, recibo +1|+1 por cada subtipo diferente que otros aliados tengan.","","''¡Cuidado, tontos! Los noxianos solo compran bestias de combate en perfectas condiciones. ¡Un rasguño y lo descuentan de su sueldo!''. —Magnate Cazador","Unidad",["GATO"],["Noxus"],"COMÚN"],"07RU015":["El Rey Poro","Origen: Decreto del Rey Poro.\nEn cada ronda, creo 1 Porogalletas en la mano la primera vez que invoques a otro poro.","Si invocaste a otros 6+ nuevos poros. Cuando subo de nivel, creo 1 Porogalleta Especial aleatoria en la mano.","Ingvar reconoce el potencial cuando lo ve. Más allá de su apariencia casera, este querido compañero bien podría ser el gobernante de un trillón de poros... si tuviese el nivel adecuado de imaginación. ","Unidad",["PORO"],["Runaterra"],"Campeón"],"07RU012":["Neeko","Origen: ¡Amigos Polimorfos de la Jungla!\nAl jugar: Puedes Disfrazarme como 1 de 3 seguidores de 2 de costo de mi Origen.","Al atacar: Si atacaste con aliados que tengan 6+ subtipos diferentes.","Neeko puede tomar muchas formas, pero su corazón nunca cambia; siempre la guía de vuelta a su familia y su bosque.","Unidad",["CAMBIAFORMAS"],["Runaterra"],"Campeón"],"07BW043":["Invocación de los Mares","Inflijo 1 de daño a una unidad. Hago Surgir 1 por cada punto de daño infligido.","","Solo los más eruditos pueden controlar los elementos a voluntad.","Hechizo",["ELEMENTAL"],["Aguasturbias"],"RARA"],"07BW035":["La Guarida del Estafador","Tus cartas en la mano tienen Fugaz.\nCuando juegas una carta, roba 1.","","''Considero que deberías conocer tu mano y mantenerla cerca, o no tener reparos en perderlo todo''. —Twisted Fate","Hito",[],["Aguasturbias"],"ÉPICA"],"07BW042":["Cazador de Cubierta","Al jugar: Manifiesto un seguidor que tenga un subtipo diferente que los aliados en juego.","","''Existe una razón por la que mantenemos a este pequeño enmarañado cerca: ¡No hemos tenido un problema de ratas en años!''. —Grumete del Heraldo","Unidad",["GATO"],["Aguasturbias"],"COMÚN"],"07BW039":["Príncipe Dragón Grinzo","Cada ronda, la primera vez que invocas a un aliado de 1 de costo, restablezco 1 de maná de hechizos.","","''Don Lagarto, ¿qué hace usted aquí? ¡¿También le gustan lo' poro'?!''. —Ingvar la Joven","Unidad",["DRAGÓN"],["Aguasturbias"],"RARA"],"07BW033":["Canción de Sirena","Invoco un Despojo aleatorio.\nOtorgo +1|+1 a los aliados de 1 de costo en todas partes.","","Algunos marineros de Aguasturbias se tapan los oídos con algodón durante las noches más tranquilas en altamar. Saben que la música submarina no es más que la promesa de una tumba bajo el agua.","Hechizo",[],["Aguasturbias"],"COMÚN"],"07IO041":["Brisa Rejuvenecedora","Curo 3 a tu nexo y roba 2 hechizos.","","''El viento es el único aliado del errante''. —Yasuo","Hechizo",["ELEMENTAL"],["Jonia"],"COMÚN"],"07IO043":["Oráculo que Todo lo Ve","Al jugar: Elige 1 de 3 hechizos Rápidos o Lentos en la mano o el mazo del enemigo. Creo 1 Grabados Adivinatorios por eso.","","El ojo que no está atado al mundo material lo ve todo. Por ciego que parezca, aquellos que toman al oráculo como un blanco fácil son rápidamente reprendidos sin piedad.","Unidad",[],["Jonia"],"RARA"],"07IO049":["Airis","Golpe al Nexo: Invoco 1 Despojo aleatorio.","","''Calla. Estamos cerca. Dijiste que querías conocer a mi amiga, ¿no es así? Confía en mí... a ella le encantará conocerte''.","Unidad",[],["Jonia"],"RARA"],"07SH038":["Cría Pakaa","Emboscar 1.\nGolpe al Nexo: Invoco 1 Protector Pakaa.","","Su dulzura es mera apariencia; su ferocidad es instintiva. Con tiempo e instrucción, hasta el pakiti más peque puede crecer con fuerza y bravura.","Unidad",["GATO"],["Shurima"],"COMÚN"],"07SH041":["Curiosidad Cara","Manifiesto una carta con Emboscar.","","El reconocimiento de la jungla es el menos deseable de los trabajos sobre todo por una razón: El lugar está lleno de sorpresas.","Hechizo",[],["Shurima"],"RARA"],"07SH004":["Merodear","Doy +2|+0 a un aliado en esta ronda. Si es 1 Sombra en la Maleza, le doy +2|+2.","","''Camina despacio, pakiti, pero ataca con firmeza''. —Nidalee","Hechizo",[],["Shurima"],"COMÚN"],"07SH013":["Nidalee","Emboscar 2","Si te he visto invocar o transformar a otros 4 aliados.","''Siempre te protegeré, chica reptil. Haremos que esos saqueadores paguen. Y lo haremos juntas''. —Nidalee","Unidad",["GATO"],["Shurima"],"Campeón"],"07SH009":["Vastaya Vengativo","Emboscar 3. Cuando me transformo desde Emboscada de Vastaya Vengativo, detengo todos los hechizos Rápidos, hechizos Lentos y Habilidades del enemigo.","","''No teman, peques, yo los protegeré... y saldaré mi deuda con Nidalee''.","Unidad",[],["Shurima"],"COMÚN"],"07SH039":["Adalid Todoterreno","Emboscar 0.\nCuando me invocan o me transformo, otorgo Vulnerable al enemigo Más débil.","","''Esta belleza puede convertir a un principiante en todo un profesional que trepa árboles y salta en las rocas. Me costó una fortuna, pero pagaré los préstamos con la piel de bestias raras...''.","Unidad",[],["Shurima"],"RARA"],"07SH044":["Aurora Hallunatis","Emboscar 4. Cuando me transformo, invoco 1 Aurora Hallunatis.","","''¡Me encantaría ver una con mis propios ojos! La mayoría de los exploradores creen que la Aurora Hallunatis es un mito, pero un joven jura que es real. Me dijo que los colores del ave son brillantes y que posee una envergadura tan larga como un hombre. 'Verla a los ojos te hace comprender que eres la presa', me contó una noche''. —Del diario de campo de Anura, día 21","Unidad",["AVE"],["Shurima"],"RARA"],"07SH003":["Saqueador de la Manada Dirigible","Emboscada 3\nCuando me transformo desde Emboscada del Saqueador de la Manada Dirigible, la próxima vez que bloquee o que me bloqueen en esta ronda, Capturo a mi enemigo.","","''¡Ja! Intenten atraparme ahora, bestias tontas. ¡Ni siquiera la gravedad puede vencer a una especie superior!''.","Unidad",[],["Shurima"],"ÉPICA"],"07SH011":["Trampa","Cuando me invocan o la primera vez que un aliado se transforma en cada ronda, otorgo Vulnerable al enemigo Más débil.","","''Hay sangre en el aire''. —Nidalee","Hito",[],["Shurima"],"COMÚN"],"07SH046":["Valle de Imitación","Cuando juegas un seguidor, me transformo en una copia exacta suya en esta ronda.","","''He aquí la parada MÁS BE-LLA y favorita del recodido. A muchas personas les gustó tanto mi recodido que constuyeron UN CHIP GRANDOTE Y FUERTOTE, que será una parada en el recodido para siempre. Díganle: ''¡'HOLAAA, CHIP GRANDOTE!''. ''A Chip Grandote le gusta TODO el mundo, especialmente las personas que vienen a su recodido''. —Las Aventuras con Chip, parte 6","Hito",[],["Shurima"],"COMÚN"],"07SH043":["Pairofante Colosal","Emboscar 5.","","Al ser sus habitantes más antiguos, dicen que los pairofantes albergan los recuerdos y el corazón de la mismísima jungla. Aunque gentiles, defenderán su hogar ante cualquier amenaza... grande o chica. ","Unidad",[],["Shurima"],"ÉPICA"],"07SH040":["Cerdoespín","Recibo +2|+1 la primera vez que un aliado se transforme.","","''Son pequeños mamíferos omnívoros con púas, las cuales pueden eyectar a altas velocidades cuando están inquietos. Su cola es puntiaguda y la mueven con agilidad, posiblemente a modo de arma defensiva. Según los exploradores más veteranos, las criaturas son notoriamente irritables y difíciles de controlar...''. —Del diario de campo de Anura, día 3","Unidad",[],["Shurima"],"RARA"],"07SH005":["Magnate Cazador","Al jugar: Manifiesto una carta con Emboscar.\nCuando un aliado se transforma, duplico su poder y su vida.","","''¡¿Perdieron TODO contra un científico y un reptil monstruoso?! Bueno, ¿qué se supone que están esperando, tontos? ¡Vayan y recuperen mi dinero!''.","Unidad",[],["Shurima"],"RARA"],"07FR011":["Templo al Hielo Verdadero","Cuando invocas a un aliado, hago que su vida sea igual a su poder.","","Aunque el significado original de este templo se ha perdido en el tiempo, su guardián de piedra sigue en pie, sin haberse doblegado ante el peso de tantas avalanchas. Cubierto de hielo, parece estar imbuido de una luz extraña y cautivadora...","Hito",[],["El Fréljord"],"ÉPICA"],"07FR010":["Garranavajas de las Nieves","Pillaje: Incremento las estadísticas de un aliado para que coincidan con las mías.","","Aunque el garranavajas de las nieves caza principalmente pequeños mamíferos, esta bestia freljordiana tiene suficientes garras para convertir casi cualquier cosa en su cena.","Unidad",["AVE"],["El Fréljord"],"COMÚN"],"07FR015":["Ingvar la Joven","Al jugar: Elige un aliado. Les otorgo +1|+1 a él y a todos los otros aliados que compartan el mismo subtipo o Manifiesto un seguidor que comparta el mismo subtipo.","","Ingvar, la autodenominada supervisora de poros y exploradora del Fréljord, está segura de que la aventura está ahí fuera, y la va a encontrar. ","Unidad",[],["El Fréljord"],"ÉPICA"],"07FR017":["Pteratormenta Cristalino","Al jugar: Inflijo 2 de daño a TODAS las demás unidades.","","La violencia inducida por el raptor de la tormenta cristalino es instantánea e indiscriminada, capaz de inclinar la balanza de cualquier batalla en un suspiro. Muchos consideran que el ave es el primer augurio de la llegada de una gran y terrible tormenta... una que transformará los cimientos de la tierra.","Unidad",["AVE"],["El Fréljord"],"RARA"],"07FR016":["Saurio Glaciar","Cuando me invocan, otorgo +1|+1 a las primeras 3 unidades de tu mazo. Si un aliado tiene un subtipo diferente al mío, roba 1 de esas unidades.","","Con un exoesqueleto que contrasta con su gran corazón, estos confiables corceles son vitales para despejar los pasos de montaña cubiertos de hielo.","Unidad",["REPTIL"],["El Fréljord"],"RARA"],"07SI010":["Aracnoide Necrótico","Cuando me invocan, invoco 2 Crías Necróticas.\nCuando otro aliado muere, Dreno 1 del nexo enemigo.","","Halladas solo en los rincones más oscuros de las Islas de la Sombra, estas arañas secretan un necroveneno mortal que adormece la piel mientras comienza a pudrirla.","Unidad",["ARAÑA"],["Islas de la Sombra"],"ÉPICA"],"07SI012":["Hilandera Hebrosa","Al jugar: Si un aliado tiene un subtipo diferente al mío, le doy -2|-0 a un enemigo en esta ronda.","","Las hilanderas hebrosas hacen sus nidos con mucho cuidado y son especialmente cariñosas con sus crías... pero también son feroces cuando se trata de enfrentar amenazas potenciales.","Unidad",["ARAÑA"],["Islas de la Sombra"],"COMÚN"],"07SI013":["Sombraespectro Proliferante","Último Aliento: Creo en el mazo una copia exacta de tu Sombraespectro Proliferante más fuerte en el mazo y luego duplico las estadísticas de Sombraespectros Proliferantes en el mazo.","","''Esta Niebla me ha dado muchas lecciones. La más importante: Saber cuándo correr''. —Centinela Ixtali","Unidad",[],["Islas de la Sombra"],"RARA"],"07SI004":["Tijeras Sagradas","Al atacar: Cuando otro aliado obtiene poder de Consagrar, también lo obtiene mi portador.","","''¡Con un buen par de tijeras e hilo de calidad, puedes reparar casi cualquier cosa!''. —Gwen","Equipo",[],["Islas de la Sombra"],"RARA"],"07MT009":["Edad de los Dragones","Roba todos los Dragones de las primeras 9 cartas de tu mazo y reduzco su costo a 0 en esta ronda. Después, añado el resto a tu mazo.","","''Conocer a un dragón es dominar el yo. Conocer muchos es dominar el mundo''. —Adorador de Dragones Ottrani","Hechizo",[],["Targón"],"RARA"],"07MT013":["Llamado Cósmico","Convoco un Celestial de 7 de costo o más, o pago 8 para reducir el costo de tus Celestiales en todas partes a la mitad, redondeado.","","El Juez vigila en la eternidad el caer de las bendiciones del cielo.","Hechizo",[],["Targón"],"COMÚN"],"07MT006":["Amantes en Desgracia","Al jugar: Lanzo Retirada a un aliado y le otorgo mis estadísticas.","","''Hay muy pocas vistas que superan en esplendor al encuentro entre la luna y el sol''. —Diana","Unidad",[],["Targón"],"COMÚN"],"07BC020":["Señor Acaparador","Cuando una o más de tus trampas o bendiciones se activen, planto 2 de ellas en el mazo de ese jugador.","","Nadie sabe desde cuándo empezó su colección el Señor Acaparador ni de dónde salió. Parece amigable... si ignoramos el rastro de peligros que va dejando a su paso.","Unidad",[],["Ciudad de Bandle"],"RARA"],"07BC016":["Llave de Retorno","Cuando me descartes, Equípame a un aliado aleatorio que no esté equipado.","","''No puedo mentir, tiendo a perder mis herramientas. Aunque esta siempre reaparece justo cuando la necesito''. —Inspector de Seguridad","Equipo",[],["Ciudad de Bandle"],"COMÚN"],"07BC018":["Erudito del Portal","Cuando me invocan, planto 1 Portal Misterioso entre las 4 cartas de arriba de tu mazo.\nCuando invocas un aliado creado, le otorgo Impacto.","","Al frente de cualquier investigación, es seguro que siempre habrá sorpresas; afortunadamente, esta es una sorpresa positiva. ","Unidad",["FEÉRICO"],["Ciudad de Bandle"],"ÉPICA"],"07BC011":["Pelusas Feroces","Cuando me invocan, otorgo +1|+1 e Impacto a los otros aliados que tengan subtipos.","","Por desgracia para este equipo de saqueadores piltovianos, solo se ven inofensivos.","Unidad",["AVE"],["Ciudad de Bandle"],"COMÚN"],"07DE014":["Sargento Inquisitivo","Al jugar: Elige una unidad de las primeras 5 cartas de tu mazo que cueste 3 o menos. Invócala y coloca el resto en tu mazo.","","El sargento de reclutamiento demaciano carga con una gran responsabilidad. Sus reclutas seguirán para ocupar muchos puestos diferentes, todos unidos en su deber y amor por Demacia.","Unidad",["ÉLITE"],["Demacia"],"ÉPICA"],"07DE015":["Falcoleón Crestado","Al jugar: Si un aliado tiene un subtipo diferente al mío, Manifesto un hechizo demaciano.","","'Grabando el primer avistamiento confirmado del Falcoleón en casi cincuenta años. Con una hermosa cresta azul y ojos inteligentes, tiene el cuerpo blindado, pero sus huesos son lo suficientemente livianos para al menos escalar árboles o para planear de forma limitada. La estructura de las alas es similar a la de los aliplatas de Demacia. Regresaré con más medidas''. —Del diario de campo de Anura, día 12","Unidad",["AVE"],["Demacia"],"RARA"],"07DE011":["Cazador de Magos Júnior","Los hechizos que cuesten menos de 3 cuestan 3.","","''¡Silencio! Esto no es un simple juego, como dices, sino la cortina de humo de algún insidioso enfrentamiento arcano. Quiero exponerte como un tramposo y un mago, viejo sinvergüenza, ¡incluso si tengo que quemar todo este establecimiento!''.","Unidad",[],["Demacia"],"COMÚN"],"07DE016":["Balen el Benevolente","Al atacar: Otorgo +0|+1 a los otros aliados con Formidable en todas partes.","","Balen es un viejo compañero de la familia Durand. Su gran tamaño contradice su gentil precisión. Aunque comenzó siendo un asistente, Balen posee sumo talento para la artesanía y gran creatividad para su práctica. Los Durand se enorgullecen de llamarlo su amigo.","Unidad",[],["Demacia"],"ÉPICA"],"08SI042":["Mordekaiser","Al jugar: Mato hasta 2 aliados.\nCuando Mates a otro aliado, lo revivo.","Si 15+ aliados han muerto. Los aliados con 5+ de poder cuentan el doble.","Atado a su armadura, en lo más profundo del Bastión Inmortal, Mordekaiser ha forjado su propio trono en el Reino Gris. Por cada necio que pretenda destruirlo, habrá cientos más dispuestos a servirle tanto en la vida como en la muerte.","Unidad",[],["Islas de la Sombra","Noxus"],"Campeón"],"08SI040":["Erastin, el Deshonrado","Cuando me invocan, me otorgo Inmortal.\nAl atacar:: Doy -1|-0 a los enemigos en esta ronda.","","Antaño, los dragones de Camavor fueron criaturas magníficas y dignas de respeto. Sin embargo, ni siquiera ellos se salvaron de la voraz corrupción de la Ruina. Y Erastin no es la excepción: donde antes hubo majestuosidad, hoy solo queda la grotesca apariencia de los inmortales.","Unidad",["DRAGÓN"],["Islas de la Sombra"],"ÉPICA"],"08SI007":["Legión de los Cercenados","Al jugar: Otorgo Inmortal a un aliado en la mano.","","No importa qué forma tenían las almas antes de su encarcelamiento en el Reino Gris. La individualidad tiene poco valor ahí. Sin rostro y sin miedo, la Legión sirve al Renacido de Hierro mucho mejor gracias a su uniformidad.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"08SI003":["Espíritus Encadenados","Último Aliento: La próxima vez que revivas a un aliado, creo una copia mía en la mano.","","''Hace mucho tiempo fuimos encadenados. Pronto tú también conocerás nuestro sufrimiento, y todos sufriremos, por los siglos de los siglos, hasta que la mano del Maestro nos conceda el olvido...''","Unidad",[],["Islas de la Sombra"],"RARA"],"08SI021":["Tintineante Solitario","Cuando otro aliado muere o se activa Último Aliento: Planto 4 Campanillas en tu mazo.","","No te preocupes por ese inquietante tintineo: Es el viejo Tintineante haciendo su recorrido. Siempre se alegra de ver a los recién llegados, pero ellos no se alegran de verlo a él.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"08SI030":["Tumba Acuática","Lanzo Aniquilar a 6 cartas del fondo del mazo enemigo.","","En las profundidades de Runaterra, existen monstruos para los que una embarcación jaull es un simple aperitivo.","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"08SI037":["Sabueso Férrico Espectral","Para usarme, mata a un aliado.\nCuando me invocan, invoco 1 Muerte a Mil Garras.","","Estos sabuesos nunca olvidan el rastro de quien intentó huir... y cuando acorralan a su presa, un mortífago nunca está lejos.","Unidad",[],["Islas de la Sombra"],"RARA"],"08SI041":["Garra del Inframundo","Mato a un aliado para infligir 5 de daño a una unidad.","","''La oscuridad es el destino de todos, menos el mío''. —Mordekaiser","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"08SI036":["Umbral del Gris","Al jugar: Maldigo a un enemigo con Terror.\nCuando juegues un aliado Titánico, destrúyeme para robar 2.","","''Te ofrecemos estas almas. Con huesos pavimentamos este camino ante ti. Desgarramos estos reinos para abrir paso a tu ejército de hierro eterno.''. —Cultista de la Garra del Inframundo","Hito",[],["Islas de la Sombra"],"RARA"],"08SI004":["Reino de la Muerte","Un aliado inicia un ataque gratis que Desafía al enemigo más fuerte.\nMato a TODAS las demás unidades.","","''La muerte es mi dominio''. —Mordekaiser","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"08SI026":["Cultista de la Garra del Inframundo","Cuando me invocan o invocas a un aliado Titánico, Maldigo al enemigo más fuerte con Terror.","","A los ojos de sus fieles, el Renacido de Hierro es la única esperanza para aquellos que anhelan el olvido. Estos sectarios reciben la paz a través de la dominación con los brazos abiertos.","Unidad",[],["Islas de la Sombra"],"RARA"],"08SI018":["Oteador Espectral","Al jugar: Elige un hechizo de Explorador para crearlo en la mano.","","''El terreno es indescifrable. La visibilidad, casi nula. Encuentro enemigos a cada paso... pero, extrañamente, también aliados inesperados''. —De los registros de expedición de la División de Reinos Lejanos del Gremio del Explorador, asignación: Islas de la Sombra","Unidad",[],["Islas de la Sombra","Targón"],"RARA"],"08SI015":["Amalgama de Ritos Infames","Para usarme, mata a un aliado.\nÚltimo Aliento: Curo 2 a tu nexo.","","Las bestias de guerra son valiosas para cualquier ejército. En el Reino Gris, son amalgamas de almas torturadas, y cada una de ellas se consume violentamente en su insensibilidad. ","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"08BW008":["Nilah","Al atacar: Creo 1 Estela Acuática entre las primeras 6 cartas de tu mazo.","Has robado 15+ cartas.","En el norte, un nuevo oponente espera a Nilah y su equipo de cazamonstruos: Una criatura llamada Volibear, que amenaza con destruir al Fréljord que alguna vez supo venerarlo. Para Nilah, poder probar sus habilidades contra un monstruo que otros consideran una deidad es una oportunidad única en la vida. Ni hablar de las criaturas inferiores que en el proceso añadirá a su lista de logros. ","Unidad",[],["Aguasturbias"],"Campeón"],"08BW032":["Felicidad Infinita","Doy +1|+0 a los aliados en esta ronda y curo 2 a los aliados heridos.","","''¡Alegría desbordante y eterna!''. —Nilah","Hechizo",["ELEMENTAL"],["Aguasturbias"],"COMÚN"],"08BW038":["Bailarina del Chakram","Al jugar: Inflijo 1 de daño a cualquier objetivo.\nTus habilidades Drenan.","","Se mueve en una danza de agua y cuchillas, creando acero a partir de la espuma de mar y el rocío. Ella no necesita ver para sentir el vaivén de sus armas, pues son agua viva que al agua volverá.","Unidad",[],["Aguasturbias"],"ÉPICA"],"08BW015":["Danzante de las Mareas","Cuando me invocan, roba 1 Nilah.\nEn cada ronda, cuando juegues tu tercera carta, doy a otros aliados +2|+0 e Imprudente en esta ronda.\nEn vez de obtener Fugaz, revélame.","","''Dicen por ahí que esa nave de extraña forma es la más rápida en la historia de Aguasturbias. Y también la más ágil. Tiene una peculiar capitana, pero a mi parecer ella sabe muy bien lo que hace. Quizá podríamos aprender algunas cosas de ella''. —Cantinero de Aguasturbias","Unidad",[],["Aguasturbias"],"ÉPICA"],"08BW002":["Filo sin Forma","Inflijo 2 de daño a una unidad. Su vida no puede bajar a menos de 1 con este ataque.","","''Los monstruos que se hacen llamar dioses son los que caen más duro, sin importar de dónde sean''. —Nilah","Hechizo",["ELEMENTAL"],["Aguasturbias"],"COMÚN"],"08BW025":["Maestre Gaviero","Una vez que robes 3+ cartas en una ronda en esta partida, recibo +1|+1 e Imprudente.","","''Oye, compa, ¿por qué tanto alboroto? ¡Relájate! ¡No hay nada en las aguas que no podamos enfrentar!''. —Devoto del Desafío","Unidad",[],["Aguasturbias"],"COMÚN"],"08BW026":["Devoto del Desafío","Cuando me invocan, Arremolino tu mano para recibir +1|+1 por cada carta Arremolinada y roba 2.","","''Ay, por favor, ¿siquiera te estás esforzando? No me hagas contenerme, ¡odio contenerme!''.","Unidad",[],["Aguasturbias"],"RARA"],"08BW028":["Octoaventurero","Al jugar: Elige un hechizo de Explorador para crearlo en la mano.","","''Un ejemplar extraño. Muy azul. Ojos bastante grandes. Incómodamente grandes. Lo tomaremos para un estudio a fondo''. —De los registros de expedición de la División de Reinos Lejanos del Gremio del Explorador, asignación: Piltóver","Unidad",[],["Aguasturbias","Piltóver y Zaun"],"RARA"],"08BW009":["Timonel Ducho","Al jugar: Manifiesto dos hechizos Elementales distintos que hayas jugado en esta partida. Cuestan 0 en esta ronda.","","''La mente es un río. Con el tiempo, la perseverancia de su flujo talla las laderas de las montañas. Y de tal forma, la mente, con ímpetu, puede aumentar su cauce y alcanzar nuevas costas''.","Unidad",[],["Aguasturbias"],"RARA"],"08BW010":["Diluvio","Por el resto de la partida, todos tus hechizos Elementales y Habilidades infligen 1 de daño adicional.","","''En manos sabias, el agua puede moldearlo todo''. —Devoto de la Sabiduría","Hechizo",["ELEMENTAL"],["Aguasturbias"],"ÉPICA"],"08BW031":["Sefirsa, Azote de las Profundidades","Cuando gastas maná para jugar otra unidad, creo una carta al azar en la mano del mismo costo. Cuesta 0 y es Fugaz.","","A pesar de su apetito por las bestias marinas más extrañas, hay algunos monstruos que ni siquiera los capitanes más experimentados de Aguasturbias se atreven a molestar. Hablan de Sefirsa en voz baja, como una luz hipnótica que se mueve en lo profundo de las olas; un monstruo que se alza sobre una fosa común de barcos hundidos y hombres ahogados.","Unidad",["MONSTRUO MARINO","DRAGÓN"],["Aguasturbias"],"ÉPICA"],"08BW037":["Croupier Honesto","Cuando juegas una carta con un costo igual a mi Poder, recibo +1|+1.","","''Oye, ¿no quieres apostar un poco más? ¡El que no arriesga no gana! Esta mesa tiene suerte esta noche, te lo aseguro. Y la casa reparte justamente en este honrado establecimiento: lo juro por la lengua de mi má''.","Unidad",[],["Aguasturbias"],"RARA"],"08BW036":["Chapitel del Arrecife Marai","Cuando gastas maná para jugar una unidad, restablezco 1 de maná de hechizos.","","''Desde hace mucho tiempo, el arrecife ha sido a la vez un refugio y un aliado. Cuida de nosotros, como nosotros cuidamos de él, para que ninguno de los dos caiga en la oscuridad''. —Abuela Marai","Hito",[],["Aguasturbias"],"COMÚN"],"08BW023":["Vikrash el Hilarante","Cuando me invocan, creo 1 Estela Acuática entre las primeras 6 cartas de tu mazo.","","''¡Miren, mis amigos, cómo el mundo entero se mueve con nosotros! Las olas danzan bajo el casco, el viento sopla en las velas, las aves planean en la brisa. ¡Síganme en nuestra más noble misión y regocíjense!''.","Unidad",[],["Aguasturbias"],"ÉPICA"],"08PZ007":["Parvada Ventiscanto","Invoco 1 Golondrina Ventiscanto y le otorgo +1|+1 por cada otro hechizo Elemental y Habilidad que hayas jugado en esta partida.\nRoba 1.","","Cuando las golondrinas del ventiscanto se reúnen en gran número, se avecina una tormenta.","Hechizo",["ELEMENTAL"],["Piltóver y Zaun"],"RARA"],"08PZ031":["Gafas Sospechosas","Elige un seguidor aliado. Transformo a mi portador en una copia exacta mientras esté equipado.","","No preguntes cómo funcionan.","Equipo",[],["Piltóver y Zaun"],"RARA"],"08PZ025":["Porobot Prototipo","Último Aliento: Otorgo ''Cuando me juegan, invoco 1 Porobot Prototipo'' a un hechizo de 6+ de costo aleatorio en la mano.","","''Solo es un prototipo'', gimoteó el aprendiz mientras las llamas consumían el laboratorio. ''¡No lo programé para comerse todos los engranes que se le atravesaran! ¡Ni siquiera sé dónde a dónde va a parar todo ese metal!''.","Unidad",["PORO"],["Piltóver y Zaun"],"RARA"],"08PZ005":["Ojo de la Tormenta","Doy +2|+0 a un aliado en esta ronda.\nRoba 2.","","''¡Descuida! La tormenta puede desatarse a tu alrededor, pero no te dañará''. —Janna","Hechizo",["ELEMENTAL"],["Piltóver y Zaun"],"COMÚN"],"08PZ019":["Torbellino Divino","Si robaste 3+ cartas en esta ronda, cuesto 2 menos.\nInflijo 3 de daño a una unidad y 2 de daño al nexo enemigo.","","''La tempestad está a mi disposición''. —Janna","Hechizo",["ELEMENTAL"],["Piltóver y Zaun"],"RARA"],"08PZ028":["Dragona Quimtech","Cuando juegas un hechizo, roba 1. Cuando robas mientras tienes completa la mano, inflijo 1 de daño al nexo enemigo.","","Zaun requiere adaptación, y la dragona quimtech no es una excepción, envuelta en la enfermiza luz verde de los aumentos mientras se aferra a las profundidades de la ciudad. Las sombras gemelas de las alas arruinadas de la dragona recorren los pasadizos oscuros, heraldos de una furia nacida de la angustia ante su propia corrupción.","Unidad",["DRAGÓN"],["Piltóver y Zaun"],"ÉPICA"],"08PZ001":["Janna","Al jugar: Arremolina 2 para robar 2 cartas en el siguiente Inicio de la ronda.\nCada ronda, las 3 primeras veces que robes una carta, reduzco su costo en 1 en esta ronda.","Te he visto jugar 8 cartas con costo reducido.","''Zaun ocupa un lugar especial en el corazón de Janna; más que cualquier otro. Después de todo, ella fue quien salvó a las pobres almas que Piltóver dejó morir. Sí... Si hay respuestas que encontrar, las obtendré aquí''. —Marinero del Viento","Unidad",[],["Piltóver y Zaun"],"Campeón"],"08PZ026":["Llamado del Ventiscanto","Invoco 1 Golondrina Ventiscanto.","","''Todos los hijos del viento responden a mi llamado''. —Janna","Hechizo",["ELEMENTAL"],["Piltóver y Zaun"],"COMÚN"],"08PZ006":["Iascylla, Cabeza de las Profundidades","Cuando juegas un hechizo Elemental o una Habilidad, lo copio con los mismos objetivos.","","''¡Ven, Iascylla! Ciertamente eres vieja si Ashlesh conoce tu nombre. Pero vieja o joven, guapa o fea, no importa. No hay mayor honor para un monstruo que caer ante mi espada en mar abierto''. —Nilah","Unidad",[],["Piltóver y Zaun"],"ÉPICA"],"08PZ018":["Marinero del Viento","Si robaste 3+ cartas en esta ronda, cuesto 2 menos.","","''Sí, tenía lo que quería. Pero lo conseguí todo por la fuerza, y eso me dejó vacío y sin rumbo. La primera cosa que encontré para seguir fue el viento, así que ahora heme aquí, esperando que me empuje hacia un camino mejor''.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"08PZ008":["Maryam, Cuidadora del Templo","Al jugar: Arremolino 1 para robar 1 carta o recargar tu maná de hechizos.","","Convencida de que fue salvada por el espíritu del viento cuando era niña, Maryam ha predicado las virtudes de Janna desde su país natal, Shurima, hasta Zaun. Ahora, como matriarca del templo de Zaun, se dedica a difundir la bondad de Janna entre los jóvenes y los marginados.","Unidad",[],["Piltóver y Zaun"],"ÉPICA"],"08PZ009":["Templo Hundido","Fin de la ronda: Arremolino tu mano.\nInicio de la ronda: Roba esa cantidad de cartas más 1.","","Fue mucho lo que se perdió en el desastroso colapso que acabó separando Zaun de Piltóver. Puede que Janna perdiera su templo a manos de las olas, pero salvó a las personas que practicaban su adoración en él.","Hito",[],["Piltóver y Zaun"],"ÉPICA"],"08PZ002":["Vendaval Aullante","Inflijo 2 de daño a una unidad.\nAumento mi daño en 1 por cada carta adicional que hayas jugado esta ronda, hasta 3 veces.","","''¡Mi furia sobre los vientos ensordecedores!''. —Janna","Hechizo",["ELEMENTAL"],["Piltóver y Zaun"],"RARA"],"08PZ024":["Pescadero Charlatán","Inicio de la ronda: TODOS los jugadores roban 1, después otorgo Fugaz a la carta del oponente.","","''Hoy es dos por uno, ¡dos por uno solo hoy! Pescado fresco, pescado este mismo... eh, ¿mes? ¡Dos por uno! ¿Cómo que no quieres el segundo? ¡Es gratis!''.","Unidad",[],["Piltóver y Zaun"],"COMÚN"],"08PZ020":["Clamanubes Insigne","Si robaste 3+ cartas en esta ronda, cuesto 2 menos.\nCuando me invocan, roba 2 cartas en el siguiente Inicio de la ronda.","","''Mi querido Céfiro. Baja de tus nubes y pósate sobre mi hombro un momento, ¿quieres?''. —Janna","Unidad",[],["Piltóver y Zaun"],"RARA"],"08FR012":["Invocación del Trueno","Roba 1.\nInvoco 1 Sello de la Tormenta.","","''En nombre de Valhir, presentamos esta ofrenda...''. —Profeta de Valhir","Hechizo",["ELEMENTAL"],["El Fréljord"],"COMÚN"],"08FR033":["Berserker Aguerrida","Cuando juegas un hechizo Lento cuyo objetivo es un solo aliado, lo copio sobre mí.","","''¿Crees que un par de flechas podrán detenerme? ¡Ja! Cualquier cosa que me lances se convertirá un arma de mi arsenal. ¡Reforjaré con hielo todo lo perdido!''.","Unidad",[],["El Fréljord"],"COMÚN"],"08FR019":["Rompecielos","Doy +1|+3 a un aliado en esta ronda.","","Cubierto de nubes y envuelto en relámpagos, el dios oso se erige intocable en el corazón de la tormenta.","Hechizo",["ELEMENTAL"],["El Fréljord"],"COMÚN"],"08FR001":["Volibear","Al jugar: Juega Tormenta Implacable 3 veces. Cada una se lanza contra un enemigo aleatorio diferente o contra el nexo enemigo si no hay ninguno.","Fin de la ronda: Si infligiste 50+ de daño.","''¡Arrodíllate ante mí, mortal, y tal vez te perdone! Tu poder es débil, pero quizá lo bastante digno para servir al mío. ¡Arrodíllate o te eliminaré de la faz de la tierra!''.","Unidad",[],["El Fréljord"],"Campeón"],"08FR018":["Guerra de Gigantes","Invoco 2 seguidores Titánicos aleatorios.\nCuesto 1 menos por cada hechizo Elemental o Habilidad que hayas jugado en esta partida (máx. 10).","","''Con su cuerpo, esculpí las montañas. Con el fuego de sus fauces, esculpí mil fiordos''. —Volibear","Hechizo",["ELEMENTAL"],["El Fréljord"],"ÉPICA"],"08FR011":["Invocallamas Caprina","Cuando juegas un hechizo Elemental o una Habilidad, Fórjame.","","''El Señor de la Forja prometió cambios y, en su lugar, forjó a martillazos las cadenas de la inacción. Quienes adoran a un dios débil son débiles por extensión. ¡Solo el poder de Valhir nos devolverá la gloria de antaño!''.","Unidad",[],["El Fréljord"],"RARA"],"08FR008":["Invocador de Tormentas","Inflijo 4 de daño a TODAS las unidades excepto a aliados Titánicos.","","''¡Que la tundra se tiña de rojo!''. —Volibear","Hechizo",["ELEMENTAL"],["El Fréljord"],"RARA"],"08FR024":["Nevicán de Yadulsk","Al atacar: Otorgo +1|+1 a los primeros 2 aliados de tu mazo.","","Aunque son originarios de Yadulsk, estos cachorros han sido domesticados por varias tribus del Fréljord para rastrear, cazar y rescatar víctimas de avalanchas. Con una complexión robusta y un fuerte apetito por la diversión, son muy queridos desde la tundra hasta la taiga.","Unidad",["PERRO"],["El Fréljord"],"COMÚN"],"08FR015":["Rhond, la Serpiente de Magma","Al jugar: Invoco 3 Sellos de la Tormenta.","","Aunque son muy pocos los que aún lo veneran, todos los freljordianos conocen la historia de la gran batalla de Volibear contra Rhond. Mucho antes de que ningún mortal pisara el gélido norte, esta destructiva batalla formó las cordilleras y los ríos de la tundra misma.","Unidad",[],["El Fréljord"],"ÉPICA"],"08FR030":["Boadir del Hielo Oscuro","Cuando me invocan, invoco 2 Siervos Congelados y los hago Avanzar hasta 2.","","''¡Era fe-feroz! Esbirros quemados hasta convertirse en hielo negro, avalanchas bajo sus garras, ¡un rugido que arrancaba la nieve de las montañas! ¡Una reina guerrera, te lo aseguro! Ma-matar esclavos es el trabajo de una reina guerrera''. — Bjerg Balbuceante","Unidad",["DRAGÓN"],["El Fréljord"],"ÉPICA"],"08FR002":["Profeta de Valhir","Cuando me invocan, invoco 1 Sello de la Tormenta.","","''Veo lo que los demás no pueden: La tormenta que hará añicos la montaña, el quebrantamiento de los huesos de la tierra. El Fréljord de antaño será forjado nuevamente con sangre: Solo es cuestión de tiempo''.","Unidad",[],["El Fréljord"],"COMÚN"],"08FR028":["Arnés Práctico","Recibo +1|+0 por cada aliado con un subtipo diferente que hayas invocado en esta partida.","","''Aquí arriba hay bestias que ni una avalancha puede detener. Por eso un buen arnés vale cada moneda''. —Trampero Avarosano","Equipo",[],["El Fréljord"],"ÉPICA"],"08FR003":["Berserker Ursino","Cuando juegas un hechizo o una Habilidad, invoco 1 Sello de la Tormenta.","","En ocasiones, los seguidores de Volibear se pierden tan profundamente en su fanatismo que empiezan a adoptar rasgos del oso. Nada se interpondrá en el camino de la voluntad de Valhir, ni siquiera aquellos a los que los Ursinos una vez llamaron compatriotas.","Unidad",[],["El Fréljord"],"RARA"],"08RU014":["Dragón Ancestral","Origen: Aspecto del Dragón.\nCuesto 1 menos por cada Bendición de Dragón diferente que hayas jugado en esta partida.\nAl jugar: Juega todas las Bendiciones de Dragón sobre mí.","Si los aliados atacaron con 75+ de poder total.","''Cuenta la leyenda que este dragón es el más antiguo de todos, que es el rey de todas las bestias aladas. Si lo domamos... ¿qué otra cosa podría interponerse en nuestro camino, Alatis? El mundo comprenderá por fin que el hombre y el dragón son más fuertes juntos''. —Volix, Amigo de Dragones","Unidad",["DRAGÓN"],["Runaterra"],"Campeón"],"08NX003":["Escupefuego Iracundo","Al jugar: Inflijo 2 de daño a un enemigo y 2 de daño al nexo enemigo.","","La expansión noxiana ha conquistado muchos pueblos, asentamientos y culturas diferentes. A menudo, las criaturas salvajes también están a merced de la máquina de guerra, pero este dragón responde a cada avance de Noxus con la misma furia violenta e infernal.","Unidad",["DRAGÓN"],["Noxus"],"ÉPICA"],"08NX024":["Legionario de Hierro","Al jugar: Inflijo 3 de daño a un aliado para infligir 3 de daño a un enemigo.","","''¡Arranca sus almas de sus prisiones de carne y hueso!''. —Mordekaiser","Unidad",[],["Noxus"],"RARA"],"08NX011":["Fuego Salvaje","Inflijo 1 de daño al nexo enemigo, el cual aumenta en 1 por cada Fuego Salvaje adicional que hayas jugado. Creo 1 Fuego Salvaje en tu mazo.","","''Cenizas, cenizas...''. —Annie","Hechizo",["ELEMENTAL"],["Noxus"],"COMÚN"],"08NX028":["Indestructible","Otorgo Inmortal a un aliado.","","''Hierro eterno''. —Mordekaiser","Hechizo",[],["Noxus"],"COMÚN"],"08NX019":["Mazanavaja de Cuerno Rojo","Golpe al Nexo: Maldigo a tu oponente con Icor.","","Aunque son útiles para el ejército de Noxus, los mazanavajas también son muy codiciados en las arenas de batalla del capitolio. Pocos oponentes, ya sean humanos o animales, se atreven a enfrentarse a esta bestia, por lo que los escasos combates contra manzanavajas atraen multitudes de toda la ciudad.","Unidad",["REPTIL"],["Noxus"],"COMÚN"],"08NX014":["Madame Directora Telsi","Los efectos de Al atacar y Al apoyar de los aliados se activan una vez más.","","La materia de Disciplina Personal de la directora Telsi está plagada de arduas tareas, golpes en las muñecas y castigos. Siempre ha sido obligatoria para los alumnos del Conservatorio Floroscura; si no lo fuera, nadie se inscribiría.","Unidad",[],["Noxus"],"ÉPICA"],"08NX012":["Adquisidor Armado","Al jugar: Elige un hechizo de Explorador para crearlo en la mano.","","''Uno pensaría que sería más fácil cavar en el desierto... ¡pero no! Cuando pasa el tiempo suficiente, la arena se convierte en piedra. Una vez más, solicito financiamiento para herramientas de repuesto''. —De los registros de expedición de la División de Reinos Lejanos del Gremio del Explorador, asignación: Shurima","Unidad",[],["Noxus","Shurima"],"RARA"],"08NX029":["Impacto Kashuri","Mato a una unidad si está herida. Si no, le inflijo 2 de daño.","","''Esto es por tu bien. Confía en mí''. —Lord Muchacrín","Hechizo",[],["Noxus"],"ÉPICA"],"08NX009":["Lord Mallat","","","''Hicieron falta siglos de planificación para encerrar a ese temible belicista... ¿y tus patéticos amigos piensan derrotarlo con 'alegría'? Niña tonta. No harás más que provocar la ira del Renacido y, al hacerlo, nos pondrás en peligro a todos''.","Unidad",[],["Noxus"],"COMÚN"],"08NX025":["Espectro Acuchillado","Cuando se revive a un aliado, le otorgo Desafío.","","''¡Sonríes, pero yo conozco la verdad de tu corazón traicionero! Me sonreían y comían de mi mesa, incluso mientras ya habían decidido apuñalarme por la espalda. Nadie volverá a engañarme. Morirás como los demás: ¡pidiendo perdón a gritos!''.","Unidad",[],["Noxus"],"RARA"],"08SH009":["Maldición Ancestral","Maldigo a un enemigo con Terror.","","Hay cosas que es mejor no desenterrar.","Hechizo",[],["Shurima"],"COMÚN"],"08SH014":["Conjuraenjambres Astado","Al jugar: Otorgo -1|-0 a dos enemigos y anulo sus palabras clave positivas.","","A pesar de su intimidante tamaño, este conjuraenjambres no suele ser violento. Cuando su enjambre se acerca a un asentamiento shurimano, los aldeanos dejan bayas frescas como ofrenda en el desierto cercano para evitar que sus visitantes se fijen en las cosechas más importantes.","Unidad",["DRAGÓN"],["Shurima"],"COMÚN"],"08SH004":["General de las Dunas","Amanecer o cuando activas otro Amanecer: Otorgo Vulnerable al enemigo Más débil.","","Los vastos ejércitos de Shurima están preparados para demostrar el poder del desierto. Cuando se da la orden, avanzan sin titubear.","Unidad",["ÉLITE"],["Shurima"],"RARA"],"08SH005":["Defensores del Disco Solar","Amanecer: Roba 1 Defensores del Disco Solar.","","''Somos los guardianes del desierto eterno, la historia viviente, los caminantes del sendero de la luz. Nos arrodillamos ante el Disco Solar y ante nada más, para que el mundo se arrodille ante la gloria de Shurima''. —Azir","Unidad",["ÉLITE"],["Shurima"],"COMÚN"],"08SH012":["Bárbara Saqueatumbas","Cuando muera otro aliado o se active Último Aliento por primera vez en cada ronda: Creo 1 Hallazgo Fortuito en la mano.","","''Eso sí que es un botín, Barb. Sabía que podía contar contigo. Espera... ¿cómo que te vieron?''. —Matón Vekaurano","Unidad",["REPTIL"],["Shurima"],"RARA"],"08SH002":["Tragadunas","Para usarme, mata a un aliado o una de tus gemas de maná 3 veces.","","El tragadunas duerme a profundidades mucho mayores que sus primos xer'sai más pequeños. Conocido por convertir en comida fácil a otros depredadores xer'sai, rara vez se le ha documentado, probablemente por el hecho de que puede tragarse dunas enteras (y a cualquier testigo). ","Unidad",[],["Shurima"],"ÉPICA"],"08MT003":["Morgana","Al jugar: Maldigo a un enemigo con Grilletes dos veces.","Has seleccionado unidades como objetivo 10+ veces.","''Vienes ante mí herida y sangrando, y sin embargo nunca he visto un semblante más alegre. Eres una mujer muy extraña, pero aquí estarás a salvo. Descansa, y cuando te sientas mejor, me gustaría escuchar tu historia''.","Unidad",[],["Targón","Demacia"],"Campeón"],"08MT005":["Mihira, Aspecto Ascendente","Al jugar: Maldigo a 2 enemigos con Grilletes dos veces.","","''Fue por el bien de mis hijas que acepté la divinidad. Fue por mi familia por lo que renuncié a mi propia humanidad, para que con esta espada llameante pudiera forjar un mundo nuevo, regido por la verdad y la justicia''.","Unidad",[],["Targón"],"ÉPICA"],"08MT042":["Ataduras para Pecadores","Maldigo a un enemigo con Grilletes.\nIncremento en 1 el costo de las maldiciones del enemigo en todas partes.","","''Para encontrar tu libertad, debes reconocer la oscuridad que hay en tu interior''. —Morgana","Hechizo",[],["Targón"],"RARA"],"08MT024":["Conjurador Ojo de Rubí","Al jugar: Otorgo Escudo Antihechizos o Arrollar a un aliado en la mano.","","''¡No tengas miedo! ¡Sigue adelante y no mires atrás! Nosotros también hicimos este viaje alguna vez. Ahora es nuestro deber proteger el tuyo. Ve rápido a su santuario y la Dama del Velo te concederá la protección que buscas''.","Unidad",[],["Targón"],"COMÚN"],"08MT045":["Conjurador Encadenado","Al jugar: Me Maldigo con Grilletes.","","Los cazadores de magos son expertos en quebrantar el espíritu de la gente. Le habían atado de manos, y restringieron su magia. Le habían despojado de la voz. Sin embargo, ya había sobrevivido a ellos antes... Y, en esta ocasión, tenía a la Dama del Velo de su lado.","Unidad",[],["Targón"],"RARA"],"08MT015":["Lisa y Dolly","Al jugar: Maldigo a un enemigo con Grilletes.","","''¡Mira, Dolly! ¡Mira lo que hago! ¡Como tú me enseñaste! ¿Crees que alguna vez podremos enseñarle a mamá lo mucho que he aprendido? ¿Crees que ya lo sabe? ¿En serio? Espero que tengas razón''. —Lisa","Unidad",[],["Targón"],"COMÚN"],"08MT030":["Dragón Gemagentil","Otorgo +1|+1 a los Dragones aliados cuando juegues un hechizo Rápido, Lento o una Habilidad.","","Los dragones pueden variar tanto en temperamento como en aspecto. Por cada especie propensa a la destrucción violenta, como los dragones infernales, hay otra igualmente dedicada a la protección de sus familias y entornos, como el lento y cariñoso dragón gemagentil.","Unidad",["DRAGÓN"],["Targón"],"RARA"],"08MT023":["Hechizo Oscuro","Aturdo a un enemigo y lo Maldigo con Grilletes.","","''¡Sufre, tal como tú has hecho sufrir!''. —Morgana","Hechizo",[],["Targón"],"RARA"],"08MT031":["Adorador de Dragones Ottrani","Cuando me invocan, curo 2 a tu nexo y obtienes una gema de maná adicional en la siguiente ronda.","","En lo alto de las montañas de Targón, un solitario Ottrani ha dedicado su vida a los dragones. Se atavía con escamas y huesos viejos, adivinando el camino a seguir por los dientes de dragón desperdigados y los rizos de humo que ascienden por la montaña.","Unidad",[],["Targón"],"ÉPICA"],"08MT009":["Protector Carioculto","Cuando me invocan o invocas a un aliado Titánico, curo 3 a tu nexo.","","Este protector oculto no ha olvidado la bendición que lo elevó más allá de ser una simple bestia, y paga esta deuda asegurándose de que cualquiera que busque cierto santuario en las laderas de Targón emprenda el viaje ileso.","Unidad",[],["Targón"],"RARA"],"08MT006":["Escudo Negro","Doy Escudo Antihechizos a un aliado en esta ronda y lo Maldigo con Grilletes.","","''¡Protegidos de la persecución!''. —Morgana","Hechizo",[],["Targón"],"RARA"],"08MT027":["Heraldo de la Convergencia Celestial","Al jugar: Activo los efectos de Amanecer y Anochecer de los otros aliados.\nAmanecer: Me otorgo Arrollar.\nAnochecer: Me otorgo Escudo Antihechizos.","","''Un anillo de fuego arde sobre nosotros. En la oscuridad presagiada, todos somos iguales''. —Orador Menguante Lunari","Unidad",["AVE"],["Targón"],"ÉPICA"],"08MT025":["Fragmento Sísmico","Si Contemplas una unidad Titánica, cuesto 3 menos.\nInflijo 7 de daño a una unidad.","","''Ups, ay, no te preocupes por eso, solo fue un pequeño temblor, solo un accidente, ¡no papá, NOP! ¡Sigamos!''. —Chip","Hechizo",["ELEMENTAL"],["Targón"],"COMÚN"],"08DE006":["Pionero Erudito","Al jugar: Elige un hechizo de Explorador para crearlo en la mano.","","''Hace frío. Tengo frío. Todo está frío, todo el tiempo. Hay lugares en los que la gente no está destinada a vivir. Por favor, envíenme a un lugar cálido después de esto''. —De los registros de expedición de la División de Reinos Lejanos del Gremio del Explorador, asignación: El Fréljord","Unidad",[],["Demacia","El Fréljord"],"RARA"],"08DE020":["Cadenas Mágicas","Otorgo +0|+2 a un aliado. Maldigo a tu oponente con Supresión.","","''¡Siente el peso de tus pecados!''. —Morgana","Hechizo",[],["Demacia"],"COMÚN"],"08DE017":["Inquisidor Cazamagos","Cuando me invocan, Maldigo a tu oponente con Supresión.","","''No podemos permitir que lleguen al santuario de la hermana caída. Su magia es tan antigua y perversa, que ni siquiera yo puedo suprimirla. ¡Rápido, lleva a estas abominaciones de vuelta al barco y luego sigue al resto montaña arriba'.","Unidad",[],["Demacia"],"RARA"],"08DE025":["Dragón de las Nubes","Cuando me invocan, reduzco en 1 el costo de todos los aliados en tu mano.","","Con su espeso pelaje para aislarse del frío, este dragón puede alcanzar altitudes mucho mayores que la mayoría de los demás dragones. Vivaces y esquivos, los dragones suelen ser vistos en las alturas, cortando las nubes con sus alas mientras vuelan de ráfaga en ráfaga.","Unidad",["DRAGÓN"],["Demacia"],"ÉPICA"],"08DE010":["Duelo de Caballeros","Doy +0|+2 a un aliado en esta ronda.\nEse aliado y un enemigo se Golpean entre sí.","","''¡En garde, colega! Imagino que no eres tan cobarde como para rechazar un duelo con un caballero''. —Caballero Laurent","Hechizo",[],["Demacia"],"COMÚN"],"08DE022":["El Alción","Cuando me invocan, roba 1 de cada campeón de tu mazo.\nEn cada ronda, la primera vez que invoques a un campeón, lanzo Preparar.","","''Recuerda, hijo mío, que si hemos de perseguir un horizonte, debemos hacerlo al servicio del hogar que dejamos atrás''. — Rey Jarvan III","Unidad",[],["Demacia"],"ÉPICA"],"08DE027":["Golpe de Garra","Otorgo +1|+1 a las Aves aliadas en todas partes. Un Ave aliada golpea a un enemigo.","","El chillido del aliplata anuncia la muerte desde lo alto.","Hechizo",[],["Demacia"],"RARA"],"08DE026":["Alatis el Gallardo","Tus Bendiciones de Dragón afectan a todos los aliados Dragón.","","''Que quede claro: no siempre fui amigo de los dragones. El buen Alatis me convenció esa primera vez que me salvó la vida. Me ha enseñado muchas cosas, pero la más importante es esta: no hay mejor vida que servir a Demacia desde el lomo de un dragón''. —Amigo de Dragones","Unidad",["DRAGÓN"],["Demacia"],"ÉPICA"],"08DE013":["Amigo de Dragones","Cuando me invocan, roba un Dragón si Contemplas un Dragón.","","''Sabes que odio admitirlo, viejo amigo, pero no podemos domarlo solos. Ya hicimos todo lo que pudimos. Avisaré al general y, respaldados por el poder de Demacia, seguro que pondremos de rodillas a esa fantástica bestia''.","Unidad",[],["Demacia"],"COMÚN"],"08IO012":["Dragón de los Océanos","Cuando juegas un hechizo Rápido, Lento o una Habilidad, curo 1 a tu nexo.","","''¡Eres una bestia formidable! Hay alegría en el roce de tus garras sobre las olas. Si alguna vez decides cazar algo más que peces y aves marinas, me encantaría enfrentarme a ti''. —Nilah","Unidad",["DRAGÓN"],["Jonia"],"RARA"],"08IO014":["Heisho, Caparazón del Mundo","En cada ronda, la primera carta que juegues cuesta 9 menos.","","Para los habitantes de este pueblo jonio, Heisho es a la vez un respetado cuidador y un amigo. Tras haber llevado sus hogares sobre su espalda desde tiempos inmemoriales, pueden confiar en que el portador de su pueblo buscará costas pacíficas en épocas turbulentas.","Unidad",["REPTIL"],["Jonia"],"ÉPICA"],"08IO021":["Danza Empírea","Detengo un hechizo Rápido, uno Lento o una Habilidad, lanzo Retirada hacia un enemigo, e invoco 1 El Empíreo.","","''Esta es nuestra danza de conmemoración''. —Irelia","Hechizo",[],["Jonia"],"RARA"],"08IO019":["Adnere el Confiable","Cuando me invocan, invoco 1 Avicultores de Adnere.","","''Esta tierra está llena de lecciones. Siempre recuerda: el paso de cada estación debe celebrarse, pues solo al final puede surgir un nuevo comienzo''.","Unidad",[],["Jonia"],"RARA"],"08IO010":["Vuelco","Lanzo Retirada a un enemigo para aumentar en 2 el costo de la siguiente unidad que tu oponente juegue esta ronda.","","''Aquellos que pretendan hacernos daño descansarán en el fondo del mar''. —Moldeador de Ríos","Hechizo",["ELEMENTAL"],["Jonia"],"COMÚN"],"08IO023":["Espíritus Saltarines del Mar","Al jugar: Invoco una copia idéntica de mí con Endeble.","","En ciertas épocas del año, cuando el viento sopla desde el mar, algunos juran haber visto las siluetas de dos enormes criaturas marinas que saltan de gozo al ritmo de la marea.","Unidad",[],["Jonia"],"COMÚN"],"08BC020":["Madrugador","Tu oponente descarta su carta de mayor costo.","","''Imagina ser un gusano y que lo último que ves antes de morir sean esos ojos. Ah, ¿los gusanos no pueden ver? Probablemente sea mejor así''. —Elle, Viajera Apática","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"08BC005":["Mochila Explosiva","Por cada Mochila Explosiva que juegues en esta partida, planto 4 Campanillas en tu mazo y 4 Hongos Venenosos en el mazo enemigo. Creo 1 Mochila Explosiva en tu mazo.","","''Regla 207: ¡Una exploradora solo lleva lo indispensable!''. —Ava Sionada","Hechizo",[],["Ciudad de Bandle"],"RARA"],"08BC021":["Cambio Sigiloso","Lanzo Retirada a un aliado para invocar 1 Buhifelino Hambriento en su lugar.","","''¿SQWUEA?''. —Buhifelino","Hechizo",[],["Ciudad de Bandle"],"RARA"],"08BC002":["Skip, ''Rey del Arrecife''","Al jugar: Elige 1 de 2 cartas que no sean campeones de la mano enemiga. La Capturo.","","''Así es, soy apuesto, veloz e imperturbable. ¿Acaso no lo sabes, anciano? ¡Soy el rey de este arrecife y estás invadiendo mi reino!''.\n''¡E-espera! ¡Vuelve ahora mismo! ¡Necesito ese espécimen para mi investigación!''. —Caracolista","Unidad",[],["Ciudad de Bandle"],"ÉPICA"],"08BC006":["Pionera de Portales","Al jugar: Elige un hechizo de Explorador para crearlo en la mano.","","''¡Me preocupa Montoncitos! Ah, últimamente se lo ve cada vez más y más nervioso. ¡Incluso un breve salto de portal le da ansiedad! No entiendo por qué''. —De los registros de expedición de la División de Reinos Lejanos del Gremio del Explorador, asignación: Ciudad de Bandle","Unidad",["YORDLE"],["Ciudad de Bandle","Jonia"],"RARA"],"08BC004":["Portia la Peculiar","Al jugar: Manifiesto a un seguidor Titánico y fijo sus estadísticas en 1|1 y su costo en 0.","","''¡Claro que conozco a la vieja Portia! Un poco despistada, pero puede conseguirte un portal a cualquier parte, en caso necesario. Un giro con su cola y ¡listo!''. — Pionera de Portales","Unidad",["DRAGÓN"],["Ciudad de Bandle"],"ÉPICA"],"08BC018":["Trampa Azucarada","Coloca un aliado en la parte inferior de tu mazo para invocar al aliado de la parte superior de tu mazo.","","''Regla 571: una exploradora siempre debe estar alerta. Nunca sabes qué puede ser una deliciosa sorpresa y qué puede ser una trampa''. —Ava Sionada","Hechizo",[],["Ciudad de Bandle"],"RARA"],"09SI015":["Un Bello Desastre","I: Mato a una unidad con un total de 5 o menos de poder y vida.\nII: Dreno 2 al nexo enemigo.\nIII: Invoco una copia idéntica de un aliado. Tiene Endeble y 1|1.","","Subió los escalones del escenario, poema en mano. No había colocado carteles para anunciar su presentación, pues ya tenía al público que le interesaba.","Hito",["HISTORIA"],["Islas de la Sombra"],"ÉPICA"],"09SI013":["La Conquista de Hierro","I-II: Elige un seguidor aliado. Creo una copia suya con Endeble en la mano con +1|+1.\nIII: Revivo al seguidor aliado más fuerte y le otorgo Endeble.","","En el Reino Gris, siluetas torturadas se aglomeran formando un ejército espectral. Una vez abiertas las puertas del reino mortal, nada las podrá detener.","Hito",["HISTORIA"],["Islas de la Sombra"],"RARA"],"09SI012":["Vacío Existencial","Otorgo Tristeza a los enemigos.","","''¿Qué sentido tiene cualquier cosa?''. —Vex","Hechizo",[],["Islas de la Sombra"],"RARA"],"09SI017":["Kharox","Cuando 1 aliado que no es Tentáculo muere o activa Último Aliento: Hago Surgir 2.","","Kharox es el remero solitario de un barco espectral al que muchos marineros llaman \"el último navío\". Se dice que convive con los espíritus de todos los navegantes que perecieron intentando llegar a las Islas.","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"09SI014":["Grimm","Al jugar: Otorgo 4 de Tristeza a una unidad.","","Misterioso romántico, poeta atormentado y gran conocedor de temas filosóficos, Grimm no le teme a la tristeza. Se sabe que la dueña sus afectos es algo quisquillosa, pero eso solo la hace más adorable a sus ojos.","Unidad",["YORDLE"],["Islas de la Sombra"],"COMÚN"],"09DE033":["Espirítulos","","","''Los espirítulos son criaturas maravillosas. Con el tiempo y los soñantes adecuados, ¡su potencial simplemente no tiene límites!''. —Madre Espíritu","Unidad",[],["Demacia","Jonia"],"COMÚN"],"09DE039":["La Luz de Demacia","I: Otorgo Ánimo a un aliado.\nII: Otorgo 2 de Ánimo a un aliado.\nIII: Aplico Acrecentar a todos los aliados.","","La ovación de la multitud se intensificaba conforme su fulgor irradiaba sus rostros asombrados. Su único objetivo siempre había sido enaltecer y apoyar a su pueblo. Ahora ellos le correspondían, coreando con devoción al unísono: ''¡Luxanna! ¡Luxanna! ¡Luxanna!''.","Hito",["HISTORIA"],["Demacia"],"RARA"],"09DE034":["Lux: Iluminada","Al apoyar: Otorgo Ánimo al aliado que apoyo y recibo Barrera en esta ronda.","Si los aliados atacaron con 20+ palabras clave positivas en total (o si las obtuvieron mientras atacaban).","La Luz se arremolinaba y formaba arcos alrededor de Luxanna mientras los habitantes de la ciudad la miraban con asombro. Aquí, ella era la Señora de la Luz de Demacia, una honorable joven Guardia de la Corona, y una maga talentosa. Aquí, Demacia era todo lo que ella siempre había querido que fuera.","Unidad",[],["Demacia"],"Campeón"],"09DE047":["Artefacto Olvidado","Invoco un Caballería de Arenisca. Luego, doy Desafío a tus aliados en esta ronda.","","Al fondo de una bóveda de objetos mágicos decomisados por Cazadores de Magos, se encuentra un extraña figura sin identificar. Hace mucho que su propósito cayó en el olvido...","Hechizo",[],["Demacia"],"RARA"],"09DE041":["El Salón de Petricita","I: Un aliado Captura a una unidad.\nII: Maldigo a tu oponente con Supresión.\nIII: Aniquilo todas las cartas Capturadas por los aliados.","","La ovación de la multitud se apagaban a medida que se adentraba en el salón. Las estatuas miraban en silencio. La oscuridad aguardaba, pero no podía dar marcha atrás. Si no, ¿quién podría evitar que Demacia se convirtiera en una pesadilla?","Hito",["HISTORIA"],["Demacia"],"ÉPICA"],"09DE030":["Incandescencia","Aplico Acrecentar a todas las unidades.","","''¡Nuestro resplandor no tiene ataduras!''. —Lux: Iluminada","Hechizo",[],["Demacia"],"COMÚN"],"09DE043":["Luz Creciente","Aplico Acrecentar a todas las unidades 3 veces.","","''¡Consagración en la luz!''. —Lux: Iluminada","Hechizo",[],["Demacia"],"RARA"],"09DE031":["Yarro Plumaluz","Al jugar: Otorgo Ánimo a un aliado en la mano.","","Ante ella se apareció un joven con un antifaz, rodeado de pétalos de rosa y criaturas luminiscentes. ''Me llamo Plumaluz. Yarro Plumaluz'', dijo. ''A su servicio, mi señora. Tengo entendido que necesitaba mi ayuda''.","Unidad",[],["Demacia"],"RARA"],"09DE046":["Sonrisa Ardiente","Aplico Acrecentar a 2 aliados, que luego Golpean a un enemigo, uno después del otro.","","''Tranquilas, señoritas. Hay suficiente Yarro para todas''. —Yarro Plumaluz","Hechizo",[],["Demacia"],"COMÚN"],"09DE045":["Alina Sueñaluz","Cuando me invocan, invoco 5 Espirítulos. Por cada uno para el que no haya espacio, otorgo 2 de Ánimo al aliado Más débil.","","''Cuando tenía tu edad, le tenía mucho miedo a esta luz. No tenía a nadie que me dijera que mi magia era un regalo; que se me había otorgado con un propósito. Pero tú me tienes a mí para eso. Así que no tengas miedo, Alina. Deja que brille''. —Lux: Iluminada","Unidad",[],["Demacia"],"ÉPICA"],"09DE040":["Cazamagos Aberrante","Cuando me invocan, otorgo Ánimo a otros aliados.","","''Lady Guardia de la Corona''. El Cazamagos emergió de entre las sombras, con una mano extendida hacia ella. Su sonrisa suplicante parecía demasiado amplia para aquel rostro oculto a la mitad. ''¿Por qué no me sigues?''.","Unidad",[],["Demacia"],"COMÚN"],"09DE036":["Espíritus Arbóreos","Al jugar: Aplico Acrecentar al resto de las unidades.","","''Andando, pequeños espíritus. Muéstrenle el camino a su soñante''. —Lillia","Unidad",[],["Demacia","Ciudad de Bandle"],"COMÚN"],"09DE029":["Espiriluz","Al apoyar: Doy todas mis palabras clave positivas y sus acumulaciones al aliado que apoyo en esta ronda.","","''Vamos, señor espíritu. ¡Aniquilemos a estas espeluznantes sombras!''. —Alina Sueñaluz","Unidad",[],["Demacia"],"RARA"],"09SH010":["Restauradora del Imperio","Al jugar: Otorgo a un Hito aliado, \"Cuando me destruyen, revivo''.","","El ascenso del emperador ha llenado de esperanza a toda Shurima. Decidida a cumplir la visión de Azir, esta maga se llama a sí misma la \"Restauradora del Imperio\". Viaja por el desierto con el objetivo de devolver su antiguo esplendor a las ruinas enterradas.","Unidad",[],["Shurima"],"COMÚN"],"09SH009":["Ejército Imperial","I: Invoco 2 Soldados de Arena.\nII: Predecir.\nIII: Cuando invocas a un aliado en esta ronda, le doy +2|+0 en esta ronda.","","Azir conoce el pasado, el presente y el futuro de Shurima. Él cree que su visión del futuro es más que un simple sueño: es una profecía que está destinado a cumplir.","Hito",["HISTORIA"],["Shurima"],"ÉPICA"],"09SH012":["Invocación de los Nacidos del Sol","Elige 1 de 3 campeones que empezaron en tu mazo y róbalo.","","Muchos artefactos de los antiguos guerreros Nacidos del Sol se perdieron en el tiempo. Aunque no siempre se puede decir lo mismo de los dioses guerreros que representan.","Hechizo",[],["Shurima"],"RARA"],"09PZ044":["Plegaria a la Luz de las Velas","I-II: Arremolino 1 para robar 1.\nIII: Roba 1.","","Este templo de Janna apenas tiene un par de muros sólidos, para estar en mayor armonía con los poderes de su diosa. Sin embargo, las numerosas velas del interior permanecen siempre encendidas, indiferentes a las tormentas que azotan el resto de Zaun.","Hito",["HISTORIA"],["Piltóver y Zaun"],"ÉPICA"],"09PZ045":["Cartógrafo de las Alturas","Al jugar: Arremolino 1 para robar otra carta que cueste más o menos que la carta que Arremolinaste.","","''No hay como la altitud para entrar en contacto con tu propia intrascendencia''.","Unidad",[],["Piltóver y Zaun"],"RARA"],"09PZ046":["Malmutación","Elige un seguidor aliado. Invoco 2 Buhifelinos Hambrientos. Luego, transformo a los aliados en copias idénticas del aliado elegido.","","''Solo una réplica más... y será perfecto''. —Imperfeccionista Malvada","Hechizo",[],["Piltóver y Zaun"],"ÉPICA"],"09IO055":["Hada de los Pétalos","Cuando me invocan, invoco 1 Espirítulos.","","''¡El cabello de nuestra Lillia es un desastre! Ve a arreglárselo, ¿sí? Recuerda: el primer mechón es para los deseos; el segundo es para sueños; y el último es para todo lo que no es lo que parece''. —Madre Espíritu","Unidad",[],["Jonia"],"RARA"],"09IO056":["Danza de los Espíritus","Lanzo Retirada a un aliado para otorgar todas las acumulaciones de su Ánimo a otro aliado.","","''¡Los sueños del corazón están a una siesta de la realidad!''. —Lillia","Hechizo",[],["Jonia"],"RARA"],"09IO048":["Madre Espíritu","Cuando me invocan, otorgo Ánimo a Espirítulos y Madres Espíritu aliados en todas partes.","","Los espíritus son enérgicos, caprichosos y no muy buenos para escuchar. Para garantizar que cada uno llegue a su soñador, la Madre Espíritu los educa con mano firme y no pocos regaños.","Unidad",[],["Jonia"],"ÉPICA"],"09IO049":["La Cosecha de Gotas de Rocío","I: Invoco un Espirítulos.\nII: Duermo a un aliado.","","Cada gota de rocío de la Madre Árbol ofrecen un vistazo a un sueño que transcurre en algún lugar de Runaterra, y cada una debe ser recolectada, alimentada y protegida con cuidado.","Hito",["HISTORIA"],["Jonia"],"COMÚN"],"09IO052":["Lillia","Cuando me invocan o al Golpear: Creo 1 Rama Colmada de Sueños en la mano o, si tienes una igual, reduzco en 1 su costo.","Si invocaste 15+ aliados o Hitos.","En el corazón del Jardín del Olvido, se acerca la cosecha de gotas de rocío. Aunque Lillia y el resto de los cuidadores del jardín cuidan estas gotitas con mucho cariño, una siniestra corrupción ahora se observa en su interior, y los sueños que muestran se han tornado oscuros y tormentosos...","Unidad",[],["Jonia"],"Campeón"],"09IO046":["Jardinera Ophelis","Al jugar: Curo por completo a un aliado. Luego, lo Duermo.","","Cuidar del Árbol de los Sueños y el jardín que lo rodea es un gran honor, pero exige sacrificio. En un ritual de respeto y agradecimiento, los cuidadores del jardín entregan sus propios recuerdos como ofrenda, con lo que pierden una parte de sí mismos cada noche.","Unidad",[],["Jonia"],"COMÚN"],"09IO051":["El Camino Enraizado","I-II: Roba 1.\nIII: Reduzco en 1 el costo de las cartas en tu mano en esta ronda.","","El Jardín del Olvido es hogar de una extraña variedad de criaturas, tanto grandes como pequeñas, y algunas con más consciencia de la que les gustaría.","Hito",["HISTORIA"],["Jonia"],"RARA"],"09IO053":["Señora Raíz","Cuando me invocan, roba 1.","","''Vaya, un día toda esta belleza habrá muerto, al igual que nosotros. Espero que me toque a mí primero. ¡Je, je, je!''.","Unidad",[],["Jonia"],"COMÚN"],"09IO045":["Capullo Floreciente","Duermo a una unidad.","","''¡Mis sueños están floreciendo!''. —Lillia","Hechizo",[],["Jonia"],"RARA"],"09IO058":["El Corazón del Árbol","I: Curo 3 a tu nexo e invoco un Espirítulos.\nII: Otorgo Ánimo a los aliados en todas partes.\nIII: Manifiesto una carta de 8 de costo o más y reduzco su costo a la mitad, redondeado.","","Los espíritus oníricos son de los habitantes más cuantiosos del Jardín. Los hay de todas formas, tamaños y personalidades. Muchos de ellos se zambullen en gotitas de rocío para guiar a sus soñantes hacia sus deseos más profundos.","Hito",["HISTORIA"],["Jonia"],"ÉPICA"],"09IO059":["Vendaval de Acero","Lanzo Aturdir a un enemigo y lo Aturdo de nuevo en el siguiente Inicio de la ronda.","","''La espada por sobre todas las cosas''. —Yone, el Cazavientos","Hechizo",[],["Jonia"],"COMÚN"],"09FR009":["El Desfile Poro","I-II: Manifiesto a un seguidor que tenga un subtipo diferente al de los aliados en el juego.\nIII: Doy +1|+1 a un aliado en esta ronda por cada aliado que tenga un subtipo.","","Ingvar forjó una relación mucho más estrecha con los súbditos del Rey Poro desde que visitó su reino. Salir en estampida a buscar aventuras en el Fréljord es una de las formas más eficaces de mejorar las relaciones diplomáticas.","Hito",["HISTORIA"],["El Fréljord"],"ÉPICA"],"09FR014":["Brynhir Cantatruenos","Al jugar: Aniquilo a una unidad en tu mano para invocar a una Chapitel Labrado en Tempestad que tenga Cuenta regresiva igual a su costo y que invoque una copia idéntica de dicha unidad. (1 como mínimo).","","''¡Me forjé en la tormenta de la montaña y en la canción de mi pueblo!''.","Unidad",[],["El Fréljord"],"ÉPICA"],"09FR010":["Poro Ultrasuave","Al jugar: Curo 1 a tu nexo por cada aliado que tenga un subtipo.","","''Jo, jo, jo, ¡mira esa bolita de peluche!''. —Pastor de Poros","Unidad",["PORO"],["El Fréljord"],"COMÚN"],"09FR012":["Tala Glacial","Otorgo vida a un aliado en una cantidad equivalente a su poder y Formidable. Luego, fijo su poder en 0.","","Solo el poder del frío invernal puede derribar algunos árboles del Fréljord.","Hechizo",[],["El Fréljord"],"RARA"],"09BC020":["Mirada Fulminante","Otorgo Tristeza a una unidad para robar 1.","","''Felicidades. Te odio''. —Vex","Hechizo",[],["Ciudad de Bandle","Islas de la Sombra"],"COMÚN"],"09BC012":["La Reunión Familiar","I: Otorgo Tristeza a una unidad.\nII: Otorgo Impacto a un aliado.\nIII: Aplico Acrecentar a 2 unidades.","","La separación no logra ablandar este corazón. Pero, al menos, las cenas familiares son más tranquilas así: justo como a Vex le gusta.","Hito",["HISTORIA"],["Ciudad de Bandle"],"ÉPICA"],"09BC001":["Vex","Al atacar: Otorgo Tristeza al enemigo Más fuerte.","Otorgaste Tristeza en +5 ocasiones distintas.","''¡Ay, esta tonta de rosa! Ya le he dicho que ODIO las fiestas, sobre todo cuando hay pastel. Qué asco. Despiértame cuando se vaya''.","Unidad",["YORDLE"],["Ciudad de Bandle","Islas de la Sombra"],"Campeón"],"09BC002":["Tío Milty","Recibo 2 deÁnimo cuando completas una historia.","","Aunque no se parece en nada a su melancólica sobrina, el Tío Milty siempre hace su mejor esfuerzo para conectar con ella. Su método favorito es contarle historias de terror a la luz de las velas.","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"09BC013":["El Dador de Alas","I-II: Elige un aliado. Luego, elige 1 de 3 seguidores que cueste 1 más para transformarlo en él.\nIII: Elige un aliado. Luego, elige 1 de 3 seguidores que cueste 2 más para transformarlo en él.","","Parece que el viejo Trevor Sueñoprofundo siempre está brincando de sueño en sueño. Por fortuna, este parece bastante tranquilo… Aunque es un poco raro que todo aquel con quien se encuentra quiera tener unas alas como las suyas.","Hito",["HISTORIA"],["Ciudad de Bandle"],"RARA"],"09BC004":["Allay","Al jugar: Recibo Ánimo u Otorgo Tristeza a una unidad.","","''¡Veeeee! ¡Esperaaa! ¡Tengo algo para ti! ¡Es una invitación a tu fiesta de cumpleaños! Y un regalito, un poco adelantado. ¡Es que ya no podía esperar! ¿No te mueres de emoción? Tenemos que planear qué nos vamos a poner, el pastel y… ¿Vee?''.","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"09BC016":["Irrupción Monstruosa","Aumento la vida o el poder de un aliado a 5 en esta ronda.","","''Es el peor regalo de la historia''. —Vex","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"09BC003":["Obsequio Grotesco","Le otorgo Tristeza a un enemigo la primera vez que es invocado.","","''Meh, no estuvo tan mal el regalo después de todo''. —Vex","Unidad",[],["Ciudad de Bandle"],"RARA"],"09BC018":["Sombra","Cuando me invocan, roba a Vex.\nRecibo +1|+0 cada vez que hayas otorgado Tristeza en esta partida.","","''¡Muéstrales cómo se hace, Sombra! Sin regalos, sin confeti y, sobre todo, SIN SOMBRERITOS DE FIESTA''. —Vex","Unidad",[],["Ciudad de Bandle","Islas de la Sombra"],"ÉPICA"],"09BC011":["Espiritristes","Al golpear: Recibo Impacto.","","''Los sueños causan efectos raros en los espíritus. Estos parecen ser… Uy, ¿es un pastel?''. —Lillia","Unidad",[],["Ciudad de Bandle"],"COMÚN"],"09BC006":["Alcalde Musculoco","Inicio de la ronda: Me aplico Acrecentar.","","El tiempo parecía detenerse mientras la extraña musculatura del alcalde emergía del pastel más alto que se pueda imaginar. ''¡QUE LOS CUMPLAS FELIZ!'', espetó el alcalde mientras flexionaba los músculos. ''¡De parte del mejor y más fornido funcionario público de Bandle!''.\n\nDe todos los sueños de Vex, este era el que más odiaba. ","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"09BW022":["Campeona de la Fosa","I: Un aliado y un enemigo se Golpean entre sí. Dicho Golpe no puede reducir su vida a menos de 1.\nII: Curo por completo a un aliado.\nIII: Creo 3 Monedas en la mano.","","Ángel ha pasado años tratando de ganar la batalla que ponga fin a todas las batallas. Todas las noches, sueña con una pila de monedas tan grande que no cabría en la bahía de Aguasturbias. Eso sí que es dinero del bueno.","Hito",["HISTORIA"],["Aguasturbias"],"ÉPICA"],"09BW028":["Dedicación Plena","Gano +1|+0 por cada carta que hayas robado en esta ronda.","","''¿Cómo que 'necesito más entrenamiento'? ¡Si he entrenado MUCHO! ¡Mira, mira!''.","Unidad",[],["Aguasturbias"],"RARA"],"09BW027":["Modales de Mercenario","Roba un seguidor enemigo con 3 o menos de vida en esta ronda. (No puedes usarlo si ya tienes 6 aliados o hitos).","","''Un poco menos de sangre, un poco más de oro: la mejor manera de empezar el día''. —Asesina a Sueldo","Hechizo",[],["Aguasturbias"],"COMÚN"],"09MT002":["Huésped de Escamahumeantes","I-II: Para activar, descarta 1. Convoco una carta Celestial que cueste 7 o más.\nIII: Reduzco en 5 el costo de una carta al azar en tu mano.","","Este Ottrani dedica su tiempo en soledad a la adoración de los dragones. Es tanta su fascinación por estas elegantes bestias que puede verlas en el mundo real y en el onírico.","Hito",["HISTORIA"],["Targón"],"ÉPICA"],"09MT004":["Bendiciones Veladas","Otorgo 2 de Ánimo a un aliado.","","''Yo seré su santuario''. —Morgana","Hechizo",[],["Targón"],"COMÚN"],"09MT005":["Soñante de Melodías Dracónicas","En cada ronda, la primera vez que Convoques, invoco 1 Cachorro de Dragón.","","''Los dragones están cerca. Puedo sentirlo. Incluso ahora, vagan entre mis sueños''.","Unidad",[],["Targón"],"ÉPICA"],"09NX025":["El Mejor de la Arena","I-II: Doy +2|+0 a un aliado en esta ronda.\nIII: Doy No bloquea a un enemigo en esta ronda.","","La arena debe parte de su popularidad al hecho de que cualquiera puede hacerse de un nombre en su interior. Este fan en particular ha visto todas las peleas de Draven que ha podido. Está convencido de que, si tuviera la misma oportunidad, también podría llegar hasta la cima.","Hito",["HISTORIA"],["Noxus"],"ÉPICA"],"09NX032":["Domador de Yetis","Para usarme, descarta 1.\nCuando me invocan, invoco 1 Yeti Enfurecido.","","El éxito de la maquinaria de guerra noxiana se debe en parte a su flexibilidad. Cuando la dificultad del terreno o las condiciones complejas exigen adaptabilidad, la milicia aprovechará incluso los recursos locales más extravagantes.","Unidad",[],["Noxus"],"RARA"],"09NX033":["Hacha de Guerra Maldita","Fin de la ronda: Si mi portador no ataca en esta ronda, le otorgo Tristeza.","","La cobardía sale cara.","Equipo",[],["Noxus"],"RARA"]};
